insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('642befe9-8465-573b-80c3-8d94b1467044','ad3bcf03-80be-5f83-8e54-e1318097cb23','yds','The main objective of this study is to measure stress levels.','Bu çalışmanın temel amacı stres düzeylerini ölçmektir.',array[]::text[],'[]'::jsonb,array['aim','goal']::text[],array[]::text[],'[]'::jsonb,'Sıfat olarak “nesnel” demektir.',array['Akademik']::text[],'draft') on conflict do nothing;
