insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('5ea51d98-9cd5-5f93-af92-1f3da5c182ed','7732b903-863c-529b-b19b-3196754846c1','yds','About 60% of respondents said they felt stressed at work.','Yanıt verenlerin yaklaşık %60''ı işte stresli hissettiğini söyledi.',array[]::text[],'["respond (f.) yanıt vermek"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft') on conflict do nothing;
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('b74a107b-f349-55f1-a9fc-8d7f2da46eea','e532d3e3-fe0f-57eb-9a29-e5c28e42d1b4','yds','The new study confirms earlier results.','Yeni çalışma önceki sonuçları doğruluyor.',array[]::text[],'["confirmation (i.) doğrulama"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft') on conflict do nothing;
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('fd261873-c042-5ce6-b6e9-fa06ff6a47fb','62b658e6-7a76-5416-8fe9-60a010aecf87','yds','The study shows a clear trend toward online learning.','Çalışma çevrim içi öğrenmeye yönelik açık bir eğilim gösteriyor.',array['a growing trend','trend toward']::text[],'[]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('f96ac762-d24d-5ff8-8a27-73cdd0d6b091','a1-be','am / is / are (olmak fiili)','Türkçedeki “-im, -sin, -dir” ekleri İngilizcede am / is / are ile yapılır: I am, he/she/it is, we/you/they are.','Olumlu: I am (I''m), you are (you''re), he/she/it is (he''s), we/they are (we''re). Olumsuz: not eklenir — I''m not, he isn''t, they aren''t. Soru: fiil başa gelir — Are you a student? Is she married? Kısa cevap: Yes, I am. / No, she isn''t. Dikkat: “be” cümlesinde do/does kullanılmaz; “Do you a student?” yanlıştır. Meslek söylerken a/an unutulmaz: She is a doctor.','[{"en":"I''m a student.","tr":"Ben öğrenciyim."},{"en":"Is he married? — No, he isn''t.","tr":"O evli mi? — Hayır, değil."},{"en":"We aren''t from Ankara.","tr":"Biz Ankaralı değiliz."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('5af1c505-d7eb-55aa-b328-0b6362bcf0e4','a1-possessives','my / your / his / her / our / their ve ''s','Sahiplik isimden önce gelen sözcükle gösterilir: my book (kitabım), her name (onun adı). Kişi adıyla ''s eklenir: Ali''s car.','I → my, you → your, he → his, she → her, it → its, we → our, they → their. Bu sözcükler her zaman bir isimden önce gelir: my brother, their house. Kişi adlarıyla ''s kullanılır: Ayşe''s phone (Ayşe''nin telefonu), my father''s job. Dikkat: it''s = it is; its = onun (cansız). Türkçede “onun” erkek ve kadın için aynıdır; İngilizcede his (erkek) / her (kadın) ayrılır.','[{"en":"This is my sister. Her name is Elif.","tr":"Bu benim kız kardeşim. Onun adı Elif."},{"en":"Murat''s job is interesting.","tr":"Murat''ın işi ilginç."},{"en":"Their house is near the sea.","tr":"Onların evi denize yakın."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('29ec3331-5684-5de8-93ee-ac44bba8c3be','a1-present-simple','Present simple: alışkanlıklar ve rutinler','Her gün, genellikle, asla gibi alışkanlıklar present simple ile anlatılır. He / she / it ile fiile -s eklenir: she works.','Olumlu: I/you/we/they work; he/she/it works (go → goes, watch → watches, study → studies, have → has). Olumsuz: don''t / doesn''t + yalın fiil — She doesn''t work on Sundays. Soru: Do / Does + özne + yalın fiil — Does he like tea? Kısa cevap: Yes, he does. Sıklık zarfları (always, usually, often, sometimes, never) fiilden önce, “be” fiilinden sonra gelir: I usually walk. / I''m always late. Dikkat: “doesn''t” ve “does” varken fiile -s eklenmez: Does she works? yanlış.','[{"en":"My brother gets up at six.","tr":"Ağabeyim altıda kalkar."},{"en":"We don''t watch TV in the morning.","tr":"Sabahları televizyon izlemeyiz."},{"en":"Does your mother cook every day? — Yes, she does.","tr":"Annen her gün yemek yapar mı? — Evet."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('00612e8e-867f-55ab-921e-275f9ee7e86a','a1-there-is-are','there is / there are (var / yok)','Bir yerde bir şeyin var olduğunu söylerken tekil için there is, çoğul için there are kullanılır.','Tekil ve sayılamayan: There''s a bed. / There''s some milk. Çoğul: There are two chairs. Olumsuz: There isn''t a lift. / There aren''t any shops. Soru: Is there a garden? — Yes, there is. / Are there any windows? — No, there aren''t. Sayılamayan isimlerde (bread, water, milk) olumsuz ve soruda “any” kullanılır. Dikkat: Türkçedeki “var” için “have” kullanılmaz; “My house has a garden” da doğrudur ama “In my house have a garden” yanlıştır.','[{"en":"There''s a small garden behind the house.","tr":"Evin arkasında küçük bir bahçe var."},{"en":"There aren''t any chairs in the kitchen.","tr":"Mutfakta hiç sandalye yok."},{"en":"Is there a bank near here? — Yes, there is.","tr":"Buralarda banka var mı? — Evet, var."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('02625f17-af5e-57c2-8a2f-6855bc99e963','a2-past-simple','Past simple: geçmişte bitmiş olaylar','Geçmişte bitmiş bir olay için fiile -ed eklenir (worked) veya düzensiz biçim kullanılır (went). Soru ve olumsuzda did / didn''t + yalın fiil.','Düzenli: work → worked, stay → stayed, study → studied, stop → stopped. Düzensiz fiiller ezberlenir: go → went, see → saw, buy → bought, have → had, take → took, make → made, eat → ate, lose → lost. Olumsuz: didn''t + yalın fiil — I didn''t see him. Soru: Did + özne + yalın fiil — Did you go out? Kısa cevap: Yes, I did. / No, I didn''t. Zaman ifadeleri: yesterday, last week, two days ago, in 2020. Dikkat: did / didn''t varken fiil geçmişe çevrilmez — Did you went? yanlış.','[{"en":"We visited Mardin last summer.","tr":"Geçen yaz Mardin''i gezdik."},{"en":"I didn''t buy anything.","tr":"Hiçbir şey almadım."},{"en":"Did she call you? — No, she didn''t.","tr":"Seni aradı mı? — Hayır, aramadı."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('7e3d8fe3-7b6e-5879-bde5-d2135c2363dc','a2-was-were','was / were: am-is-are''nin geçmişi','Geçmişte bir durumu anlatırken I / he / she / it ile was, you / we / they ile were kullanılır.','Olumlu: I was tired. They were at home. Olumsuz: wasn''t / weren''t — The hotel wasn''t expensive. Soru: Was it good? Were you there? Kısa cevap: Yes, it was. / No, they weren''t. Var/yok: There was a problem. / There were many people. Dikkat: sıfat ve yer anlatırken was/were kullanılır, did değil — “How did the film?” yanlış; doğrusu “How was the film?”','[{"en":"The weather was perfect.","tr":"Hava mükemmeldi."},{"en":"We weren''t at home on Sunday.","tr":"Pazar günü evde değildik."},{"en":"Was the museum open? — Yes, it was.","tr":"Müze açık mıydı? — Evet, açıktı."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('60588716-9529-5803-8669-650ba63d1393','a2-future-plans','Gelecek: going to, present continuous ve will','Niyet ve planlar için going to, saati/yeri belli ayarlanmış planlar için present continuous, anlık karar ve tahmin için will kullanılır.','going to + yalın fiil: önceden verilmiş karar — I''m going to start a course. Present continuous: ayarlanmış plan — I''m flying to Van on Monday (bilet alındı). will + yalın fiil: tahmin veya o an verilen karar — I think it will rain. / I''ll help you. Olumsuz: I''m not going to … / I won''t … Soru: Are you going to …? / Will you …? Zaman ifadeleri: tomorrow, next week, this weekend, in two days. Dikkat: “going to” sonrası fiil yalın kalır: going to visit (going to visiting değil).','[{"en":"I''m going to cook pasta tonight.","tr":"Bu akşam makarna yapacağım."},{"en":"We''re having a party on Saturday.","tr":"Cumartesi parti veriyoruz."},{"en":"It''s cold. I''ll close the window.","tr":"Hava soğuk. Pencereyi kapatayım."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('c3955b88-19e3-5edf-9f7f-b3c16fa6a32f','a2-comparatives','Karşılaştırma: -er / more, the -est / the most, as … as','İki şeyi karşılaştırırken kısa sıfatlara -er (cheaper), uzunlara more (more expensive) eklenir ve than kullanılır. “En” için the -est / the most.','Kısa sıfat: cheap → cheaper → the cheapest; big → bigger → the biggest; easy → easier → the easiest. Uzun sıfat: comfortable → more comfortable → the most comfortable. Düzensiz: good → better → the best; bad → worse → the worst; far → further → the furthest. Eşitlik: as big as (kadar büyük); not as cheap as (kadar ucuz değil). Dikkat: “more cheaper” gibi iki karşılaştırma bir arada kullanılmaz.','[{"en":"My bag is heavier than yours.","tr":"Benim çantam seninkinden daha ağır."},{"en":"This is the most popular café in the area.","tr":"Burası bölgedeki en popüler kafe."},{"en":"The test wasn''t as hard as I thought.","tr":"Sınav düşündüğüm kadar zor değildi."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('2214bc16-8749-57e5-87e2-26e8445a4a26','b1-conditionals','if cümleleri (1. ve 2. tip) ve tavsiye','Gerçek olasılık: If + present, will + fiil. Hayal ve gerçek dışı durum: If + past, would + fiil. Tavsiye için should / If I were you, I''d …','1. tip (olası): If it rains, we''ll stay at home. 2. tip (hayal / düşük olasılık): If I had a car, I would drive to work. “If I were you, I''d …” tavsiyede yaygındır (be fiili tüm öznelerde were olabilir). unless = if … not: Unless you hurry, you''ll miss it. Tavsiye: You should / shouldn''t …, You''d better … (daha güçlü, uyarı), Why don''t you …? Dikkat: if tarafında will / would kullanılmaz — If I will see him yanlış. Türkçe “-se/-sa” iki tipin de karşılığı olabilir; olasılığa bak.','[{"en":"If you leave now, you''ll catch the train.","tr":"Şimdi çıkarsan trene yetişirsin."},{"en":"If I lived by the sea, I''d swim every day.","tr":"Deniz kenarında yaşasam her gün yüzerdim."},{"en":"You''d better call her before it''s too late.","tr":"Çok geç olmadan onu arasan iyi olur."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('9294e63c-9b9d-54d4-86aa-8be64b531cc4','b1-gerund-infinitive','Fiilden sonra -ing mi, to mu?','Bazı fiillerden sonra -ing (enjoy, mind, avoid, suggest), bazılarından sonra to + fiil (want, decide, hope, manage, afford) gelir.','-ing alanlar: enjoy, mind, avoid, finish, suggest, keep, can''t stand, it''s worth, look forward to (to edattır!). to alanlar: want, would like, decide, hope, plan, promise, manage, afford, need, learn. Her ikisi (az anlam farkıyla): like, love, start, begin. Edatlardan sonra hep -ing: interested in learning, good at cooking, instead of driving, before leaving. Dikkat: I''m looking forward to see you yanlış → to seeing you.','[{"en":"Do you mind closing the door?","tr":"Kapıyı kapatır mısın?"},{"en":"We can''t afford to buy a house yet.","tr":"Henüz ev almaya paramız yetmiyor."},{"en":"She''s good at solving problems.","tr":"Problem çözmekte iyidir."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('52bfdbf9-22a5-57aa-9839-36003347bc22','b1-present-perfect','Present perfect: deneyim ve sonucu bugünü etkileyen olaylar','Zamanı belli olmayan deneyimler ve etkisi bugün süren olaylar have / has + üçüncü hâl ile anlatılır. Zaman belliyse past simple kullanılır.','Kuruluş: have/has + V3 (I''ve seen, she has left). Kullanımlar: (1) Deneyim — Have you ever been to Van? I''ve never tried it. (2) Yakın geçmiş ve sonucu — I''ve lost my keys (şimdi yok). I''ve just eaten. (3) Henüz/çoktan — Have you finished yet? I''ve already paid. Past simple ile fark: belli bir zaman söylenince past simple — I''ve been to Rome (ne zaman olduğu önemsiz) / I went there in 2022 (zaman belli). Dikkat: yesterday, last week, in 2020, ago gibi ifadeler present perfect ile kullanılmaz. been to = gidip geldi; gone to = gitti, hâlâ orada.','[{"en":"Have you ever met a famous person?","tr":"Hiç ünlü biriyle tanıştın mı?"},{"en":"I''ve already seen this film.","tr":"Bu filmi zaten izledim."},{"en":"She''s gone to the bank. She''ll be back soon.","tr":"Bankaya gitti, birazdan döner."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('32dc1ac6-61b6-544e-8ac6-a6ced743f78f','b1-for-since','for / since ve “ne zamandır”','Geçmişte başlayıp hâlâ süren durumlar present perfect ile anlatılır. Süre için for, başlangıç noktası için since kullanılır.','for + süre: for two hours, for ten years, for a long time. since + başlangıç: since Monday, since 2015, since I was a child. Soru: How long have you lived here? Türkçede “İki yıldır burada yaşıyorum” şimdiki zamanla söylenir; İngilizcede present perfect gerekir: I''ve lived here for two years (I live here for two years yanlış). Eylem fiillerinde süreç vurgusu için present perfect continuous da olur: I''ve been waiting for an hour. Durum fiilleri (know, be, have, like) continuous yapılmaz: I''ve known her since school.','[{"en":"We''ve been married for twelve years.","tr":"On iki yıldır evliyiz."},{"en":"He has worked here since March.","tr":"Marttan beri burada çalışıyor."},{"en":"How long have you had this car?","tr":"Bu araba ne zamandır sende?"}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('9623a8a9-63c9-5443-82e7-dab3ac22d3e5','b2-relative-clauses','Relative clauses: who / which / that / whose / where','İsmi tanımlayan yan cümleler who (insan), which (nesne), whose (sahiplik), where (yer) ile kurulur. Virgüllü cümleler sadece ek bilgi verir ve that almaz.','Tanımlayıcı (virgülsüz): Hangi kişi/şey olduğunu söyler — The man who called you is my boss. Burada who/which yerine that de olur; nesne konumundaysa zamir düşebilir: The book (that) I read. Ek bilgi veren (virgüllü): Kişi/şey zaten bellidir — My sister, who lives in Ankara, is a lawyer. Bu tipte that kullanılmaz ve zamir düşmez. whose = -in …-ı: a student whose phone was stolen. where = yer: the town where I grew up. Türkçede bu yapılar “-en, -dığı” sıfat-fiilleriyle karşılanır: “Ankara''da yaşayan kız kardeşim”.','[{"en":"The laptop that I bought last week has stopped working.","tr":"Geçen hafta aldığım dizüstü bilgisayar çalışmayı bıraktı."},{"en":"Our manager, who has worked here for 20 years, is retiring.","tr":"20 yıldır burada çalışan müdürümüz emekli oluyor."},{"en":"That''s the hotel where we stayed on our honeymoon.","tr":"Balayımızda kaldığımız otel orası."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('5224c758-4a8e-52fd-a3d8-b2a48a3af0be','b2-concession','Karşıtlık ve görüş: although, despite, however, whereas','although + cümle, despite / in spite of + isim veya -ing, however iki cümle arasında, whereas / while iki şeyi karşılaştırırken kullanılır.','Although it rained, we went out. = Despite the rain, we went out. = It rained. However, we went out. Despite + -ing: Despite feeling ill, she came. Although ile but aynı cümlede kullanılmaz (Türkçedeki “-e rağmen … ama” yapısını çevirmeyin). whereas / while: I like tea, whereas my wife prefers coffee. Görüş bildirme: In my opinion, … / I see your point, but … / To some extent, I agree. / On the other hand, … Sonuç: As a result, … / Therefore, …','[{"en":"Although the flat is small, it''s very bright.","tr":"Daire küçük olmasına rağmen çok aydınlık."},{"en":"Despite the delay, we arrived on time.","tr":"Gecikmeye rağmen zamanında vardık."},{"en":"Some people love winter, whereas others can''t wait for summer.","tr":"Bazıları kışı severken, diğerleri yazı iple çeker."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('835b44c9-28c4-54d9-ae43-5e5a34bb98b4','b2-third-conditional-wish','3. tip if ve wish / if only','Geçmişte olmamış bir şeyi hayal ederken If + had + V3, would have + V3 kullanılır. Keşke cümleleri: şimdi için wish + past, geçmiş için wish + had + V3.','3. tip: If I had known, I would have helped. (Bilseydim yardım ederdim — ama bilmiyordum.) Olumsuz: If she hadn''t missed the bus, she wouldn''t have been late. Kısaltmalar: I''d known = I had known; I''d have = I would have. wish: Şimdiki durumdan şikâyet — I wish I had more time / I wish I could drive. Geçmiş pişmanlık — I wish I had studied medicine. If only aynı anlamda ama daha güçlü: If only I''d listened! Başkasının davranışından şikâyet: I wish you would stop shouting. Dikkat: if tarafında would kullanılmaz: If I would have known yanlış.','[{"en":"If we had booked earlier, we would have got a cheaper flight.","tr":"Daha erken ayırtsaydık daha ucuz uçuş bulurduk."},{"en":"I wish I had taken that job.","tr":"Keşke o işi kabul etseydim."},{"en":"If only it would stop raining!","tr":"Keşke yağmur dursa!"}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('b07f4ba5-302b-5172-a1d0-605568bf693e','b2-past-modals','Geçmiş modallar: should have, must have, might have, can''t have','Modal + have + V3 geçmişle ilgili eleştiri (should have), güçlü tahmin (must have), olasılık (might / could have) ve imkânsızlık (can''t have) bildirir.','should have + V3: yapılması gerekirdi ama yapılmadı — We should have left earlier. shouldn''t have: yapılmamalıydı — I shouldn''t have said that. must have + V3: kanıta dayalı güçlü tahmin — She must have been tired. might / may / could have + V3: olasılık — They might have got lost. can''t / couldn''t have + V3: olamaz — He can''t have finished already! Dikkat: “must not have” olumsuz tahmin için genelde kullanılmaz; “can''t have” tercih edilir. Modal sonrası have yalındır: should had yanlış.','[{"en":"You shouldn''t have paid so much.","tr":"Bu kadar çok ödememeliydin."},{"en":"The lights are off. They must have gone out.","tr":"Işıklar kapalı. Dışarı çıkmış olmalılar."},{"en":"She can''t have forgotten — I reminded her twice.","tr":"Unutmuş olamaz — ona iki kez hatırlattım."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('4f33dbbc-f273-5e38-9c3a-0a544c9fe9a6','c1-hedging','Temkinli dil (hedging) ve edilgen bildirme','Akademik yazıda kesin iddialardan kaçınılır: tend to, appear to, may, suggest, it could be argued that, is thought to be.','Fiiller: suggest, indicate, appear, seem, tend to (proves, shows yerine). Modallar: may, might, could. Zarflar: possibly, arguably, largely, to some extent. Edilgen bildirme: It is believed that … / X is thought to be … / X is said to have … (She is said to have left the country.) Kalıplar: It could be argued that … / There is evidence that … / This may be due to … Türkçede “-dığı düşünülmektedir, -abilir” yapılarına karşılık gelir. Aşırı hedging metni zayıflatır; iddia gücünü kanıta göre ayarla.','[{"en":"These findings suggest that the policy may have been effective.","tr":"Bu bulgular politikanın etkili olmuş olabileceğini düşündürüyor."},{"en":"The virus is believed to have originated in bats.","tr":"Virüsün yarasalardan kaynaklandığına inanılıyor."},{"en":"Students tend to perform better in the morning.","tr":"Öğrenciler sabahları daha iyi performans gösterme eğiliminde."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('86d19096-36e9-58cb-a165-059d7bff5d47','c1-nominalisation','İsimleştirme (nominalisation) ve resmî bağlantılar','Resmî yazıda fiil yerine isim kullanılır: prices increased → the increase in prices; they failed → their failure.','increase → an increase in, decline → a decline in, fail → failure, decide → decision, analyse → analysis, improve → improvement, lack → a lack of. Örnek: Because the government did not act quickly, unemployment rose. → The government''s failure to act quickly led to a rise in unemployment. Bağlantı ifadeleri: due to / owing to + isim, in terms of, with regard to, in light of, as a result of. Bu yapı bilgiyi yoğunlaştırır ve nesnel bir ton verir; aşırı kullanımı metni ağırlaştırır.','[{"en":"The rapid growth of online shopping has changed city centres.","tr":"Çevrim içi alışverişin hızlı büyümesi şehir merkezlerini değiştirdi."},{"en":"Owing to a lack of evidence, the case was dropped.","tr":"Kanıt yetersizliği nedeniyle dava düştü."},{"en":"In light of these findings, we recommend further research.","tr":"Bu bulgular ışığında daha fazla araştırma öneriyoruz."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('9f62770b-0dcb-581e-914e-3aefa3f2b7b3','c1-inversion','Devrik yapı (inversion): Not only, Rarely, Never, Hardly','Olumsuz veya kısıtlayıcı bir ifade cümle başına alındığında yardımcı fiil özneden önce gelir: Rarely have I seen …','Kalıplar: Never have I … / Rarely / Seldom have I … / Not only did she …, but she also … / Hardly / Scarcely had we … when … / No sooner had we … than … / Under no circumstances should you … / Only then / Only after … did I … / Little did they know … Yardımcı fiil yoksa do/does/did eklenir: Not only did he apologise… Resmî yazıda, konuşmada ve hikâye anlatımında vurgu için kullanılır. Dikkat: devrik yapı yalnız başa alınan ifadeden sonraki ana cümleye uygulanır: Only after she left did I understand (did I, not did she).','[{"en":"Never have I felt so welcome.","tr":"Hiç bu kadar hoş karşılandığımı hissetmemiştim."},{"en":"No sooner had I arrived than it started to rain.","tr":"Varır varmaz yağmur başladı."},{"en":"Little did we know what was coming.","tr":"Neler olacağından habersizdik."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('d7797f43-8a0d-5854-9018-e5f916b89b22','c1-cleft-sentences','Cleft cümleler: What I need is…, It was … that…','Bir bilgiyi öne çıkarmak için cümle ikiye bölünür: What I need is a break. / It was Ayşe who called.','What-cleft: What I love about this city is its food. (Bu şehirde sevdiğim şey yemekleri.) Fiil vurgusu: What she did was (to) call the police. It-cleft: It was in 2019 that we met. / It''s the price that worries me. All / The thing / The reason: All I need is … / The thing is (that) … / The reason (why) … is that … Türkçedeki vurgu (“Beni arayan Ayşe''ydi”) İngilizcede sıralamayla değil bu yapılarla sağlanır. Dikkat: What-cleft öznesi tekil sayılır: What we need is more volunteers.','[{"en":"What annoys me is the noise.","tr":"Beni rahatsız eden şey gürültü."},{"en":"It was the manager who made the final decision.","tr":"Son kararı veren müdürdü."},{"en":"What we did was cancel the trip.","tr":"Yaptığımız şey geziyi iptal etmekti."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('6af81054-a0b7-596b-8426-6497c8119c3b','c2-subjunctive','Subjunctive ve gerçek dışı geçmiş biçimler','suggest, insist, recommend, it is essential/imperative that sonrasında özne + yalın fiil gelir (he be, she go). It''s time, would rather, as if sonrasında geçmiş biçim gerçek dışılık bildirir.','Mandative subjunctive: I recommend that she apply early. It is vital that he be present. (-s yok, “be” çekimsiz.) İngiliz İngilizcesinde “should + fiil” de kullanılır: … that she should apply. Sabit ifadeler: Be that as it may, Come what may, So be it, God save the Queen. Gerçek dışı geçmiş: It''s (high) time we left. / I''d rather you stayed. / He acts as if he owned the place. / If only I knew. Bu yapılar resmî yazıda ve sözleşmelerde sık görülür; Türkçede “-mesi gerekir, -sin” yapılarına karşılık gelir.','[{"en":"The committee recommended that the project be postponed.","tr":"Komite projenin ertelenmesini önerdi."},{"en":"It''s time you got a proper job.","tr":"Artık doğru düzgün bir iş bulmanın vakti geldi."},{"en":"Come what may, I''ll support you.","tr":"Ne olursa olsun seni destekleyeceğim."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('6f90d51f-94ad-5c44-a700-7f119b87a9a9','c2-mixed-conditionals','Karma if ve devrik koşul (Had I known…, Should you…)','Geçmişteki koşulun şimdiki sonucu: If I had …, I would be … now. Kalıcı özelliğin geçmişteki sonucu: If I were …, I would have … Resmî dilde if düşer ve devrik yapı kurulur.','Geçmiş → şimdi: If she hadn''t moved to İzmir, she wouldn''t be so happy now. Şimdi/kalıcı → geçmiş: If he weren''t so stubborn, he would have apologised. Devrik koşul (if olmadan): Had I known = If I had known; Were I in your position = If I were in your position; Should you need help = If you (happen to) need help; Were it not for / Had it not been for = olmasaydı. Devrik koşullarda olumsuzluk kısaltılmaz: Had I not seen it (Hadn''t I seen yanlış).','[{"en":"Had I known about the strike, I would have taken the ferry.","tr":"Grevden haberim olsaydı vapura binerdim."},{"en":"If I hadn''t learned English, I wouldn''t have this job now.","tr":"İngilizce öğrenmeseydim şimdi bu işim olmazdı."},{"en":"Were I in your shoes, I would accept the offer.","tr":"Senin yerinde olsam teklifi kabul ederdim."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('0eef7c35-4a46-5f40-a760-72ae36798851','c2-participle-clauses','Participle clauses: Having done…, Built in…, Given that…','Yan cümleler -ing, V3 veya having + V3 ile kısaltılır: Having finished, she left. / Built in 1890, the bridge… Özne iki cümlede aynı olmalıdır.','-ing (etken, eşzamanlı ya da neden): Feeling tired, I went to bed. / Not knowing the way, we asked. Having + V3 (önce olan eylem): Having read the report, she called the client. V3 (edilgen): Written in 1920, the novel is still popular. Kalıplaşmış ifadeler: Given that…, Considering…, Generally speaking…, Judging by… Dikkat (sarkan ortaç): Walking home, the rain started. yanlıştır — yürüyen yağmur değil; doğrusu: Walking home, I got caught in the rain. What with … and … konuşma dilinde nedenleri sıralar.','[{"en":"Having lived abroad for years, he found it hard to settle back home.","tr":"Yıllarca yurt dışında yaşadıktan sonra memlekete yeniden alışmakta zorlandı."},{"en":"Surrounded by mountains, the village is hard to reach in winter.","tr":"Dağlarla çevrili köye kışın ulaşmak zor."},{"en":"Judging by her smile, the interview went well.","tr":"Gülümsemesine bakılırsa görüşme iyi geçmiş."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('412fcdc3-d793-518b-8bf2-721123a56fa3','c2-ellipsis-substitution','Ellipsis ve ikame: so / not, do so, the former / the latter','Tekrardan kaçınmak için cümle parçaları düşürülür veya so, not, do so, one, the former / the latter gibi sözcüklerle ikame edilir.','so / not: I think so. / I hope not. / I''m afraid so. do so (resmî): Applicants who wish to do so may submit a portfolio. Yardımcı fiille ellipsis: I haven''t finished, but Ali has. / She left early, as did I. / He can swim and so can I. / Neither do I. one / ones: I''d like the red one. the former / the latter: önce ve sonra anılanı gösterir. Vurgu: so much so that …, if so / if not. Türkçede doğal olan tekrarlar İngilizcede genelde ikameyle kaçınılır; bu, akıcı ve olgun bir üslubun işaretidir.','[{"en":"Is the shop open on Sundays? — I believe so.","tr":"Dükkân pazar günü açık mı? — Sanırım öyle."},{"en":"Some students passed; others did not.","tr":"Bazı öğrenciler geçti; bazıları geçmedi."},{"en":"If you have any questions, please do not hesitate to ask. If not, we''ll continue.","tr":"Sorunuz varsa çekinmeden sorun. Yoksa devam edelim."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('3bf15cc6-24b0-5ade-bd72-578e2cc35706','first-conditional','First conditional (olası koşul)','Gelecekte olası bir durum ve sonucu için If + geniş zaman, will + yalın fiil kullanılır: If we add a fan, the temperature will drop.','If''li kısımda will kullanılmaz: If it will rain yanlıştır. Sonuç kısmında can, might, should da gelebilir: If the part arrives today, we can finish tomorrow. unless = if not: Unless we fix it, the line will stop.','[{"en":"If we use a thicker cable, it won''t overheat.","tr":"Daha kalın bir kablo kullanırsak aşırı ısınmaz."},{"en":"If the part arrives today, we can finish tomorrow.","tr":"Parça bugün gelirse yarın bitirebiliriz."},{"en":"Unless we inspect it, we won''t find the crack.","tr":"Muayene etmezsek çatlağı bulamayız."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('9279b596-fe91-567a-9d51-125884641a4b','suggestions-recommend','suggest ve recommend ile öneri','suggest/recommend + -ing ya da suggest/recommend + that + özne + yalın fiil kullanılır: We recommend using a filter. I suggest that we test it again.','suggest/recommend + kişi + to + fiil yanlıştır: I suggest you to test yanlış; doğrusu I suggest (that) you test it. Seçenek sunmak için One option is to … / Another option is to … kullanılır. Resmî raporlarda: It is recommended that …','[{"en":"We recommend replacing the filter every month.","tr":"Filtrenin her ay değiştirilmesini öneriyoruz."},{"en":"I suggest that we stop the line now.","tr":"Hattı şimdi durdurmamızı öneriyorum."},{"en":"Another option is to buy a new pump.","tr":"Bir diğer seçenek yeni bir pompa almak."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('456ec5da-d7b5-550b-9e0c-056b23139658','comparatives','Karşılaştırma (comparatives)','Kısa sıfatlar -er ve than alır: lighter than. Uzun sıfatlarda more kullanılır: more efficient than.','Düzensiz biçimler: good → better, bad → worse. Farkın büyüklüğü: much / far / slightly + -er: much lighter, slightly heavier. Eşitlik: as … as: as strong as steel. Kat: twice as heavy as. En üstünlük: the lightest, the most efficient. “more heavier” gibi çift karşılaştırma yanlıştır.','[{"en":"The new motor is more efficient than the old one.","tr":"Yeni motor eskisinden daha verimli."},{"en":"Aluminum is much lighter than steel.","tr":"Alüminyum çelikten çok daha hafif."},{"en":"This part is twice as heavy as that one.","tr":"Bu parça ötekinin iki katı ağır."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('d5774794-79d5-5598-b2ee-b28a68901a09','measurements-numbers','Ölçü ve sayıları söyleme','Boyut: 60 by 120 cm (altmışa yüz yirmi). Ondalık ayırıcı noktadır ve “point” diye okunur: 0.05 = zero point zero five.','Binlik ayırıcı virgüldür: 1,000. ± “plus or minus” diye okunur. Birim çoğulu: 2 kilograms; sıfat olarak tekil: a 2-kilogram part. Oranlar “per” ile: 30 liters per minute. Aralık: from −20 to 60 degrees Celsius. up to = -e kadar (üst sınır).','[{"en":"The plate measures 200 by 300 mm.","tr":"Plaka 200''e 300 mm boyutunda."},{"en":"The tolerance is plus or minus 0.05 mm.","tr":"Tolerans artı eksi 0,05 mm."},{"en":"The pump can deliver up to 40 liters per minute.","tr":"Pompa dakikada 40 litreye kadar basabilir."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('192debd3-9082-5b07-80a0-40d56570f67c','zero-conditional','Zero conditional (her zaman geçerli koşul)','Her zaman aynı sonucu veren durumlar için If + geniş zaman, geniş zaman kullanılır: If the pressure drops, the valve closes.','Teknik açıklamalarda ve kılavuzlarda çok yaygındır. If yerine When de kullanılabilir: When the light turns red, the system stops. Gelecekteki tek bir olası durum için first conditional kullanılır: If it rains tomorrow, we will test indoors.','[{"en":"If the temperature exceeds 100 °C, the system stops.","tr":"Sıcaklık 100 °C''yi aşarsa sistem durur."},{"en":"When you press this button, the pump starts.","tr":"Bu düğmeye bastığında pompa çalışır."},{"en":"If water gets inside, the sensor fails.","tr":"İçeri su girerse sensör arızalanır."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('0e47e1be-1f21-5acc-aab3-01552452cccd','past-passive','Geçmiş zamanda edilgen yapı','Test raporlarında işi kimin yaptığı önemli değilse was/were + fiilin 3. hâli kullanılır: The samples were tested at 20 °C.','Tekil özne: was tested; çoğul özne: were tested. Olumsuz: wasn''t measured. Soru: Was it calibrated? Yapan belirtilecekse: The test was carried out by the quality team. Raporlarda etken yapı (We tested …) da kabul edilir; edilgen daha resmî durur.','[{"en":"The samples were tested at 20 °C.","tr":"Numuneler 20 °C''de test edildi."},{"en":"The sensor was calibrated last month.","tr":"Sensör geçen ay kalibre edildi."},{"en":"Was the data recorded correctly?","tr":"Veriler doğru kaydedildi mi?"}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5','going-to-plans','be going to ve will ile gelecek','Önceden karar verilmiş planlar için am/is/are going to + yalın fiil: I''m going to visit my parents. Konuşma anında verilen kararlar ve sözler için will: I''ll call you later.','Ayarlanmış buluşmalar için present continuous da kullanılır: I''m meeting Ayşe tomorrow. Olumsuz: I''m not going to … / I won''t … Konuşmada going to çoğu zaman “gonna” diye söylenir ama resmî yazıda kullanılmaz. will kısaltmaları: I''ll, you''ll, we''ll.','[{"en":"I''m going to clean the house on Saturday.","tr":"Cumartesi evi temizleyeceğim."},{"en":"I''ll send you the address.","tr":"Sana adresi göndereceğim."},{"en":"We''re meeting at six.","tr":"Altıda buluşuyoruz."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('7be2ff59-b822-5d17-b28c-77b5dd4bad29','frequency-adverbs','Sıklık zarfları','always, usually, often, sometimes, rarely, never ne sıklıkla yaptığını anlatır ve genelde ana fiilden önce gelir: I usually walk to work.','be fiilinden sonra gelir: I''m always tired on Mondays. Sıklık sorusu: How often do you …? Cevaplar: once a week, twice a month, every day (genelde cümle sonunda). never zaten olumsuzdur; “don''t never” denmez.','[{"en":"I usually have breakfast at eight.","tr":"Genellikle sekizde kahvaltı yaparım."},{"en":"She is never late.","tr":"O asla geç kalmaz."},{"en":"How often do you go to the gym?","tr":"Spor salonuna ne sıklıkla gidersin?"}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('61191619-612d-5027-a1fe-6212fc28bc5e','present-simple','Present Simple (geniş zaman)','Alışkanlıklar, kalıcı durumlar ve genel gerçekler için kullanılır: I work at a bank. He, she, it ile fiil -s alır: She works.','Olumsuz: I don''t / She doesn''t + yalın fiil. Soru: Do you …? / Does she …? Sıklık zarfları (always, usually, often, sometimes, never) genelde fiilden önce gelir: I usually walk to work. like, know, need, want gibi durum fiilleri çoğunlukla -ing almaz.','[{"en":"I work at a small company.","tr":"Küçük bir şirkette çalışıyorum."},{"en":"She doesn''t drink coffee.","tr":"Kahve içmez."},{"en":"Do you live near here?","tr":"Buraya yakın mı oturuyorsun?"}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('451cf418-a1b2-5782-8a95-8dc5c6a0b92d','to-be','to be: am / is / are','Kim olduğunu, nereli olduğunu ve nasıl hissettiğini anlatırken am/is/are kullanılır: I''m a nurse. She''s from İzmir.','I am (I''m); you, we, they are (''re); he, she, it is (''s). Olumsuz: I''m not, isn''t, aren''t. Soru: Are you a student? Is he at work? Meslekten önce a/an gelir: I''m an engineer. Sıfat + edat kalıpları çok kullanılır: good at, interested in, sure about, stuck on.','[{"en":"I''m a teacher.","tr":"Öğretmenim."},{"en":"Are you from Ankara?","tr":"Ankaralı mısın?"},{"en":"We aren''t sure about the plan.","tr":"Plandan emin değiliz."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('851477de-6cca-5819-9b94-be7428c7eb31','would-like','would like ve would you mind','Bir şey isterken I''d like + isim ya da I''d like to + fiil kibar bir yoldur: I''d like a refund. I''d like to speak to the manager.','I want daha doğrudandır; restoranda ve mağazada I''d like tercih edilir. Teklif: Would you like some tea? Çok nazik rica: Would you mind + -ing: Would you mind closing the window? Buna “No, not at all.” yanıtı “Hayır, hiç sorun değil” demektir; yani rica kabul edilmiştir.','[{"en":"I''d like the soup, please.","tr":"Çorba alayım, lütfen."},{"en":"Would you like a coffee?","tr":"Kahve ister misin?"},{"en":"Would you mind waiting a minute?","tr":"Bir dakika bekler misiniz?"}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('d5daeed1-3188-5fc9-bf18-7fc0d1d582be','can-have-to','can, could ve have to','can/could yetenek, izin ve rica bildirir: Can I sit here? Could you help me? have to zorunluluk bildirir: I have to leave early.','can ve could sonrası yalın fiil gelir, “to” gelmez. could, can''den daha naziktir. have to, he/she/it ile has to olur. Olumsuzu farklıdır: don''t have to “gerek yok”, mustn''t “yasak” demektir. Sık kalıp: I can''t make it = gelemiyorum, yetişemiyorum.','[{"en":"Could I have the bill, please?","tr":"Hesabı alabilir miyim, lütfen?"},{"en":"I have to work late tonight.","tr":"Bu akşam geç saate kadar çalışmam gerekiyor."},{"en":"You don''t have to bring anything.","tr":"Bir şey getirmene gerek yok."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('d8558e30-a9d6-599b-badb-54d137a6308c','present-perfect-continuous','Süregelen durumlar: have been + -ing ve have had','Geçmişte başlayıp hâlâ süren belirtiler için have been + fiil-ing ya da have had kullanılır; süre için for, başlangıç için since.','I''ve been coughing for three days (üç gündür öksürüyorum). I''ve had this rash since Monday (pazartesiden beri bu döküntü var). Doktor sorusu: How long have you had this pain? Bitmiş bir olayda geçmiş zaman kullanılır: I fell yesterday. Hayat boyu deneyim için ever: Have you ever had surgery?','[{"en":"I''ve been coughing for three days.","tr":"Üç gündür öksürüyorum."},{"en":"How long have you had this pain?","tr":"Ne zamandır bu ağrı var?"},{"en":"I''ve had a fever since Sunday.","tr":"Pazardan beri ateşim var."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('d0ce0122-6b50-5a5c-9acb-81c3e9022a7f','imperatives-advice','Talimat ve öneri: Take …, You should …, You''ll need to …','İlaç ve tedavi talimatlarında emir kipi (Take, Avoid) ve should / need to / make sure yapıları kullanılır.','Emir kipi doğrudan ve nettir: Take one tablet twice a day. Daha yumuşak öneri: You should rest. Zorunluluk: You''ll need to have an X-ray. Uyarı: Make sure you drink enough water. Olumsuz: Don''t take it on an empty stomach. Avoid sonrası fiil -ing alır: avoid driving.','[{"en":"Take one tablet twice a day.","tr":"Günde iki kez bir tablet alın."},{"en":"Don''t drive after taking this medicine.","tr":"Bu ilacı aldıktan sonra araba kullanmayın."},{"en":"You should avoid lifting heavy things.","tr":"Ağır şeyler kaldırmaktan kaçınmalısınız."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('0f975d51-eeae-5d81-8159-c91595116b6f','pharmacy-frequency','Sıklık ve süre: twice a day, every 8 hours, for a week','İlaç talimatlarında sıklık “… a day / every … hours”, süre “for …”, zaman “before / after / with” ile söylenir.','Sıklık: once a day (günde bir), twice a day (günde iki), three times a day (günde üç), every eight hours (sekiz saatte bir). Süre: for five days (beş gün boyunca), until the pack is finished (kutu bitene kadar). Zaman: before meals (yemekten önce), after meals (yemekten sonra), with food (yemekle), at bedtime (yatarken). Soru: How often …? (ne sıklıkla), How long …? (ne kadar süre).','[{"en":"Take one tablet every eight hours.","tr":"Sekiz saatte bir tablet alın."},{"en":"Use the drops three times a day for a week.","tr":"Damlaları bir hafta boyunca günde üç kez kullanın."},{"en":"How long should I take it for?","tr":"Ne kadar süre almalıyım?"}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('b82ec38c-25ce-5968-86bf-cf52a35f95ce','if-clauses-instructions','Koşullu talimatlar: If you …, take / stop / see','Prospektüslerde “If + şimdiki zaman, emir kipi” yapısı sık geçer: belirli bir durumda ne yapılacağını söyler.','Yapı: If + özne + şimdiki zaman, emir kipi. If you miss a dose, take it as soon as you remember. If you feel dizzy, do not drive. If symptoms persist, see a doctor. “if” cümlesinde will kullanılmaz: If you will feel … yanlıştır. Yerine “in case of + isim” de kullanılabilir: In case of overdose, contact a doctor.','[{"en":"If you feel dizzy, do not drive.","tr":"Başınız dönerse araç kullanmayın."},{"en":"If symptoms persist, see a doctor.","tr":"Belirtiler geçmezse doktora görünün."},{"en":"In case of an allergic reaction, stop taking it.","tr":"Alerjik reaksiyon durumunda kullanmayı bırakın."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('3e9a97ae-1d43-53b8-91a9-7132362c4453','ward-questions','Hastaya kibar soru: How …? Is there …? When can I …?','Serviste sorular kısa ve kibardır. Soru kelimesi + yardımcı fiil + özne sırası kullanılır; “just”, “Is that OK?” yumuşatır.','Soru sırası: How + sıfat + is it? (How bad is the pain?), When + can + I …? (When can I go home?). Var mı sorusu: Is there anyone who …? / Is there anything …? Yumuşatma: I''m just going to …, is that OK? ve Would you like …? Hastanın sorusunda da aynı sıra korunur: Can I have some water? (I can have değil).','[{"en":"How bad is the pain now?","tr":"Ağrı şu an ne kadar kötü?"},{"en":"I''m just going to check your drip, is that OK?","tr":"Şimdi serumunuza bakacağım, olur mu?"},{"en":"When can I have something to eat?","tr":"Ne zaman bir şey yiyebilirim?"}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('8345e4b2-b920-5777-8e3e-30174e85411d','future-plans-hospital','Planlanan işlemler: will / be going to / be + -ing','Kesinleşmiş hastane planları için “be going to” veya “be + -ing”, tahmin ve söz için “will” kullanılır.','Planlanmış işlem: You''re having surgery tomorrow at nine (yarın dokuzda ameliyat oluyorsunuz). Niyet: We''re going to take some blood (biraz kan alacağız). Tahmin: You''ll feel better in a few days (birkaç güne kendinizi daha iyi hissedeceksiniz). Söz: I''ll bring you some water (size su getireceğim). Edilgen gelecek: Your stitches will be removed next week.','[{"en":"You''re having an X-ray this afternoon.","tr":"Bu öğleden sonra röntgen çektireceksiniz."},{"en":"We''re going to keep you here tonight.","tr":"Bu gece sizi burada tutacağız."},{"en":"You''ll feel much better tomorrow.","tr":"Yarın çok daha iyi hissedeceksiniz."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('16367d68-e368-5168-a91c-8cd0a27160dc','employment-law-modals','Hak ve yükümlülük: be entitled to, must, shall, may','İş hukukunda hak “be entitled to”, yükümlülük “must / shall”, izin “may” ile ifade edilir.','Hak: Employees are entitled to paid leave (çalışanların ücretli izin hakkı vardır). Yükümlülük: The employer must pay salaries on time. Sözleşme dili: The employee shall give four weeks'' notice (… verecektir). İzin: The employee may work from home two days a week (… çalışabilir). Yasak: The employee shall not disclose confidential information.','[{"en":"Employees are entitled to 14 days of paid leave.","tr":"Çalışanların 14 gün ücretli izin hakkı vardır."},{"en":"The employee shall give four weeks'' notice.","tr":"Çalışan dört hafta önceden bildirimde bulunacaktır."},{"en":"The employee may work remotely on Fridays.","tr":"Çalışan cuma günleri uzaktan çalışabilir."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('579f790c-122b-5a4c-9727-9f6a1b9c44dd','formal-letters-legal','Resmî mektup kalıpları: I am writing to …, Please find attached …, We hereby …','Hukuki ve resmî yazışmalar amaç cümlesiyle başlar, ek ve teyit kalıplarıyla devam eder, resmî kapanışla biter.','Açılış: Dear Ms Smith / Dear Sir or Madam. Amaç: I am writing to inform you that … / I am writing to give notice of … Ek: Please find attached a copy of … Teyit: We hereby confirm that … Rica: We would be grateful if you could … İstek: Please sign and return … by … Kapanış: Kind regards / Yours sincerely (isim biliniyorsa) / Yours faithfully (bilinmiyorsa, İngiliz kullanımı).','[{"en":"I am writing to give notice of my resignation.","tr":"İstifamı bildirmek için yazıyorum."},{"en":"Please find attached the signed contract.","tr":"İmzalı sözleşme ekte sunulmuştur."},{"en":"We hereby confirm that the payment has been received.","tr":"Ödemenin alındığını işbu yazıyla teyit ederiz."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('5dea6707-1af4-5744-a755-f5101202772c','legal-modals','Sözleşmede modal fiiller: shall, may, must, is entitled to','Sözleşmede shall yükümlülük, may hak/izin, must kesin zorunluluk bildirir; is entitled to bir hakka sahip olmayı anlatır.','The supplier shall deliver the goods (tedarikçi teslim edecektir: yükümlülük). Either party may terminate (taraflar feshedebilir: hak). The buyer must pay within 30 days (zorunluluk). The employee is entitled to paid leave (hak). Günlük dilde shall nadir kullanılır ama sözleşmelerde standarttır. Olumsuz: shall not = yapmayacaktır (yasak).','[{"en":"The tenant shall not sublet the flat.","tr":"Kiracı daireyi başkasına kiraya vermeyecektir."},{"en":"Either party may terminate this agreement.","tr":"Taraflardan her biri bu sözleşmeyi feshedebilir."},{"en":"The buyer is entitled to a refund.","tr":"Alıcı para iadesi hakkına sahiptir."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('f67d8e99-5efb-5381-a4f0-c3b2f6e90c67','legal-conditions','Koşul ve istisna: in the event of, unless, failure to','Hukuki metinlerde koşullar if yerine çoğu zaman in the event of, provided that, unless ve failure to yapılarıyla anlatılır.','In the event of a delay, the buyer will be informed (gecikme durumunda). Unless otherwise agreed (aksi kararlaştırılmadıkça). Provided that the payment is made, the goods will be delivered (ödemenin yapılması şartıyla). Failure to comply will result in termination (uyulmaması fesihle sonuçlanır).','[{"en":"In the event of a dispute, Turkish courts have jurisdiction.","tr":"Uyuşmazlık hâlinde Türk mahkemeleri yetkilidir."},{"en":"Unless otherwise stated, prices include VAT.","tr":"Aksi belirtilmedikçe fiyatlara KDV dahildir."},{"en":"Failure to pay will result in a penalty.","tr":"Ödeme yapılmaması cezayla sonuçlanır."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('15a40f50-45a8-5c7c-9de2-6e6eee3caa49','court-passive-reporting','Mahkeme dili: edilgen yapı ve aktarma fiilleri','Mahkeme sürecini anlatırken edilgen (was adjourned, was found guilty) ve aktarma fiilleri (ruled that, claimed that, denied …) sık kullanılır.','Edilgen: The hearing was adjourned (duruşma ertelendi). He was found guilty (suçlu bulundu). The case was dismissed (dava reddedildi). Aktarma: The court ruled that … (mahkeme … karar verdi), The plaintiff claims that … (davacı … iddia ediyor), The defendant denied the allegations (davalı iddiaları reddetti). deny sonrası isim ya da -ing gelir: denied breaching the contract.','[{"en":"The case was dismissed.","tr":"Dava reddedildi."},{"en":"The plaintiff claims that the goods were damaged.","tr":"Davacı malların hasarlı olduğunu iddia ediyor."},{"en":"The defendant denied breaching the contract.","tr":"Davalı sözleşmeyi ihlal ettiğini reddetti."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('1e667df4-3d60-5a3d-bf4b-db340b45ad36','formal-advice-requirements','Resmî tavsiye ve zorunluluk: must, are required to, we would advise','Avukat yazışmasında zorunluluk “must / are required to”, tavsiye “we would advise you to / it is advisable to” ile verilir.','Zorunluluk: You must file the appeal within 14 days. You are required to attend the hearing. Tavsiye: We would advise you to keep copies of all documents. It is advisable to seek legal advice. Olasılık: The court may ask for further evidence. Yumuşak dil: We would be grateful if you could send …','[{"en":"You are required to attend the hearing in person.","tr":"Duruşmaya bizzat katılmanız gerekmektedir."},{"en":"We would advise you not to sign the agreement yet.","tr":"Sözleşmeyi henüz imzalamamanızı tavsiye ederiz."},{"en":"The court may ask for further evidence.","tr":"Mahkeme ek delil isteyebilir."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('a5f9d0fc-be42-50ae-afd1-5c3a477c4150','modal-suggestions-should','should ve could ile öneri','Öneri yaparken should (yapmalı) daha güçlü, could (yapabiliriz) daha yumuşaktır. Ardından fiil yalın gelir: We should add a test.','Maybe we could … / What about adding …? / Why don''t we …? kalıpları nazik öneridir. Modal fiiller ek almaz ve “to” ile kullanılmaz: should to add yanlıştır. Olumsuz: You shouldn''t merge it yet. Kod incelemesinde doğrudan emir (Change this.) yerine öneri kalıbı daha kibar durur.','[{"en":"We should add a test for this case.","tr":"Bu durum için bir test eklemeliyiz."},{"en":"Maybe we could cache the result.","tr":"Belki sonucu önbelleğe alabiliriz."},{"en":"You shouldn''t merge it before the tests pass.","tr":"Testler geçmeden birleştirmemelisin."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('65dafd22-780c-55e5-96c7-520eb58691f9','passive-voice-basics','Edilgen yapı (passive voice)','İşi kimin yaptığı önemli değilse be + fiilin 3. hâli kullanılır: The bug was fixed. This should be moved.','Zamanlara göre: is fixed (geniş), was fixed (geçmiş), has been fixed (sonuç), will be fixed (gelecek), should be fixed (gereklilik). Yapan belirtilecekse “by” kullanılır: The PR was approved by Ece. Teknik metinlerde ve raporlarda çok yaygındır.','[{"en":"The bug was fixed in version 2.4.","tr":"Hata 2.4 sürümünde düzeltildi."},{"en":"This logic should be moved to a helper.","tr":"Bu mantık bir yardımcıya taşınmalı."},{"en":"The PR was approved by two reviewers.","tr":"PR iki inceleyen tarafından onaylandı."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('6abb00b5-f7d0-5462-97e1-00928664f27f','past-simple-reporting','Past Simple ile olanı anlatma','Biten olayları anlatırken fiilin geçmiş hâli kullanılır: It crashed. I fixed it. Düzensiz fiillere dikkat: see → saw, find → found.','Olumsuz ve soru “did” ile kurulur ve fiil yalın kalır: It didn''t crash. Did it crash? Hata kayıtlarında olayların sırası verilir: First I logged in, then the page froze. Zaman belirtilmişse (yesterday, at 10 am) past simple gerekir; zaman yoksa ve sonuç şimdi önemliyse present perfect tercih edilir: I''ve fixed it.','[{"en":"The app crashed after the update.","tr":"Uygulama güncellemeden sonra çöktü."},{"en":"I didn''t see any errors in the log.","tr":"Kayıtta hiçbir hata görmedim."},{"en":"Did you restart the server?","tr":"Sunucuyu yeniden başlattın mı?"}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('6a11b3cb-d93f-533d-b6d2-56af6ab35df5','present-perfect-results','Present Perfect ile sonuç bildirme','Geçmişte yapılan ama sonucu şimdi önemli olan işler için have/has + fiilin 3. hâli kullanılır: I''ve finished the tests.','Belirli bir geçmiş zaman söylenmez: I''ve fixed the bug (I''ve fixed it yesterday denmez; zaman varsa past simple: I fixed it yesterday). Soru: Have you tried restarting it? Olumsuz: We haven''t deployed yet. “already” ve “yet” sık birlikte kullanılır: I''ve already merged it. / Has QA tested it yet?','[{"en":"I''ve finished the API integration.","tr":"API entegrasyonunu bitirdim."},{"en":"Have you tried clearing the cache?","tr":"Önbelleği temizlemeyi denedin mi?"},{"en":"We haven''t released the hotfix yet.","tr":"Acil düzeltmeyi henüz yayımlamadık."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('07f46ae3-6018-5f8f-8bda-377e874ddc92','present-continuous','Present Continuous (şimdiki zaman)','Şu an ya da bu günlerde süren işler için am/is/are + fiil-ing kullanılır. Toplantıda en sık kalıp: I''m working on …','Olumlu: I''m (I am) working on the login page. Olumsuz: I''m not working on it today. Soru: Are you working on the API? Durum bildiren bazı fiiller (know, need, want) genellikle -ing almaz: I need help (I''m needing help değil). “Bu hafta, bu sprint” gibi geçici süreçler için de kullanılır: This week we''re fixing bugs.','[{"en":"I''m working on the login page.","tr":"Giriş sayfası üzerinde çalışıyorum."},{"en":"Are you working on the API today?","tr":"Bugün API üzerinde mi çalışıyorsun?"},{"en":"We aren''t adding new features this week.","tr":"Bu hafta yeni özellik eklemiyoruz."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('d5e18b4b-8396-58e1-90d3-60ff590c1767','polite-requests-could','Could you …? ile nazik istek','Bir iş arkadaşından nazikçe bir şey isterken Could you + yalın fiil kullanılır. Can you daha samimidir.','Could you review my code? (nazik) · Can you review my code? (samimi) · Would you mind reviewing my code? (daha yumuşak; mind sonrası fiil -ing alır). Could we …? biçimi ortak bir öneri veya plan değişikliği için kullanılır: Could we move the demo? Cevap verirken: Sure. / Of course. / Sorry, I can''t today.','[{"en":"Could you take a look at my pull request?","tr":"Pull request''ime bir göz atabilir misin?"},{"en":"Would you mind sharing the logs?","tr":"Kayıtları paylaşır mısın?"},{"en":"Could we move the meeting to 3 pm?","tr":"Toplantıyı saat 15''e alabilir miyiz?"}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('ab246489-675d-583d-8e43-a239cdb66f2a','announcements-passive','Anons dili: edilgen yapı ve “please + fiil”','Havalimanı anonsları edilgen yapı (has been delayed) ve rica bildiren “please proceed / please have … ready” kalıplarıyla kurulur.','Edilgen: Flight BA 678 has been delayed (rötar yaptı), has been cancelled (iptal edildi), is now boarding (biniş başladı). Rica: Passengers are kindly requested to … / Please proceed to gate 9. / Please have your boarding pass ready. Zaman: The gate will close in ten minutes. Yolcunun cümlesi: My flight has been cancelled. Has the gate changed?','[{"en":"Flight LH 1301 has been delayed.","tr":"LH 1301 sefer sayılı uçuş rötar yaptı."},{"en":"Please have your boarding pass ready.","tr":"Lütfen biniş kartınızı hazır bulundurun."},{"en":"The gate will close in ten minutes.","tr":"Kapı on dakika içinde kapanacak."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('8c120d15-94e9-5183-b37d-b34780b51767','complaints-polite','Kibar şikâyet ve talep: I''m afraid …, Would it be possible to …?','Rötar ya da kayıp bagajda sorunu sakin söyleyip çözüm istemek için I''m afraid …, I was wondering if …, Would it be possible to …? kullanılır.','Sorunu belirt: I''m afraid my bag hasn''t arrived. Çözüm iste: Would it be possible to rebook me on the next flight? Daha yumuşak: I was wondering if you could help me. Hak sor: Am I entitled to a meal voucher? Teşekkür: Thanks for your help — I really appreciate it.','[{"en":"I''m afraid my bag hasn''t arrived.","tr":"Maalesef çantam gelmedi."},{"en":"Would it be possible to rebook me on the next flight?","tr":"Beni bir sonraki uçuşa aktarmanız mümkün mü?"},{"en":"Am I entitled to a meal voucher?","tr":"Yemek kuponu hakkım var mı?"}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('0866ecaa-2cdb-5df1-b0a5-fb0697124e56','ordering-food','Sipariş vermek: I''ll have …, Could I get …?, without …','Restoranda sipariş “I''ll have …” ya da “Could I get …?” ile verilir; değişiklik “with / without / on the side” ile istenir.','Sipariş: I''ll have the chicken. / Could I get a coffee, please? Değişiklik: without onions (soğansız), with extra cheese (ekstra peynirli), dressing on the side (sos ayrı). Soru: Does it come with …? / Does this contain nuts? Hesap: Could we have the check, please? / Can we pay separately? Garsonun sorusu: Are you ready to order? / Anything else?','[{"en":"I''ll have the pasta without mushrooms.","tr":"Mantarsız makarna alayım."},{"en":"Could I get the dressing on the side?","tr":"Sosu ayrı alabilir miyim?"},{"en":"Can we pay separately?","tr":"Ayrı ayrı ödeyebilir miyiz?"}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('e7e2e237-32cd-5f36-88d2-26afdef9a4ef','transport-prepositions','Ulaşım edatları: by bus, on foot, get on / get off, change at','Araçla gitmek “by + araç”, yürümek “on foot”; araca binmek “get on”, inmek “get off”, aktarma “change at”.','by bus / by train / by taxi (araçla), on foot (yürüyerek). Otobüs ve trene: get on / get off; arabaya ve taksiye: get in / get out of. Aktarma: change at Central Station. Durak: at the next stop. Yön: towards the city centre (merkeze doğru). Süre: It takes 20 minutes by bus.','[{"en":"It takes 20 minutes by bus.","tr":"Otobüsle 20 dakika sürüyor."},{"en":"Get off at the third stop.","tr":"Üçüncü durakta inin."},{"en":"Change at Central Station for line 2.","tr":"2 numaralı hat için Merkez İstasyonu''nda aktarma yapın."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('a5a06244-837e-5d75-a164-db5014b69b3c','polite-hotel-language','Otelde kibar dil: Could I …?, Would you like …?, I''m afraid …','Misafirle konuşurken doğrudan emir yerine Could I …?, Would you like …? ve kötü haber için I''m afraid … kullanılır.','Bilgi isterken: Could I have your passport, please? Teklif ederken: Would you like a room with a view? Olumsuz haber verirken yumuşatmak için: I''m afraid we''re fully booked. / Unfortunately, the pool is closed today. Özür: We apologize for the inconvenience. Misafir de aynı yapıları kullanır: Could you call a taxi for me?','[{"en":"Could I have your name, please?","tr":"Adınızı alabilir miyim, lütfen?"},{"en":"Would you like some help with your luggage?","tr":"Bavullarınız için yardım ister misiniz?"},{"en":"I''m afraid the restaurant is closed now.","tr":"Korkarım restoran şu an kapalı."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('c36bc526-816e-5d15-843f-1b7cf3da1ff3','directions-prepositions','Yol tarifi ve yer edatları','Yer tarif ederken next to, opposite, on the left, at the end of gibi edatlar ve go straight, turn left gibi emir kipleri kullanılır.','Go straight on and turn left at the traffic lights. The pharmacy is next to the bank, opposite the post office. It''s at the end of the street, on the right. Mesafe: It''s a five-minute walk / It''s within walking distance. Soru: How do I get to the beach? / Is it far from here?','[{"en":"Go straight and turn right at the corner.","tr":"Düz gidin ve köşeden sağa dönün."},{"en":"The café is opposite the museum.","tr":"Kafe müzenin karşısında."},{"en":"It''s within walking distance.","tr":"Yürüme mesafesinde."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('1b0b85f6-765e-57cd-838b-8e483d2c0e86','linkers-cause-effect','Neden-sonuç bağlaçları','Neden: because + cümle; because of / due to + isim. Sonuç: so, therefore, thus, consequently, as a result. Amaç: so that + cümle.','Bağlacın ardından ne geldiğine bak: cümle mi, isim mi? because the weather was bad / because of the bad weather. therefore ve consequently genelde noktalı virgül veya noktadan sonra gelir ve ardından virgül alır. otherwise “aksi takdirde” anlamında koşullu bir sonuç bildirir.','[{"en":"Because of the strike, all trains were cancelled.","tr":"Grev yüzünden bütün trenler iptal edildi."},{"en":"The sample was small; therefore, the results are limited.","tr":"Örneklem küçüktü; bu nedenle sonuçlar sınırlı."},{"en":"He left early so that he could catch the bus.","tr":"Otobüse yetişebilmek için erken çıktı."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('18bb25a1-8990-5403-bef1-60ed86047678','linkers-contrast','Karşıtlık bağlaçları','Cümle ile: although, even though, whereas, while. İsim ile: despite, in spite of. Cümle başında bağlantı zarfı olarak: however, nevertheless, in contrast.','although + cümle: Although it rained, … / despite + isim veya -ing: Despite the rain, … / Despite being tired, … “despite of” yanlıştır. whereas iki durumu karşılaştırır: A is cheap, whereas B is expensive. however ve nevertheless noktalı virgül veya noktadan sonra gelir. Paragraf sorularında karşıtlık bağlacından sonra çoğu zaman yazarın asıl görüşü gelir.','[{"en":"Although it was late, they continued working.","tr":"Geç olmasına rağmen çalışmaya devam ettiler."},{"en":"Despite the high price, the product sold well.","tr":"Yüksek fiyatına rağmen ürün iyi sattı."},{"en":"Some people learn by reading, whereas others learn by doing.","tr":"Bazı insanlar okuyarak öğrenirken diğerleri yaparak öğrenir."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('720f608f-5573-5769-bc14-e12bd1dbaa95','change-verbs','Değişimi anlatma: increase, rise, fall, decline','Fiil: Prices rose/fell by 5%. İsim: There was a 5% rise/fall in prices. by = değişim miktarı, to = ulaşılan değer, from … to = başlangıç ve son değer.','rise (rose, risen) nesne almaz; raise nesne ister: The company raised prices. Zarf + fiil: increased sharply, fell slightly. Sıfat + isim: a sharp increase, a slight fall. Grafik metinlerinde sık geçenler: peak (zirve), remain stable (sabit kalmak), fluctuate (dalgalanmak), level off (sabitlenmek), account for (… oluşturmak).','[{"en":"Sales rose by 10% to 2 million.","tr":"Satışlar %10 artarak 2 milyona çıktı."},{"en":"There was a slight fall in exports.","tr":"İhracatta hafif bir düşüş oldu."},{"en":"The company raised its prices.","tr":"Şirket fiyatlarını artırdı."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('c2448d19-7c6a-5373-b84f-f0ecdb345163','present-perfect-trends','Eğilimlerde present perfect','Geçmişte başlayıp etkisi süren değişimler için has/have + fiilin 3. hâli kullanılır: The number of users has doubled since 2020.','since + başlangıç noktası (since 2020), for + süre (for ten years), over the last decade. Sürecin devam ettiğini vurgulamak için present perfect continuous: Prices have been rising for months. Belirli ve bitmiş bir zaman söyleniyorsa past simple gerekir: Prices rose in 2021.','[{"en":"Internet use has increased over the last decade.","tr":"İnternet kullanımı son on yılda arttı."},{"en":"The number of students has grown since 2015.","tr":"Öğrenci sayısı 2015''ten beri arttı."},{"en":"Prices have been rising for six months.","tr":"Fiyatlar altı aydır yükseliyor."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('bfcf9a85-caf2-5d11-b852-1fdd48d940df','reporting-verbs','Raporlama fiilleri (suggest, show, claim …)','Akademik metinlerde bulgular suggest, show, indicate, reveal, claim gibi fiillerle aktarılır. Fiilin gücü önemlidir: show kesin, suggest temkinlidir.','Yapı: özne + fiil + that + cümle: The data indicate that … Temkinli dil (hedging): may, might, likely, appear to: The drug may reduce pain. Okuma sorularında yazarın kesin mi temkinli mi konuştuğuna dikkat et. claim (iddia eder) çoğu zaman yazarın bu görüşe mesafeli olduğunu ima eder.','[{"en":"The data indicate that the effect is small.","tr":"Veriler etkinin küçük olduğunu gösteriyor."},{"en":"Some experts claim that the method is unsafe.","tr":"Bazı uzmanlar yöntemin güvenli olmadığını iddia ediyor."},{"en":"It is likely that prices will rise.","tr":"Fiyatların artması muhtemel."}]'::jsonb,'draft') on conflict do nothing;
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('5745b079-cf8a-5e9d-9c2f-f10b9ed53ed7','relative-clauses','İlgi cümlecikleri (who, which, that)','Bir ismi açıklayan cümlecikte insanlar için who, nesneler için which, ikisi için de that kullanılır: participants who slept less, a study which lasted ten years.','whose iyelik bildirir: students whose parents work abroad. where yer bildirir: the city where the study was done. Virgüllü (ek bilgi veren) ilgi cümleciğinde that kullanılmaz: The study, which lasted ten years, … Cümle tamamlama sorularında ismin insan mı nesne mi olduğuna ve virgüle bak.','[{"en":"Students who sleep well perform better.","tr":"İyi uyuyan öğrenciler daha iyi performans gösterir."},{"en":"The method, which was developed in 2010, is still popular.","tr":"2010''da geliştirilen yöntem hâlâ yaygın."},{"en":"This is the lab where the tests were done.","tr":"Testlerin yapıldığı laboratuvar burası."}]'::jsonb,'draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c751d22e-086f-59d4-bc9b-241d50f92f60','My name is …','is','My name is Kerem.','Benim adım Kerem.','[{"en":"My name","tr":"benim adım"},{"en":"is","tr":"-dır"}]'::jsonb,'f96ac762-d24d-5ff8-8a27-73cdd0d6b091',array['Tanışma']::text[],array['Günlük']::text[],'Benim adım …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('36f72847-dcf1-51a2-9897-66f0ab474282','I''m a/an …','I''m','I''m an engineer.','Ben mühendisim.','[{"en":"I''m","tr":"ben …im"},{"en":"an engineer","tr":"(bir) mühendis"}]'::jsonb,'f96ac762-d24d-5ff8-8a27-73cdd0d6b091',array['Tanışma','Meslek']::text[],array['Günlük']::text[],'Ben …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('eef1cd99-a975-5ddf-83fe-d693bf912452','Where are you from? — I''m from …','are','Where are you from?','Nerelisin?','[{"en":"Where","tr":"nereden"},{"en":"are you from","tr":"-lısın"}]'::jsonb,'f96ac762-d24d-5ff8-8a27-73cdd0d6b091',array['Tanışma']::text[],array['Soru']::text[],'Ben …lıyım.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('78c0a427-ac52-50dc-badd-d15c653bf217','This is my …','is','This is my mother.','Bu benim annem.','[{"en":"This is","tr":"bu"},{"en":"my mother","tr":"benim annem"}]'::jsonb,'5af1c505-d7eb-55aa-b328-0b6362bcf0e4',array['Tanıştırma']::text[],array['Günlük']::text[],'Bu benim …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('44dce2bc-95af-515d-bb5d-71d0459acd9c','His/Her name is …','Her','Her name is Selin.','Onun (kızın) adı Selin.','[{"en":"Her name","tr":"onun (kadın) adı"},{"en":"is Selin","tr":"Selin"}]'::jsonb,'5af1c505-d7eb-55aa-b328-0b6362bcf0e4',array['Tanıştırma']::text[],array['Günlük']::text[],'Onun adı …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6dfe6f55-b132-55a8-84a0-907052f11edc','How old are you? — I''m … years old.','old','How old are you?','Kaç yaşındasın?','[{"en":"How old","tr":"kaç yaşında"},{"en":"are you","tr":"-sın"}]'::jsonb,'f96ac762-d24d-5ff8-8a27-73cdd0d6b091',array['Tanışma']::text[],array['Soru']::text[],'… yaşındayım.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7e145833-4989-56ba-a10a-afe049248ab6','Are you a …? — Yes, I am. / No, I''m not.','Are','Are you a teacher?','Öğretmen misin?','[{"en":"Are you","tr":"misin"},{"en":"a teacher","tr":"öğretmen"}]'::jsonb,'f96ac762-d24d-5ff8-8a27-73cdd0d6b091',array['Tanışma']::text[],array['Soru']::text[],'… misin?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('364f67e2-0697-5671-bcb8-dc50be47e373','He isn''t … / They aren''t …','aren''t','My parents aren''t at home.','Annemle babam evde değil.','[{"en":"My parents","tr":"annemle babam"},{"en":"aren''t","tr":"değil"},{"en":"at home","tr":"evde"}]'::jsonb,'f96ac762-d24d-5ff8-8a27-73cdd0d6b091',array['Günlük']::text[],array['Olumsuz']::text[],'Annemle babam … değil.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('e02c2931-7682-544a-8cc1-d466f6904fc4','What''s your …?','your','What''s your email address?','E-posta adresin ne?','[{"en":"What''s","tr":"ne"},{"en":"your email address","tr":"e-posta adresin"}]'::jsonb,'5af1c505-d7eb-55aa-b328-0b6362bcf0e4',array['Form doldurma']::text[],array['Soru']::text[],'… ne?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('1dd4ef10-546c-5da5-87c3-6dd14d72ca71','We''re … / They''re …','They''re','They''re my cousins from London.','Onlar Londra''dan kuzenlerim.','[{"en":"They''re","tr":"onlar …"},{"en":"my cousins","tr":"kuzenlerim"}]'::jsonb,'f96ac762-d24d-5ff8-8a27-73cdd0d6b091',array['Tanıştırma']::text[],array['Günlük']::text[],'Onlar …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b90f79a4-4e21-5e1b-a8c9-e48a583b8166','I usually … in the morning.','have','I usually have a shower in the morning.','Sabahları genellikle duş alırım.','[{"en":"I usually","tr":"genellikle"},{"en":"have a shower","tr":"duş alırım"},{"en":"in the morning","tr":"sabahları"}]'::jsonb,'29ec3331-5684-5de8-93ee-ac44bba8c3be',array['Rutin']::text[],array['Günlük']::text[],'Sabahları genellikle …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3bf49f95-f50a-5337-8439-3481948c09f8','She works …','works','She works in a bank.','O bir bankada çalışıyor.','[{"en":"She works","tr":"o çalışıyor"},{"en":"in a bank","tr":"bir bankada"}]'::jsonb,'29ec3331-5684-5de8-93ee-ac44bba8c3be',array['Meslek']::text[],array['Günlük']::text[],'O … çalışıyor.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f03ce547-c384-5539-b5c3-5913debc2d4e','Do you like …?','Do','Do you like spicy food?','Acı yemek sever misin?','[{"en":"Do you like","tr":"sever misin"},{"en":"spicy food","tr":"acı yemek"}]'::jsonb,'29ec3331-5684-5de8-93ee-ac44bba8c3be',array['Sohbet']::text[],array['Soru']::text[],'… sever misin?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('935631d3-f299-5a98-ac46-95d4db1a8ac9','He doesn''t …','doesn''t','He doesn''t drink coffee.','O kahve içmez.','[{"en":"He doesn''t","tr":"o …mez"},{"en":"drink coffee","tr":"kahve içmek"}]'::jsonb,'29ec3331-5684-5de8-93ee-ac44bba8c3be',array['Günlük']::text[],array['Olumsuz']::text[],'O … içmez.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('1660ed3b-cd22-58cc-9568-06be3b947420','There''s a … in the …','There''s','There''s a sofa in the living room.','Oturma odasında bir kanepe var.','[{"en":"There''s a sofa","tr":"bir kanepe var"},{"en":"in the living room","tr":"oturma odasında"}]'::jsonb,'00612e8e-867f-55ab-921e-275f9ee7e86a',array['Ev']::text[],array['Tanımlama']::text[],'Oturma odasında … var.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('49eb6cdd-fce6-5743-864c-fe85da268b31','There are … in my …','are','There are two bathrooms in my flat.','Dairemde iki banyo var.','[{"en":"There are","tr":"var"},{"en":"two bathrooms","tr":"iki banyo"},{"en":"in my flat","tr":"dairemde"}]'::jsonb,'00612e8e-867f-55ab-921e-275f9ee7e86a',array['Ev']::text[],array['Tanımlama']::text[],'Dairemde … var.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('5c148dee-ce22-5ad7-8875-d468bd9dcbe6','Is there a … ?','there','Is there a supermarket near your house?','Evinin yakınında bir süpermarket var mı?','[{"en":"Is there","tr":"var mı"},{"en":"a supermarket","tr":"bir süpermarket"},{"en":"near your house","tr":"evinin yakınında"}]'::jsonb,'00612e8e-867f-55ab-921e-275f9ee7e86a',array['Ev','Yer']::text[],array['Soru']::text[],'Evinin yakınında … var mı?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c7183bc0-eb16-5d20-8b41-6b7f88561a9b','What time do you …?','do','What time do you finish work?','İşi saat kaçta bitirirsin?','[{"en":"What time","tr":"saat kaçta"},{"en":"do you finish","tr":"bitirirsin"},{"en":"work","tr":"iş"}]'::jsonb,'29ec3331-5684-5de8-93ee-ac44bba8c3be',array['Rutin']::text[],array['Soru']::text[],'Saat kaçta …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('1026cb1f-c56d-519f-8111-feecad490d19','I … at … o''clock.','at','I have lunch at one o''clock.','Saat birde öğle yemeği yerim.','[{"en":"I have lunch","tr":"öğle yemeği yerim"},{"en":"at one o''clock","tr":"saat birde"}]'::jsonb,'29ec3331-5684-5de8-93ee-ac44bba8c3be',array['Saat']::text[],array['Günlük']::text[],'Saat … öğle yemeği yerim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('33e11182-cec2-5020-8b02-66e3c9b4ea58','There isn''t any … / There aren''t any …','isn''t','There isn''t any bread left.','Hiç ekmek kalmadı.','[{"en":"There isn''t any","tr":"hiç … yok"},{"en":"bread","tr":"ekmek"},{"en":"left","tr":"kalmış"}]'::jsonb,'00612e8e-867f-55ab-921e-275f9ee7e86a',array['Ev','Yemek']::text[],array['Olumsuz']::text[],'Hiç … kalmadı.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('26049fd6-5608-5fe3-bb6c-0556b7fc7fc7','What did you do …?','did','What did you do on Saturday?','Cumartesi ne yaptın?','[{"en":"What did you do","tr":"ne yaptın"},{"en":"on Saturday","tr":"cumartesi"}]'::jsonb,'02625f17-af5e-57c2-8a2f-6855bc99e963',array['Sohbet']::text[],array['Soru']::text[],'… ne yaptın?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b8446068-4217-59ab-877e-e863b5a6ba23','I went to … with …','went','I went to a concert with my sister.','Kız kardeşimle bir konsere gittim.','[{"en":"I went to","tr":"-e gittim"},{"en":"with my sister","tr":"kız kardeşimle"}]'::jsonb,'02625f17-af5e-57c2-8a2f-6855bc99e963',array['Sohbet']::text[],array['Günlük']::text[],'Kız kardeşimle … gittim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('eaecd550-f794-55cd-a21d-6e4c802cc913','I didn''t … because …','didn''t','I didn''t go out because it was raining.','Yağmur yağdığı için dışarı çıkmadım.','[{"en":"I didn''t go out","tr":"dışarı çıkmadım"},{"en":"because","tr":"çünkü"}]'::jsonb,'02625f17-af5e-57c2-8a2f-6855bc99e963',array['Sohbet']::text[],array['Olumsuz']::text[],'… için dışarı çıkmadım.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('da58415c-5c2d-5a5d-830d-d61ee964aea1','It was really …','was','It was really fun.','Gerçekten eğlenceliydi.','[{"en":"It was","tr":"-ydi"},{"en":"really fun","tr":"gerçekten eğlenceli"}]'::jsonb,'7e3d8fe3-7b6e-5879-bde5-d2135c2363dc',array['Görüş']::text[],array['Günlük']::text[],'Gerçekten …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('37d41dbe-f12c-5969-9d16-9a113d04147d','Were you at … ?','Were','Were you at home last night?','Dün gece evde miydin?','[{"en":"Were you","tr":"miydin"},{"en":"at home","tr":"evde"},{"en":"last night","tr":"dün gece"}]'::jsonb,'7e3d8fe3-7b6e-5879-bde5-d2135c2363dc',array['Sohbet']::text[],array['Soru']::text[],'Dün gece … miydin?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f32b1624-bfe1-50b3-896a-9c1e32ec6069','When I was …, I …','lived','When I was a child, I lived in a village.','Çocukken bir köyde yaşardım.','[{"en":"When I was a child","tr":"çocukken"},{"en":"I lived","tr":"yaşardım"},{"en":"in a village","tr":"bir köyde"}]'::jsonb,'02625f17-af5e-57c2-8a2f-6855bc99e963',array['Anı']::text[],array['Anlatı']::text[],'…ken bir köyde yaşardım.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('e1d49b11-7f17-5360-a3a2-6a563bb59aba','How was your …?','was','How was your trip?','Gezin nasıl geçti?','[{"en":"How was","tr":"nasıldı"},{"en":"your trip","tr":"gezin"}]'::jsonb,'7e3d8fe3-7b6e-5879-bde5-d2135c2363dc',array['Sohbet']::text[],array['Soru']::text[],'… nasıl geçti?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a473e273-7c01-5264-a093-da0953fff40b','There were lots of … at …','were','There were lots of people at the festival.','Festivalde bir sürü insan vardı.','[{"en":"There were","tr":"vardı"},{"en":"lots of people","tr":"bir sürü insan"}]'::jsonb,'7e3d8fe3-7b6e-5879-bde5-d2135c2363dc',array['Anlatı']::text[],array['Tanımlama']::text[],'Festivalde bir sürü … vardı.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('38969f49-9b20-59d6-bbed-471e06b92b51','First we …, then we …','then','First we had lunch, then we went to the museum.','Önce öğle yemeği yedik, sonra müzeye gittik.','[{"en":"First","tr":"önce"},{"en":"then","tr":"sonra"},{"en":"after that","tr":"ondan sonra"}]'::jsonb,'02625f17-af5e-57c2-8a2f-6855bc99e963',array['Anlatı']::text[],array['Anlatı']::text[],'Önce öğle yemeği yedik, sonra … gittik.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('4e46753d-7252-5eae-a7f3-dc9f2c7f2420','Did you enjoy …?','enjoy','Did you enjoy the concert?','Konser hoşuna gitti mi?','[{"en":"Did you enjoy","tr":"hoşuna gitti mi"},{"en":"the concert","tr":"konser"}]'::jsonb,'02625f17-af5e-57c2-8a2f-6855bc99e963',array['Sohbet']::text[],array['Soru']::text[],'… hoşuna gitti mi?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7fc54f60-25e0-5859-adb4-7f9f13b6c078','I''m going to … next …','learn','I''m going to learn to drive next year.','Seneye araba kullanmayı öğreneceğim.','[{"en":"I''m going to","tr":"-eceğim (niyet)"},{"en":"learn","tr":"öğrenmek"},{"en":"next year","tr":"seneye"}]'::jsonb,'60588716-9529-5803-8669-650ba63d1393',array['Plan']::text[],array['Günlük']::text[],'Seneye … öğreneceğim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a1eda1e5-85aa-5635-b387-d6aa465c91c8','Are you going to … ?','to','Are you going to watch the match tonight?','Bu akşam maçı izleyecek misin?','[{"en":"Are you going to","tr":"-ecek misin"},{"en":"watch","tr":"izlemek"},{"en":"tonight","tr":"bu akşam"}]'::jsonb,'60588716-9529-5803-8669-650ba63d1393',array['Plan']::text[],array['Soru']::text[],'Bu akşam … izleyecek misin?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('df91b876-700a-5394-b9e0-b387212de82d','I''m … on …','meeting','I''m meeting my friends on Friday.','Cuma günü arkadaşlarımla buluşuyorum.','[{"en":"I''m meeting","tr":"buluşuyorum (ayarlanmış plan)"},{"en":"on Friday","tr":"cuma günü"}]'::jsonb,'60588716-9529-5803-8669-650ba63d1393',array['Plan']::text[],array['Günlük']::text[],'Cuma günü …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b9176026-bb12-5ce1-93bb-8ea82f58ac4f','… is …-er than …','faster','The train is faster than the bus.','Tren otobüsten daha hızlı.','[{"en":"The train is","tr":"tren"},{"en":"faster than","tr":"-den daha hızlı"},{"en":"the bus","tr":"otobüs"}]'::jsonb,'c3955b88-19e3-5edf-9f7f-b3c16fa6a32f',array['Karşılaştırma']::text[],array['Tanımlama']::text[],'Tren otobüsten daha …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('8de71039-58ef-515b-b4d1-73c2c5ef1c9b','… is more … than …','expensive','Living in İstanbul is more expensive than living in Sivas.','İstanbul''da yaşamak Sivas''ta yaşamaktan daha pahalı.','[{"en":"is more expensive","tr":"daha pahalı"},{"en":"than","tr":"-den"}]'::jsonb,'c3955b88-19e3-5edf-9f7f-b3c16fa6a32f',array['Karşılaştırma']::text[],array['Görüş']::text[],'İstanbul''da yaşamak Sivas''ta yaşamaktan daha …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('616c6b48-27cb-5cc9-af83-179a7a030a5c','It''s the most … in …','most','It''s the most beautiful beach in Turkey.','Türkiye''deki en güzel plaj.','[{"en":"the most beautiful","tr":"en güzel"},{"en":"in Turkey","tr":"Türkiye''de"}]'::jsonb,'c3955b88-19e3-5edf-9f7f-b3c16fa6a32f',array['Karşılaştırma']::text[],array['Tanımlama']::text[],'Türkiye''deki en … plaj.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('45db8301-61cc-5c16-a59b-ce0ba21b7bac','Can I try … on?','try','Can I try this jacket on?','Bu ceketi deneyebilir miyim?','[{"en":"Can I try","tr":"deneyebilir miyim"},{"en":"this jacket on","tr":"bu ceketi (üstüme)"}]'::jsonb,'c3955b88-19e3-5edf-9f7f-b3c16fa6a32f',array['Alışveriş']::text[],array['Kibar']::text[],'… deneyebilir miyim?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('03d81a7c-92ab-5687-b388-51e004e5675f','How much is/are …?','are','How much are these sunglasses?','Bu güneş gözlüğü ne kadar?','[{"en":"How much","tr":"ne kadar"},{"en":"are these sunglasses","tr":"bu güneş gözlüğü"}]'::jsonb,'c3955b88-19e3-5edf-9f7f-b3c16fa6a32f',array['Alışveriş']::text[],array['Soru']::text[],'… ne kadar?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b72eab08-7b81-51a7-a891-5e4f5f656e6f','… isn''t as … as …','as','My new flat isn''t as big as my old one.','Yeni dairem eskisi kadar büyük değil.','[{"en":"isn''t as big","tr":"o kadar büyük değil"},{"en":"as my old one","tr":"eskisi kadar"}]'::jsonb,'c3955b88-19e3-5edf-9f7f-b3c16fa6a32f',array['Karşılaştırma']::text[],array['Olumsuz']::text[],'Yeni dairem eskisi kadar … değil.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6797fc42-c1d4-5753-9463-d6a1c2b2e0da','I think it will …','will','I think it will be sunny tomorrow.','Bence yarın hava güneşli olacak.','[{"en":"I think","tr":"bence"},{"en":"it will be","tr":"olacak"},{"en":"tomorrow","tr":"yarın"}]'::jsonb,'60588716-9529-5803-8669-650ba63d1393',array['Tahmin']::text[],array['Görüş']::text[],'Bence yarın hava … olacak.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d3ad70e5-baaa-5e7c-91ce-3c060784ca15','If you …, you''ll …','pass','If you study every day, you''ll pass the exam.','Her gün çalışırsan sınavı geçersin.','[{"en":"If you study","tr":"çalışırsan"},{"en":"you''ll pass","tr":"geçersin"}]'::jsonb,'2214bc16-8749-57e5-87e2-26e8445a4a26',array['Tavsiye']::text[],array['Koşul']::text[],'Her gün çalışırsan …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('68dc6b9f-36d4-596c-a55a-e391f5fbc9e4','If I were you, I''d …','talk','If I were you, I''d talk to your manager.','Senin yerinde olsam müdürünle konuşurdum.','[{"en":"If I were you","tr":"senin yerinde olsam"},{"en":"I''d talk","tr":"konuşurdum"}]'::jsonb,'2214bc16-8749-57e5-87e2-26e8445a4a26',array['Tavsiye']::text[],array['Kibar']::text[],'Senin yerinde olsam …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('43dad03e-106b-571f-ac68-7ed1d8078261','If I had …, I would …','had','If I had more time, I would learn the piano.','Daha çok vaktim olsaydı piyano öğrenirdim.','[{"en":"If I had","tr":"olsaydı"},{"en":"more time","tr":"daha çok vakit"},{"en":"I would learn","tr":"öğrenirdim"}]'::jsonb,'2214bc16-8749-57e5-87e2-26e8445a4a26',array['Hayal']::text[],array['Koşul']::text[],'Daha çok vaktim olsaydı …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ec936d2d-399e-59df-b64b-4d316937acfd','You should … / You shouldn''t …','shouldn''t','You shouldn''t drink coffee before bed.','Yatmadan önce kahve içmemelisin.','[{"en":"You shouldn''t","tr":"-memelisin"},{"en":"drink coffee","tr":"kahve içmek"},{"en":"before bed","tr":"yatmadan önce"}]'::jsonb,'2214bc16-8749-57e5-87e2-26e8445a4a26',array['Tavsiye']::text[],array['Tavsiye']::text[],'Yatmadan önce … içmemelisin.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7c14c75e-8bb2-5646-860c-77a18e9c7cfd','Why don''t you …?','ask','Why don''t you ask for a discount?','Neden indirim istemiyorsun? (İste bence.)','[{"en":"Why don''t you","tr":"neden …mıyorsun (öneri)"},{"en":"ask for","tr":"istemek"}]'::jsonb,'2214bc16-8749-57e5-87e2-26e8445a4a26',array['Öneri']::text[],array['Samimi']::text[],'Neden … istemiyorsun?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('e2842970-3ef1-58fe-b30d-2152e70cafa6','I enjoy / I don''t mind / I can''t stand …-ing','waiting','I can''t stand waiting in queues.','Kuyrukta beklemeye hiç dayanamam.','[{"en":"I can''t stand","tr":"dayanamam"},{"en":"waiting","tr":"beklemek"},{"en":"in queues","tr":"kuyrukta"}]'::jsonb,'9294e63c-9b9d-54d4-86aa-8be64b531cc4',array['Tercih']::text[],array['Görüş']::text[],'… hiç dayanamam.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('896ef5b7-fb46-5811-b942-ce9e7e737ee3','I''d like / I want / I''ve decided to …','to','I''ve decided to change my job.','İşimi değiştirmeye karar verdim.','[{"en":"I''ve decided","tr":"karar verdim"},{"en":"to change","tr":"değiştirmeye"},{"en":"my job","tr":"işimi"}]'::jsonb,'9294e63c-9b9d-54d4-86aa-8be64b531cc4',array['Karar']::text[],array['Anlatı']::text[],'… karar verdim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('4b72b378-bb7e-5117-92e0-095a722d3071','It''s (not) worth …-ing','arguing','It''s not worth arguing about it.','Bunun hakkında tartışmaya değmez.','[{"en":"It''s not worth","tr":"değmez"},{"en":"arguing","tr":"tartışmak"}]'::jsonb,'9294e63c-9b9d-54d4-86aa-8be64b531cc4',array['Tavsiye']::text[],array['Görüş']::text[],'… değmez.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d8e68f3e-c4ea-5618-aacb-0a5eab26182a','Do you mind if I …?','open','Do you mind if I open the window?','Pencereyi açmamın sakıncası var mı?','[{"en":"Do you mind if","tr":"sakıncası var mı"},{"en":"I open","tr":"açmam"}]'::jsonb,'9294e63c-9b9d-54d4-86aa-8be64b531cc4',array['Kibar istek']::text[],array['Kibar']::text[],'… sakıncası var mı?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c5e72d28-1ff1-58c7-89b7-483f4e2f1c6a','… unless you …','unless','The shop won''t give you a refund unless you have the receipt.','Fişin yoksa mağaza para iadesi yapmaz.','[{"en":"won''t give you a refund","tr":"iade yapmaz"},{"en":"unless you have","tr":"yoksa"},{"en":"the receipt","tr":"fiş"}]'::jsonb,'2214bc16-8749-57e5-87e2-26e8445a4a26',array['Alışveriş']::text[],array['Koşul']::text[],'… mağaza para iadesi yapmaz.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7baac3dd-66ec-5176-9171-972b89e2d443','Have you ever …?','tried','Have you ever tried Korean food?','Hiç Kore yemeği denedin mi?','[{"en":"Have you ever","tr":"hiç …dın mı"},{"en":"tried","tr":"denemek (üçüncü hâl)"}]'::jsonb,'52bfdbf9-22a5-57aa-9839-36003347bc22',array['Sohbet']::text[],array['Soru']::text[],'Hiç … denedin mi?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('2ed30dfa-9eef-59a8-a781-5007347aa6d2','I''ve never … before.','seen','I''ve never seen snow before.','Daha önce hiç kar görmedim.','[{"en":"I''ve never","tr":"hiç …madım"},{"en":"seen","tr":"görmek (üçüncü hâl)"},{"en":"before","tr":"daha önce"}]'::jsonb,'52bfdbf9-22a5-57aa-9839-36003347bc22',array['Deneyim']::text[],array['Anlatı']::text[],'Daha önce hiç … görmedim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('db498171-22d2-5844-bbff-65ce7b56a578','I''ve been … for …','been','I''ve been a nurse for six years.','Altı yıldır hemşireyim.','[{"en":"I''ve been","tr":"…dır …im"},{"en":"a nurse","tr":"hemşire"},{"en":"for six years","tr":"altı yıldır"}]'::jsonb,'32dc1ac6-61b6-544e-8ac6-a6ced743f78f',array['Meslek']::text[],array['Anlatı']::text[],'… yıldır hemşireyim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('e7418ea9-7932-58d8-abc9-88a46620ba23','How long have you …?','worked','How long have you worked here?','Ne zamandır burada çalışıyorsun?','[{"en":"How long","tr":"ne zamandır"},{"en":"have you worked","tr":"çalışıyorsun"},{"en":"here","tr":"burada"}]'::jsonb,'32dc1ac6-61b6-544e-8ac6-a6ced743f78f',array['Sohbet']::text[],array['Soru']::text[],'Ne zamandır …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('777f65f6-7fac-5753-8c4d-ca392acb38a9','I haven''t … yet.','decided','I haven''t decided yet.','Henüz karar vermedim.','[{"en":"I haven''t decided","tr":"karar vermedim"},{"en":"yet","tr":"henüz"}]'::jsonb,'52bfdbf9-22a5-57aa-9839-36003347bc22',array['Durum']::text[],array['Olumsuz']::text[],'Henüz …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('bad900b7-8b9d-54ff-adb9-c49a29384d81','I''ve just …','sent','I''ve just sent you the file.','Dosyayı sana az önce gönderdim.','[{"en":"I''ve just sent","tr":"az önce gönderdim"},{"en":"you the file","tr":"sana dosyayı"}]'::jsonb,'52bfdbf9-22a5-57aa-9839-36003347bc22',array['İş']::text[],array['Günlük']::text[],'… sana az önce gönderdim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('29461043-62d7-5cae-8a1e-f150b6d00b30','… since I was …','was','I''ve played the guitar since I was twelve.','On iki yaşımdan beri gitar çalıyorum.','[{"en":"I''ve played","tr":"çalıyorum (o zamandan beri)"},{"en":"since I was twelve","tr":"on iki yaşımdan beri"}]'::jsonb,'32dc1ac6-61b6-544e-8ac6-a6ced743f78f',array['Anlatı']::text[],array['Anlatı']::text[],'… beri gitar çalıyorum.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('fdda8de9-f4f1-5238-87ee-1ffb14270a4f','I''ve been to … . I went there in …','went','I''ve been to Rome. I went there in 2022.','Roma''ya gittim; 2022''de gitmiştim.','[{"en":"I''ve been to","tr":"(hayatımda) gittim"},{"en":"I went there","tr":"oraya gittim"},{"en":"in 2022","tr":"2022''de"}]'::jsonb,'52bfdbf9-22a5-57aa-9839-36003347bc22',array['Deneyim']::text[],array['Anlatı']::text[],'… gittim; 2022''de gitmiştim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('730b3de6-1377-590d-b748-11a1995c5db4','It''s the first time I''ve …','driven','It''s the first time I''ve driven on the left.','Soldan ilk kez araba kullanıyorum.','[{"en":"It''s the first time","tr":"ilk kez"},{"en":"I''ve driven","tr":"araba kullandım"}]'::jsonb,'52bfdbf9-22a5-57aa-9839-36003347bc22',array['Deneyim']::text[],array['Anlatı']::text[],'… ilk kez araba kullanıyorum.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('adf994d1-8b9f-5307-8023-fa78f627cf02','… has changed a lot since …','changed','My life has changed a lot since I moved.','Taşındığımdan beri hayatım çok değişti.','[{"en":"My life has changed","tr":"hayatım değişti"},{"en":"a lot","tr":"çok"},{"en":"since I moved","tr":"taşındığımdan beri"}]'::jsonb,'32dc1ac6-61b6-544e-8ac6-a6ced743f78f',array['Değişim']::text[],array['Anlatı']::text[],'… beri hayatım çok değişti.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('90bb72e7-ac7d-5495-964a-a833fbd88ec7','… is the person who …','who','She''s the colleague who helped me with the project.','Projede bana yardım eden iş arkadaşı o.','[{"en":"the colleague","tr":"iş arkadaşı"},{"en":"who helped me","tr":"bana yardım eden"}]'::jsonb,'9623a8a9-63c9-5443-82e7-dab3ac22d3e5',array['Tanımlama']::text[],array['Nötr']::text[],'… iş arkadaşı o.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('58e64e15-65b7-5ca7-b44a-ea2552487af7','…, which …, …','which','The report, which was published yesterday, shows a rise in prices.','Dün yayımlanan rapor fiyatlarda bir artış gösteriyor.','[{"en":"The report,","tr":"rapor"},{"en":"which was published yesterday,","tr":"dün yayımlanan"}]'::jsonb,'9623a8a9-63c9-5443-82e7-dab3ac22d3e5',array['Bilgi verme']::text[],array['Resmî']::text[],'Dün yayımlanan rapor …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7b680876-d5a1-59cf-8c7a-541e824d038d','Although …, …','didn''t','Although he trained hard, he didn''t win the race.','Çok çalışmasına rağmen yarışı kazanamadı.','[{"en":"Although he trained hard","tr":"çok çalışmasına rağmen"},{"en":"he didn''t win","tr":"kazanamadı"}]'::jsonb,'5224c758-4a8e-52fd-a3d8-b2a48a3af0be',array['Anlatı']::text[],array['Nötr']::text[],'… rağmen yarışı kazanamadı.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7d873b62-d2da-54fa-8a39-458acb9db02e','Despite …-ing / Despite the …, …','having','Despite having little money, they travelled a lot.','Az paraları olmasına rağmen çok seyahat ettiler.','[{"en":"Despite having","tr":"-mesine rağmen"},{"en":"little money","tr":"az para"}]'::jsonb,'5224c758-4a8e-52fd-a3d8-b2a48a3af0be',array['Anlatı']::text[],array['Nötr']::text[],'… rağmen çok seyahat ettiler.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('719e9c43-5f82-5c7f-8112-93c8281d0016','I see your point, but …','point','I see your point, but I think it''s too risky.','Ne demek istediğini anlıyorum ama bence çok riskli.','[{"en":"I see your point","tr":"ne demek istediğini anlıyorum"},{"en":"but I think","tr":"ama bence"}]'::jsonb,'5224c758-4a8e-52fd-a3d8-b2a48a3af0be',array['Tartışma']::text[],array['Kibar']::text[],'Ne demek istediğini anlıyorum ama bence …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('4af2675d-81fb-541c-ab2b-6c5328fb0d31','One reason for this is that …','reason','One reason for this is that rents are rising.','Bunun bir nedeni kiraların artması.','[{"en":"One reason for this","tr":"bunun bir nedeni"},{"en":"is that","tr":"-dır ki"}]'::jsonb,'5224c758-4a8e-52fd-a3d8-b2a48a3af0be',array['Akademik yazı']::text[],array['Resmî']::text[],'Bunun bir nedeni …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a4b3782f-b12e-5e35-a3ad-7fd0058dc732','… the place where …','where','This is the café where we first met.','İlk tanıştığımız kafe burası.','[{"en":"the café","tr":"kafe"},{"en":"where we first met","tr":"ilk tanıştığımız"}]'::jsonb,'9623a8a9-63c9-5443-82e7-dab3ac22d3e5',array['Tanımlama']::text[],array['Anlatı']::text[],'… kafe burası.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c2d5f7f6-d161-5439-852f-4357d273df96','… whose … is/was …','whose','I met a man whose brother works at NASA.','Kardeşi NASA''da çalışan bir adamla tanıştım.','[{"en":"a man","tr":"bir adam"},{"en":"whose brother","tr":"kardeşi"}]'::jsonb,'9623a8a9-63c9-5443-82e7-dab3ac22d3e5',array['Anlatı']::text[],array['Nötr']::text[],'… bir adamla tanıştım.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('2f1d50ef-6578-5d25-b8ae-798bc102112c','While some people …, others …','others','While some people prefer cities, others would rather live in the countryside.','Bazı insanlar şehirleri tercih ederken, diğerleri kırsalda yaşamayı yeğler.','[{"en":"While some people","tr":"bazı insanlar …ken"},{"en":"others would rather","tr":"diğerleri … yeğler"}]'::jsonb,'5224c758-4a8e-52fd-a3d8-b2a48a3af0be',array['Akademik yazı']::text[],array['Resmî']::text[],'Bazı insanlar … diğerleri kırsalda yaşamayı yeğler.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a49edd97-505a-5b20-a525-9fecc2c85c84','It depends on whether …','on','It depends on whether we get the funding.','Fonu alıp almamamıza bağlı.','[{"en":"It depends on","tr":"-e bağlı"},{"en":"whether we get","tr":"alıp almamamız"}]'::jsonb,'5224c758-4a8e-52fd-a3d8-b2a48a3af0be',array['Tartışma']::text[],array['Nötr']::text[],'… bağlı.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('22795964-b327-53d5-975f-51efc0a119ab','If I had …, I would have …','caught','If I had left earlier, I would have caught the train.','Daha erken çıksaydım trene yetişirdim.','[{"en":"If I had left","tr":"çıksaydım"},{"en":"I would have caught","tr":"yetişirdim"}]'::jsonb,'835b44c9-28c4-54d9-ae43-5e5a34bb98b4',array['Pişmanlık']::text[],array['Koşul']::text[],'Daha erken çıksaydım …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d4e0dbe7-30d8-5a2d-b796-70b5847177be','If you hadn''t …, we wouldn''t have …','hadn''t','If you hadn''t helped me, I wouldn''t have finished on time.','Bana yardım etmeseydin zamanında bitiremezdim.','[{"en":"If you hadn''t helped","tr":"yardım etmeseydin"},{"en":"I wouldn''t have finished","tr":"bitiremezdim"}]'::jsonb,'835b44c9-28c4-54d9-ae43-5e5a34bb98b4',array['Teşekkür']::text[],array['Koşul']::text[],'Bana yardım etmeseydin …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('282ced64-499d-590e-807f-c09ca48c169d','I wish I had …','had','I wish I had brought my camera.','Keşke fotoğraf makinemi getirseydim.','[{"en":"I wish","tr":"keşke"},{"en":"I had brought","tr":"getirseydim"}]'::jsonb,'835b44c9-28c4-54d9-ae43-5e5a34bb98b4',array['Pişmanlık']::text[],array['Duygu']::text[],'Keşke … getirseydim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('5baa9803-6abf-5eba-881e-b38961657e91','I wish I could …','could','I wish I could speak Italian.','Keşke İtalyanca konuşabilsem.','[{"en":"I wish","tr":"keşke"},{"en":"I could speak","tr":"konuşabilsem"}]'::jsonb,'835b44c9-28c4-54d9-ae43-5e5a34bb98b4',array['Hayal']::text[],array['Duygu']::text[],'Keşke … konuşabilsem.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7fe20e37-e297-55af-b61b-4ae30eb37cf0','You should have …','booked','You should have booked the tickets earlier.','Biletleri daha önce ayırtmalıydın.','[{"en":"You should have booked","tr":"ayırtmalıydın"},{"en":"earlier","tr":"daha önce"}]'::jsonb,'b07f4ba5-302b-5172-a1d0-605568bf693e',array['Eleştiri']::text[],array['Doğrudan']::text[],'… daha önce ayırtmalıydın.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d28482de-aea1-582a-8c5e-ef7a14e61152','It must have been …','been','It must have been a difficult decision.','Zor bir karar olmuş olmalı.','[{"en":"It must have been","tr":"olmuş olmalı"},{"en":"a difficult decision","tr":"zor bir karar"}]'::jsonb,'b07f4ba5-302b-5172-a1d0-605568bf693e',array['Empati']::text[],array['Kibar']::text[],'… olmuş olmalı.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('92a1b183-ed5b-5cec-9b80-5c5047f84abe','He might / could have …','left','He might have left his phone at home.','Telefonunu evde bırakmış olabilir.','[{"en":"He might have left","tr":"bırakmış olabilir"},{"en":"at home","tr":"evde"}]'::jsonb,'b07f4ba5-302b-5172-a1d0-605568bf693e',array['Tahmin']::text[],array['Nötr']::text[],'… evde bırakmış olabilir.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('8d6b642f-1a61-5aaf-95c1-fe1df4a8c152','I wouldn''t have … if I''d known …','known','I wouldn''t have come if I''d known it was so expensive.','Bu kadar pahalı olduğunu bilseydim gelmezdim.','[{"en":"I wouldn''t have come","tr":"gelmezdim"},{"en":"if I''d known","tr":"bilseydim"}]'::jsonb,'835b44c9-28c4-54d9-ae43-5e5a34bb98b4',array['Pişmanlık']::text[],array['Koşul']::text[],'… bilseydim gelmezdim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('8cfc893c-63a1-55b4-a971-b283e840b4b6','It turned out that …','turned out','It turned out that the shop was closed on Sundays.','Dükkânın pazarları kapalı olduğu ortaya çıktı.','[{"en":"It turned out","tr":"ortaya çıktı"},{"en":"that the shop was closed","tr":"dükkânın kapalı olduğu"}]'::jsonb,'b07f4ba5-302b-5172-a1d0-605568bf693e',array['Anlatı']::text[],array['Anlatı']::text[],'… ortaya çıktı.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7eeb0ff9-b7b3-5151-8a71-b98817d3a7bc','I''m sorry I didn''t … / I should have …','call','I''m sorry I didn''t call you back.','Seni geri aramadığım için üzgünüm.','[{"en":"I''m sorry","tr":"üzgünüm"},{"en":"I didn''t call you back","tr":"seni geri aramadım"}]'::jsonb,'b07f4ba5-302b-5172-a1d0-605568bf693e',array['Özür']::text[],array['Kibar']::text[],'… için üzgünüm.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c8eed8b6-7297-5f3f-aa2f-122cfcea52b1','It could be argued that …','argued','It could be argued that social media increases loneliness.','Sosyal medyanın yalnızlığı artırdığı ileri sürülebilir.','[{"en":"It could be argued","tr":"ileri sürülebilir"},{"en":"that …","tr":"-diği"}]'::jsonb,'4f33dbbc-f273-5e38-9c3a-0a544c9fe9a6',array['Akademik yazı']::text[],array['Temkinli']::text[],'… ileri sürülebilir.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('39a32160-e365-5fa4-a08f-62e4c647e0cc','… appears to …','appears','The treatment appears to reduce symptoms.','Tedavinin belirtileri azalttığı görülüyor.','[{"en":"The treatment appears","tr":"tedavinin … görülüyor"},{"en":"to reduce symptoms","tr":"belirtileri azalttığı"}]'::jsonb,'4f33dbbc-f273-5e38-9c3a-0a544c9fe9a6',array['Akademik yazı']::text[],array['Temkinli']::text[],'Tedavinin … görülüyor.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ef639511-6038-5815-a5af-65bad8e8f28a','… is thought / believed to …','thought','The painting is thought to be over 500 years old.','Tablonun 500 yıldan daha eski olduğu düşünülüyor.','[{"en":"The painting is thought","tr":"tablonun … düşünülüyor"},{"en":"to be","tr":"olduğu"}]'::jsonb,'4f33dbbc-f273-5e38-9c3a-0a544c9fe9a6',array['Bilgi verme']::text[],array['Resmî']::text[],'Tablonun … olduğu düşünülüyor.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('05afb6d2-9a51-5626-862c-b52260e94f7d','There is (growing) evidence that …','evidence','There is growing evidence that exercise improves memory.','Egzersizin hafızayı geliştirdiğine dair giderek artan kanıtlar var.','[{"en":"There is growing evidence","tr":"giderek artan kanıtlar var"},{"en":"that exercise improves","tr":"egzersizin geliştirdiğine"}]'::jsonb,'4f33dbbc-f273-5e38-9c3a-0a544c9fe9a6',array['Akademik yazı']::text[],array['Resmî']::text[],'… dair giderek artan kanıtlar var.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6b1803c4-0862-5d0a-877a-85bad5b7138e','The results suggest that …','suggest','The results suggest that the method is effective.','Sonuçlar yöntemin etkili olduğunu düşündürüyor.','[{"en":"The results suggest","tr":"sonuçlar düşündürüyor"},{"en":"that the method is effective","tr":"yöntemin etkili olduğunu"}]'::jsonb,'4f33dbbc-f273-5e38-9c3a-0a544c9fe9a6',array['Akademik yazı']::text[],array['Temkinli']::text[],'Sonuçlar … düşündürüyor.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('20b3f766-2c5c-5798-9aef-c8671682920a','The … in … has led to …','increase','The increase in rents has led to a housing crisis.','Kiralardaki artış bir konut krizine yol açtı.','[{"en":"The increase in rents","tr":"kiralardaki artış"},{"en":"has led to","tr":"yol açtı"},{"en":"a housing crisis","tr":"bir konut krizi"}]'::jsonb,'86d19096-36e9-58cb-a165-059d7bff5d47',array['Akademik yazı']::text[],array['Resmî']::text[],'Kiralardaki … bir konut krizine yol açtı.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c680f651-8a19-5b6c-a523-93617b8455b1','Due to the … of …, …','lack','Due to the lack of funding, the project was cancelled.','Fon eksikliği nedeniyle proje iptal edildi.','[{"en":"Due to the lack of","tr":"… eksikliği nedeniyle"},{"en":"the project was cancelled","tr":"proje iptal edildi"}]'::jsonb,'86d19096-36e9-58cb-a165-059d7bff5d47',array['Rapor']::text[],array['Resmî']::text[],'… nedeniyle proje iptal edildi.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('fc0c8619-4205-56af-a815-f52b9dddae43','To a large extent, …','extent','To a large extent, success depends on preparation.','Başarı büyük ölçüde hazırlığa bağlıdır.','[{"en":"To a large extent","tr":"büyük ölçüde"},{"en":"depends on","tr":"-e bağlıdır"}]'::jsonb,'4f33dbbc-f273-5e38-9c3a-0a544c9fe9a6',array['Akademik yazı']::text[],array['Temkinli']::text[],'… büyük ölçüde hazırlığa bağlıdır.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('01a592c9-902c-5d01-9409-9a796e72c5b9','This may be due to …','due','This may be due to differences in sample size.','Bu, örneklem büyüklüğündeki farklardan kaynaklanıyor olabilir.','[{"en":"This may be due to","tr":"bundan kaynaklanıyor olabilir"},{"en":"differences in","tr":"-deki farklar"}]'::jsonb,'4f33dbbc-f273-5e38-9c3a-0a544c9fe9a6',array['Tartışma bölümü']::text[],array['Temkinli']::text[],'Bu, … kaynaklanıyor olabilir.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('189599bf-7f6e-59cc-9d65-4cad1cbcdbdd','With regard to …, …','regard','With regard to your request, we will reply within five days.','Talebinizle ilgili olarak beş gün içinde dönüş yapacağız.','[{"en":"With regard to","tr":"ile ilgili olarak"},{"en":"we will reply","tr":"dönüş yapacağız"}]'::jsonb,'86d19096-36e9-58cb-a165-059d7bff5d47',array['Resmî yazışma']::text[],array['Resmî']::text[],'… ilgili olarak beş gün içinde dönüş yapacağız.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a69ee99c-5240-5bcb-91d2-9b1d30f391c7','Not only did …, but … also …','did','Not only did she win the race, but she also broke the record.','Yalnızca yarışı kazanmakla kalmadı, rekoru da kırdı.','[{"en":"Not only did she win","tr":"yalnızca kazanmakla kalmadı"},{"en":"but she also broke","tr":"aynı zamanda kırdı"}]'::jsonb,'9f62770b-0dcb-581e-914e-3aefa3f2b7b3',array['Vurgu']::text[],array['Resmî']::text[],'Yalnızca … kalmadı, rekoru da kırdı.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c73fc50d-d15d-58c4-a48b-07902073e2d0','Rarely have I …','have','Rarely have I met someone so generous.','Bu kadar cömert biriyle nadiren karşılaştım.','[{"en":"Rarely have I","tr":"nadiren …dım"},{"en":"met someone so generous","tr":"bu kadar cömert biriyle karşılaşmak"}]'::jsonb,'9f62770b-0dcb-581e-914e-3aefa3f2b7b3',array['Vurgu']::text[],array['Edebî']::text[],'… nadiren karşılaştım.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('90ccaac0-f9ba-59f2-8f4f-a010cb632878','Hardly had … when …','had','Hardly had we sat down when the fire alarm went off.','Daha yeni oturmuştuk ki yangın alarmı çaldı.','[{"en":"Hardly had we sat down","tr":"daha yeni oturmuştuk"},{"en":"when","tr":"ki"}]'::jsonb,'9f62770b-0dcb-581e-914e-3aefa3f2b7b3',array['Anlatı']::text[],array['Edebî']::text[],'Daha yeni oturmuştuk ki …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a6fa905a-b6a6-5764-9990-4e5e96b5cfa4','Under no circumstances should …','should','Under no circumstances should you share your password.','Şifreni hiçbir koşulda paylaşmamalısın.','[{"en":"Under no circumstances","tr":"hiçbir koşulda"},{"en":"should you share","tr":"paylaşmalısın (devrik)"}]'::jsonb,'9f62770b-0dcb-581e-914e-3aefa3f2b7b3',array['Uyarı']::text[],array['Resmî']::text[],'… hiçbir koşulda paylaşmamalısın.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d211ace8-e956-5a30-8c6c-d507d89487b0','What I need is …','What','What I need is a few days off.','Benim ihtiyacım olan birkaç gün izin.','[{"en":"What I need","tr":"ihtiyacım olan şey"},{"en":"is a few days off","tr":"birkaç gün izin"}]'::jsonb,'d7797f43-8a0d-5854-9018-e5f916b89b22',array['Vurgu']::text[],array['Doğrudan']::text[],'Benim ihtiyacım olan …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('949f743f-824d-585c-868b-12453c74f9a5','It was … who/that …','who','It was my grandmother who taught me to cook.','Bana yemek yapmayı öğreten babaannemdi.','[{"en":"It was my grandmother","tr":"(o kişi) babaannemdi"},{"en":"who taught me","tr":"bana öğreten"}]'::jsonb,'d7797f43-8a0d-5854-9018-e5f916b89b22',array['Vurgu']::text[],array['Anlatı']::text[],'Bana yemek yapmayı öğreten …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('1702396c-c09a-59f3-b915-e582d7d399c0','What surprised me most was …','was','What surprised me most was how friendly people were.','Beni en çok şaşırtan, insanların ne kadar cana yakın olduğuydu.','[{"en":"What surprised me most","tr":"beni en çok şaşırtan"},{"en":"was how friendly","tr":"ne kadar cana yakın olduğuydu"}]'::jsonb,'d7797f43-8a0d-5854-9018-e5f916b89b22',array['Anlatı']::text[],array['Anlatı']::text[],'Beni en çok şaşırtan …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('04e6ea82-6430-5d29-b12c-9ca64d72bcce','The reason why … is that …','that','The reason why I left is that I wanted a new challenge.','Ayrılmamın nedeni yeni bir meydan okuma istememdi.','[{"en":"The reason why I left","tr":"ayrılmamın nedeni"},{"en":"is that","tr":"şudur ki"}]'::jsonb,'d7797f43-8a0d-5854-9018-e5f916b89b22',array['Açıklama']::text[],array['Resmî']::text[],'Ayrılmamın nedeni …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a7b68fdc-a0e1-5285-a98f-df5a00d848a1','Only then did … realise …','did','Only then did I realise how serious it was.','Ancak o zaman durumun ne kadar ciddi olduğunu fark ettim.','[{"en":"Only then","tr":"ancak o zaman"},{"en":"did I realise","tr":"fark ettim (devrik)"}]'::jsonb,'9f62770b-0dcb-581e-914e-3aefa3f2b7b3',array['Anlatı']::text[],array['Edebî']::text[],'Ancak o zaman … fark ettim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c089afc3-c40f-59be-a049-140a69dd51d6','All I want is …','is','All I want is a quiet weekend.','Tek istediğim sakin bir hafta sonu.','[{"en":"All I want","tr":"tek istediğim"},{"en":"is a quiet weekend","tr":"sakin bir hafta sonu"}]'::jsonb,'d7797f43-8a0d-5854-9018-e5f916b89b22',array['Vurgu']::text[],array['Günlük']::text[],'Tek istediğim …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('1be8a999-a3df-5079-bb2c-a415bf487740','I suggest (that) he …','be','I suggest that he be informed immediately.','Ona hemen haber verilmesini öneririm.','[{"en":"I suggest that","tr":"-mesini öneririm"},{"en":"he be informed","tr":"ona haber verilmesi"}]'::jsonb,'6af81054-a0b7-596b-8426-6497c8119c3b',array['Resmî öneri']::text[],array['Çok resmî']::text[],'… hemen haber verilmesini öneririm.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('510defc9-a2e2-5c53-aa48-ef3b00395a65','It is essential that … (base form)','submit','It is essential that every applicant submit the form by Friday.','Her başvuru sahibinin formu cumaya kadar teslim etmesi şart.','[{"en":"It is essential that","tr":"-mesi şart"},{"en":"every applicant submit","tr":"her başvuru sahibinin teslim etmesi"}]'::jsonb,'6af81054-a0b7-596b-8426-6497c8119c3b',array['Resmî yazı']::text[],array['Çok resmî']::text[],'Her başvuru sahibinin … şart.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('66122045-a49b-52b5-ad1c-fe7772258871','If I had …, I would be … now.','would','If I had taken that job, I would be living in Berlin now.','O işi kabul etseydim şimdi Berlin''de yaşıyor olurdum.','[{"en":"If I had taken","tr":"kabul etseydim (geçmiş)"},{"en":"I would be living","tr":"yaşıyor olurdum (şimdi)"}]'::jsonb,'6f90d51f-94ad-5c44-a700-7f119b87a9a9',array['Pişmanlık']::text[],array['Koşul']::text[],'O işi kabul etseydim şimdi … olurdum.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ad99c134-56ab-5045-9ad1-93c1fd21552d','If I were …, I would have …','were','If I were more organised, I wouldn''t have missed the deadline.','Daha düzenli biri olsaydım son teslim tarihini kaçırmazdım.','[{"en":"If I were more organised","tr":"daha düzenli olsaydım (genel özellik)"},{"en":"I wouldn''t have missed","tr":"kaçırmazdım (geçmiş)"}]'::jsonb,'6f90d51f-94ad-5c44-a700-7f119b87a9a9',array['Öz değerlendirme']::text[],array['Koşul']::text[],'Daha … biri olsaydım son teslim tarihini kaçırmazdım.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('1a943ab9-7846-5fb5-b69f-9e3e5ef82a46','It''s (high) time we …','started','It''s high time we started taking this seriously.','Bunu ciddiye almaya başlamamızın vakti çoktan geldi.','[{"en":"It''s high time","tr":"vakti çoktan geldi"},{"en":"we started","tr":"başlamamızın"}]'::jsonb,'6af81054-a0b7-596b-8426-6497c8119c3b',array['Eleştiri']::text[],array['Vurgulu']::text[],'… vakti çoktan geldi.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('09d4fac5-e26a-53e6-92e1-1ed6ece572ce','I''d rather you didn''t …','didn''t','I''d rather you didn''t mention it to anyone.','Bunu kimseye söylemesen daha iyi olur.','[{"en":"I''d rather","tr":"tercih ederim"},{"en":"you didn''t mention","tr":"söylemesen"}]'::jsonb,'6af81054-a0b7-596b-8426-6497c8119c3b',array['Kibar ricalar']::text[],array['Kibar']::text[],'… daha iyi olur.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f2209d93-4918-5dd5-bf5d-26e836582ba4','… as if/though …','were','He talks as if he were the boss.','Sanki patronmuş gibi konuşuyor.','[{"en":"He talks","tr":"konuşuyor"},{"en":"as if he were","tr":"sanki …mış gibi"}]'::jsonb,'6af81054-a0b7-596b-8426-6497c8119c3b',array['Tanımlama']::text[],array['Eleştirel']::text[],'Sanki … gibi konuşuyor.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('28d4dce2-74af-58b5-af12-a51939b097b3','Were it not for …, …','would','Were it not for your help, we would never have finished.','Senin yardımın olmasaydı asla bitiremezdik.','[{"en":"Were it not for","tr":"… olmasaydı (devrik if)"},{"en":"we would never have finished","tr":"asla bitiremezdik"}]'::jsonb,'6f90d51f-94ad-5c44-a700-7f119b87a9a9',array['Teşekkür']::text[],array['Resmî']::text[],'… olmasaydı asla bitiremezdik.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0b7abdf1-9251-5084-be36-420ada636427','Should you need …, please …','need','Should you need any further information, please contact us.','Daha fazla bilgiye ihtiyaç duyarsanız lütfen bize ulaşın.','[{"en":"Should you need","tr":"ihtiyaç duyarsanız (devrik if)"},{"en":"please contact us","tr":"lütfen bize ulaşın"}]'::jsonb,'6f90d51f-94ad-5c44-a700-7f119b87a9a9',array['Resmî e-posta']::text[],array['Çok resmî']::text[],'… ihtiyaç duyarsanız lütfen bize ulaşın.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('16accb3d-c76e-5322-8e04-bafb2b5b2e5e','Be that as it may, …','may','Be that as it may, we still need a decision today.','Her ne olursa olsun, bugün yine de bir karar vermemiz gerekiyor.','[{"en":"Be that as it may","tr":"her ne olursa olsun"},{"en":"we still need","tr":"yine de gerekiyor"}]'::jsonb,'6af81054-a0b7-596b-8426-6497c8119c3b',array['Tartışma']::text[],array['Resmî']::text[],'Her ne olursa olsun, …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ca835138-4986-5c8a-9916-49c8558fd275','Having …, he/she …','finished','Having finished her degree, she moved to Lisbon.','Diplomasını aldıktan sonra Lizbon''a taşındı.','[{"en":"Having finished","tr":"bitirdikten sonra"},{"en":"she moved","tr":"taşındı"}]'::jsonb,'0eef7c35-4a46-5f40-a760-72ae36798851',array['Anlatı']::text[],array['Edebî']::text[],'… sonra Lizbon''a taşındı.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ea065b11-fb3f-54fc-85dd-dcdb972a54d0','Not knowing …, I …','knowing','Not knowing what to say, I just smiled.','Ne diyeceğimi bilemeyince sadece gülümsedim.','[{"en":"Not knowing","tr":"bilmediğim için"},{"en":"I just smiled","tr":"sadece gülümsedim"}]'::jsonb,'0eef7c35-4a46-5f40-a760-72ae36798851',array['Anlatı']::text[],array['Edebî']::text[],'… sadece gülümsedim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('90b9082e-03c9-5f8f-b99d-6cc5b063733e','… in …, the … is …','Built','Built in 1890, the bridge is still in use.','1890''da inşa edilen köprü hâlâ kullanılıyor.','[{"en":"Built in 1890","tr":"1890''da inşa edilen"},{"en":"the bridge is still in use","tr":"köprü hâlâ kullanılıyor"}]'::jsonb,'0eef7c35-4a46-5f40-a760-72ae36798851',array['Bilgi verme']::text[],array['Resmî']::text[],'… inşa edilen köprü hâlâ kullanılıyor.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('dd6a66e5-0305-588f-abb5-0594383d009e','Given the …, it''s not surprising that …','circumstances','Given the circumstances, it''s not surprising that he resigned.','Koşullar göz önüne alındığında istifa etmesi şaşırtıcı değil.','[{"en":"Given the circumstances","tr":"koşullar göz önüne alındığında"},{"en":"it''s not surprising","tr":"şaşırtıcı değil"}]'::jsonb,'0eef7c35-4a46-5f40-a760-72ae36798851',array['Yorum']::text[],array['Resmî']::text[],'… göz önüne alındığında istifa etmesi şaşırtıcı değil.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f6771a08-96e6-55c2-9320-2643b478e822','I hope so. / I''m afraid not.','not','Will it rain tomorrow? — I hope not.','Yarın yağmur yağacak mı? — Umarım yağmaz.','[{"en":"I hope not","tr":"umarım …mez"},{"en":"I hope so","tr":"umarım öyledir"}]'::jsonb,'412fcdc3-d793-518b-8bf2-721123a56fa3',array['Konuşma']::text[],array['Doğal']::text[],'Umarım …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('abf10222-dcc5-5184-b402-35a3d29a0f10','… if you wish to do so.','so','You may cancel your membership if you wish to do so.','Dilerseniz üyeliğinizi iptal edebilirsiniz.','[{"en":"if you wish","tr":"dilerseniz"},{"en":"to do so","tr":"bunu yapmak"}]'::jsonb,'412fcdc3-d793-518b-8bf2-721123a56fa3',array['Resmî yazı']::text[],array['Resmî']::text[],'Dilerseniz …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('03c0f515-2241-519f-bd92-eea764f99218','… the former …, the latter …','former','Tea and coffee are both popular; the former is cheaper, the latter stronger.','Çay ve kahve ikisi de popüler; ilki daha ucuz, ikincisi daha sert.','[{"en":"the former","tr":"ilki (önce anılan)"},{"en":"the latter","tr":"ikincisi (sonra anılan)"}]'::jsonb,'412fcdc3-d793-518b-8bf2-721123a56fa3',array['Akademik yazı']::text[],array['Resmî']::text[],'Çay ve kahve ikisi de popüler; ilki daha …, ikincisi daha sert.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6695b853-7528-57a4-8365-a980596ac09e','…, as did … / … and so did …','did','She voted against the plan, as did most of her colleagues.','Plana karşı oy verdi; meslektaşlarının çoğu da öyle yaptı.','[{"en":"as did","tr":"… da öyle yaptı (devrik)"},{"en":"most of her colleagues","tr":"meslektaşlarının çoğu"}]'::jsonb,'412fcdc3-d793-518b-8bf2-721123a56fa3',array['Anlatı']::text[],array['Resmî']::text[],'Plana karşı oy verdi; … öyle yaptı.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a16f0b34-8f62-56ca-85d7-33766a0feecd','What with … and …, …','with','What with the traffic and the rain, we arrived an hour late.','Trafik de yağmur da derken bir saat geç vardık.','[{"en":"What with … and …","tr":"… de … de derken"},{"en":"we arrived late","tr":"geç vardık"}]'::jsonb,'0eef7c35-4a46-5f40-a760-72ae36798851',array['Konuşma']::text[],array['Doğal']::text[],'… derken bir saat geç vardık.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b0a12e4b-b405-5a38-a39a-85d705c79dfc','…, so much so that …','so','She loved the city, so much so that she never left.','Şehri o kadar çok sevdi ki bir daha hiç ayrılmadı.','[{"en":"so much so that","tr":"o kadar ki"},{"en":"she never left","tr":"hiç ayrılmadı"}]'::jsonb,'412fcdc3-d793-518b-8bf2-721123a56fa3',array['Anlatı']::text[],array['Vurgulu']::text[],'Şehri o kadar çok sevdi ki …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ba589ee5-bb12-52a3-af48-fc201a72cbdb','If we …, … will …','will drop','If we add a fan, the temperature will drop.','Bir fan eklersek sıcaklık düşer.','[{"en":"If we add a fan","tr":"bir fan eklersek"},{"en":"the temperature","tr":"sıcaklık"},{"en":"will drop","tr":"düşecek"}]'::jsonb,'3bf15cc6-24b0-5ade-bd72-578e2cc35706',array['Toplantı','Öneri']::text[],array['Nötr']::text[],'Şunu yaparsak sıcaklık düşer: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('2acf9154-f037-5f77-9854-1e614af5a9d7','The problem is that …','is that','The problem is that the cable is too thin.','Sorun, kablonun fazla ince olması.','[{"en":"The problem","tr":"sorun"},{"en":"is that","tr":"şu ki"},{"en":"the cable is too thin","tr":"açıklama"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Toplantı','Rapor']::text[],array['Nötr']::text[],'Sorun şu: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a0cdcdf9-0be9-565e-825f-10dbab219d2d','One option is to …','One option is','One option is to replace the bearing.','Seçeneklerden biri rulmanı değiştirmek.','[{"en":"One option is","tr":"seçeneklerden biri"},{"en":"to replace the bearing","tr":"öneri (to + fiil)"}]'::jsonb,'9279b596-fe91-567a-9d51-125884641a4b',array['Toplantı','E-posta']::text[],array['Nötr']::text[],'Seçeneklerden biri şu: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c092b83c-9db6-5cde-8b9a-9edf6fe177a5','I suggest that we …','that we','I suggest that we test it again.','Tekrar test etmemizi öneriyorum.','[{"en":"I suggest","tr":"öneriyorum"},{"en":"that we","tr":"-memizi"},{"en":"test it again","tr":"öneri (yalın fiil)"}]'::jsonb,'9279b596-fe91-567a-9d51-125884641a4b',array['Toplantı','E-posta']::text[],array['Resmî']::text[],'Şunu yapmamızı öneriyorum: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d54f574e-d3d9-5f2a-9196-663c2d4421ab','… is caused by …','caused by','The noise is caused by a loose screw.','Ses gevşek bir vidadan kaynaklanıyor.','[{"en":"The noise","tr":"ses"},{"en":"is caused by","tr":"… kaynaklanıyor"},{"en":"a loose screw","tr":"neden"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Rapor','Toplantı']::text[],array['Nötr']::text[],'Ses şundan kaynaklanıyor: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f99a5141-dcf3-5c65-8819-2a8a365b1706','To avoid …, we should …','avoid','To avoid overheating, we should add a fan.','Aşırı ısınmayı önlemek için bir fan eklemeliyiz.','[{"en":"To avoid overheating","tr":"aşırı ısınmayı önlemek için"},{"en":"we should add a fan","tr":"bir fan eklemeliyiz"}]'::jsonb,'a5f9d0fc-be42-50ae-afd1-5c3a477c4150',array['Toplantı','Öneri']::text[],array['Nötr']::text[],'Şunu önlemek için bir fan eklemeliyiz: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d6e21946-3f3d-5091-b458-1b94f937b094','The advantage of … is that …','advantage','The advantage of this design is that it''s cheaper.','Bu tasarımın avantajı daha ucuz olması.','[{"en":"The advantage of this design","tr":"bu tasarımın avantajı"},{"en":"is that","tr":"şu ki"},{"en":"it''s cheaper","tr":"gerekçe"}]'::jsonb,'456ec5da-d7b5-550b-9e0c-056b23139658',array['Toplantı','Rapor']::text[],array['Nötr']::text[],'Bu tasarımın avantajı şu: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d751f72a-6d83-55d7-9b8a-07cfb18aeb26','How long will it take to …?','take','How long will it take to fix the line?','Hattı tamir etmek ne kadar sürer?','[{"en":"How long","tr":"ne kadar"},{"en":"will it take","tr":"sürer"},{"en":"to fix the line","tr":"iş"}]'::jsonb,'4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5',array['Toplantı','Planlama']::text[],array['Nötr']::text[],'Şunu yapmak ne kadar sürer: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3dbb14ba-164b-51d7-9c3e-c55a4db89b86','We could either … or …','either','We could either repair the pump or buy a new one.','Ya pompayı tamir edebiliriz ya da yenisini alabiliriz.','[{"en":"We could either","tr":"ya … -ebiliriz"},{"en":"repair the pump","tr":"1. seçenek"},{"en":"or buy a new one","tr":"ya da yenisini almak"}]'::jsonb,'a5f9d0fc-be42-50ae-afd1-5c3a477c4150',array['Toplantı']::text[],array['Nötr']::text[],'Ya şunu yapabiliriz ya da yenisini alabiliriz: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7e03af13-cf58-5e99-b7ad-5697d1c2f6ba','For safety reasons, …','reasons','For safety reasons, wear gloves in the lab.','Güvenlik nedeniyle laboratuvarda eldiven tak.','[{"en":"For safety reasons","tr":"güvenlik nedeniyle"},{"en":"wear gloves","tr":"talimat (emir kipi)"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Güvenlik','Kılavuz']::text[],array['Resmî']::text[],'Güvenlik nedeniyle şunu yap: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f3c8fd03-f101-5295-8a23-63e4d8f0ffbe','… is …-er than …','quieter than','The new pump is quieter than the old one.','Yeni pompa eskisinden daha sessiz.','[{"en":"The new pump","tr":"yeni pompa"},{"en":"is quieter than","tr":"-den daha sessiz"},{"en":"the old one","tr":"eskisi"}]'::jsonb,'456ec5da-d7b5-550b-9e0c-056b23139658',array['Teknik toplantı','Rapor']::text[],array['Nötr']::text[],'Yeni pompa eskisinden daha ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('af4ca369-6ef5-5506-931d-9fa0f8791e30','It measures … by …','measures','The panel measures 60 by 120 cm.','Panel 60''a 120 cm boyutunda.','[{"en":"The panel","tr":"panel"},{"en":"measures","tr":"… ölçüsünde"},{"en":"60 by 120 cm","tr":"en × boy"}]'::jsonb,'d5774794-79d5-5598-b2ee-b28a68901a09',array['Teknik özellik']::text[],array['Nötr']::text[],'Panelin ölçüsü: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('eeb5321f-1d1e-5c4a-a8d9-7aca24148afb','It''s made of …','made of','The housing is made of stainless steel.','Gövde paslanmaz çelikten yapılmış.','[{"en":"The housing","tr":"gövde"},{"en":"is made of","tr":"-den yapılmış"},{"en":"stainless steel","tr":"malzeme"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Teknik özellik']::text[],array['Nötr']::text[],'Gövde şundan yapılmış: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('dc6f8a11-53b1-5c29-bb70-1b1fac6e3e47','It operates at …','operates at','The system operates at 24 volts.','Sistem 24 voltta çalışır.','[{"en":"The system","tr":"sistem"},{"en":"operates at","tr":"… değerinde çalışır"},{"en":"24 volts","tr":"değer"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Teknik özellik']::text[],array['Nötr']::text[],'Sistem şu değerde çalışır: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c2fd071c-7e52-5a0c-86a9-6c4f034e4ffd','It can … up to …','up to','The crane can lift up to two tons.','Vinç iki tona kadar kaldırabilir.','[{"en":"The crane can lift","tr":"vinç kaldırabilir"},{"en":"up to","tr":"-e kadar"},{"en":"two tons","tr":"üst sınır"}]'::jsonb,'d5774794-79d5-5598-b2ee-b28a68901a09',array['Teknik özellik']::text[],array['Nötr']::text[],'Vinç şuna kadar kaldırabilir: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('cf3a5bce-0c75-5da7-8bcd-9358b3849b1c','The difference between … is …','difference','The difference between the two readings is 0.3 mm.','İki ölçüm arasındaki fark 0,3 mm.','[{"en":"The difference","tr":"fark"},{"en":"between the two readings","tr":"iki ölçüm arasındaki"},{"en":"is 0.3 mm","tr":"değer"}]'::jsonb,'d5774794-79d5-5598-b2ee-b28a68901a09',array['Rapor','Teknik toplantı']::text[],array['Nötr']::text[],'İki ölçüm arasındaki fark: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3119a233-8316-5152-8079-c296e372bb70','The result is within …','within','The result is within the allowed range.','Sonuç izin verilen aralığın içinde.','[{"en":"The result","tr":"sonuç"},{"en":"is within","tr":"içinde"},{"en":"the allowed range","tr":"sınır"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Kalite','Rapor']::text[],array['Nötr']::text[],'Sonuç şunun içinde: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c2067317-925b-54e2-bdf0-5ab3309a6cca','… should not exceed …','exceed','The temperature should not exceed 80 °C.','Sıcaklık 80 °C''yi aşmamalı.','[{"en":"The temperature","tr":"sıcaklık"},{"en":"should not exceed","tr":"aşmamalı"},{"en":"80 °C","tr":"sınır"}]'::jsonb,'a5f9d0fc-be42-50ae-afd1-5c3a477c4150',array['Güvenlik','Kılavuz']::text[],array['Uyarı']::text[],'Sıcaklık şunu aşmamalı: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('76e80029-f9fa-5e12-b355-7139fcd77f66','Compared to …, …','Compared to','Compared to steel, aluminum is much lighter.','Çelikle karşılaştırıldığında alüminyum çok daha hafif.','[{"en":"Compared to steel","tr":"çelikle karşılaştırıldığında"},{"en":"aluminum is much lighter","tr":"alüminyum çok daha hafif"}]'::jsonb,'456ec5da-d7b5-550b-9e0c-056b23139658',array['Teknik toplantı','Rapor']::text[],array['Nötr']::text[],'Alüminyum şununla karşılaştırıldığında çok daha hafif: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a9009ae2-219b-55c0-bfc2-e8fe1c4bf3c0','According to …, …','According to','According to the datasheet, the maximum load is 5 kN.','Veri sayfasına göre azami yük 5 kN.','[{"en":"According to the datasheet","tr":"veri sayfasına göre"},{"en":"the maximum load is 5 kN","tr":"bilgi"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Rapor','Teknik toplantı']::text[],array['Resmî']::text[],'Şuna göre azami yük 5 kN: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6fe54c92-5675-53cd-9eea-9f99d5740dee','If …, the … (her zaman geçerli sonuç)','closes','If the pressure drops, the valve closes automatically.','Basınç düşerse vana otomatik olarak kapanır.','[{"en":"If the pressure drops","tr":"basınç düşerse"},{"en":"the valve closes","tr":"vana kapanır"},{"en":"automatically","tr":"otomatik olarak"}]'::jsonb,'192debd3-9082-5b07-80a0-40d56570f67c',array['Kılavuz','Teknik açıklama']::text[],array['Nötr']::text[],'… vana otomatik olarak kapanır.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a6489ca4-5daf-56fc-890b-2c4190a52611','The … was tested at …','was tested','The battery was tested at −20 °C.','Pil −20 °C''de test edildi.','[{"en":"The battery","tr":"pil"},{"en":"was tested","tr":"test edildi"},{"en":"at −20 °C","tr":"koşul"}]'::jsonb,'0e47e1be-1f21-5acc-aab3-01552452cccd',array['Test raporu']::text[],array['Resmî']::text[],'Pil şu koşulda test edildi: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('bd13d00e-0516-54bd-be51-79fdf9dff016','The results show that …','show that','The results show that the coating works well.','Sonuçlar kaplamanın iyi çalıştığını gösteriyor.','[{"en":"The results","tr":"sonuçlar"},{"en":"show that","tr":"-dığını gösteriyor"},{"en":"the coating works well","tr":"bulgu"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Test raporu','Sunum']::text[],array['Resmî']::text[],'Sonuçlar şunu gösteriyor: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a70ff061-3170-519f-8339-010505b20e66','It failed after …','after','The bearing failed after 3,000 hours.','Rulman 3.000 saat sonra arızalandı.','[{"en":"The bearing failed","tr":"rulman arızalandı"},{"en":"after 3,000 hours","tr":"3.000 saat sonra"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Test raporu']::text[],array['Nötr']::text[],'Rulman şundan sonra arızalandı: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3d193241-ffbe-5aee-a947-4a386aba93e5','There was no sign of …','sign of','There was no sign of corrosion after the test.','Testten sonra korozyon belirtisi yoktu.','[{"en":"There was no","tr":"yoktu"},{"en":"sign of corrosion","tr":"korozyon belirtisi"},{"en":"after the test","tr":"testten sonra"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Test raporu']::text[],array['Resmî']::text[],'Testten sonra şunun belirtisi yoktu: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3f6001d8-cf2f-5b9b-a059-5d18b1b70394','We need to repeat … because …','repeat','We need to repeat the test because the sensor was loose.','Sensör gevşek olduğu için testi tekrarlamamız gerekiyor.','[{"en":"We need to repeat","tr":"tekrarlamamız gerekiyor"},{"en":"the test","tr":"iş"},{"en":"because the sensor was loose","tr":"neden"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['Toplantı','Laboratuvar']::text[],array['Nötr']::text[],'Sensör gevşek olduğu için şunu tekrarlamamız gerekiyor: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7b26e8d1-0de8-5cb5-909b-1ee189f35646','… increased by …','by','The temperature increased by 15 degrees.','Sıcaklık 15 derece arttı.','[{"en":"The temperature","tr":"sıcaklık"},{"en":"increased by","tr":"… kadar arttı"},{"en":"15 degrees","tr":"artış miktarı"}]'::jsonb,'720f608f-5573-5769-bc14-e12bd1dbaa95',array['Test raporu']::text[],array['Nötr']::text[],'Sıcaklık şu kadar arttı: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7eb5be40-357b-52b7-81e9-368206d66e6c','Under … conditions, …','Under','Under normal conditions, the motor runs at 1,500 rpm.','Normal koşullar altında motor 1.500 devirde çalışır.','[{"en":"Under normal conditions","tr":"normal koşullar altında"},{"en":"the motor runs at 1,500 rpm","tr":"motor 1.500 devirde çalışır"}]'::jsonb,'192debd3-9082-5b07-80a0-40d56570f67c',array['Teknik açıklama']::text[],array['Resmî']::text[],'… motor 1.500 devirde çalışır.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('4b500344-8168-558a-b831-3df26de9c52b','We observed …','observed','We observed a small vibration at high speed.','Yüksek hızda küçük bir titreşim gözlemledik.','[{"en":"We observed","tr":"gözlemledik"},{"en":"a small vibration","tr":"gözlem"},{"en":"at high speed","tr":"koşul"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Test raporu']::text[],array['Resmî']::text[],'Şunu gözlemledik: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('1bb37809-e0e2-5532-a067-2c431433d57c','We recommend …-ing','using','We recommend using a thicker seal.','Daha kalın bir conta kullanılmasını öneriyoruz.','[{"en":"We recommend","tr":"öneriyoruz"},{"en":"using a thicker seal","tr":"öneri (-ing)"}]'::jsonb,'9279b596-fe91-567a-9d51-125884641a4b',array['Test raporu','Toplantı']::text[],array['Resmî']::text[],'Şunu öneriyoruz: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6e79395f-e354-54a4-b267-77b6e064096d','I''m going to … this weekend.','going to','I''m going to visit my parents this weekend.','Bu hafta sonu ailemi ziyaret edeceğim.','[{"en":"I''m going to","tr":"-eceğim (plan)"},{"en":"visit my parents","tr":"eylem"},{"en":"this weekend","tr":"bu hafta sonu"}]'::jsonb,'4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5',array['Sohbet','Plan yapma']::text[],array['Günlük']::text[],'Bu hafta sonu şunu yapacağım: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b8212bf2-d967-5ff8-a24c-3280572ae7fa','How about …?','about','How about going to the cinema tonight?','Bu akşam sinemaya gitmeye ne dersin?','[{"en":"How about","tr":"ne dersin"},{"en":"going to the cinema","tr":"öneri (-ing veya isim)"}]'::jsonb,'a5f9d0fc-be42-50ae-afd1-5c3a477c4150',array['Plan yapma','Davet']::text[],array['Samimi']::text[],'Şuna ne dersin: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('fa024ecc-9dd9-51c8-93aa-b7c01dafe404','Are you free on …?','on','Are you free on Friday evening?','Cuma akşamı müsait misin?','[{"en":"Are you free","tr":"müsait misin"},{"en":"on Friday evening","tr":"zaman"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Plan yapma','Davet']::text[],array['Günlük']::text[],'… müsait misin?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('70574ff3-ec1a-5ba6-99f6-a00b1d67bb86','I always … before …','before','I always check my email before work.','İşten önce her zaman e-postalarımı kontrol ederim.','[{"en":"I always","tr":"her zaman"},{"en":"check my email","tr":"eylem"},{"en":"before work","tr":"işten önce"}]'::jsonb,'7be2ff59-b822-5d17-b28c-77b5dd4bad29',array['Sohbet','Rutin']::text[],array['Günlük']::text[],'İşten önce her zaman şunu yaparım: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('53eb02b5-87d0-57be-abe9-819c977dcb23','I have to … today.','have to','I have to finish this report today.','Bu raporu bugün bitirmem gerekiyor.','[{"en":"I have to","tr":"-mem gerekiyor"},{"en":"finish this report","tr":"yapılacak iş"},{"en":"today","tr":"bugün"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['Sohbet','Mazeret']::text[],array['Günlük']::text[],'Bugün şunu yapmam gerekiyor: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('fb59a901-f0bb-539f-bdee-bca6a85c15b6','I''m meeting … tomorrow.','meeting','I''m meeting Ayşe for lunch tomorrow.','Yarın öğle yemeğinde Ayşe''yle buluşacağım.','[{"en":"I''m meeting","tr":"buluşacağım (ayarlanmış plan)"},{"en":"Ayşe for lunch","tr":"kim ve ne için"},{"en":"tomorrow","tr":"yarın"}]'::jsonb,'07f46ae3-6018-5f8f-8bda-377e874ddc92',array['Plan yapma']::text[],array['Günlük']::text[],'Yarın … buluşacağım.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('39513978-0c89-5532-9b5d-21828c93c602','Let''s meet at …','meet','Let''s meet at the café near the station.','İstasyonun yakınındaki kafede buluşalım.','[{"en":"Let''s","tr":"-elim"},{"en":"meet","tr":"buluş-"},{"en":"at the café","tr":"yer"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Plan yapma']::text[],array['Samimi']::text[],'Şurada buluşalım: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('41c61d73-b622-57a2-888c-2c31b760d66d','It takes … to get to …','takes','It takes about 40 minutes to get to work.','İşe gitmek yaklaşık 40 dakika sürüyor.','[{"en":"It takes","tr":"sürüyor"},{"en":"about 40 minutes","tr":"süre"},{"en":"to get to work","tr":"işe gitmek"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Sohbet','Rutin']::text[],array['Günlük']::text[],'İşe gitmek şu kadar sürüyor: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a2023554-3c00-56e4-90d6-f4f4861dc5d0','Sorry, I can''t make it …','make it','Sorry, I can''t make it tonight.','Kusura bakma, bu akşam gelemiyorum.','[{"en":"Sorry","tr":"kusura bakma"},{"en":"I can''t make it","tr":"gelemiyorum, yetişemiyorum"},{"en":"tonight","tr":"zaman"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['Davet','Mazeret']::text[],array['Nazik']::text[],'Kusura bakma, şu zaman gelemiyorum: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('da21158b-5c90-53fd-a2b7-ec6baedef19b','What time does … start?','does','What time does the movie start?','Film saat kaçta başlıyor?','[{"en":"What time","tr":"saat kaçta"},{"en":"does the movie start","tr":"film başlıyor"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Plan yapma']::text[],array['Günlük']::text[],'… saat kaçta başlıyor?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('acaa600b-c294-5ab3-9d83-9bdb4c9723c2','I''m a/an …','a','I''m a software developer.','Yazılım geliştiriciyim.','[{"en":"I''m","tr":"ben …-im"},{"en":"a","tr":"bir"},{"en":"software developer","tr":"meslek"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Tanışma','İş görüşmesi']::text[],array['Günlük']::text[],'Mesleğim: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b48d5d1a-1cf7-542f-b615-d0775a16cdf4','I work at …','at','I work at a bank in Kadıköy.','Kadıköy''de bir bankada çalışıyorum.','[{"en":"I work","tr":"çalışıyorum"},{"en":"at","tr":"-de"},{"en":"a bank in Kadıköy","tr":"iş yeri"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Tanışma','İş görüşmesi']::text[],array['Günlük']::text[],'Şurada çalışıyorum: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0fa081c3-6341-5e06-9514-4754fe2c5f68','I''ve lived in … for … years.','for','I''ve lived in İstanbul for five years.','Beş yıldır İstanbul''da yaşıyorum.','[{"en":"I''ve lived","tr":"yaşıyorum (geçmişten beri)"},{"en":"in İstanbul","tr":"yer"},{"en":"for five years","tr":"beş yıldır"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Tanışma']::text[],array['Günlük']::text[],'Beş yıldır şurada yaşıyorum: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c7b52092-30a2-5715-bc72-924b495469ca','I like …-ing in my free time.','reading','I like reading in my free time.','Boş zamanımda okumayı severim.','[{"en":"I like","tr":"severim"},{"en":"reading","tr":"-mayı (fiil + -ing)"},{"en":"in my free time","tr":"boş zamanımda"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Tanışma','Sohbet']::text[],array['Günlük']::text[],'Boş zamanımda şunu severim: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('8fae41bd-2fc9-59bb-a986-732080a64e13','I''m good at …','at','I''m good at solving problems.','Problem çözmekte iyiyim.','[{"en":"I''m good","tr":"iyiyim"},{"en":"at","tr":"… konusunda"},{"en":"solving problems","tr":"beceri"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Tanışma','İş görüşmesi']::text[],array['Günlük']::text[],'Şunda iyiyim: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('8b237c02-b4e2-5010-8127-09f3f95a7465','I don''t … very often.','don''t','I don''t watch TV very often.','Pek sık televizyon izlemem.','[{"en":"I don''t","tr":"-mam"},{"en":"watch TV","tr":"eylem"},{"en":"very often","tr":"çok sık"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Sohbet']::text[],array['Günlük']::text[],'Şunu pek sık yapmam: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3345c65f-14ee-5f14-96ed-d6049b88ebc2','How long have you …?','have you','How long have you lived here?','Ne zamandır burada yaşıyorsun?','[{"en":"How long","tr":"ne zamandır"},{"en":"have you","tr":"(sen) -"},{"en":"lived here","tr":"süren durum"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Tanışma','Sohbet']::text[],array['Günlük']::text[],'Ne zamandır şunu yapıyorsun: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('cd4e9a10-ee9b-590c-9122-849667c2754d','What kind of … do you like?','kind of','What kind of music do you like?','Ne tür müzik seversin?','[{"en":"What kind of","tr":"ne tür"},{"en":"music","tr":"konu"},{"en":"do you like","tr":"seversin"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Sohbet']::text[],array['Günlük']::text[],'Ne tür … seversin?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('cf27d220-fac9-5685-b12a-0b65d3b1631f','I live with …','live with','I live with my sister.','Kız kardeşimle yaşıyorum.','[{"en":"I live","tr":"yaşıyorum"},{"en":"with","tr":"ile"},{"en":"my sister","tr":"kişi"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Tanışma','Sohbet']::text[],array['Günlük']::text[],'… ile yaşıyorum.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d6c652c6-66be-51a5-8eb9-1798060ac6cb','See you …!','See you','See you on Monday!','Pazartesi görüşürüz!','[{"en":"See you","tr":"görüşürüz"},{"en":"on Monday","tr":"zaman"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Selamlaşma']::text[],array['Samimi']::text[],'… görüşürüz!','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('10d64ffe-9f09-5040-8b56-7e4a270ffba3','I''d like …, please.','like','I''d like a glass of water, please.','Bir bardak su istiyorum, lütfen.','[{"en":"I''d like","tr":"istiyorum (kibar)"},{"en":"a glass of water","tr":"istenen şey"},{"en":"please","tr":"lütfen"}]'::jsonb,'851477de-6cca-5819-9b94-be7428c7eb31',array['Restoran','Mağaza']::text[],array['Nazik']::text[],'… istiyorum, lütfen.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('727a54da-9ef5-5b2d-9394-2fdff91cf41a','Could I have …?','have','Could I have the menu, please?','Menüyü alabilir miyim, lütfen?','[{"en":"Could I","tr":"-ebilir miyim"},{"en":"have","tr":"al-"},{"en":"the menu","tr":"istenen şey"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['Restoran','Otel']::text[],array['Nazik']::text[],'Şunu alabilir miyim: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('1df442b0-c7a8-59d9-9dfd-be153e6f2fbe','Is it okay if I …?','if','Is it okay if I open the window?','Pencereyi açsam olur mu?','[{"en":"Is it okay","tr":"olur mu"},{"en":"if I","tr":"-sam"},{"en":"open the window","tr":"eylem"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['İzin isteme']::text[],array['Nazik']::text[],'Şunu yapsam olur mu: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7beabc93-c6b3-5b6c-9027-6cec8ebddde9','There''s a problem with …','with','There''s a problem with my room key.','Oda anahtarımda bir sorun var.','[{"en":"There''s a problem","tr":"bir sorun var"},{"en":"with","tr":"… ile ilgili"},{"en":"my room key","tr":"sorunlu şey"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Otel','Mağaza']::text[],array['Nötr']::text[],'Şunda bir sorun var: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6a192f9c-3be6-5aff-a1da-9492fda3e953','The … doesn''t work.','doesn''t','The air conditioner doesn''t work.','Klima çalışmıyor.','[{"en":"The air conditioner","tr":"arızalı şey"},{"en":"doesn''t work","tr":"çalışmıyor"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Otel','Ev']::text[],array['Nötr']::text[],'… çalışmıyor.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('16272a2c-0563-58b3-a73e-c009c5f16e96','How much is …?','is','How much is this backpack?','Bu sırt çantası ne kadar?','[{"en":"How much","tr":"ne kadar"},{"en":"is","tr":"-dir"},{"en":"this backpack","tr":"ürün"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Mağaza']::text[],array['Günlük']::text[],'… ne kadar?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6bcef6ab-b76c-5166-b900-231dc9b01e8c','Can you help me …?','carry','Can you help me carry these boxes?','Bu kutuları taşımama yardım edebilir misin?','[{"en":"Can you help me","tr":"bana yardım edebilir misin"},{"en":"carry these boxes","tr":"eylem (yalın fiil)"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['Yardım isteme']::text[],array['Samimi']::text[],'Şunu yapmama yardım edebilir misin: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ec6bfe1f-0a2e-588f-8973-2b0aa48c2ee4','I think I was charged …','was charged','I think I was charged twice for this.','Sanırım bunun için benden iki kez ücret alındı.','[{"en":"I think","tr":"sanırım"},{"en":"I was charged","tr":"benden ücret alındı"},{"en":"twice","tr":"iki kez"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Mağaza','Otel','Banka']::text[],array['Nazik']::text[],'Sanırım benden ücret alındı: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('9c898ed0-b425-5670-b1db-1dc730b61d07','Would you mind …-ing?','turning','Would you mind turning the music down?','Müziğin sesini kısar mısınız?','[{"en":"Would you mind","tr":"… mısınız (çok nazik)"},{"en":"turning the music down","tr":"eylem (-ing)"}]'::jsonb,'851477de-6cca-5819-9b94-be7428c7eb31',array['Komşu','Rica']::text[],array['Çok nazik']::text[],'Şunu yapar mısınız: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b769039c-eb8f-564a-8dfb-0a14f19d03d3','I ordered …, but I got …','but','I ordered a medium, but I got a large.','Orta boy sipariş ettim ama bana büyük boy geldi.','[{"en":"I ordered","tr":"sipariş ettim"},{"en":"a medium","tr":"istenen"},{"en":"but I got a large","tr":"ama gelen"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Restoran','Online alışveriş']::text[],array['Nötr']::text[],'Şunu sipariş ettim ama başka bir şey geldi: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0149bfda-62bd-5d7d-aab4-05cdc6f934df','I''ve been feeling … since …','been feeling','I''ve been feeling tired since last week.','Geçen haftadan beri kendimi yorgun hissediyorum.','[{"en":"I''ve been","tr":"-dır, -yorum (süregelen)"},{"en":"feeling","tr":"hissediyorum"},{"en":"since last week","tr":"geçen haftadan beri"}]'::jsonb,'d8558e30-a9d6-599b-badb-54d137a6308c',array['Muayene']::text[],array['Günlük']::text[],'… beri kendimi … hissediyorum.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('13b5ddef-4766-5ac0-8899-081cd2ba3046','It hurts when I …','hurts','It hurts when I swallow.','Yutkunduğumda acıyor.','[{"en":"It hurts","tr":"acıyor"},{"en":"when I","tr":"-dığımda"},{"en":"swallow","tr":"eylem"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Muayene']::text[],array['Günlük']::text[],'… acıyor.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('e3455a49-9a80-5cb4-8f7d-e2e8e5897ecb','Have you ever had …?','ever had','Have you ever had surgery?','Hiç ameliyat oldunuz mu?','[{"en":"Have you","tr":"(siz) … mı"},{"en":"ever","tr":"hiç"},{"en":"had surgery","tr":"ameliyat oldunuz"}]'::jsonb,'d8558e30-a9d6-599b-badb-54d137a6308c',array['Hasta öyküsü']::text[],array['Resmî']::text[],'Hiç … oldunuz mu / geçirdiniz mi?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('5f4c43f3-d019-54bd-be0d-0ba5b5a3bb26','You''ll need to …','need to','You''ll need to stay in bed for two days.','İki gün yatakta kalmanız gerekecek.','[{"en":"You''ll","tr":"(siz) -acaksınız"},{"en":"need to","tr":"-manız gerekecek"},{"en":"stay in bed","tr":"yatakta kalmak"}]'::jsonb,'d0ce0122-6b50-5a5c-9acb-81c3e9022a7f',array['Tedavi']::text[],array['Resmî','Talimat']::text[],'… gerekecek.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a6b0bf66-0c45-56fd-9afb-392bcc8ce1f0','Make sure you …','sure','Make sure you finish the whole course of antibiotics.','Antibiyotik kürünün tamamını bitirdiğinizden emin olun.','[{"en":"Make sure","tr":"emin olun"},{"en":"you finish","tr":"bitirdiğinizden"},{"en":"the whole course","tr":"kürün tamamı"}]'::jsonb,'d0ce0122-6b50-5a5c-9acb-81c3e9022a7f',array['İlaç talimatı']::text[],array['Talimat']::text[],'… emin olun.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('653b7b98-b8e0-5666-a348-039e60224257','You should avoid …','avoid','You should avoid heavy lifting for a month.','Bir ay boyunca ağır kaldırmaktan kaçınmalısınız.','[{"en":"You should","tr":"-malısınız"},{"en":"avoid","tr":"kaçınmak"},{"en":"heavy lifting","tr":"ağır kaldırma"}]'::jsonb,'d0ce0122-6b50-5a5c-9acb-81c3e9022a7f',array['Tedavi']::text[],array['Resmî']::text[],'… kaçınmalısınız.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('672a4d8c-49bd-5f14-af35-76b9737da61a','Is it serious?','serious','Is it serious, doctor?','Ciddi mi, doktor?','[{"en":"Is it","tr":"o … mı"},{"en":"serious","tr":"ciddi"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Muayene']::text[],array['Günlük']::text[],'… mi?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('573da908-43af-5173-b0af-4afca904c598','Take … every … hours.','every','Take two tablets every six hours.','Her altı saatte bir iki tablet alın.','[{"en":"Take","tr":"alın"},{"en":"two tablets","tr":"miktar"},{"en":"every six hours","tr":"her altı saatte bir"}]'::jsonb,'d0ce0122-6b50-5a5c-9acb-81c3e9022a7f',array['İlaç talimatı']::text[],array['Talimat']::text[],'Her … saatte bir … alın.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a793da83-3afe-5277-8047-19d8db8bde5a','I''m going to check your …','going to','I''m going to check your temperature now.','Şimdi ateşinize bakacağım.','[{"en":"I''m going to","tr":"-acağım"},{"en":"check","tr":"bakmak, kontrol etmek"},{"en":"your temperature","tr":"ateşiniz"}]'::jsonb,'4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5',array['Muayene']::text[],array['Resmî']::text[],'Şimdi …(-ize) bakacağım.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('69b0208c-f765-556b-b69c-a476a26db6d0','Is there any history of … in your family?','history of','Is there any history of diabetes in your family?','Ailenizde diyabet öyküsü var mı?','[{"en":"Is there any","tr":"… var mı"},{"en":"history of","tr":"öyküsü"},{"en":"in your family","tr":"ailenizde"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Hasta öyküsü']::text[],array['Resmî']::text[],'Ailenizde … öyküsü var mı?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('1cb7d501-ead0-55af-8f0e-885479823698','Is it safe to take … with …?','safe to take','Is it safe to take this with alcohol?','Bunu alkolle birlikte almak güvenli mi?','[{"en":"Is it safe","tr":"güvenli mi"},{"en":"to take","tr":"almak"},{"en":"with alcohol","tr":"alkolle"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Eczane']::text[],array['Kibar','Soru']::text[],'Bunu … ile birlikte almak güvenli mi?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('00b2b9f8-2bf4-517f-a5f7-79a31ecd8ad2','How often should I …?','often','How often should I use the inhaler?','İnhaleri ne sıklıkla kullanmalıyım?','[{"en":"How often","tr":"ne sıklıkla"},{"en":"should I","tr":"-malıyım"},{"en":"use","tr":"kullanmak"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Eczane']::text[],array['Soru']::text[],'… ne sıklıkla kullanmalıyım?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('20bf3cfa-ff1e-5630-9ae7-53bf36bf57f9','Do I need a prescription for …?','prescription','Do I need a prescription for these antibiotics?','Bu antibiyotikler için reçete gerekiyor mu?','[{"en":"Do I need","tr":"gerekiyor mu"},{"en":"a prescription","tr":"reçete"},{"en":"for …","tr":"… için"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Eczane']::text[],array['Soru']::text[],'… için reçete gerekiyor mu?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a947bb17-af9e-5fdd-9a0e-7b4d86d46291','Don''t take more than … in 24 hours.','more than','Don''t take more than four tablets in 24 hours.','24 saatte dörtten fazla tablet almayın.','[{"en":"Don''t take","tr":"almayın"},{"en":"more than","tr":"-den fazla"},{"en":"in 24 hours","tr":"24 saatte"}]'::jsonb,'d0ce0122-6b50-5a5c-9acb-81c3e9022a7f',array['Etiket','Talimat']::text[],array['Uyarı']::text[],'24 saatte … fazlasını almayın.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('91d0ee15-a256-5fc8-af47-32b88d443c17','Can I take it while I''m …?','while','Can I take it while I''m breastfeeding?','Emzirirken bunu alabilir miyim?','[{"en":"Can I take it","tr":"alabilir miyim"},{"en":"while I''m …","tr":"…-ken"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Eczane']::text[],array['Soru']::text[],'… bunu alabilir miyim?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d97ce27a-3c9d-527e-983c-34d55fa56eac','It should be taken …','should be taken','It should be taken with food.','Yemekle birlikte alınmalıdır.','[{"en":"It should be","tr":"-malıdır"},{"en":"taken","tr":"alınmış (edilgen)"},{"en":"with food","tr":"yemekle"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Etiket','Talimat']::text[],array['Resmî']::text[],'… alınmalıdır.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('91feb7de-e288-56aa-ae0f-f0ce148d9e20','What should I do if I …?','if I','What should I do if I miss a dose?','Bir dozu unutursam ne yapmalıyım?','[{"en":"What should I do","tr":"ne yapmalıyım"},{"en":"if I …","tr":"eğer …-rsam"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Eczane']::text[],array['Soru']::text[],'… ne yapmalıyım?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f199fb29-79ba-50f8-865e-9702f05a077e','Keep … out of the reach of children.','out of the reach','Keep all medicines out of the reach of children.','Tüm ilaçları çocukların ulaşamayacağı yerde tutun.','[{"en":"Keep","tr":"tutun"},{"en":"out of the reach of","tr":"ulaşamayacağı yerde"}]'::jsonb,'d0ce0122-6b50-5a5c-9acb-81c3e9022a7f',array['Etiket']::text[],array['Uyarı','Resmî']::text[],'… çocukların ulaşamayacağı yerde tutun.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c15842de-7d44-5e36-87ae-9d1b97922336','I''m allergic to …','allergic to','I''m allergic to penicillin.','Penisiline alerjim var.','[{"en":"I''m allergic","tr":"alerjim var"},{"en":"to …","tr":"-e"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Eczane','Muayene']::text[],array['Günlük']::text[],'… alerjim var.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('dbcebc9f-dd8e-5409-95c9-83b88bdb006e','Do you have anything for …?','anything for','Do you have anything for a sore throat?','Boğaz ağrısı için bir şeyiniz var mı?','[{"en":"Do you have","tr":"var mı"},{"en":"anything","tr":"bir şey"},{"en":"for …","tr":"… için"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Eczane']::text[],array['Günlük','Kibar']::text[],'… için bir şeyiniz var mı?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('e7a75727-6e6b-5d62-a44b-4d8ba6628aa5','On a scale of 0 to 10, how … is it?','bad','On a scale of 0 to 10, how bad is the pain now?','0''dan 10''a bir ölçekte ağrı şu an ne kadar kötü?','[{"en":"On a scale of 0 to 10","tr":"0''dan 10''a bir ölçekte"},{"en":"how bad","tr":"ne kadar kötü"}]'::jsonb,'3e9a97ae-1d43-53b8-91a9-7132362c4453',array['Hastane']::text[],array['Soru','Resmî']::text[],'0''dan 10''a bir ölçekte … ne kadar kötü?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('cb7c07e0-1c8c-5c06-9f67-9492294d74bf','I''m just going to … , is that OK?','take','I''m just going to take your blood pressure, is that OK?','Şimdi tansiyonunuzu ölçeceğim, olur mu?','[{"en":"I''m just going to","tr":"şimdi …-eceğim"},{"en":"is that OK?","tr":"olur mu?"}]'::jsonb,'3e9a97ae-1d43-53b8-91a9-7132362c4453',array['Hastane']::text[],array['Kibar']::text[],'Şimdi …, olur mu?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ec1794f6-2d02-5c67-b559-a4a038e0eaac','Have you had anything to … since …?','eat','Have you had anything to eat since midnight?','Gece yarısından beri bir şey yediniz mi?','[{"en":"Have you had","tr":"… mi"},{"en":"anything to eat","tr":"yiyecek bir şey"},{"en":"since midnight","tr":"gece yarısından beri"}]'::jsonb,'d8558e30-a9d6-599b-badb-54d137a6308c',array['Ameliyat hazırlığı']::text[],array['Soru']::text[],'Gece yarısından beri bir şey … mi?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('2c23ad24-593d-55f1-8a06-4b5a890f17f7','You''ll be able to … after …','able to','You''ll be able to go home after the doctor sees you.','Doktor sizi gördükten sonra eve gidebileceksiniz.','[{"en":"You''ll be able to","tr":"-ebileceksiniz"},{"en":"after …","tr":"…-den sonra"}]'::jsonb,'d0ce0122-6b50-5a5c-9acb-81c3e9022a7f',array['Taburculuk']::text[],array['Günlük']::text[],'Doktor sizi gördükten sonra … -ebileceksiniz.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('8373abd7-4037-5fdd-9ab8-44486f90fc61','Try to avoid … for …','avoid','Try to avoid lifting anything heavy for six weeks.','Altı hafta boyunca ağır bir şey kaldırmamaya çalışın.','[{"en":"Try to","tr":"-maya çalışın"},{"en":"avoid + -ing","tr":"-mekten kaçınmak"},{"en":"for six weeks","tr":"altı hafta boyunca"}]'::jsonb,'d0ce0122-6b50-5a5c-9acb-81c3e9022a7f',array['Taburculuk']::text[],array['Tavsiye']::text[],'Altı hafta boyunca … çalışın.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b82ca181-3ea6-5618-b391-cc95cf9dc77d','Let me know if you …','know','Let me know if you feel sick.','Midenizin bulandığını hissederseniz bana söyleyin.','[{"en":"Let me know","tr":"bana haber verin"},{"en":"if you …","tr":"eğer …-rsanız"}]'::jsonb,'d0ce0122-6b50-5a5c-9acb-81c3e9022a7f',array['Hastane']::text[],array['Kibar']::text[],'… bana söyleyin.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('dcdc7994-b479-52bb-86ac-3ab9cf2a72db','When can I …?','can I','When can I go back to work?','İşe ne zaman dönebilirim?','[{"en":"When can I","tr":"ne zaman …-ebilirim"},{"en":"go back to work","tr":"işe dönmek"}]'::jsonb,'3e9a97ae-1d43-53b8-91a9-7132362c4453',array['Taburculuk']::text[],array['Soru']::text[],'Ne zaman …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ae6b01b9-6cd0-5877-95c7-72734a0815a7','You''ll need to come back for …','come back','You''ll need to come back for a check-up in two weeks.','İki hafta sonra kontrol için tekrar gelmeniz gerekecek.','[{"en":"You''ll need to","tr":"-meniz gerekecek"},{"en":"come back","tr":"geri gelmek"},{"en":"for a check-up","tr":"kontrol için"}]'::jsonb,'d0ce0122-6b50-5a5c-9acb-81c3e9022a7f',array['Taburculuk']::text[],array['Resmî']::text[],'… için tekrar gelmeniz gerekecek.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('edf64b48-6f00-5d0a-9406-51e3ab3b734e','Is there anyone who can …?','pick you up','Is there anyone who can pick you up from the hospital?','Sizi hastaneden alabilecek biri var mı?','[{"en":"Is there anyone","tr":"biri var mı"},{"en":"who can …","tr":"…-ebilecek"}]'::jsonb,'3e9a97ae-1d43-53b8-91a9-7132362c4453',array['Taburculuk']::text[],array['Soru','Kibar']::text[],'… biri var mı?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('394d50e2-c808-5a19-92c2-e99a9ee16b71','It''s normal to … for a few days.','normal','It''s normal to feel tired for a few days.','Birkaç gün yorgun hissetmek normal.','[{"en":"It''s normal","tr":"normal"},{"en":"to feel tired","tr":"yorgun hissetmek"},{"en":"for a few days","tr":"birkaç gün"}]'::jsonb,'d0ce0122-6b50-5a5c-9acb-81c3e9022a7f',array['Taburculuk']::text[],array['Güven verici']::text[],'Birkaç gün … normal.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0f3b2d63-b31d-5d05-96e6-0b020502b1c4','Under the terms of …, …','terms of','Under the terms of your contract, you must give one month''s notice.','Sözleşmenizin şartlarına göre bir ay önceden bildirimde bulunmalısınız.','[{"en":"Under the terms of","tr":"… şartlarına göre"},{"en":"you must give notice","tr":"bildirimde bulunmalısınız"}]'::jsonb,'5dea6707-1af4-5744-a755-f5101202772c',array['Sözleşme']::text[],array['Resmî']::text[],'… şartlarına göre bir ay önceden bildirimde bulunmalısınız.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f30e9b88-7f2c-513a-b904-4a5d8ac63f77','Every employee is entitled to …','entitled to','Every employee is entitled to 14 days of paid leave.','Her çalışanın 14 gün ücretli izin hakkı vardır.','[{"en":"is entitled to","tr":"… hakkı vardır"},{"en":"paid leave","tr":"ücretli izin"}]'::jsonb,'5dea6707-1af4-5744-a755-f5101202772c',array['İş hukuku']::text[],array['Resmî']::text[],'Her çalışanın … hakkı vardır.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('fe97c92f-5b19-542c-91e8-8e738f086ea5','I am writing to give notice of my …','notice','I am writing to give notice of my resignation.','İstifamı bildirmek için yazıyorum.','[{"en":"I am writing to","tr":"… için yazıyorum"},{"en":"give notice of","tr":"bildirmek"}]'::jsonb,'1e667df4-3d60-5a3d-bf4b-db340b45ad36',array['Resmî mektup']::text[],array['Resmî']::text[],'… bildirmek için yazıyorum.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('627c1de2-111a-55a6-9b17-574de6c301d9','We process your personal data to …','process','We process your personal data to provide our services.','Kişisel verilerinizi hizmetlerimizi sunmak için işliyoruz.','[{"en":"We process","tr":"işliyoruz"},{"en":"your personal data","tr":"kişisel verilerinizi"},{"en":"to provide","tr":"sunmak için"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Gizlilik politikası']::text[],array['Resmî']::text[],'Kişisel verilerinizi … için işliyoruz.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f4e25da9-4ea3-5bad-a79b-368d5a2949b3','… is subject to the approval of …','subject to','The transfer of shares is subject to the approval of the board.','Hisse devri yönetim kurulunun onayına tabidir.','[{"en":"is subject to","tr":"-e tabidir"},{"en":"the approval of","tr":"… onayı"}]'::jsonb,'f67d8e99-5efb-5381-a4f0-c3b2f6e90c67',array['Şirket']::text[],array['Resmî']::text[],'Hisse devri … onayına tabidir.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('28671b67-4506-5b2f-bcaa-b0824cac1caa','The employee shall not disclose …','disclose','The employee shall not disclose any confidential information.','Çalışan hiçbir gizli bilgiyi ifşa etmeyecektir.','[{"en":"shall not","tr":"-meyecektir (yükümlülük)"},{"en":"disclose","tr":"ifşa etmek"}]'::jsonb,'5dea6707-1af4-5744-a755-f5101202772c',array['Sözleşme']::text[],array['Resmî']::text[],'Çalışan … ifşa etmeyecektir.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c00d0433-7312-5203-9b70-86110241e92c','Please sign and return … by …','sign and return','Please sign and return the attached contract by Monday.','Lütfen ekteki sözleşmeyi pazartesiye kadar imzalayıp geri gönderin.','[{"en":"Please sign","tr":"lütfen imzalayın"},{"en":"and return","tr":"ve geri gönderin"},{"en":"by Monday","tr":"pazartesiye kadar"}]'::jsonb,'1e667df4-3d60-5a3d-bf4b-db340b45ad36',array['Resmî yazı']::text[],array['Resmî','Kibar']::text[],'Lütfen … imzalayıp geri gönderin.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f1eab840-9f6e-5ae1-9a56-2c408013fa67','In the event of …, the employee will …','event of','In the event of dismissal, the employee will receive severance pay.','İşten çıkarılma durumunda çalışan kıdem tazminatı alır.','[{"en":"In the event of","tr":"… durumunda"},{"en":"the employee will receive","tr":"çalışan alır"}]'::jsonb,'f67d8e99-5efb-5381-a4f0-c3b2f6e90c67',array['Sözleşme']::text[],array['Resmî']::text[],'… durumunda çalışan kıdem tazminatı alır.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('836f8e91-a616-5ddd-8746-556938ab823a','We hereby confirm that …','confirm','We hereby confirm that Ms Demir has worked for us since 2022.','Sayın Demir''in 2022''den beri bizde çalıştığını işbu yazıyla teyit ederiz.','[{"en":"We hereby confirm","tr":"işbu yazıyla teyit ederiz"},{"en":"that …","tr":"…-dığını"}]'::jsonb,'1e667df4-3d60-5a3d-bf4b-db340b45ad36',array['Resmî yazı']::text[],array['Resmî']::text[],'… işbu yazıyla teyit ederiz.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('49622f30-ea99-52c7-845f-9437e9d89cac','You can withdraw your consent by …','withdraw','You can withdraw your consent by changing your settings.','Ayarlarınızı değiştirerek rızanızı geri çekebilirsiniz.','[{"en":"You can withdraw","tr":"geri çekebilirsiniz"},{"en":"your consent","tr":"rızanızı"},{"en":"by changing","tr":"değiştirerek"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Gizlilik politikası']::text[],array['Resmî']::text[],'… rızanızı geri çekebilirsiniz.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('fa3acb2f-6e0c-55d0-91bc-2374e2ac2f02','The … shall …','shall','The tenant shall pay the rent by the fifth day of each month.','Kiracı kirayı her ayın beşine kadar ödeyecektir.','[{"en":"The tenant","tr":"kiracı"},{"en":"shall","tr":"-ecektir (yükümlülük)"},{"en":"pay the rent","tr":"kirayı ödemek"}]'::jsonb,'5dea6707-1af4-5744-a755-f5101202772c',array['Sözleşme']::text[],array['Çok resmî']::text[],'… -ecektir (yükümlülük).','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7c9458b8-f54e-5a40-96a6-73c851f6c341','Either party may …','may','Either party may terminate this agreement in writing.','Taraflardan her biri bu sözleşmeyi yazılı olarak feshedebilir.','[{"en":"Either party","tr":"taraflardan her biri"},{"en":"may","tr":"-ebilir (izin, hak)"},{"en":"terminate","tr":"feshetmek"}]'::jsonb,'5dea6707-1af4-5744-a755-f5101202772c',array['Sözleşme']::text[],array['Çok resmî']::text[],'Taraflardan her biri … -ebilir.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('e539b221-5f0c-5934-b512-8c7a7bb7d25c','… subject to …','subject to','The price is subject to change without notice.','Fiyat önceden bildirilmeksizin değiştirilebilir.','[{"en":"The price is","tr":"fiyat …"},{"en":"subject to","tr":"-e tabidir"},{"en":"change","tr":"değişiklik"}]'::jsonb,'5dea6707-1af4-5744-a755-f5101202772c',array['Sözleşme']::text[],array['Resmî']::text[],'… -e tabidir.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('992453a1-0a8d-5482-8b30-f251c6dbbcfa','In the event of …, …','event of','In the event of a dispute, the parties will first try mediation.','Bir uyuşmazlık durumunda taraflar önce arabuluculuğa başvuracaktır.','[{"en":"In the event of","tr":"… durumunda"},{"en":"a dispute","tr":"uyuşmazlık"},{"en":"the parties will","tr":"taraflar …acaktır"}]'::jsonb,'f67d8e99-5efb-5381-a4f0-c3b2f6e90c67',array['Sözleşme']::text[],array['Çok resmî']::text[],'… durumunda, …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('bb418aaa-441b-5e8b-b93e-0262f231f244','Unless otherwise agreed, …','otherwise agreed','Unless otherwise agreed, all payments are due within 30 days.','Aksi kararlaştırılmadıkça tüm ödemelerin vadesi 30 gündür.','[{"en":"Unless","tr":"… medikçe"},{"en":"otherwise agreed","tr":"aksi kararlaştırılmadıkça"},{"en":"all payments are due","tr":"tüm ödemelerin vadesi"}]'::jsonb,'f67d8e99-5efb-5381-a4f0-c3b2f6e90c67',array['Sözleşme']::text[],array['Çok resmî']::text[],'Aksi … sürece, …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('204310a4-6510-57e1-b7f7-ced1dc861c2e','Please find attached …','attached','Please find attached the signed copy of the contract.','Ekte sözleşmenin imzalı kopyasını bulabilirsiniz.','[{"en":"Please find","tr":"bulabilirsiniz"},{"en":"attached","tr":"ekte"},{"en":"the signed copy","tr":"imzalı kopya"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['E-posta']::text[],array['Resmî']::text[],'Ekte … bulabilirsiniz.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f5cba552-fec5-5b69-98b3-5346a6ff406c','We would be grateful if you could …','grateful','We would be grateful if you could reply by Friday.','Cuma gününe kadar cevap verebilirseniz minnettar oluruz.','[{"en":"We would be grateful","tr":"minnettar oluruz"},{"en":"if you could","tr":"-ebilirseniz"},{"en":"reply by Friday","tr":"cuma gününe kadar cevap vermek"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['E-posta']::text[],array['Çok resmî']::text[],'… minnettar oluruz.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a4ab28bd-ffc4-5204-8847-5aff54c18fe6','Further to our …, …','Further to','Further to our phone call, I am sending you the draft agreement.','Telefon görüşmemize istinaden size sözleşme taslağını gönderiyorum.','[{"en":"Further to","tr":"-e istinaden"},{"en":"our phone call","tr":"telefon görüşmemiz"},{"en":"I am sending","tr":"gönderiyorum"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['E-posta']::text[],array['Resmî']::text[],'…(-e) istinaden, …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('e877ad1b-ece9-5127-9ec0-64aeac8bbc57','The … is entitled to …','entitled to','The employee is entitled to 14 days of paid leave.','Çalışan 14 gün ücretli izin hakkına sahiptir.','[{"en":"The employee","tr":"çalışan"},{"en":"is entitled to","tr":"… hakkına sahiptir"},{"en":"paid leave","tr":"ücretli izin"}]'::jsonb,'5dea6707-1af4-5744-a755-f5101202772c',array['İş hukuku']::text[],array['Resmî']::text[],'… hakkına sahiptir.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('79929e0d-2808-5410-8ebf-59d7202cfadc','Failure to … will result in …','pay','Failure to pay on time will result in a late fee.','Zamanında ödeme yapılmaması gecikme ücretiyle sonuçlanacaktır.','[{"en":"Failure to pay","tr":"ödeme yapılmaması"},{"en":"will result in","tr":"ile sonuçlanacaktır"},{"en":"a late fee","tr":"gecikme ücreti"}]'::jsonb,'f67d8e99-5efb-5381-a4f0-c3b2f6e90c67',array['Sözleşme','Uyarı']::text[],array['Resmî']::text[],'… yapılmaması … ile sonuçlanacaktır.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0ddfd32c-f279-5481-93cc-1d4994141bd4','We intend to … on behalf of our client.','intend to','We intend to file a claim on behalf of our client.','Müvekkilimiz adına bir talepte bulunmayı düşünüyoruz.','[{"en":"We intend to","tr":"-meyi düşünüyoruz"},{"en":"on behalf of our client","tr":"müvekkilimiz adına"}]'::jsonb,'5dea6707-1af4-5744-a755-f5101202772c',array['Hukuki yazışma']::text[],array['Resmî']::text[],'Müvekkilimiz adına … düşünüyoruz.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3082b410-a011-5b7b-a4e1-ee983995e03f','The hearing has been … to …','postponed','The hearing has been postponed to 3 June.','Duruşma 3 Haziran''a ertelendi.','[{"en":"The hearing","tr":"duruşma"},{"en":"has been postponed","tr":"ertelendi"},{"en":"to 3 June","tr":"3 Haziran''a"}]'::jsonb,'0e47e1be-1f21-5acc-aab3-01552452cccd',array['Dava süreci']::text[],array['Resmî']::text[],'Duruşma 3 Haziran''a …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f2659f78-588f-5f45-8555-1f0a43afb46c','According to the …, …','witness','According to the witness, the car was going too fast.','Tanığa göre araba çok hızlı gidiyordu.','[{"en":"According to","tr":"-e göre"},{"en":"the witness","tr":"tanık"}]'::jsonb,'bfcf9a85-caf2-5d11-b852-1fdd48d940df',array['Dava süreci']::text[],array['Resmî','Nesnel']::text[],'…, araba çok hızlı gidiyordu.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('47e6e9de-d08c-55c2-af69-784e4222b6f9','My client denies …','denies','My client denies any wrongdoing.','Müvekkilim herhangi bir yanlış yaptığını reddediyor.','[{"en":"My client","tr":"müvekkilim"},{"en":"denies","tr":"reddediyor"},{"en":"any wrongdoing","tr":"herhangi bir kusuru"}]'::jsonb,'bfcf9a85-caf2-5d11-b852-1fdd48d940df',array['Dava süreci']::text[],array['Resmî']::text[],'Müvekkilim … reddediyor.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('475c1e8a-4dd8-517b-91a9-c132ebe6cfad','The court ruled that …','ruled that','The court ruled that the contract was void.','Mahkeme sözleşmenin geçersiz olduğuna karar verdi.','[{"en":"The court ruled","tr":"mahkeme karar verdi"},{"en":"that …","tr":"…-dığına"}]'::jsonb,'bfcf9a85-caf2-5d11-b852-1fdd48d940df',array['Karar']::text[],array['Resmî']::text[],'Mahkeme … karar verdi.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d7cb3b09-8468-50a6-9057-0399f5ce18c7','We would advise you to …','advise','We would advise you to keep all receipts.','Tüm fişleri saklamanızı tavsiye ederiz.','[{"en":"We would advise you","tr":"size tavsiye ederiz"},{"en":"to keep","tr":"saklamanızı"}]'::jsonb,'5dea6707-1af4-5744-a755-f5101202772c',array['Hukuki yazışma']::text[],array['Resmî','Kibar']::text[],'… tavsiye ederiz.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c2bd44db-77ce-5d4a-8bf1-ef3380d4be16','You are required to submit … by …','required to','You are required to submit the documents by Friday.','Belgeleri cumaya kadar sunmanız gerekmektedir.','[{"en":"You are required to","tr":"-meniz gerekmektedir"},{"en":"by Friday","tr":"cumaya kadar"}]'::jsonb,'5dea6707-1af4-5744-a755-f5101202772c',array['Resmî yazı']::text[],array['Resmî']::text[],'… sunmanız gerekmektedir.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b4f1d5b1-d61c-5907-9350-0f1a896b8cf8','In light of …, we …','light of','In light of the new evidence, we will ask for a retrial.','Yeni deliller ışığında yeniden yargılama talep edeceğiz.','[{"en":"In light of","tr":"ışığında"},{"en":"we will ask for","tr":"talep edeceğiz"}]'::jsonb,'f67d8e99-5efb-5381-a4f0-c3b2f6e90c67',array['Hukuki yazışma']::text[],array['Resmî']::text[],'… ışığında yeniden yargılama talep edeceğiz.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('bfa803b7-f3a8-51f8-a10f-fdce090dfc6b','The deadline for … is …','deadline','The deadline for filing an appeal is 14 days.','İtiraz için süre 14 gündür.','[{"en":"The deadline for","tr":"… için son tarih / süre"},{"en":"is 14 days","tr":"14 gündür"}]'::jsonb,'f67d8e99-5efb-5381-a4f0-c3b2f6e90c67',array['Dava süreci']::text[],array['Resmî']::text[],'… için süre 14 gündür.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('9a783a15-1fb4-5f4d-b42b-917f258b3469','without admitting …','without admitting','The company agreed to pay without admitting liability.','Şirket sorumluluğu kabul etmeden ödemeyi kabul etti.','[{"en":"without admitting","tr":"kabul etmeden"},{"en":"liability","tr":"sorumluluk"}]'::jsonb,'f67d8e99-5efb-5381-a4f0-c3b2f6e90c67',array['Sulh']::text[],array['Resmî']::text[],'Şirket … kabul etmeden ödemeyi kabul etti.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7adbf318-5efd-5e2e-b28e-14d3f40a48bb','What do you think about …?','think about','What do you think about moving this to a helper?','Bunu bir yardımcı fonksiyona taşımaya ne dersin?','[{"en":"What do you think","tr":"ne dersin"},{"en":"about","tr":"… hakkında"},{"en":"moving this to a helper","tr":"öneri (-ing)"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Kod inceleme','Toplantı']::text[],array['Nazik']::text[],'Şuna ne dersin: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('bd7477cd-2b4e-52f7-840d-a02dcc5cdf29','Maybe we could …','could','Maybe we could add a test for this case.','Belki bu durum için bir test ekleyebiliriz.','[{"en":"Maybe","tr":"belki"},{"en":"we could","tr":"-ebiliriz"},{"en":"add a test","tr":"öneri"}]'::jsonb,'a5f9d0fc-be42-50ae-afd1-5c3a477c4150',array['Kod inceleme','Toplantı']::text[],array['Nazik']::text[],'Belki şunu yapabiliriz: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('31d6953c-039d-5f1f-89e0-643298800389','This should be moved to …','should be moved','This logic should be moved to the service layer.','Bu mantık servis katmanına taşınmalı.','[{"en":"This logic","tr":"bu mantık"},{"en":"should be moved","tr":"taşınmalı"},{"en":"to the service layer","tr":"hedef yer"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Kod inceleme']::text[],array['Nötr']::text[],'Bu mantık şuraya taşınmalı: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('31fb5980-d444-5978-a927-eebca21d5000','Can we use … instead of …?','instead of','Can we use a map instead of two arrays?','İki dizi yerine bir map kullanabilir miyiz?','[{"en":"Can we use","tr":"kullanabilir miyiz"},{"en":"a map","tr":"önerilen"},{"en":"instead of two arrays","tr":"iki dizi yerine"}]'::jsonb,'a5f9d0fc-be42-50ae-afd1-5c3a477c4150',array['Kod inceleme']::text[],array['Nazik']::text[],'İki dizi yerine şunu kullanabilir miyiz: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('fa696a34-1ee7-519b-8ae1-f8b27c398f19','I left a few comments on …','left','I left a few comments on your PR.','PR''ına birkaç yorum bıraktım.','[{"en":"I left","tr":"bıraktım"},{"en":"a few comments","tr":"birkaç yorum"},{"en":"on your PR","tr":"PR''ına"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Kod inceleme','Ekip mesajı']::text[],array['Nötr']::text[],'Şuna birkaç yorum bıraktım: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d4c7c769-160e-5c0c-becf-f5944cd54fe2','I''m not sure about …','sure about','I''m not sure about this approach.','Bu yaklaşımdan emin değilim.','[{"en":"I''m not sure","tr":"emin değilim"},{"en":"about","tr":"… hakkında"},{"en":"this approach","tr":"konu"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Kod inceleme','Toplantı']::text[],array['Temkinli']::text[],'Şundan emin değilim: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3be75488-3984-5917-bb89-9e4a1be97536','I''ve updated the PR based on …','based on','I''ve updated the PR based on your feedback.','PR''ı geri bildirimine göre güncelledim.','[{"en":"I''ve updated the PR","tr":"PR''ı güncelledim"},{"en":"based on","tr":"… göre"},{"en":"your feedback","tr":"dayanak"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Kod inceleme']::text[],array['Nötr']::text[],'PR''ı şuna göre güncelledim: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('27660a55-2c0a-5838-a593-1f521e61139e','Is there a reason why …?','reason why','Is there a reason why we don''t use the existing helper?','Mevcut yardımcı fonksiyonu kullanmamamızın bir nedeni var mı?','[{"en":"Is there a reason","tr":"bir nedeni var mı"},{"en":"why","tr":"neden"},{"en":"we don''t use the existing helper","tr":"sorulan durum"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Kod inceleme']::text[],array['Nazik']::text[],'Şunun bir nedeni var mı: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0262ab52-1953-59c0-88b3-a66f7846d997','This will break … if …','break','This will break the build if the file is missing.','Dosya yoksa bu, derlemeyi bozar.','[{"en":"This will break","tr":"bu bozar"},{"en":"the build","tr":"etkilenen şey"},{"en":"if the file is missing","tr":"dosya yoksa"}]'::jsonb,'3bf15cc6-24b0-5ade-bd72-578e2cc35706',array['Kod inceleme']::text[],array['Uyarı']::text[],'Dosya yoksa bu, şunu bozar: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3af08709-f3b4-500f-a3b2-c517c381a237','Thanks for …','for the review','Thanks for the review, I''ll fix it now.','İnceleme için teşekkürler, hemen düzeltiyorum.','[{"en":"Thanks","tr":"teşekkürler"},{"en":"for the review","tr":"… için"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Kod inceleme','Ekip mesajı']::text[],array['Nazik']::text[],'Şunun için teşekkürler: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('e10e4121-d7f2-5c7a-bd28-373f13b7e08b','I''m getting … when …','getting','I''m getting a 500 error when I log in.','Giriş yaptığımda 500 hatası alıyorum.','[{"en":"I''m getting","tr":"alıyorum"},{"en":"a 500 error","tr":"hata"},{"en":"when I log in","tr":"giriş yaptığımda"}]'::jsonb,'07f46ae3-6018-5f8f-8bda-377e874ddc92',array['Hata bildirme','Ekip mesajı']::text[],array['Nötr']::text[],'Giriş yaptığımda şunu alıyorum: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('755b710c-445c-547f-84be-10b8a1f1284d','It started … after …','failing','It started failing after the last update.','Son güncellemeden sonra hata vermeye başladı.','[{"en":"It started","tr":"başladı"},{"en":"failing","tr":"hata vermeye"},{"en":"after the last update","tr":"son güncellemeden sonra"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Hata bildirme']::text[],array['Nötr']::text[],'Son güncellemeden sonra şu başladı: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('66196c9f-b01a-554f-9d1d-4ac6f93654ca','Have you tried …?','tried','Have you tried clearing the cache?','Önbelleği temizlemeyi denedin mi?','[{"en":"Have you tried","tr":"denedin mi"},{"en":"clearing the cache","tr":"önerilen çözüm (-ing)"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Yardım etme','Ekip mesajı']::text[],array['Nazik']::text[],'Şunu denedin mi: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a862f106-bdc7-5ce7-92a5-09b434ddf592','The problem seems to be …','seems to be','The problem seems to be in the config file.','Sorun yapılandırma dosyasında gibi görünüyor.','[{"en":"The problem","tr":"sorun"},{"en":"seems to be","tr":"gibi görünüyor"},{"en":"in the config file","tr":"yer"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Hata bildirme','Toplantı']::text[],array['Temkinli']::text[],'Sorun şurada gibi görünüyor: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d9336008-94f9-53fc-92f4-49edce0f2b3b','I fixed it by …','by','I fixed it by updating the driver.','Sürücüyü güncelleyerek düzelttim.','[{"en":"I fixed it","tr":"düzelttim"},{"en":"by","tr":"-erek"},{"en":"updating the driver","tr":"yöntem (-ing)"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Durum bildirme','Ekip mesajı']::text[],array['Nötr']::text[],'Şunu yaparak düzelttim: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('aaea652c-a224-5827-ad3c-e171af3c00b2','It should be fixed in …','should be fixed','It should be fixed in the next build.','Bir sonraki derlemede düzelmiş olması gerekiyor.','[{"en":"It should be","tr":"olması gerekir"},{"en":"fixed","tr":"düzeltilmiş"},{"en":"in the next build","tr":"zaman/yer"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Durum bildirme','Müşteriye yanıt']::text[],array['Temkinli']::text[],'Şurada düzelmiş olması gerekiyor: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a3ee9ff0-d785-58f8-bfba-5e3f82526356','Can you check if …?','check if','Can you check if the API is up?','API''nin çalışıp çalışmadığını kontrol edebilir misin?','[{"en":"Can you","tr":"-ebilir misin"},{"en":"check if","tr":"… mı diye kontrol et-"},{"en":"the API is up","tr":"kontrol edilen durum"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Yardım isteme','Ekip mesajı']::text[],array['Samimi']::text[],'Şunu kontrol edebilir misin: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('e591c7a6-b124-5edf-9378-7bc920446660','I noticed that …','noticed','I noticed that the images load slowly.','Görsellerin yavaş yüklendiğini fark ettim.','[{"en":"I noticed","tr":"fark ettim"},{"en":"that","tr":"-dığını"},{"en":"the images load slowly","tr":"fark edilen durum"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Hata bildirme','Kod inceleme']::text[],array['Nötr']::text[],'Şunu fark ettim: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('bfc1c6cb-3136-5e4f-8d52-83f5736da428','The error says …','says','The error says ''permission denied''.','Hata “izin reddedildi” diyor.','[{"en":"The error","tr":"hata (mesajı)"},{"en":"says","tr":"diyor"},{"en":"''permission denied''","tr":"mesaj metni"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Hata bildirme']::text[],array['Nötr']::text[],'Hata şunu diyor: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f3c2001f-a806-553f-92f5-d033846c3723','It only happens when …','happens','It only happens when the user is offline.','Yalnızca kullanıcı çevrimdışıyken oluyor.','[{"en":"It only happens","tr":"yalnızca oluyor"},{"en":"when","tr":"-dığında"},{"en":"the user is offline","tr":"koşul"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Hata bildirme']::text[],array['Nötr']::text[],'Yalnızca şu durumda oluyor: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0c511d7b-7bdb-525e-b42f-491f0ca4abe5','I''m working on …','working on','I''m working on the login page.','Giriş sayfası üzerinde çalışıyorum.','[{"en":"I''m","tr":"ben (-yorum)"},{"en":"working on","tr":"üzerinde çalış-"},{"en":"the login page","tr":"değişen iş"}]'::jsonb,'07f46ae3-6018-5f8f-8bda-377e874ddc92',array['Toplantı','Ekip mesajı']::text[],array['Günlük']::text[],'… üzerinde çalışıyorum.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('08114d70-ea33-5db5-b4e5-64308c03b4e6','I''m stuck on …','stuck on','I''m stuck on the database migration.','Veritabanı taşıma işinde takıldım.','[{"en":"I''m stuck","tr":"takıldım"},{"en":"on","tr":"(bir şey) üzerinde"},{"en":"the database migration","tr":"sorunlu iş"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Toplantı','Yardım isteme']::text[],array['Günlük']::text[],'Şurada takıldım: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0a8b2822-c804-515d-a3ee-f4608831c53d','Could you take a look at …?','Could you take a look at','Could you take a look at my pull request?','Pull request''ime bir göz atabilir misin?','[{"en":"Could you","tr":"-ebilir misin"},{"en":"take a look at","tr":"bir göz at-"},{"en":"my pull request","tr":"bakılacak şey"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Kod inceleme','Yardım isteme']::text[],array['Nazik']::text[],'Şuna bir göz atabilir misin: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('9b236b92-c4ad-5f11-b132-30bc7756cf22','I''ve finished …','finished','I''ve finished the API integration.','API entegrasyonunu bitirdim.','[{"en":"I''ve","tr":"(ben) -dim"},{"en":"finished","tr":"bitir-"},{"en":"the API integration","tr":"biten iş"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Toplantı','Durum raporu']::text[],array['Günlük']::text[],'Şunu bitirdim: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('55b74f94-6c30-5a3a-81c8-835664822b71','Today I''m going to …','going to','Today I''m going to write the unit tests.','Bugün birim testlerini yazacağım.','[{"en":"Today","tr":"bugün"},{"en":"I''m going to","tr":"-eceğim (plan)"},{"en":"write the unit tests","tr":"yapılacak iş"}]'::jsonb,'4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5',array['Toplantı','Durum raporu']::text[],array['Günlük']::text[],'Bugün şunu yapacağım: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c1739b6d-bfe2-50d6-9e70-023b3cee37ad','I need some help with …','help with','I need some help with the deployment script.','Dağıtım betiğinde biraz yardıma ihtiyacım var.','[{"en":"I need","tr":"ihtiyacım var"},{"en":"some help with","tr":"biraz yardım (… konusunda)"},{"en":"the deployment script","tr":"konu"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Yardım isteme','Ekip mesajı']::text[],array['Nötr']::text[],'Şu konuda biraz yardıma ihtiyacım var: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('05080be0-da92-5dc0-bde9-c3bdf334f1cf','I''m waiting for …','waiting for','I''m waiting for feedback from the client.','Müşteriden geri bildirim bekliyorum.','[{"en":"I''m waiting","tr":"bekliyorum"},{"en":"for","tr":"(bir şeyi)"},{"en":"feedback from the client","tr":"beklenen şey"}]'::jsonb,'07f46ae3-6018-5f8f-8bda-377e874ddc92',array['Toplantı','Durum raporu']::text[],array['Nötr']::text[],'Şunu bekliyorum: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('10ad0c1a-14fa-5a1d-81d3-e0fbe3fb0cac','Any updates on …?','updates on','Any updates on the payment bug?','Ödeme hatasıyla ilgili yeni bir gelişme var mı?','[{"en":"Any updates","tr":"yeni gelişme var mı"},{"en":"on","tr":"… ile ilgili"},{"en":"the payment bug","tr":"konu"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Ekip mesajı','Toplantı']::text[],array['Samimi']::text[],'Şu konuda yeni bir gelişme var mı: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0b2c5e67-1b09-55b8-86e7-127253fb9537','I''ll share … with the team.','share','I''ll share the meeting notes with the team.','Toplantı notlarını ekiple paylaşacağım.','[{"en":"I''ll","tr":"-eceğim"},{"en":"share","tr":"paylaş-"},{"en":"the meeting notes","tr":"paylaşılan şey"},{"en":"with the team","tr":"ekiple"}]'::jsonb,'4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5',array['Toplantı','Ekip mesajı']::text[],array['Nötr']::text[],'Şunu ekiple paylaşacağım: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('70f85303-5ca0-5b90-8c2c-66222b65a74b','Could we move … to …?','move','Could we move the demo to Thursday?','Demoyu perşembeye alabilir miyiz?','[{"en":"Could we","tr":"-ebilir miyiz"},{"en":"move","tr":"taşı-, al-"},{"en":"the demo","tr":"etkinlik"},{"en":"to Thursday","tr":"perşembeye"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Planlama','Ekip mesajı']::text[],array['Nazik']::text[],'Şunu başka bir güne alabilir miyiz: …?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ebc3be55-b179-594b-9c65-4340d799e06d','My flight has been …','been cancelled','My flight has been cancelled.','Uçuşum iptal edildi.','[{"en":"My flight","tr":"uçuşum"},{"en":"has been cancelled","tr":"iptal edildi"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Havalimanı']::text[],array['Günlük']::text[],'Uçuşum …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6377b62c-b3f5-5c68-92ae-f24e96c52d5b','What time does … start?','boarding','What time does boarding start?','Biniş saat kaçta başlıyor?','[{"en":"What time","tr":"saat kaçta"},{"en":"does … start","tr":"başlıyor"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Havalimanı']::text[],array['Soru']::text[],'… saat kaçta başlıyor?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('9d7bead2-91e2-5600-b503-77f28c609e7f','Could you help me find …?','find','Could you help me find gate 22?','22 numaralı kapıyı bulmama yardım edebilir misiniz?','[{"en":"Could you help me","tr":"bana yardım edebilir misiniz"},{"en":"find …","tr":"…-ı bulmak"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Havalimanı']::text[],array['Kibar']::text[],'… bulmama yardım edebilir misiniz?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d5e4e113-0949-5c4d-9527-2b980324fb16','I''m connecting to … — will I make it?','connecting','I''m connecting to Rome — will I make it?','Roma''ya aktarma yapıyorum, yetişebilecek miyim?','[{"en":"I''m connecting to","tr":"… aktarma yapıyorum"},{"en":"will I make it?","tr":"yetişebilecek miyim?"}]'::jsonb,'07f46ae3-6018-5f8f-8bda-377e874ddc92',array['Aktarma']::text[],array['Endişe','Günlük']::text[],'… aktarma yapıyorum, yetişebilecek miyim?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('95e7166c-2c1d-53cb-b006-5d630d9c142a','My … hasn''t arrived.','suitcase','My suitcase hasn''t arrived.','Valizim gelmedi.','[{"en":"My suitcase","tr":"valizim"},{"en":"hasn''t arrived","tr":"gelmedi"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Bagaj']::text[],array['Şikâyet']::text[],'… gelmedi.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('be891746-c71a-5fef-9dc4-6f2ee1f9802b','Is there a fee for …?','fee','Is there a fee for extra baggage?','Ek bagaj için ücret var mı?','[{"en":"Is there a fee","tr":"ücret var mı"},{"en":"for …","tr":"… için"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Havalimanı']::text[],array['Soru']::text[],'… için ücret var mı?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ccb90e91-1e01-5a8a-9d19-8838d3c3e092','I''d like to change my … to …','change','I''d like to change my flight to Friday.','Uçuşumu cumaya değiştirmek istiyorum.','[{"en":"I''d like to","tr":"-mek istiyorum"},{"en":"change my flight","tr":"uçuşumu değiştirmek"},{"en":"to Friday","tr":"cumaya"}]'::jsonb,'851477de-6cca-5819-9b94-be7428c7eb31',array['Havalimanı','Bilet']::text[],array['Kibar']::text[],'Uçuşumu … değiştirmek istiyorum.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d45132ca-99a0-5d66-8923-7f8a775f8688','Passengers … please proceed to gate …','proceed to','All passengers please proceed to gate 7.','Tüm yolcuların 7 numaralı kapıya ilerlemesi rica olunur.','[{"en":"please proceed","tr":"ilerlemesi rica olunur"},{"en":"to gate 7","tr":"7 numaralı kapıya"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Anons']::text[],array['Resmî']::text[],'… 7 numaralı kapıya ilerlemesi rica olunur.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3dc223d7-1c54-501f-ab65-850a90ca93c1','How long is the …?','delay','How long is the delay?','Rötar ne kadar?','[{"en":"How long","tr":"ne kadar"},{"en":"is the delay","tr":"rötar"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Havalimanı']::text[],array['Soru']::text[],'… ne kadar?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('5699a88a-e689-56cc-8d67-5e7e5fa0f443','I have nothing to …','declare','I have nothing to declare.','Beyan edecek bir şeyim yok.','[{"en":"I have nothing","tr":"hiçbir şeyim yok"},{"en":"to declare","tr":"beyan edecek"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Gümrük']::text[],array['Resmî']::text[],'… bir şeyim yok.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('89745699-e4c9-5fca-94f9-67cd7e0b23de','I''ll have the …, please.','have','I''ll have the grilled fish, please.','Izgara balık alayım, lütfen.','[{"en":"I''ll have","tr":"alayım"},{"en":"the grilled fish","tr":"ızgara balık"},{"en":"please","tr":"lütfen"}]'::jsonb,'851477de-6cca-5819-9b94-be7428c7eb31',array['Restoran']::text[],array['Kibar','Günlük']::text[],'… alayım, lütfen.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('dce151cb-3833-5416-b4ec-2187aeb6d747','Is it far from here to …?','far','Is it far from here to the old town?','Buradan eski şehre uzak mı?','[{"en":"Is it far","tr":"uzak mı"},{"en":"from here","tr":"buradan"},{"en":"to the old town","tr":"eski şehre"}]'::jsonb,'c36bc526-816e-5d15-843f-1b7cf3da1ff3',array['Yol sorma']::text[],array['Soru']::text[],'Buradan … uzak mı?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('36eeb9c0-2740-5c0e-b13c-707d666ecf28','Which line goes to …?','line','Which line goes to the airport?','Havalimanına hangi hat gidiyor?','[{"en":"Which line","tr":"hangi hat"},{"en":"goes to","tr":"-e gidiyor"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Ulaşım']::text[],array['Soru']::text[],'… hangi hat gidiyor?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('21e470f5-ee10-509a-997d-76b4678fcdb3','Does it come with …?','come with','Does it come with salad?','Yanında salata geliyor mu?','[{"en":"Does it come","tr":"geliyor mu"},{"en":"with salad","tr":"salatayla"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Restoran']::text[],array['Soru']::text[],'Yanında … geliyor mu?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('26fa24b6-373d-5ae9-be16-e859410db004','Can I pay by …?','pay by','Can I pay by card?','Kartla ödeyebilir miyim?','[{"en":"Can I pay","tr":"ödeyebilir miyim"},{"en":"by card","tr":"kartla"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Alışveriş','Restoran']::text[],array['Günlük']::text[],'… ödeyebilir miyim?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0e37ad8f-a94f-5e08-b8c6-7365fa2be26d','How much is a … ticket?','return','How much is a return ticket?','Gidiş-dönüş bilet ne kadar?','[{"en":"How much is","tr":"ne kadar"},{"en":"a return ticket","tr":"gidiş-dönüş bilet"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Ulaşım','Gezi']::text[],array['Soru']::text[],'… bilet ne kadar?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d85d5b83-792a-543f-918b-564e09f79e6f','What would you recommend for …?','recommend','What would you recommend for a first-time visitor?','İlk kez gelen biri için ne önerirsiniz?','[{"en":"What would you recommend","tr":"ne önerirsiniz"},{"en":"for …","tr":"… için"}]'::jsonb,'851477de-6cca-5819-9b94-be7428c7eb31',array['Gezi','Restoran']::text[],array['Kibar','Soru']::text[],'… için ne önerirsiniz?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b7b89da1-56c8-5f77-bb9c-e43e16478019','Is there a … near here?','pharmacy','Is there a pharmacy near here?','Yakınlarda bir eczane var mı?','[{"en":"Is there a","tr":"var mı"},{"en":"near here","tr":"yakınlarda"}]'::jsonb,'c36bc526-816e-5d15-843f-1b7cf3da1ff3',array['Yol sorma']::text[],array['Soru']::text[],'Yakınlarda … var mı?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ba54c4fa-5bd7-5314-a0e5-be8fc7ad5a62','We''ve booked a tour of … for …','booked','We''ve booked a tour of the palace for 10 am.','Saray için saat 10''a bir tur ayırttık.','[{"en":"We''ve booked","tr":"ayırttık"},{"en":"a tour of","tr":"… turu"},{"en":"for 10 am","tr":"saat 10''a"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Gezi']::text[],array['Günlük']::text[],'… bir tur ayırttık.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f78ffaec-8e2b-562d-ae1e-0ee3bd67a6df','Could you take a photo of …?','take a photo','Could you take a photo of us, please?','Bizim bir fotoğrafımızı çekebilir misiniz, lütfen?','[{"en":"Could you","tr":"-ebilir misiniz"},{"en":"take a photo","tr":"fotoğraf çekmek"},{"en":"of us","tr":"bizim"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Gezi']::text[],array['Kibar']::text[],'… fotoğrafını çekebilir misiniz, lütfen?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('941c4c6e-916d-5384-8046-80f95018b6ff','I''d like to book … for …','book','I''d like to book a double room for three nights.','Üç gece için çift kişilik bir oda ayırtmak istiyorum.','[{"en":"I''d like to","tr":"-mak istiyorum"},{"en":"book","tr":"ayırtmak"},{"en":"for three nights","tr":"üç gece için"}]'::jsonb,'851477de-6cca-5819-9b94-be7428c7eb31',array['Rezervasyon']::text[],array['Kibar']::text[],'… için … ayırtmak istiyorum.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('9c2dfc91-1dec-5439-b0f1-4f4662afbc5c','Could I have your …, please?','have','Could I have your passport, please?','Pasaportunuzu alabilir miyim, lütfen?','[{"en":"Could I have","tr":"alabilir miyim"},{"en":"your passport","tr":"pasaportunuz"},{"en":"please","tr":"lütfen"}]'::jsonb,'851477de-6cca-5819-9b94-be7428c7eb31',array['Resepsiyon']::text[],array['Kibar']::text[],'…(-nizi) alabilir miyim, lütfen?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c2d2445f-0893-5fcf-8733-1493f4cfc2f3','I''m afraid there''s a problem with …','afraid','I''m afraid there''s a problem with my room.','Korkarım odamla ilgili bir sorun var.','[{"en":"I''m afraid","tr":"korkarım, maalesef"},{"en":"there''s a problem","tr":"bir sorun var"},{"en":"with my room","tr":"odamla ilgili"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['Şikâyet']::text[],array['Kibar']::text[],'Korkarım … ilgili bir sorun var.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('da3e5683-ff76-5c9e-909f-4cb5705d1a87','Would you like …?','like','Would you like a wake-up call?','Uyandırma servisi ister misiniz?','[{"en":"Would you like","tr":"ister misiniz"},{"en":"a wake-up call","tr":"teklif edilen şey"}]'::jsonb,'851477de-6cca-5819-9b94-be7428c7eb31',array['Resepsiyon','Öneri']::text[],array['Kibar']::text[],'… ister misiniz?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d5f6fc47-060a-540a-886a-8ca0ced679a4','Is … included in the price?','included','Is breakfast included in the price?','Kahvaltı fiyata dahil mi?','[{"en":"Is breakfast","tr":"kahvaltı … mı"},{"en":"included","tr":"dahil"},{"en":"in the price","tr":"fiyata"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Rezervasyon']::text[],array['Günlük']::text[],'… fiyata dahil mi?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('30e5e409-4d74-53ac-a9a4-3b3e8aa130c0','I''ll send someone to … right away.','send someone','I''ll send someone to fix it right away.','Hemen tamir etmesi için birini göndereceğim.','[{"en":"I''ll","tr":"-acağım"},{"en":"send someone","tr":"birini göndermek"},{"en":"right away","tr":"hemen"}]'::jsonb,'4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5',array['Şikâyet karşılama']::text[],array['Resmî']::text[],'Hemen … birini göndereceğim.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('38dae450-3cd4-54cc-a95c-5ad5cb1040a3','How do I get to …?','get to','How do I get to the museum from here?','Buradan müzeye nasıl giderim?','[{"en":"How do I","tr":"nasıl"},{"en":"get to","tr":"-e ulaşmak, gitmek"},{"en":"the museum","tr":"yer"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Yol tarifi']::text[],array['Günlük']::text[],'…(-e) nasıl giderim?','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('12494556-20cd-59cf-84ae-fc962fbcc027','It''s a …-minute walk from here.','minute walk','It''s a ten-minute walk from here.','Buradan on dakikalık yürüme mesafesinde.','[{"en":"It''s a","tr":"-dir"},{"en":"ten-minute walk","tr":"on dakikalık yürüyüş"},{"en":"from here","tr":"buradan"}]'::jsonb,'d5774794-79d5-5598-b2ee-b28a68901a09',array['Yol tarifi']::text[],array['Günlük']::text[],'Buradan … dakikalık yürüme mesafesinde.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('65c73b91-c410-508d-94be-30e2a6e79e98','Unfortunately, we don''t have …','don''t have','Unfortunately, we don''t have any rooms with a balcony left.','Maalesef balkonlu odamız kalmadı.','[{"en":"Unfortunately","tr":"maalesef"},{"en":"we don''t have","tr":"(bizde) yok"},{"en":"any rooms","tr":"hiç oda"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Resepsiyon']::text[],array['Kibar']::text[],'Maalesef … yok.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c288623b-9f16-598c-a509-47cf63a8759e','If you need anything, please …','call','If you need anything, please call reception.','Bir şeye ihtiyacınız olursa lütfen resepsiyonu arayın.','[{"en":"If you need anything","tr":"bir şeye ihtiyacınız olursa"},{"en":"please","tr":"lütfen"},{"en":"call reception","tr":"resepsiyonu arayın"}]'::jsonb,'3bf15cc6-24b0-5ade-bd72-578e2cc35706',array['Resepsiyon']::text[],array['Kibar']::text[],'Bir şeye ihtiyacınız olursa lütfen …','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c05b1a7e-f245-527a-b8ce-551e51fd5a75','Although …, …','Although','Although the test was difficult, most students passed.','Sınav zor olmasına rağmen öğrencilerin çoğu geçti.','[{"en":"Although","tr":"-e rağmen (+ cümle)"},{"en":"the test was difficult","tr":"sınav zordu"},{"en":"most students passed","tr":"öğrencilerin çoğu geçti"}]'::jsonb,'18bb25a1-8990-5403-bef1-60ed86047678',array['Cümle tamamlama']::text[],array['Akademik']::text[],'… olmasına rağmen öğrencilerin çoğu geçti.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a308e396-daed-5e15-8493-d90b33730bd0','Despite …, …','Despite','Despite the rain, the event was a success.','Yağmura rağmen etkinlik başarılı geçti.','[{"en":"Despite","tr":"-e rağmen (+ isim)"},{"en":"the rain","tr":"yağmur"},{"en":"the event was a success","tr":"etkinlik başarılıydı"}]'::jsonb,'18bb25a1-8990-5403-bef1-60ed86047678',array['Cümle tamamlama']::text[],array['Akademik']::text[],'… rağmen etkinlik başarılı geçti.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('47739fcc-552d-50cf-a5f0-3088a32d88f9','…, whereas …','whereas','Some species adapt quickly, whereas others die out.','Bazı türler hızla uyum sağlarken diğerleri yok oluyor.','[{"en":"Some species adapt quickly","tr":"bazı türler hızla uyum sağlar"},{"en":"whereas","tr":"oysa, -iken"},{"en":"others die out","tr":"diğerleri yok olur"}]'::jsonb,'18bb25a1-8990-5403-bef1-60ed86047678',array['Cümle tamamlama','Paragraf']::text[],array['Akademik']::text[],'Bazı türler hızla uyum sağlarken diğerleri ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('8e266ee9-5c45-5ac3-a74b-fc5c7672ee47','…; however, …','however','The method is cheap; however, it is not very accurate.','Yöntem ucuz; ancak çok hassas değil.','[{"en":"The method is cheap","tr":"yöntem ucuz"},{"en":"however","tr":"ancak"},{"en":"it is not very accurate","tr":"karşıt bilgi"}]'::jsonb,'18bb25a1-8990-5403-bef1-60ed86047678',array['Paragraf','Cümle tamamlama']::text[],array['Akademik']::text[],'Yöntem ucuz; ancak ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('741d4a17-0c9c-596b-b053-aa2e824c1ea8','…; therefore, …','therefore','Fuel prices rose sharply; therefore, airline tickets became more expensive.','Yakıt fiyatları keskin biçimde arttı; bu nedenle uçak biletleri pahalandı.','[{"en":"Fuel prices rose sharply","tr":"yakıt fiyatları keskin biçimde arttı"},{"en":"therefore","tr":"bu nedenle"},{"en":"airline tickets became more expensive","tr":"sonuç"}]'::jsonb,'1b0b85f6-765e-57cd-838b-8e483d2c0e86',array['Paragraf','Cümle tamamlama']::text[],array['Akademik']::text[],'Yakıt fiyatları keskin biçimde arttı; bu nedenle ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('491fdfae-8975-5b64-8f3e-a20c495494e6','… because of …','because of','The match was postponed because of heavy snow.','Maç yoğun kar yüzünden ertelendi.','[{"en":"The match was postponed","tr":"maç ertelendi"},{"en":"because of","tr":"yüzünden (+ isim)"},{"en":"heavy snow","tr":"neden"}]'::jsonb,'1b0b85f6-765e-57cd-838b-8e483d2c0e86',array['Cümle tamamlama']::text[],array['Akademik']::text[],'Maç şu yüzden ertelendi: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c564e1d1-c506-558a-b3f2-0faf2fb1a93b','… so that …','so that','She saved money so that she could study abroad.','Yurt dışında okuyabilmek için para biriktirdi.','[{"en":"She saved money","tr":"para biriktirdi"},{"en":"so that","tr":"-sın diye, -mek için"},{"en":"she could study abroad","tr":"amaç"}]'::jsonb,'1b0b85f6-765e-57cd-838b-8e483d2c0e86',array['Cümle tamamlama']::text[],array['Akademik']::text[],'Şunu yapabilmek için para biriktirdi: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('40d0887e-dd6d-5339-a2b9-90f7f45c5c3a','Unlike …, …','Unlike','Unlike her brother, she enjoys math.','Erkek kardeşinin aksine matematiği seviyor.','[{"en":"Unlike her brother","tr":"ağabeyinin aksine"},{"en":"she enjoys math","tr":"matematiği seviyor"}]'::jsonb,'18bb25a1-8990-5403-bef1-60ed86047678',array['Cümle tamamlama']::text[],array['Akademik']::text[],'… aksine matematiği seviyor.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f87f9b2d-a453-5086-a2db-d9df4d2d27ce','…. In contrast, …','In contrast','Northern cities are cold. In contrast, southern cities are warm.','Kuzey şehirleri soğuk. Buna karşılık güney şehirleri sıcak.','[{"en":"Northern cities are cold","tr":"kuzey şehirleri soğuk"},{"en":"In contrast","tr":"buna karşılık"},{"en":"southern cities are warm","tr":"karşıt bilgi"}]'::jsonb,'18bb25a1-8990-5403-bef1-60ed86047678',array['Paragraf']::text[],array['Akademik']::text[],'Kuzey şehirleri soğuk. Buna karşılık ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('051fdaf0-b840-5e97-8f70-f497e7bc526c','…; otherwise, …','otherwise','Save your work often; otherwise, you may lose it.','Çalışmanı sık sık kaydet; aksi takdirde kaybedebilirsin.','[{"en":"Save your work often","tr":"çalışmanı sık kaydet"},{"en":"otherwise","tr":"aksi takdirde"},{"en":"you may lose it","tr":"olası sonuç"}]'::jsonb,'1b0b85f6-765e-57cd-838b-8e483d2c0e86',array['Cümle tamamlama']::text[],array['Akademik']::text[],'Çalışmanı sık sık kaydet; aksi takdirde ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('9db36306-fe3c-5d1b-bbea-8ac38cf71dc2','… increased from … to …','from','The price increased from 10 to 15 dollars.','Fiyat 10 dolardan 15 dolara çıktı.','[{"en":"The price increased","tr":"fiyat arttı"},{"en":"from 10","tr":"10''dan"},{"en":"to 15 dollars","tr":"15 dolara"}]'::jsonb,'720f608f-5573-5769-bc14-e12bd1dbaa95',array['Grafik']::text[],array['Akademik']::text[],'Fiyat … çıktı.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('59a7a2e0-846d-5b5c-bdd1-eac4c14ea33b','… has risen since …','has risen','The number of users has risen since 2020.','Kullanıcı sayısı 2020''den beri arttı.','[{"en":"The number of users","tr":"kullanıcı sayısı"},{"en":"has risen","tr":"arttı (ve etkisi sürüyor)"},{"en":"since 2020","tr":"2020''den beri"}]'::jsonb,'c2448d19-7c6a-5373-b84f-f0ecdb345163',array['Grafik','Paragraf']::text[],array['Akademik']::text[],'Kullanıcı sayısı şundan beri arttı: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3596ab13-2220-56c8-9621-91e020c26711','There was a … rise in …','in','There was a sharp rise in food prices.','Gıda fiyatlarında keskin bir artış oldu.','[{"en":"There was","tr":"oldu"},{"en":"a sharp rise","tr":"keskin bir artış"},{"en":"in food prices","tr":"gıda fiyatlarında"}]'::jsonb,'720f608f-5573-5769-bc14-e12bd1dbaa95',array['Grafik']::text[],array['Akademik']::text[],'Şunda keskin bir artış oldu: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f1de5645-020e-5650-8cce-58a1314f2ad0','… fell by …','by','Unemployment fell by two percentage points.','İşsizlik iki yüzde puan düştü.','[{"en":"Unemployment fell","tr":"işsizlik düştü"},{"en":"by","tr":"… kadar (değişim miktarı)"},{"en":"two percentage points","tr":"miktar"}]'::jsonb,'720f608f-5573-5769-bc14-e12bd1dbaa95',array['Grafik']::text[],array['Akademik']::text[],'İşsizlik şu kadar düştü: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('90c1b6e1-c1d7-5d96-97ce-bc88f62844d0','The number of … has …','The number of','The number of students has grown.','Öğrenci sayısı arttı.','[{"en":"The number of","tr":"… sayısı (tekil)"},{"en":"students","tr":"sayılan şey"},{"en":"has grown","tr":"arttı"}]'::jsonb,'c2448d19-7c6a-5373-b84f-f0ecdb345163',array['Grafik','Paragraf']::text[],array['Akademik']::text[],'… sayısı arttı.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c5cc0df3-9d95-5b15-8249-397e06245ade','… -er than in …','than','Sales were higher than in 2022.','Satışlar 2022''dekinden daha yüksekti.','[{"en":"Sales were higher","tr":"satışlar daha yüksekti"},{"en":"than","tr":"-den"},{"en":"in 2022","tr":"karşılaştırılan"}]'::jsonb,'456ec5da-d7b5-550b-9e0c-056b23139658',array['Grafik']::text[],array['Akademik']::text[],'Satışlar şundan daha yüksekti: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('74f8fdaa-2059-5ee6-98f4-9cef001337e2','… remained … throughout …','throughout','Prices remained stable throughout the year.','Fiyatlar yıl boyunca sabit kaldı.','[{"en":"Prices remained stable","tr":"fiyatlar sabit kaldı"},{"en":"throughout","tr":"boyunca"},{"en":"the year","tr":"süre"}]'::jsonb,'720f608f-5573-5769-bc14-e12bd1dbaa95',array['Grafik']::text[],array['Akademik']::text[],'Fiyatlar şu süre boyunca sabit kaldı: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6f808e3d-df3a-53e3-8288-496eb9e7a3f2','… accounted for … of …','accounted for','Women accounted for 60% of the participants.','Katılımcıların %60''ını kadınlar oluşturuyordu.','[{"en":"Women","tr":"kadınlar"},{"en":"accounted for","tr":"oluşturuyordu"},{"en":"60% of the participants","tr":"pay"}]'::jsonb,'720f608f-5573-5769-bc14-e12bd1dbaa95',array['Grafik','Paragraf']::text[],array['Akademik']::text[],'Kadınlar şunu oluşturuyordu: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('42f6f17c-860c-5653-aff9-c218425a59a7','… tend to …','tend to','Older people tend to use fewer apps.','Yaşlı insanlar daha az uygulama kullanma eğiliminde.','[{"en":"Older people","tr":"yaşlı insanlar"},{"en":"tend to","tr":"… eğilimindedir"},{"en":"use fewer apps","tr":"davranış"}]'::jsonb,'bfcf9a85-caf2-5d11-b852-1fdd48d940df',array['Paragraf']::text[],array['Temkinli']::text[],'Yaşlı insanlar şu eğilimde: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('4248f873-b86f-5f7b-8444-9e6136ab04c1','By the end of …, …','By the end of','By the end of 2030, the population will reach 90 million.','2030 sonuna kadar nüfus 90 milyona ulaşacak.','[{"en":"By the end of 2030","tr":"2030 sonuna kadar"},{"en":"the population will reach","tr":"nüfus ulaşacak"},{"en":"90 million","tr":"değer"}]'::jsonb,'4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5',array['Tahmin','Paragraf']::text[],array['Akademik']::text[],'… sonuna kadar nüfus 90 milyona ulaşacak.','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('4c6a8ae5-21b6-508c-82a9-9df47b76da57','The results suggest that …','suggest that','The results suggest that exercise improves memory.','Sonuçlar egzersizin hafızayı geliştirdiğini düşündürüyor.','[{"en":"The results","tr":"sonuçlar"},{"en":"suggest that","tr":"-dığını düşündürüyor (temkinli)"},{"en":"exercise improves memory","tr":"bulgu"}]'::jsonb,'bfcf9a85-caf2-5d11-b852-1fdd48d940df',array['Akademik metin']::text[],array['Temkinli']::text[],'Sonuçlar şunu düşündürüyor: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('9ff6ccc1-c387-514e-9147-ef4c5603a985','It has been shown that …','has been shown','It has been shown that bilingual children learn faster.','İki dilli çocukların daha hızlı öğrendiği gösterilmiştir.','[{"en":"It has been shown","tr":"gösterilmiştir"},{"en":"that","tr":"-dığı"},{"en":"bilingual children learn faster","tr":"bulgu"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Akademik metin']::text[],array['Resmî']::text[],'Şu gösterilmiştir: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('735d5503-77b9-568d-b56d-6b379ac285ba','a study which …','which','This is a study which examined 500 schools.','Bu, 500 okulu inceleyen bir çalışma.','[{"en":"a study","tr":"bir çalışma"},{"en":"which","tr":"ki o (nesne için)"},{"en":"examined 500 schools","tr":"açıklama"}]'::jsonb,'5745b079-cf8a-5e9d-9c2f-f10b9ed53ed7',array['Akademik metin']::text[],array['Resmî']::text[],'Bu, şunu yapan bir çalışma: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6e1b2230-e0df-568f-9853-14657f00ed5d','Participants who …','who','Participants who slept less made more errors.','Daha az uyuyan katılımcılar daha çok hata yaptı.','[{"en":"Participants","tr":"katılımcılar"},{"en":"who slept less","tr":"daha az uyuyan"},{"en":"made more errors","tr":"daha çok hata yaptı"}]'::jsonb,'5745b079-cf8a-5e9d-9c2f-f10b9ed53ed7',array['Akademik metin']::text[],array['Resmî']::text[],'Şu katılımcılar daha çok hata yaptı: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('2194e5c3-6f95-56b8-8095-110bbd026f15','The aim of this study is to …','The aim of this study is','The aim of this study is to investigate the effects of noise.','Bu çalışmanın amacı gürültünün etkilerini araştırmaktır.','[{"en":"The aim of this study","tr":"bu çalışmanın amacı"},{"en":"is","tr":"-dır"},{"en":"to investigate …","tr":"amaç (to + fiil)"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Akademik metin']::text[],array['Resmî']::text[],'Bu çalışmanın amacı şudur: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('1e3c5c5e-57ed-558e-ad1a-cad3718a7e4a','Further research is needed to …','is needed','Further research is needed to confirm these results.','Bu sonuçları doğrulamak için daha fazla araştırma gerekiyor.','[{"en":"Further research","tr":"daha fazla araştırma"},{"en":"is needed","tr":"gerekiyor"},{"en":"to confirm these results","tr":"amaç"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Akademik metin']::text[],array['Temkinli']::text[],'Şunun için daha fazla araştırma gerekiyor: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b14c58ed-bf4a-5314-977d-1a7a5100be9e','… is associated with …','is associated with','Poor sleep is associated with lower grades.','Kötü uyku daha düşük notlarla ilişkilidir.','[{"en":"Poor sleep","tr":"kötü uyku"},{"en":"is associated with","tr":"ile ilişkilidir"},{"en":"lower grades","tr":"ilişkili durum"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Akademik metin']::text[],array['Temkinli']::text[],'Kötü uyku şununla ilişkilidir: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c5000994-55ac-5438-b1df-10a0fe4d88ef','Researchers found that …','found','Researchers found that the treatment reduced pain.','Araştırmacılar tedavinin ağrıyı azalttığını buldu.','[{"en":"Researchers","tr":"araştırmacılar"},{"en":"found that","tr":"-dığını buldu"},{"en":"the treatment reduced pain","tr":"bulgu"}]'::jsonb,'bfcf9a85-caf2-5d11-b852-1fdd48d940df',array['Akademik metin']::text[],array['Nötr']::text[],'Araştırmacılar şunu buldu: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('750a5315-59d1-5856-80a4-c557b8b6e153','It is likely that …','likely','It is likely that the trend will continue.','Eğilimin devam etmesi muhtemeldir.','[{"en":"It is likely","tr":"muhtemeldir"},{"en":"that","tr":"-mesi"},{"en":"the trend will continue","tr":"olasılık"}]'::jsonb,'bfcf9a85-caf2-5d11-b852-1fdd48d940df',array['Akademik metin']::text[],array['Temkinli']::text[],'Şu muhtemeldir: ….','draft') on conflict do nothing;
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('18bcc1b4-db45-5082-96a1-43ad5c59a639','This may be due to …','due to','This may be due to the small sample size.','Bu, küçük örneklem büyüklüğünden kaynaklanıyor olabilir.','[{"en":"This may be","tr":"bu … olabilir"},{"en":"due to","tr":"-den kaynaklanan"},{"en":"the small sample size","tr":"olası neden"}]'::jsonb,'1b0b85f6-765e-57cd-838b-8e483d2c0e86',array['Akademik metin']::text[],array['Temkinli']::text[],'Bu, şundan kaynaklanıyor olabilir: ….','draft') on conflict do nothing;
