insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('428f3995-20b2-507d-b705-dc13d8cba805','f09dfa1f-eed0-5346-96f6-634586a50e09','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"It depends on whether we get the funding.","options":["Projede bana yardım eden iş arkadaşı o.","Fonu alıp almamamıza bağlı.","Dün yayımlanan rapor fiyatlarda bir artış gösteriyor.","Çok çalışmasına rağmen yarışı kazanamadı."]}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Projede bana yardım eden iş arkadaşı o.":"Bu, “She''s the colleague who helped me with the project.” cümlesinin anlamı.","Dün yayımlanan rapor fiyatlarda bir artış gösteriyor.":"Bu, “The report, which was published yesterday, shows a rise in prices.” cümlesinin anlamı.","Çok çalışmasına rağmen yarışı kazanamadı.":"Bu, “Although he trained hard, he didn''t win the race.” cümlesinin anlamı."}'::jsonb,'It depends on whether we get the funding. = Fonu alıp almamamıza bağlı.',3,'draft') on conflict do nothing;
