insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('1453edd3-1b65-5266-8d71-c03f1993c0c7','17b3f424-c7c4-589c-911f-5fb9bce66daf','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Supervisor","en":"You write that social media ''causes'' anxiety. Can you prove that?"},{"speaker":"Supervisor","en":"Good. And what about your sample?"}],"options":["The sample is perfect, no problem.","One limitation is that the sample only included university students, so the results may not apply to other groups.","One limitations is the sample."],"scenario_id":"cfdcb320-8396-5113-bb28-5fc95234c7a2"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"The sample is perfect, no problem.":"Akademik değerlendirme yok.","One limitations is the sample.":"“One” sonrası tekil gelir."}'::jsonb,'Sınırlılık temkinli dille açıklanmış.',4,'draft') on conflict do nothing;
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('5a917de5-07e9-5721-a090-99dc1d24d252','139db3f3-c499-5502-9bce-7398df4d7307','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Client","en":"Why was our order delayed by two weeks?"}],"options":["Because our supplier did bad.","With regard to the delay, it was due to a shortage of components at our supplier.","With regarding the delay, because shortage."],"scenario_id":"1ffbc8ae-5e3b-5549-93b0-08f33429926b"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Because our supplier did bad.":"Resmî değil ve belirsiz.","With regarding the delay, because shortage.":"Kalıp bozuk ve cümle eksik."}'::jsonb,'Resmî bağlantı ve isimleştirme doğru.',4,'draft') on conflict do nothing;
