insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('b7fb0793-f24d-53da-bd2d-f1980a9984d2','97197712-53c6-5916-bfd6-0719b845c90e','listen_choice','listening','{"instruction_tr":"Cümleyi dinle. Anlamı hangisi?","audio_text":"The plan worked, albeit more slowly than expected.","options":["Bütçe kesintisi her toplantıda herkesin bildiği ama konuşmadığı konuydu.","Onun vaatlerine ihtiyatla yaklaşırdım.","Lafı dolandırmayı bırak da ne olduğunu anlat.","Plan, beklenenden daha yavaş da olsa işe yaradı."]}'::jsonb,'{"index":3}'::jsonb,array[]::text[],'{"Onun vaatlerine ihtiyatla yaklaşırdım.":"Bu, “take with a pinch of salt” örneğinin çevirisi.","Lafı dolandırmayı bırak da ne olduğunu anlat.":"Bu, “beat around the bush” örneğinin çevirisi.","Bütçe kesintisi her toplantıda herkesin bildiği ama konuşmadığı konuydu.":"Bu, “the elephant in the room” örneğinin çevirisi."}'::jsonb,'“The plan worked, albeit more slowly than expected.” = Plan, beklenenden daha yavaş da olsa işe yaradı.',5,'draft') on conflict do nothing;
