insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('38997152-43af-5e77-bc1b-e7cb1cd41245','2de9615d-c776-56c5-b91a-13b018b45136','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"I suggest that he be informed immediately.","options":["Her başvuru sahibinin formu cumaya kadar teslim etmesi şart.","Daha düzenli biri olsaydım son teslim tarihini kaçırmazdım.","O işi kabul etseydim şimdi Berlin''de yaşıyor olurdum.","Ona hemen haber verilmesini öneririm."]}'::jsonb,'{"index":3}'::jsonb,array[]::text[],'{"Her başvuru sahibinin formu cumaya kadar teslim etmesi şart.":"Bu, “It is essential that every applicant submit the form by Friday.” cümlesinin anlamı.","O işi kabul etseydim şimdi Berlin''de yaşıyor olurdum.":"Bu, “If I had taken that job, I would be living in Berlin now.” cümlesinin anlamı.","Daha düzenli biri olsaydım son teslim tarihini kaçırmazdım.":"Bu, “If I were more organised, I wouldn''t have missed the deadline.” cümlesinin anlamı."}'::jsonb,'I suggest that he be informed immediately. = Ona hemen haber verilmesini öneririm.',5,'draft') on conflict do nothing;
