insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('ebc7ae4d-bacb-555f-9ae5-4a91027415df','bfc81c3d-61ff-5d25-a16c-1aaad5f1dccc','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Chair","en":"Let''s discuss the launch date. What''s your recommendation?"},{"speaker":"Chair","en":"But the marketing campaign has already started."}],"options":["Despite the campaign is started, safety important.","Notwithstanding of the campaign, the product must safe.","Notwithstanding the campaign, it is imperative that the product be safe. Frankly, that''s the elephant in the room."],"scenario_id":"33307968-8c84-57a3-aae1-acdab5061efc"}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"Despite the campaign is started, safety important.":"“Despite” sonrası cümle gelmez; fiil eksik.","Notwithstanding of the campaign, the product must safe.":"“notwithstanding” edat almaz ve fiil eksik."}'::jsonb,'Çok resmî edat, subjunctive ve deyim doğru.',5,'draft') on conflict do nothing;
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('09e3d206-eae3-578d-b8c6-13897aa5ac0a','02ca0735-6345-5aa7-b3c1-196d44b3bed7','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Emre","en":"Don''t beat around the bush. What do you really think of my plan?"}],"options":["Honestly, it''s bad.","Honestly, the idea is great, but you''ve cut corners on the financial part.","Honestly, you cut the corner on finance."],"scenario_id":"f43f57e1-5a76-5c76-b380-c428558dce3f"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Honestly, it''s bad.":"Gerekçesiz ve yapıcı değil.","Honestly, you cut the corner on finance.":"Deyim “cut corners” (çoğul, tanımlıksız)."}'::jsonb,'Deyim doğru ve geri bildirim yapıcı.',5,'draft') on conflict do nothing;
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('644c17c9-bd77-5462-959c-38a91d8af697','02ca0735-6345-5aa7-b3c1-196d44b3bed7','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Emre","en":"Don''t beat around the bush. What do you really think of my plan?"},{"speaker":"Emre","en":"You''ve hit the nail on the head. I wasn''t sure about the numbers."}],"options":["If I were you, I''d get an accountant to check them. Had I done that with my café, I''d be in a much better position now.","If I had done that, I would have be better now.","Had I did that, I''d be better now."],"scenario_id":"f43f57e1-5a76-5c76-b380-c428558dce3f"}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"If I had done that, I would have be better now.":"Karma koşulda “I would be … now”.","Had I did that, I''d be better now.":"Devrik koşulda “Had I done”."}'::jsonb,'Tavsiye ve devrik karma koşul doğru.',5,'draft') on conflict do nothing;
