insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('c560312a-3f87-5a67-84ae-086a25f0b6ed','4f39a8aa-edac-50f3-ba36-7e99723f61f4','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"Having finished her degree, she moved to Lisbon.","options":["Ne diyeceğimi bilemeyince sadece gülümsedim.","1890''da inşa edilen köprü hâlâ kullanılıyor.","Koşullar göz önüne alındığında istifa etmesi şaşırtıcı değil.","Diplomasını aldıktan sonra Lizbon''a taşındı."]}'::jsonb,'{"index":3}'::jsonb,array[]::text[],'{"Ne diyeceğimi bilemeyince sadece gülümsedim.":"Bu, “Not knowing what to say, I just smiled.” cümlesinin anlamı.","1890''da inşa edilen köprü hâlâ kullanılıyor.":"Bu, “Built in 1890, the bridge is still in use.” cümlesinin anlamı.","Koşullar göz önüne alındığında istifa etmesi şaşırtıcı değil.":"Bu, “Given the circumstances, it''s not surprising that he resigned.” cümlesinin anlamı."}'::jsonb,'Having finished her degree, she moved to Lisbon. = Diplomasını aldıktan sonra Lizbon''a taşındı.',5,'draft') on conflict do nothing;
