insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('26aa69ea-4808-5eee-af5b-d2b37c03bdce','3ed1ffb4-477b-537a-82c3-df636bdc7e72','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"Not knowing what to say, I just smiled.","options":["Ne diyeceğimi bilemeyince sadece gülümsedim.","Koşullar göz önüne alındığında istifa etmesi şaşırtıcı değil.","1890''da inşa edilen köprü hâlâ kullanılıyor.","Yarın yağmur yağacak mı? — Umarım yağmaz."]}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"1890''da inşa edilen köprü hâlâ kullanılıyor.":"Bu, “Built in 1890, the bridge is still in use.” cümlesinin anlamı.","Koşullar göz önüne alındığında istifa etmesi şaşırtıcı değil.":"Bu, “Given the circumstances, it''s not surprising that he resigned.” cümlesinin anlamı.","Yarın yağmur yağacak mı? — Umarım yağmaz.":"Bu, “Will it rain tomorrow? — I hope not.” cümlesinin anlamı."}'::jsonb,'Not knowing what to say, I just smiled. = Ne diyeceğimi bilemeyince sadece gülümsedim.',5,'draft') on conflict do nothing;
