insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('7f69b072-2a02-5403-88a1-e5d8f4a6d1fe','46d52875-ac85-5e16-a901-3a31b3c1ea9a','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"Built in 1890, the bridge is still in use.","options":["Yarın yağmur yağacak mı? — Umarım yağmaz.","Koşullar göz önüne alındığında istifa etmesi şaşırtıcı değil.","Dilerseniz üyeliğinizi iptal edebilirsiniz.","1890''da inşa edilen köprü hâlâ kullanılıyor."]}'::jsonb,'{"index":3}'::jsonb,array[]::text[],'{"Koşullar göz önüne alındığında istifa etmesi şaşırtıcı değil.":"Bu, “Given the circumstances, it''s not surprising that he resigned.” cümlesinin anlamı.","Yarın yağmur yağacak mı? — Umarım yağmaz.":"Bu, “Will it rain tomorrow? — I hope not.” cümlesinin anlamı.","Dilerseniz üyeliğinizi iptal edebilirsiniz.":"Bu, “You may cancel your membership if you wish to do so.” cümlesinin anlamı."}'::jsonb,'Built in 1890, the bridge is still in use. = 1890''da inşa edilen köprü hâlâ kullanılıyor.',5,'draft') on conflict do nothing;
