insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('5a0f2b63-b933-5dc5-9dcd-cc2e541eee46','3bd2368d-3b3c-5f47-abf8-0579ac8f6aab','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"You can withdraw your consent by changing your settings.","options":["Sözleşmenizin şartlarına göre bir ay önceden bildirimde bulunmalısınız.","Her çalışanın 14 gün ücretli izin hakkı vardır.","Ayarlarınızı değiştirerek rızanızı geri çekebilirsiniz.","İstifamı bildirmek için yazıyorum."]}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"Sözleşmenizin şartlarına göre bir ay önceden bildirimde bulunmalısınız.":"Bu, “Under the terms of your contract, you must give one month''s notice.” cümlesinin anlamı.","Her çalışanın 14 gün ücretli izin hakkı vardır.":"Bu, “Every employee is entitled to 14 days of paid leave.” cümlesinin anlamı.","İstifamı bildirmek için yazıyorum.":"Bu, “I am writing to give notice of my resignation.” cümlesinin anlamı."}'::jsonb,'You can withdraw your consent by changing your settings. = Ayarlarınızı değiştirerek rızanızı geri çekebilirsiniz.',3,'draft') on conflict do nothing;
