insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('d97752b9-068b-5017-8ed8-ec8cedd11ae3','ed17308c-ff97-51fe-9ae8-40c0a5dfdd87','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"HR","en":"Hi, you wanted to talk to me?"},{"speaker":"HR","en":"Under the terms of your employment contract, it''s four weeks. You''ll need to put it in writing."}],"options":["Of course. I''ll send you a formal letter today. Am I entitled to my unused leave?","OK. Can I don''t work the four weeks?","Writing is not necessary."],"scenario_id":"83e4f848-4ca9-5290-8551-7a38736ee546"}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"OK. Can I don''t work the four weeks?":"Soru yapısı bozuk.","Writing is not necessary.":"Sözleşme şartına aykırı."}'::jsonb,'Süreci kabul edip hakkını kibarca soruyor.',3,'draft') on conflict do nothing;
