insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('aa31b5f3-fda5-5554-a432-0cd16f942755','8a7b1308-47ec-5620-bca8-8b81d8d29626','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Lecturer","en":"Can you describe the trend in sales?"}],"options":["Sales increased steady from 2015 to 2019.","Sales has increase from 2015 to 2019.","Sales increased steadily from 2015 to 2019 and reached a peak in 2020."],"scenario_id":"fe40c5ab-c9ec-5af1-8c5e-f427e0fd11c3"}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"Sales increased steady from 2015 to 2019.":"Fiili niteleyen zarf gerekir: steadily.","Sales has increase from 2015 to 2019.":"Çoğul özne ve fiil biçimi yanlış; bitmiş dönem için past simple gerekir."}'::jsonb,'Zarf, zaman ve “reach a peak” kalıbı doğru.',3,'draft') on conflict do nothing;
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('dce26e62-f0d6-54da-8514-0f87da3cd665','8a7b1308-47ec-5620-bca8-8b81d8d29626','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Lecturer","en":"Can you describe the trend in sales?"},{"speaker":"Lecturer","en":"And what happened after 2020?"}],"options":["They have fallen in 2021 by slightly.","They fell slight and then leveled up.","They fell slightly and then leveled off."],"scenario_id":"fe40c5ab-c9ec-5af1-8c5e-f427e0fd11c3"}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"They have fallen in 2021 by slightly.":"Belirli bir yılla present perfect kullanılmaz; “by slightly” yanlış.","They fell slight and then leveled up.":"Zarf gerekir (slightly); “level up” seviye atlamak demektir."}'::jsonb,'Hafif düşüşü ve sabitlenmeyi doğru anlatıyor.',3,'draft') on conflict do nothing;
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('74915a96-3025-58e6-915c-55681b4d9bef','94696ac6-ac6e-5a6e-aa72-5f7813d67e59','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Friend","en":"The report says women accounted for 60% of the participants. What does that mean?"}],"options":["It means that six out of ten participants were women.","It means that women counted the participants.","It means that exactly 60 women took part."],"scenario_id":"32d1bc34-393a-5e7d-8eab-6732a4e7908d"}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"It means that women counted the participants.":"“account for” burada saymak anlamında değildir.","It means that exactly 60 women took part.":"Oran ile sayı karıştırılmış; toplam katılımcı sayısı verilmiyor."}'::jsonb,'“account for” burada “oluşturmak” demektir.',2,'draft') on conflict do nothing;
