insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('596c81f6-fa62-5119-80bf-479999c95c98','4a71443f-7aec-54e4-8fac-e8634d80e98e','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Classmate","en":"The abstract says: ''The findings suggest that exercise may improve memory in older adults.'' What does that mean?"},{"speaker":"Classmate","en":"So was their hypothesis supported?"}],"options":["Yes, so no further research is needed.","Partly. The results point in that direction, but they are not conclusive.","No, because the hypothesis was a participant."],"scenario_id":"2395615d-48ce-59f6-bacb-a46363b07e11"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Yes, so no further research is needed.":"Temkinli bulgular kesin sonuç sayılmaz; çıkarım yanlış.","No, because the hypothesis was a participant.":"Hipotez bir katılımcı değildir; anlamsız."}'::jsonb,'Temkinli bulguyu doğru yorumluyor.',3,'draft') on conflict do nothing;
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('a0f01f2b-bd12-5db8-bea8-6cbda55a8d61','83cc93e4-da20-54fa-8a46-a4fec28d34a7','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Professor","en":"What is one limitation of this study?"}],"options":["The sample was very small, so the results are more reliable.","The sample was very small, so the results may not be reliable.","The limitation is that the study was conducted."],"scenario_id":"9a3142fd-5e83-5f4b-b49b-83f05ab9110d"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"The sample was very small, so the results are more reliable.":"Küçük örneklem güvenilirliği artırmaz; mantık hatası.","The limitation is that the study was conducted.":"Anlamsız bir gerekçe."}'::jsonb,'Kısıtlılığı ve sonucunu mantıklı biçimde bağlıyor.',3,'draft') on conflict do nothing;
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('fc3bed94-864a-5e79-ae44-fca216be3429','83cc93e4-da20-54fa-8a46-a4fec28d34a7','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Professor","en":"What is one limitation of this study?"},{"speaker":"Professor","en":"Good. Why do you think the two groups gave different answers?"}],"options":["This may be due to cultural differences between the groups.","This may be do to cultural differences.","This may be due of cultural differences."],"scenario_id":"9a3142fd-5e83-5f4b-b49b-83f05ab9110d"}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"This may be do to cultural differences.":"“do” bir fiildir; doğrusu “due to”.","This may be due of cultural differences.":"Edat yanlış: due to."}'::jsonb,'Olası nedeni temkinli bir dille söylüyor.',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('2fdc5ae6-8ceb-533d-bf3d-aa728d7eae1c','0fe90fa6-b48a-543a-a4ef-332bf34e617c','Dil kursunda ilk gün','Dil kursundaki ilk dersindesin. Yanındaki öğrenci seninle tanışmak istiyor.','[{"speaker":"Sam","en":"Hi! I''m Sam. What''s your name?","tr":"Merhaba! Ben Sam. Adın ne?"},{"choose":[{"en":"Hi, I Defne.","correct":false,"why_tr":"Fiil eksik: I''m Defne."},{"en":"Hi Sam, I''m Defne. Nice to meet you.","correct":true,"why_tr":"Adını söylüyor ve kibarca selamlıyor."},{"en":"Hi, my name Defne.","correct":false,"why_tr":"“is” eksik: My name is Defne."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Sam","en":"Nice to meet you too. Where are you from?","tr":"Ben de memnun oldum. Nerelisin?"},{"choose":[{"en":"I from Konya.","correct":false,"why_tr":"“am” eksik."},{"en":"I''m of Konya.","correct":false,"why_tr":"Nereli olmak “from” ile söylenir."},{"en":"I''m from Konya. And you?","correct":true,"why_tr":"“I''m from …” doğru yapı ve soruyu geri soruyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Sam","en":"I''m from Canada. Are you a student here?","tr":"Ben Kanadalıyım. Burada öğrenci misin?"},{"choose":[{"en":"Yes, I am. I''m a student at the university too.","correct":true,"why_tr":"Kısa cevap ve ek bilgi doğru."},{"en":"Yes, I''m.","correct":false,"why_tr":"Kısa olumlu cevapta kısaltma yapılmaz: Yes, I am."},{"en":"Yes, I do.","correct":false,"why_tr":"“Are you …?” sorusunun cevabı “Yes, I am.”"}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['04aa3502-f442-5e85-a4da-6a56c1d34643','632d092a-76af-5378-a767-9b02b842083d','d13dfc3b-9dd9-58f7-b85d-f77c30115e33','a4e4f949-dea3-566a-91be-14149a412e88']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('f0ade465-6d77-5e61-af09-31bb1c4d0b69','0fe90fa6-b48a-543a-a4ef-332bf34e617c','Aile fotoğrafı','Bir arkadaşına telefonundaki aile fotoğrafını gösteriyorsun.','[{"speaker":"Lucy","en":"Nice photo! Who are these people?","tr":"Güzel fotoğraf! Bu insanlar kim?"},{"choose":[{"en":"These is my parents.","correct":false,"why_tr":"“These” ile “are” kullanılır."},{"en":"These are my parents, and this is my sister.","correct":true,"why_tr":"Çoğul için “These are”, tekil için “this is”."},{"en":"This are my parents.","correct":false,"why_tr":"Çoğul isimle “These are” gerekir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Lucy","en":"Is your sister married?","tr":"Kız kardeşin evli mi?"},{"choose":[{"en":"Yes, she does.","correct":false,"why_tr":"“Is …?” sorusuna “she is” ile cevap verilir."},{"en":"Yes, she is. Her husband is a doctor.","correct":true,"why_tr":"Kısa cevap ve “her husband” doğru."},{"en":"Yes, she is. His husband is a doctor.","correct":false,"why_tr":"Kadın için iyelik “her” olur."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Lucy","en":"And who is this tall boy?","tr":"Peki bu uzun boylu çocuk kim?"},{"choose":[{"en":"That''s my brother, Can. He''s fifteen.","correct":true,"why_tr":"Kişiyi tanıtıyor ve yaşını söylüyor."},{"en":"That''s my brother. She''s fifteen.","correct":false,"why_tr":"Erkek için “he” kullanılır."},{"en":"He my brother.","correct":false,"why_tr":"“is” eksik."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['296728b3-f7c8-5cd5-9e8b-ce38bb50af4e','b28f24ed-d64d-521f-9acc-8941ec48c74c','a11c6128-f4eb-5c24-b2ce-0070f3274566','b8bd1683-92cd-54d8-ac81-6c0b11010dcc']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('5401331d-255e-5ea8-8f4f-895e81930691','fe12b100-e015-5fb9-929c-a7577550770c','Günlük rutin sohbeti','Yeni bir iş arkadaşı günlük rutinini soruyor.','[{"speaker":"Tom","en":"You''re always here early! What time do you get up?","tr":"Hep erkencisin! Saat kaçta kalkıyorsun?"},{"choose":[{"en":"I get usually up at six.","correct":false,"why_tr":"Sıklık zarfı fiilden önce gelir."},{"en":"I usually getting up at six.","correct":false,"why_tr":"Yardımcı fiil olmadan -ing kullanılmaz."},{"en":"I usually get up at six. I go to work by metro.","correct":true,"why_tr":"Rutin present simple ile doğru anlatılıyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Tom","en":"Wow. Do you have breakfast at home?","tr":"Vay. Kahvaltıyı evde mi yapıyorsun?"},{"choose":[{"en":"No, I doesn''t.","correct":false,"why_tr":"“I” ile “don''t” kullanılır."},{"en":"No, I not have.","correct":false,"why_tr":"Olumsuz için “don''t have” gerekir."},{"en":"No, I don''t. I have breakfast at the office.","correct":true,"why_tr":"Kısa cevap ve açıklama doğru."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Tom","en":"Good idea. The café downstairs is great.","tr":"İyi fikir. Alt kattaki kafe harika."}]'::jsonb,array['aefbc601-099c-50bb-a63d-6e3d305bf617','bd8b2a69-e0ea-5d29-85cc-278d054a3868','41650d79-c1a9-5b12-91d6-d6c3e6f0c119','c9beb292-4c35-588e-a4cf-b02f63556abe']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('876532d5-9faf-5d80-92a3-6c9fe63edbe2','fe12b100-e015-5fb9-929c-a7577550770c','Ev görmeye gitmek','Kiralık bir daireye bakıyorsun ve ev sahibine sorular soruyorsun.','[{"speaker":"Owner","en":"Come in! This is the living room.","tr":"Buyurun! Burası oturma odası."},{"choose":[{"en":"It''s nice. How many bedrooms are there?","correct":true,"why_tr":"Çoğul isimle “are there” doğru."},{"en":"It''s nice. How much bedrooms have?","correct":false,"why_tr":"Sayılabilen isim için “How many” kullanılır."},{"en":"It''s nice. How many bedroom is there?","correct":false,"why_tr":"“How many” çoğul isim ve “are” ister."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Owner","en":"There are two bedrooms and a big kitchen.","tr":"İki yatak odası ve büyük bir mutfak var."},{"choose":[{"en":"Great. Is there a bus stop near here?","correct":true,"why_tr":"“Is there …?” doğru soru."},{"en":"Great. Has a bus stop near here?","correct":false,"why_tr":"Özne ve doğru yapı eksik."},{"en":"Great. Is it a bus stop near here?","correct":false,"why_tr":"Var olup olmadığı “Is there” ile sorulur."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Owner","en":"Yes, there''s one next to the supermarket.","tr":"Evet, süpermarketin yanında bir tane var."}]'::jsonb,array['dce2fc8f-8d1f-520f-9dca-4e85e58e426d','939930f2-7234-59ad-ac79-4c0e7a378dc8','0fa91d95-b1fa-55e2-90f4-81f649dbffb8','8579ebb6-380f-58bb-96f1-edb62cdb3fd0']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('a1294416-6631-5b5f-8451-cf67977a271c','61d6af77-625c-535b-96ca-5f8745c3a368','Pazartesi sabahı sohbet','İş arkadaşın hafta sonunu nasıl geçirdiğini soruyor.','[{"speaker":"Anna","en":"Morning! How was your weekend?","tr":"Günaydın! Hafta sonun nasıldı?"},{"choose":[{"en":"It was great, thanks. I went to Bursa with my family.","correct":true,"why_tr":"“was” ve “went” doğru kullanılmış."},{"en":"It is great. I go to Bursa.","correct":false,"why_tr":"Geçmiş anlatılıyor; geçmiş zaman gerekir."},{"en":"It were great.","correct":false,"why_tr":"“It” ile “was” kullanılır."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Anna","en":"Nice! What did you do there?","tr":"Güzel! Orada ne yaptınız?"},{"choose":[{"en":"We visited the old bazaar and ate İskender. We had a great time.","correct":true,"why_tr":"Past simple ile doğru sıralanmış."},{"en":"We visit the old bazaar and eat İskender.","correct":false,"why_tr":"Fiiller geçmiş zamanda olmalı."},{"en":"We did visited the old bazaar.","correct":false,"why_tr":"“did” ile fiil yalın olur; olumlu cümlede “did” gerekmez."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Anna","en":"Was it crowded?","tr":"Kalabalık mıydı?"},{"choose":[{"en":"Yes, it was. There were lots of tourists.","correct":true,"why_tr":"Kısa cevap ve “there were” doğru."},{"en":"Yes, there was lots of tourists.","correct":false,"why_tr":"Çoğul isimle “there were”."},{"en":"Yes, it did.","correct":false,"why_tr":"“Was it …?” sorusuna “it was” ile cevap verilir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['49041cf9-e9cd-54f5-8b69-3c26f18e1db1','e97272dc-7a6a-5323-95a8-bdc7f0a3a134','ae67ce8c-1ac8-5f3a-b3d7-78a381cc0adc','853407f0-429c-58e0-bcbf-7b5d13446ad1']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('7a2224aa-88c6-5d14-8b7e-5a1fc1544c0b','61d6af77-625c-535b-96ca-5f8745c3a368','Kayıp çanta','Otobüste çantanı unuttun ve kayıp eşya bürosuna gittin.','[{"speaker":"Officer","en":"Good morning. How can I help?","tr":"Günaydın. Nasıl yardımcı olabilirim?"},{"choose":[{"en":"I losted my bag.","correct":false,"why_tr":"“lose” düzensizdir: lost."},{"en":"I lose my bag yesterday.","correct":false,"why_tr":"“yesterday” geçmiş zaman ister: lost."},{"en":"I lost my bag yesterday. I forgot it on the number 12 bus.","correct":true,"why_tr":"Geçmiş zamanla net açıklama."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Officer","en":"What time did you get off the bus?","tr":"Otobüsten saat kaçta indiniz?"},{"choose":[{"en":"I did got off at five.","correct":false,"why_tr":"“did” sonrası fiil yalın olur."},{"en":"At about half past five, on the way home from work.","correct":true,"why_tr":"Saat ve bağlam verilmiş."},{"en":"I get off at half past five.","correct":false,"why_tr":"Soru geçmişte; cevap geçmişte olmalı."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Officer","en":"Let me check… Is it a black backpack?","tr":"Bir bakayım… Siyah bir sırt çantası mı?"}]'::jsonb,array['82713498-3cd4-50b9-abfd-8de4152311e9','f84343f8-b67d-545f-8220-5a5ba452e2b5','2ab33f4f-7536-53ed-a1c9-6903b3f71e2e','07f86a14-e4e8-51fb-9c6d-eb3da1171d34']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('9ed188a2-94c9-5bdb-9ce0-f190649fe175','bc5f3cd8-55f8-5a25-8906-26008f507e61','Hafta sonu planı yapmak','Bir arkadaşın hafta sonu planlarını soruyor ve birlikte bir şey yapmayı teklif ediyor.','[{"speaker":"Ece","en":"Do you have any plans for Saturday?","tr":"Cumartesi için bir planın var mı?"},{"choose":[{"en":"Yes, I meet my cousin tomorrow morning yesterday.","correct":false,"why_tr":"Zaman ifadeleri çelişiyor."},{"en":"Yes, I''m meeting my cousin in the morning, but I''m free in the evening.","correct":true,"why_tr":"Ayarlanmış plan için present continuous doğru."},{"en":"Yes, I''m going meet my cousin.","correct":false,"why_tr":"“going to” kalıbında “to” eksik."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Ece","en":"Great! Shall we have dinner? I can book a table.","tr":"Harika! Akşam yemeği yiyelim mi? Masa ayırtabilirim."},{"choose":[{"en":"Good idea. I''ll probably be home by six, so let''s say eight?","correct":true,"why_tr":"Tahmin için “will probably” ve öneri."},{"en":"Good idea. I probably am home by six.","correct":false,"why_tr":"Gelecek için “I''ll probably be” gerekir."},{"en":"Good idea. I''m going to be probably home.","correct":false,"why_tr":"“probably” yeri yanlış; doğal değil."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Ece","en":"Perfect. I''m going to invite Mert too.","tr":"Mükemmel. Mert''i de davet edeceğim."}]'::jsonb,array['5008ff29-3292-5037-b23f-e13e8daee6c3','7697a770-9372-55a4-8d62-207c8791aa34','b83512b6-103e-51b1-89e3-a5f2e228a618','8e79fbc0-ae70-5ff2-a844-4f055ac49716']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('ba555b47-a7d2-50bd-975f-a976f88f6e5d','bc5f3cd8-55f8-5a25-8906-26008f507e61','Mağazada','Bir mağazada ceket bakıyorsun ve satış görevlisiyle konuşuyorsun.','[{"speaker":"Assistant","en":"Hi, can I help you?","tr":"Merhaba, yardımcı olabilir miyim?"},{"choose":[{"en":"Yes, can I try this jacket on? Do you have it in a medium size?","correct":true,"why_tr":"Kibar istek ve beden sorusu doğru."},{"en":"Yes, I want try this jacket.","correct":false,"why_tr":"“want to try” olmalı ve giysi için “try on” kullanılır."},{"en":"Yes, can I test this jacket?","correct":false,"why_tr":"Giysi için “try on” kullanılır."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Assistant","en":"Sure, here you are. The changing room is over there.","tr":"Tabii, buyurun. Deneme kabini şurada."},{"choose":[{"en":"It''s expensive than the blue one.","correct":false,"why_tr":"Karşılaştırma için “more expensive” gerekir."},{"en":"It''s more expensiver than the blue one.","correct":false,"why_tr":"“more” ve “-er” birlikte kullanılmaz."},{"en":"Thanks. It''s nice, but it''s more expensive than the blue one. Is there a discount?","correct":true,"why_tr":"Karşılaştırma ve indirim sorusu doğru."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Assistant","en":"Yes, there''s 15% off today. Do you want to pay by card?","tr":"Evet, bugün %15 indirim var. Kartla mı ödemek istersiniz?"}]'::jsonb,array['a3497be0-8bda-5c55-ac89-af5f2f5cfc69','eeb104a3-065e-5a06-ac3b-dca5fc98c19f','6cca8a6b-b0a1-5cc1-9c73-41764ca123f3','1c03c4d2-43c7-5406-a028-c0ba48fc3e3c']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('4f9495f5-ff05-5350-9d76-641cc51e361d','8886d6de-85b1-5473-95de-ae8213ec5037','Arkadaşına tavsiye','Arkadaşın iki iş teklifi arasında kaldı ve senden fikir istiyor.','[{"speaker":"Melis","en":"I need some advice. One job pays more, but the other is closer to home.","tr":"Biraz tavsiyeye ihtiyacım var. Bir iş daha çok ödüyor ama diğeri eve daha yakın."},{"choose":[{"en":"If I were you, I''d choosing the closer one.","correct":false,"why_tr":"“would” sonrası yalın fiil gelir."},{"en":"If I am you, I will choose the closer one.","correct":false,"why_tr":"Tavsiyede kalıp “If I were you, I''d …”."},{"en":"If I were you, I''d choose the closer one. Commuting every day is really tiring.","correct":true,"why_tr":"2. tip koşulla doğru tavsiye."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Melis","en":"But the salary difference is big.","tr":"Ama maaş farkı büyük."},{"choose":[{"en":"Then it might be worth to ask for a better offer.","correct":false,"why_tr":"“worth” sonrası -ing gelir."},{"en":"Then you should to ask for a better offer.","correct":false,"why_tr":"“should” sonrası “to” gelmez."},{"en":"Then it might be worth asking the closer company for a better offer.","correct":true,"why_tr":"“worth + -ing” doğru kullanılmış."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Melis","en":"Good idea. I''ll call them tomorrow and decide after that.","tr":"İyi fikir. Yarın onları arayıp sonra karar vereceğim."}]'::jsonb,array['0fb344f2-4465-5ae1-a2a5-53db10c8450b','5fe752fe-7ae0-5976-9ab0-d0e29579230d','071fa95c-8f65-5668-8d70-218a447468a9','b417ba94-98ab-5db9-90e2-c403a1d8026a']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('bb3d468a-4080-5b58-9eff-c26d0aa4f3b4','8886d6de-85b1-5473-95de-ae8213ec5037','Doktor tavsiyesi','Uyku sorunun için doktora gittin. Doktor alışkanlıklarını soruyor.','[{"speaker":"Doctor","en":"So, you can''t sleep well. Do you drink coffee in the evening?","tr":"Demek iyi uyuyamıyorsunuz. Akşamları kahve içiyor musunuz?"},{"choose":[{"en":"Yes, I do drink. I stress.","correct":false,"why_tr":"Doğal değil."},{"en":"Yes, I do. And I usually feel stressed because of work.","correct":true,"why_tr":"Kısa cevap ve durum doğru anlatılmış."},{"en":"Yes, I am. And I feel stressful.","correct":false,"why_tr":"“Do you …?” sorusuna “I do”; kişi için “stressed”."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Doctor","en":"You should avoid drinking coffee after 4 pm. And if you rest a bit after work, you''ll sleep better.","tr":"Saat 4''ten sonra kahve içmekten kaçınmalısınız. İşten sonra biraz dinlenirseniz daha iyi uyursunuz."},{"choose":[{"en":"OK. I enjoy walking, so I''ll go for a walk every evening.","correct":true,"why_tr":"“enjoy + -ing” ve plan doğru."},{"en":"OK. If I will walk, I sleep better.","correct":false,"why_tr":"“if” tarafında “will” kullanılmaz."},{"en":"OK. I enjoy to walk, so I walk.","correct":false,"why_tr":"“enjoy” sonrası -ing gelir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Doctor","en":"Perfect. Let''s see how you feel in two weeks.","tr":"Mükemmel. İki hafta sonra nasıl hissettiğinize bakalım."}]'::jsonb,array['7788b9c5-66d6-5257-b4cd-15418e542a3a','d69f2122-0822-55c2-812e-fbe6c0d59959','4c289d16-9ed8-5180-8511-7b9335a3ed09','c5a7ad5c-064d-58f0-9f51-54480894052e']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('b5933d89-b1b6-5623-ae19-826377a3504d','cda9518c-acc9-50f6-8edf-1221122b1601','İş görüşmesinde deneyim anlatmak','Bir otelde resepsiyon pozisyonu için görüşmedesin. Görüşmeci deneyimini soruyor.','[{"speaker":"Manager","en":"Tell me about your experience. Have you ever worked in a hotel?","tr":"Bize deneyiminden bahset. Hiç bir otelde çalıştın mı?"},{"choose":[{"en":"Yes, I did. I work at a hotel since 2023.","correct":false,"why_tr":"“since” ile present perfect gerekir."},{"en":"Yes, I have. I''ve worked at a hotel in Bodrum since 2023.","correct":true,"why_tr":"Hâlâ süren iş için present perfect ve “since”."},{"en":"Yes, I have. I''ve worked at a hotel for 2023.","correct":false,"why_tr":"Yıl başlangıç noktası; “since” gerekir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Manager","en":"Great. Have you ever worked abroad?","tr":"Harika. Hiç yurt dışında çalıştın mı?"},{"choose":[{"en":"Yes. I''ve spent a summer in Ireland in 2021.","correct":false,"why_tr":"Belli bir yıl varken past simple kullanılır."},{"en":"Yes. I spent a summer in Ireland in 2021. It was a great experience.","correct":true,"why_tr":"Belli zaman için past simple doğru."},{"en":"Yes. I''ve been in abroad.","correct":false,"why_tr":"“abroad” edatsız kullanılır."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Manager","en":"Excellent. What have you learned from it?","tr":"Mükemmel. Bundan ne öğrendin?"}]'::jsonb,array['32810408-e91c-5eda-a686-b4654e03ee77','86f36d8e-74ce-5969-9499-48eab8c74b95','96387c50-82e1-5d59-8971-f54e8ca8db3e','bfc2d6eb-739d-55f9-82ed-114ae70091be']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('4024a07c-c9c8-5b0b-8eaa-48287c91d922','cda9518c-acc9-50f6-8edf-1221122b1601','Uzun zamandır görmediğin bir arkadaş','Üç yıldır görmediğin bir arkadaşınla karşılaştın.','[{"speaker":"Ozan","en":"Hey! I haven''t seen you for ages! What''s new?","tr":"Hey! Seni çok uzun zamandır görmedim! Ne var ne yok?"},{"choose":[{"en":"Lots! I just move and I take up running.","correct":false,"why_tr":"Fiiller present perfect olmalı."},{"en":"Lots! I''ve just moved and I''ve took up running.","correct":false,"why_tr":"“take” üçüncü hâli “taken”."},{"en":"Lots! I''ve just moved to a new flat and I''ve taken up running.","correct":true,"why_tr":"Yakın geçmiş için “just” ve present perfect."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Ozan","en":"Running? Wow. How far have you run?","tr":"Koşu mu? Vay. Ne kadar koştun?"},{"choose":[{"en":"So far I''ve done two 10K races. And I''ve given up sugar!","correct":true,"why_tr":"“So far” ve present perfect doğru."},{"en":"So far I''ve give up sugar.","correct":false,"why_tr":"Üçüncü hâl “given”."},{"en":"So far I did two races last month and next month.","correct":false,"why_tr":"Zaman ifadeleri çelişiyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Ozan","en":"Amazing. You look great!","tr":"Harika. Çok iyi görünüyorsun!"}]'::jsonb,array['0c3c89e7-cc4a-5d58-bdb4-ed8b4a3b3df9','40a7ca9b-1910-5ed8-ab56-30b4630e676f','b5a4604f-2fd6-5dd5-befd-37294f7370bf','12526299-472b-51a2-b181-1cff5b7e3b72']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('c24f0c48-b3ae-5928-9314-03a27e33130e','7bf0c681-79b3-5002-b1b1-c7d262f7cff7','Toplantıda fikir ayrılığı','Ekipte dört günlük çalışma haftası tartışılıyor. Bir iş arkadaşın karşı çıkıyor.','[{"speaker":"Can","en":"I don''t think a four-day week would work. We''d never finish our projects.","tr":"Dört günlük haftanın işe yarayacağını sanmıyorum. Projelerimizi asla bitiremeyiz."},{"choose":[{"en":"I see your point, but studies show people are more productive when they''re rested.","correct":true,"why_tr":"Karşı görüşü kabul edip kanıtla cevap veriyor."},{"en":"Although I see your point, but I disagree.","correct":false,"why_tr":"“Although” ile “but” birlikte kullanılmaz."},{"en":"You are wrong. It is good.","correct":false,"why_tr":"Kaba ve gerekçesiz."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Can","en":"Maybe, but what about clients who need us on Fridays?","tr":"Belki, ama cuma günü bize ihtiyaç duyan müşteriler ne olacak?"},{"choose":[{"en":"That''s a fair point. To some extent, a rota could solve that.","correct":true,"why_tr":"Haklı noktayı kabul edip çözüm öneriyor."},{"en":"That''s fair point to some extend.","correct":false,"why_tr":"“a” eksik ve “extent” olmalı."},{"en":"That''s a fair point. Despite we could make a rota.","correct":false,"why_tr":"“Despite” sonrası özne + fiil gelmez."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Can","en":"OK, I''m willing to try it for a month.","tr":"Tamam, bir ay denemeye razıyım."}]'::jsonb,array['08178299-6f4c-5742-9937-2ef39d46a665','2a3696fa-ee12-52d7-bc35-7e6dd2dfec2c','52452260-3485-5e4a-b91c-cc54d1102429','45cf3e80-b10f-5898-9a8d-0c26047aa1a2']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('294da9e7-acea-584b-9564-8ac9e0c355f4','7bf0c681-79b3-5002-b1b1-c7d262f7cff7','Mahalle toplantısı','Mahallene yeni bir alışveriş merkezi yapılması planlanıyor. Toplantıda söz aldın.','[{"speaker":"Chair","en":"Does anyone want to comment on the new shopping centre?","tr":"Yeni alışveriş merkezi hakkında yorum yapmak isteyen var mı?"},{"choose":[{"en":"Yes. According to me, it''s bad.","correct":false,"why_tr":"“According to me” doğal değil ve gerekçe yok."},{"en":"Yes. In my opinion, it''ll have a negative impact on the small shops which have been here for decades.","correct":true,"why_tr":"Görüş ve relative clause doğru."},{"en":"Yes. I oppose to it.","correct":false,"why_tr":"“oppose” edat almaz."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Chair","en":"But it would create jobs, wouldn''t it?","tr":"Ama iş imkânı yaratırdı, değil mi?"},{"choose":[{"en":"Some, yes. Although the new jobs, many businesses would close.","correct":false,"why_tr":"“Although” sonrası cümle gerekir."},{"en":"Some, yes. Despite of the new jobs, many would close.","correct":false,"why_tr":"“despite” edat almaz."},{"en":"Some, yes. However, despite the new jobs, many local businesses would probably close.","correct":true,"why_tr":"“However” ve “despite + isim” doğru."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Chair","en":"Thank you. Let''s hear from the other side as well.","tr":"Teşekkürler. Diğer tarafı da dinleyelim."}]'::jsonb,array['aca6dd92-5c77-5d74-bb0f-3f3599ac90ca','a24cc76c-cb12-5e5a-89bc-0f3ded5a2016','64e70e87-8b17-5745-b02d-b14c548105bb','4024e846-be0a-5d76-8854-b57b6b27ccec']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('1ba24434-1fbe-5a9e-83e4-a87176652fe3','0d6376db-346e-5a63-b3ee-03e2b9fef8c1','Kaçırılan uçak','Arkadaşınla havalimanına geç kaldınız ve uçağı kaçırdınız.','[{"speaker":"Ali","en":"I can''t believe we missed it! The gate closed five minutes ago.","tr":"İnanamıyorum, kaçırdık! Kapı beş dakika önce kapandı."},{"choose":[{"en":"I know. We must have left earlier.","correct":false,"why_tr":"“must have” tahmin bildirir; pişmanlık değil."},{"en":"I know. We should have left home an hour earlier.","correct":true,"why_tr":"Geçmiş eleştiri için “should have + V3”."},{"en":"I know. We should left home earlier.","correct":false,"why_tr":"“should have left” olmalı."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Ali","en":"If we hadn''t stopped for coffee, we would have made it.","tr":"Kahve için durmasaydık yetişirdik."},{"choose":[{"en":"If we wouldn''t stop, we made it.","correct":false,"why_tr":"3. tip yapısı bozuk."},{"en":"Yes, it''s your fault totally.","correct":false,"why_tr":"Kaba ve doğal değil."},{"en":"Maybe, but don''t blame yourself. The traffic was terrible too.","correct":true,"why_tr":"Teselli ve “blame yourself” doğru."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Ali","en":"You''re right. Let''s ask about the next flight.","tr":"Haklısın. Bir sonraki uçuşu soralım."}]'::jsonb,array['5b08dc95-3f68-562d-b85e-33b5f486fe5a','0e68a7d4-9644-5642-af5d-b0548ea101df','7700135a-5bc1-5f0a-a46d-eb329e3d1a79','67db7a23-240b-5f7e-95a7-20c7d4144385']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('9da3d8f5-4bc9-50ff-9b2d-d83c999b173b','0d6376db-346e-5a63-b3ee-03e2b9fef8c1','Toplantıya gelmeyen iş arkadaşı','Önemli bir toplantıya iş arkadaşın Kerem gelmedi. Ekip olarak nedenini tahmin ediyorsunuz.','[{"speaker":"Lena","en":"Where''s Kerem? He''s never late.","tr":"Kerem nerede? Asla geç kalmaz."},{"choose":[{"en":"He might have got stuck in traffic. There was an accident on the bridge.","correct":true,"why_tr":"Olasılık için “might have + V3”."},{"en":"He must got stuck.","correct":false,"why_tr":"“must have got” olmalı."},{"en":"He might get stuck in traffic yesterday.","correct":false,"why_tr":"Geçmiş tahmin için “might have got”."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Lena","en":"But he takes the metro.","tr":"Ama metroyla geliyor."},{"choose":[{"en":"True. Then he mustn''t have been in traffic.","correct":false,"why_tr":"Olumsuz tahminde “can''t have” tercih edilir."},{"en":"True. Then he can''t have been in traffic. He must have forgotten the meeting.","correct":true,"why_tr":"“can''t have” ve “must have” doğru tahminler."},{"en":"True. Then he can''t be in traffic yesterday.","correct":false,"why_tr":"Geçmiş için “can''t have been”."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Lena","en":"Here''s a message from him… It turns out his son is ill.","tr":"Ondan bir mesaj geldi… Anlaşılan oğlu hastaymış."}]'::jsonb,array['a2fc076a-7f47-5d66-81f7-ee94fa302b9f','afb4c455-070f-5e5e-94cb-66c4766fc77e','15a45da8-580a-5cad-9ac3-01f98860eaf3','1fa50db5-3f28-584c-a109-6b344e2bdf68']::uuid[],'choice',4,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('cfdcb320-8396-5113-bb28-5fc95234c7a2','46fa5ffe-78fe-5175-8072-3b2621cc801c','Danışmanla tez görüşmesi','Tez danışmanınla bulgularını konuşuyorsun. Danışman iddialarının fazla kesin olduğunu düşünüyor.','[{"speaker":"Supervisor","en":"You write that social media ''causes'' anxiety. Can you prove that?","tr":"Sosyal medyanın kaygıya ‘neden olduğunu’ yazmışsın. Bunu kanıtlayabilir misin?"},{"choose":[{"en":"The findings suggests it causes.","correct":false,"why_tr":"“findings” çoğul; “suggest” olmalı ve iddia hâlâ fazla kesin."},{"en":"Yes, it is 100% proved.","correct":false,"why_tr":"Akademik dilde aşırı kesin."},{"en":"Not exactly. The findings suggest a significant correlation, but not causation.","correct":true,"why_tr":"Temkinli dil ve doğru terimler."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Supervisor","en":"Good. And what about your sample?","tr":"Güzel. Peki ya örneklemin?"},{"choose":[{"en":"The sample is perfect, no problem.","correct":false,"why_tr":"Akademik değerlendirme yok."},{"en":"One limitation is that the sample only included university students, so the results may not apply to other groups.","correct":true,"why_tr":"Sınırlılık temkinli dille açıklanmış."},{"en":"One limitations is the sample.","correct":false,"why_tr":"“One” sonrası tekil gelir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Supervisor","en":"Exactly. Add that to your discussion section.","tr":"Kesinlikle. Bunu tartışma bölümüne ekle."}]'::jsonb,array['17b3f424-c7c4-589c-911f-5fb9bce66daf','2f83fc00-4447-5e21-b4df-332dc3b6723f','55be0fcf-89f6-5517-b997-b1023df97c6e','ffe12472-eb43-55c7-9d11-e498fd505478']::uuid[],'choice',4,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('1ffbc8ae-5e3b-5549-93b0-08f33429926b','46fa5ffe-78fe-5175-8072-3b2621cc801c','Resmî e-postaya cevap','Bir müşteri gecikmeli teslimat için şikâyet etti. Resmî bir dille cevap veriyorsun.','[{"speaker":"Client","en":"Why was our order delayed by two weeks?","tr":"Siparişimiz neden iki hafta gecikti?"},{"choose":[{"en":"Because our supplier did bad.","correct":false,"why_tr":"Resmî değil ve belirsiz."},{"en":"With regard to the delay, it was due to a shortage of components at our supplier.","correct":true,"why_tr":"Resmî bağlantı ve isimleştirme doğru."},{"en":"With regarding the delay, because shortage.","correct":false,"why_tr":"Kalıp bozuk ve cümle eksik."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Client","en":"How will you prevent this in future?","tr":"Gelecekte bunu nasıl önleyeceksiniz?"},{"choose":[{"en":"We will try, maybe.","correct":false,"why_tr":"Profesyonel değil."},{"en":"We added a second supplier, therefore reducing risk.","correct":false,"why_tr":"“therefore” bu yapıda kullanılmaz; “thereby” gerekir."},{"en":"We have added a second supplier, thereby reducing the risk of similar delays.","correct":true,"why_tr":"“thereby + -ing” doğru kullanılmış."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Client","en":"Thank you for the explanation.","tr":"Açıklamanız için teşekkürler."}]'::jsonb,array['139db3f3-c499-5502-9bce-7398df4d7307','862df686-51f1-5ce7-af34-e53e460185e6','48fba1b6-1403-5e11-b508-d5eab8f4fb3e','5e11371b-7eff-5a77-97d1-d41b06173d63']::uuid[],'choice',4,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('2eb52f74-58ff-5a59-bc36-b8f9cd344e19','39054825-3f71-5559-9822-6a4004d50c22','Yönetime öneri sunmak','Şirkette esnek çalışma saatleri için yönetime bir öneri sunuyorsun.','[{"speaker":"Director","en":"So, what exactly are you proposing?","tr":"Peki, tam olarak ne öneriyorsunuz?"},{"choose":[{"en":"That we''re proposing is flexible start time.","correct":false,"why_tr":"Cleft için “What” gerekir."},{"en":"What we''re proposing is a flexible start time between 8 and 10.","correct":true,"why_tr":"Cleft cümleyle öneri net vurgulanmış."},{"en":"We proposing flexible time.","correct":false,"why_tr":"Yardımcı fiil eksik."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Director","en":"Is it feasible? Won''t some teams be understaffed in the morning?","tr":"Uygulanabilir mi? Bazı ekipler sabah eksik personelle kalmaz mı?"},{"choose":[{"en":"Not only cover would be maintained, but also productivity.","correct":false,"why_tr":"Devrik yapıda yardımcı fiil özneden önce gelir."},{"en":"Yes it''s feasible, I think, maybe.","correct":false,"why_tr":"Zayıf ve gerekçesiz."},{"en":"We''ve looked into that. Not only would cover be maintained, but productivity would also rise substantially.","correct":true,"why_tr":"Devrik yapı ve “substantially” doğru kullanılmış."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Director","en":"That''s a compelling argument. Send me the full proposal.","tr":"İkna edici bir argüman. Bana önerinin tamamını gönderin."}]'::jsonb,array['7e820b00-d776-50d3-84e3-6d67bb89cbbe','d3ee7680-0834-5f26-a778-fc5eac90c6d6','24f04bf0-010d-559a-aa14-b15e974b3277','d0936f70-c8ab-598c-a906-a91317c4c6fa']::uuid[],'choice',4,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('5248f821-fce1-5bd4-bdb3-cdc519568430','39054825-3f71-5559-9822-6a4004d50c22','Etkileyici bir deneyimi anlatmak','Bir mülakatta “Seni en çok etkileyen deneyim neydi?” diye soruluyor.','[{"speaker":"Interviewer","en":"Tell me about an experience that changed you.","tr":"Seni değiştiren bir deneyimden bahset."},{"choose":[{"en":"Was a trip changed me.","correct":false,"why_tr":"Özne ve yapı eksik."},{"en":"It was a volunteering trip to Hatay that changed my perspective.","correct":true,"why_tr":"It-cleft ile deneyim vurgulanmış."},{"en":"It was a volunteering trip what changed me.","correct":false,"why_tr":"It-cleft''te “that / which” kullanılır, “what” değil."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Interviewer","en":"What did you learn from it?","tr":"Bundan ne öğrendin?"},{"choose":[{"en":"Seldom I saw people work together.","correct":false,"why_tr":"“Seldom” başta ise devrik yapı gerekir."},{"en":"Rarely I have seen people work so well.","correct":false,"why_tr":"“Rarely” başta ise “have I” gerekir."},{"en":"Rarely have I seen people work together so well. It was pivotal in my decision to study social work.","correct":true,"why_tr":"Devrik yapı ve “pivotal” doğru."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Interviewer","en":"That''s very interesting. Thank you.","tr":"Çok ilginç. Teşekkürler."}]'::jsonb,array['63f87d23-dbbd-57a2-9798-658ddfbb93ff','31726678-7686-5f67-8d37-e1a6b1cae8d1','f21f1a60-8e1a-5b3c-9a67-2756285c0349','55c407a9-c688-538e-a19f-00d783e730b5']::uuid[],'choice',4,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('33307968-8c84-57a3-aae1-acdab5061efc','e6ae5d8c-b653-5966-870b-5abc222f4d1b','Yönetim kurulu toplantısı','Bir yönetim kurulu toplantısında yeni projenin ertelenmesini öneriyorsun.','[{"speaker":"Chair","en":"Let''s discuss the launch date. What''s your recommendation?","tr":"Lansman tarihini konuşalım. Öneriniz nedir?"},{"choose":[{"en":"I recommend that the launch be postponed until the safety tests are complete.","correct":true,"why_tr":"Subjunctive (be postponed) doğru."},{"en":"I recommend that the launch is postpone.","correct":false,"why_tr":"Yapı bozuk: “be postponed” olmalı."},{"en":"I recommend to postpone the launch it.","correct":false,"why_tr":"Gramer hatalı."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Chair","en":"But the marketing campaign has already started.","tr":"Ama pazarlama kampanyası çoktan başladı."},{"choose":[{"en":"Despite the campaign is started, safety important.","correct":false,"why_tr":"“Despite” sonrası cümle gelmez; fiil eksik."},{"en":"Notwithstanding of the campaign, the product must safe.","correct":false,"why_tr":"“notwithstanding” edat almaz ve fiil eksik."},{"en":"Notwithstanding the campaign, it is imperative that the product be safe. Frankly, that''s the elephant in the room.","correct":true,"why_tr":"Çok resmî edat, subjunctive ve deyim doğru."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Chair","en":"Point taken. For the time being, we''ll hold the launch.","tr":"Anlaşıldı. Şimdilik lansmanı bekletiyoruz."}]'::jsonb,array['bfc81c3d-61ff-5d25-a16c-1aaad5f1dccc','2477e713-2bf8-532e-8e9b-4e9a5b5c819b','6464b0da-9dd8-5258-a092-2b8b5bf96e19','0b64555a-3700-59f8-9cd6-f25b38d4485c']::uuid[],'choice',5,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('f43f57e1-5a76-5c76-b380-c428558dce3f','e6ae5d8c-b653-5966-870b-5abc222f4d1b','Dürüst geri bildirim','Bir arkadaşın yazdığı iş planını okudun. Senden açık sözlü bir yorum istiyor.','[{"speaker":"Emre","en":"Don''t beat around the bush. What do you really think of my plan?","tr":"Lafı dolandırma. Planım hakkında gerçekten ne düşünüyorsun?"},{"choose":[{"en":"Honestly, it''s bad.","correct":false,"why_tr":"Gerekçesiz ve yapıcı değil."},{"en":"Honestly, the idea is great, but you''ve cut corners on the financial part.","correct":true,"why_tr":"Deyim doğru ve geri bildirim yapıcı."},{"en":"Honestly, you cut the corner on finance.","correct":false,"why_tr":"Deyim “cut corners” (çoğul, tanımlıksız)."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Emre","en":"You''ve hit the nail on the head. I wasn''t sure about the numbers.","tr":"Tam üstüne bastın. Rakamlardan emin değildim."},{"choose":[{"en":"If I were you, I''d get an accountant to check them. Had I done that with my café, I''d be in a much better position now.","correct":true,"why_tr":"Tavsiye ve devrik karma koşul doğru."},{"en":"If I had done that, I would have be better now.","correct":false,"why_tr":"Karma koşulda “I would be … now”."},{"en":"Had I did that, I''d be better now.","correct":false,"why_tr":"Devrik koşulda “Had I done”."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Emre","en":"Thanks. I was on the fence, but now I''ll definitely do that.","tr":"Sağ ol. Kararsızdım ama şimdi kesinlikle yapacağım."}]'::jsonb,array['02ca0735-6345-5aa7-b3c1-196d44b3bed7','f98dbe3c-bcd7-59b7-ac2d-e1f0e7164e82','4fa3de78-223b-5242-bef2-4b8e2694f05a','78e0deec-d512-5732-90cb-756612277072']::uuid[],'choice',5,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('5f877c89-6e1d-57ed-bcab-4598c03931b2','d085f43c-2ece-5c98-b9a2-fccd790e4488','Editörle metin üzerinde çalışmak','Bir dergiye yazdığın yazıyı editörünle gözden geçiriyorsun. Editör üslubu eleştiriyor.','[{"speaker":"Editor","en":"The ideas are good, but the introduction is rather verbose.","tr":"Fikirler iyi ama giriş biraz uzun ve laf kalabalığı dolu."},{"choose":[{"en":"Fair. I make it succinctly.","correct":false,"why_tr":"Gramer hatalı ve sıfat yerine zarf kullanılmış."},{"en":"Fair enough. I''ll make it more succinct and get to the point faster.","correct":true,"why_tr":"Eleştiriyi kabul edip somut çözüm öneriyor."},{"en":"Fair enough. I''ll make it more verbose.","correct":false,"why_tr":"Anlam terse döndü."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Editor","en":"Also, the second section doesn''t follow on from the first.","tr":"Ayrıca ikinci bölüm birinciden mantıklı biçimde devam etmiyor."},{"choose":[{"en":"Having reread it, I see what you mean. I''ll add a link so the argument is more coherent.","correct":true,"why_tr":"Participle clause ve “coherent” doğru."},{"en":"Having reread it, the argument isn''t coherent.","correct":false,"why_tr":"Sarkan ortaç: yeniden okuyan argüman değil, sensin."},{"en":"Rereading it, I am see your point.","correct":false,"why_tr":"“am see” yanlış."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Editor","en":"Great. Readers should get the gist from the first paragraph.","tr":"Harika. Okurlar ana fikri ilk paragraftan anlamalı."}]'::jsonb,array['a1d1cf90-84aa-5a7d-acdf-72af3f49b67d','29ec9828-fb11-5611-bb22-495c8416c1e1','ca17f5b0-53b8-5475-a85b-b97872a94f45','3b65349b-8b62-50ea-9552-15ee18f3a7fa']::uuid[],'choice',5,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('544cdaf7-d633-5e5f-a005-3c1cbd77e781','d085f43c-2ece-5c98-b9a2-fccd790e4488','Kitap kulübü tartışması','Kitap kulübünde bir romanı tartışıyorsunuz.','[{"speaker":"Mina","en":"What did you think of the novel?","tr":"Romanı nasıl buldun?"},{"choose":[{"en":"I loved. Very vivid prose it is.","correct":false,"why_tr":"Nesne eksik ve sıralama doğal değil."},{"en":"I loved it. The prose is valid.","correct":false,"why_tr":"“valid” geçerli demektir; edebî tasvirde anlamsız."},{"en":"I loved it. The prose is simple, yet the descriptions are incredibly vivid.","correct":true,"why_tr":"Edebî kelimeler doğru kullanılmış."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Mina","en":"I agree. And the ending alludes to the first chapter, doesn''t it?","tr":"Katılıyorum. Ve son bölüm ilk bölüme gönderme yapıyor, değil mi?"},{"choose":[{"en":"Yes, it alludes on the first chapter.","correct":false,"why_tr":"Edat “to”."},{"en":"It is, and so is the title.","correct":false,"why_tr":"“alludes” eylem fiili; yardımcı fiil “does”."},{"en":"It does, and so does the title. The author juxtaposes the two scenes beautifully.","correct":true,"why_tr":"Ellipsis (It does, so does …) ve “juxtapose” doğru."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Mina","en":"Exactly. Needless to say, I''m reading her next book.","tr":"Aynen. Söylemeye gerek yok, sıradaki kitabını okuyorum."}]'::jsonb,array['0485cf66-8cea-5fdc-9f5a-db61944df917','9f0859a2-23fb-5b04-853e-6fdf13a0d3a9','c37180bc-9f7e-5cce-9841-424cd7fdfa3f','ade44690-4d5d-5c01-98c5-e4d00dd1996b']::uuid[],'choice',5,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('4ccdde2c-4345-55a0-a739-3b81887070ae','6fbbf6ec-47c4-5a61-ae2a-085acb973117','Aşırı ısınma toplantısı','Bir makine sürekli aşırı ısınıp duruyor. Ekip toplantısında sorunu ve çözümü anlatıyorsun.','[{"speaker":"Manager","en":"Why does the machine keep stopping?","tr":"Makine neden sürekli duruyor?"},{"choose":[{"en":"It overheats after about an hour. The problem is that the fan is too small.","correct":true,"why_tr":"Belirtiyi ve nedeni net anlatıyor."},{"en":"It is overheat because the fan small.","correct":false,"why_tr":"Fiil yapısı bozuk ve ikinci cümlede “is” eksik."},{"en":"It overhears after about an hour.","correct":false,"why_tr":"“overhear” kulak misafiri olmak demektir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Manager","en":"What do you suggest?","tr":"Ne öneriyorsun?"},{"choose":[{"en":"I suggest you to install a larger fan.","correct":false,"why_tr":"“suggest you to” yanlış; “I suggest that we install …” denir."},{"en":"If we install a larger fan, the temperature will drop. It''s a cheap solution.","correct":true,"why_tr":"First conditional doğru kullanılmış ve gerekçe veriyor."},{"en":"If we will install a larger fan, the temperature drops.","correct":false,"why_tr":"If''li kısımda “will” kullanılmaz; sonuç kısmında gerekir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['bd452d1c-f72a-5a10-aba9-dcb781346581','6877aabb-c98a-547c-b67d-a552a9ba7300','0c94d6d1-8459-5bc8-ada3-ba0c8b61c22a']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('b01af5ca-9ef0-5201-8c89-7ffabce2585b','6fbbf6ec-47c4-5a61-ae2a-085acb973117','Geçici ve kalıcı çözüm','Üretim hattında bir parça arızalandı. Yeni parça gelene kadar ne yapacağınızı konuşuyorsunuz.','[{"speaker":"Colleague","en":"The new part won''t arrive until Friday. What can we do now?","tr":"Yeni parça cumaya kadar gelmeyecek. Şimdi ne yapabiliriz?"},{"choose":[{"en":"As a temporary fix, we could use the spare part from line 2.","correct":true,"why_tr":"Uygulanabilir geçici bir çözüm öneriyor."},{"en":"As a permanent fix, we can wait until Friday.","correct":false,"why_tr":"Beklemek kalıcı bir çözüm değildir; anlam çelişkili."},{"en":"As a temporal fix, we could use the spare part from line 2.","correct":false,"why_tr":"“temporal” zamanla ilgili demektir; “geçici” için “temporary” kullanılır."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Colleague","en":"Good idea, but line 2 will have some downtime.","tr":"İyi fikir ama 2. hatta biraz duruş olacak."},{"choose":[{"en":"True, it''s a take-off.","correct":false,"why_tr":"“take-off” kalkış demektir."},{"en":"True, it''s a trade-off. Two hours of downtime is better than three days.","correct":true,"why_tr":"Ödünleşimi görüp gerekçeyle karar veriyor."},{"en":"True, so line 2 has no downtime.","correct":false,"why_tr":"Az önce söyleneni inkâr ediyor; çelişkili."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['43bfccda-4491-56cb-827f-e769d98cef4a','0f930437-1ce5-5c0e-b449-d3f922be758c','c876530d-4950-5c77-8df6-ca2e0792b84c']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('f195b6de-af95-580f-aa74-2d350cf8bf5e','c016cb37-6858-58cd-ae01-49689b107921','Tedarikçiyle teknik görüşme','Bir tedarikçiyle yeni bir pompanın teknik özelliklerini konuşuyorsun.','[{"speaker":"Supplier","en":"This model can pump up to 40 liters per minute.","tr":"Bu model dakikada 40 litreye kadar pompalayabilir."},{"choose":[{"en":"That''s good. What''s the total wait of the unit?","correct":false,"why_tr":"“wait” beklemek demektir."},{"en":"That''s good. How much weights the unit?","correct":false,"why_tr":"Soru yapısı bozuk; doğrusu “How much does it weigh?”"},{"en":"That''s good. What''s the total weight of the unit?","correct":true,"why_tr":"Doğru ve ilgili bir soru soruyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Supplier","en":"It weighs about 18 kg, and the tank capacity is 50 liters.","tr":"Yaklaşık 18 kg ağırlığında ve depo kapasitesi 50 litre."},{"choose":[{"en":"Great. Could you sent me the datasheet?","correct":false,"why_tr":"“could” sonrası fiil yalın olur: send."},{"en":"Great. Could you send me the datasheet with all the speculations?","correct":false,"why_tr":"“speculations” spekülasyon demektir."},{"en":"Great. Could you send me the datasheet with all the specifications?","correct":true,"why_tr":"Kibar ve somut bir istek."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['12dbb87c-76e8-5812-a127-a4be97017eb6','d1711756-5239-586c-a974-19406657411b','e04967ef-0be8-5ae7-b43f-12351446c933']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('81f5e814-fd79-5170-a9c6-a4bb60566203','c016cb37-6858-58cd-ae01-49689b107921','Malzeme seçimi','Ekip toplantısında bir drone gövdesi için malzeme seçiyorsunuz.','[{"speaker":"Engineer","en":"Should we use steel or aluminum for the frame?","tr":"Gövde için çelik mi alüminyum mu kullanalım?"},{"choose":[{"en":"Steel, because it''s lighter than aluminum.","correct":false,"why_tr":"Teknik olarak yanlış: çelik alüminyumdan ağırdır."},{"en":"Aluminum, because it is more heavier than steel.","correct":false,"why_tr":"“more heavier” yanlış; ayrıca alüminyum çelikten hafiftir."},{"en":"Aluminum. Compared to steel, it''s much lighter, and we need a lightweight frame.","correct":true,"why_tr":"Seçimi doğru bir gerekçeyle yapıyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Engineer","en":"But is it durable enough in wet conditions?","tr":"Peki ıslak koşullarda yeterince dayanıklı mı?"},{"choose":[{"en":"Yes, if we add a protective coating.","correct":true,"why_tr":"Koşulu belirterek yanıt veriyor."},{"en":"Yes, it''s during in wet conditions.","correct":false,"why_tr":"“during” bir edattır."},{"en":"Yes, it is enough durable.","correct":false,"why_tr":"Kelime sırası yanlış: durable enough."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['f6d2dbda-03bc-5ea5-bdf8-aefc05a08842','097fac93-06b0-55ab-b550-2027b4c25fcc','22b27d26-4cf8-5f33-8519-f5a260a3fca9']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('ad597b64-bc91-5e6a-ac47-51367354f2fa','233b0925-1efe-5baa-9090-54d6f8aef7d6','Test sonucunu bildirme','Test yöneticisi, dünkü titreşim testinin nasıl geçtiğini soruyor.','[{"speaker":"Test manager","en":"How did the vibration test go yesterday?","tr":"Dünkü titreşim testi nasıl geçti?"},{"choose":[{"en":"Eight units past, but two felt after 200 cycles.","correct":false,"why_tr":"“past” ve “felt” yanlış kelimeler: passed, failed."},{"en":"Eight units are passing yesterday.","correct":false,"why_tr":"“yesterday” ile geçmiş zaman gerekir."},{"en":"Eight units passed, but two failed after 200 cycles.","correct":true,"why_tr":"Sonucu sayılarla ve net biçimde veriyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Test manager","en":"Do we know why the two units failed?","tr":"İki ünitenin neden başarısız olduğunu biliyor muyuz?"},{"choose":[{"en":"Yes, because they passed.","correct":false,"why_tr":"Anlamsız: geçtikleri için başarısız olmadılar."},{"en":"We found a small crack near the weld. We need to repeat the test with new samples.","correct":true,"why_tr":"Nedeni ve sonraki adımı açıklıyor."},{"en":"We found a small crab near the weld.","correct":false,"why_tr":"“crab” yengeç demektir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['a6858448-fbfc-5e83-a8af-7ce4d0a864a9','062925df-3b46-54be-8c2b-607fbf414f63','d2ea5cdd-0eb6-52c6-ad12-575f51457852']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('12d5757e-7898-5966-a985-2afd20a2f227','233b0925-1efe-5baa-9090-54d6f8aef7d6','Sensör sapması','Laboratuvarda bir meslektaşın bir sensörün değerlerinin tuhaf olduğunu söylüyor.','[{"speaker":"Colleague","en":"The readings from sensor B look strange today.","tr":"B sensöründen gelen değerler bugün tuhaf görünüyor."},{"choose":[{"en":"Yes, we celebrate it every month.","correct":false,"why_tr":"“celebrate” kutlamak demektir."},{"en":"Yes, there''s a deviation of about 2%. When was it last calibrated?","correct":true,"why_tr":"Gözlemi sayıyla veriyor ve doğru soruyu soruyor."},{"en":"Yes, there''s a devotion of about 2%.","correct":false,"why_tr":"“devotion” bağlılık demektir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Colleague","en":"Last month. I''ll calibrate it again and repeat the measurement.","tr":"Geçen ay. Tekrar kalibre edip ölçümü tekrarlayacağım."},{"choose":[{"en":"Good idea, but don''t repeat nothing.","correct":false,"why_tr":"Çift olumsuzluk ve anlam bozuk."},{"en":"Good idea. Then we can check if the results are reputable.","correct":false,"why_tr":"“reputable” saygın demektir."},{"en":"Good idea. Then we can check if the results are repeatable.","correct":true,"why_tr":"Mantıklı bir sonraki adımı söylüyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['4a53e8a5-376b-5f6b-a0a2-5ef8ae419739','643a2090-eb26-5f9d-a24b-6a8144033ea4','56a6bfb7-69aa-5ed1-8230-274315630873']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('c14cf23a-7068-591e-8333-463f9c43cdd8','1ec86e14-8694-5f09-89f1-2ad9ef7f19f5','Hafta sonu planı','Bir arkadaşın seni cumartesi müzedeki yeni sergiye çağırıyor.','[{"speaker":"Zeynep","en":"Are you free on Saturday? There''s a new exhibition at the museum.","tr":"Cumartesi müsait misin? Müzede yeni bir sergi var."},{"choose":[{"en":"Yes, I''m free in the afternoon. How about meeting at two?","correct":true,"why_tr":"Müsaitliğini söyleyip somut bir saat öneriyor."},{"en":"Yes, I''m going to free on Saturday.","correct":false,"why_tr":"“going to” sonrası fiil gerekir; doğrusu “I''m free”."},{"en":"Yes, I''m fee in the afternoon.","correct":false,"why_tr":"“fee” ücret demektir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Zeynep","en":"Two o''clock works for me. Let''s meet at the main entrance.","tr":"Saat iki bana uyar. Ana girişte buluşalım."},{"choose":[{"en":"Sound good, see you yesterday.","correct":false,"why_tr":"“Sounds” gerekir; “yesterday” ise anlamsız."},{"en":"Sounds good! See you on Saturday.","correct":true,"why_tr":"Kabul ediyor ve doğal biçimde vedalaşıyor."},{"en":"Sounds goods! See you on Saturday.","correct":false,"why_tr":"“goods” mal, eşya demektir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['4cd556b3-816a-522a-b69c-e9ed338b3d4b','1e9e12b5-cf63-550f-818c-d7d45e2dddb1','5711851b-1aa6-5815-903e-a06483040924']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('a87f13c2-a1e7-58c0-87ba-8441378bc5b7','1ec86e14-8694-5f09-89f1-2ad9ef7f19f5','Yemeği erteleme','Bu akşamki yemeğe gidemeyeceksin. Arkadaşına nazikçe haber veriyorsun.','[{"speaker":"Kerem","en":"We''re still meeting for dinner tonight, right?","tr":"Bu akşam yemekte buluşuyoruz, değil mi?"},{"choose":[{"en":"I''m afraid I can. I have to work late.","correct":false,"why_tr":"Olumlu cevap ardından gelen mazeretle çelişiyor."},{"en":"I''m afraid of I can''t, I postpone Friday.","correct":false,"why_tr":"“of” fazla ve cümle bozuk."},{"en":"I''m afraid I can''t. I have to work late. Can we postpone it until Friday?","correct":true,"why_tr":"Nazikçe reddediyor, nedenini söylüyor ve yeni bir zaman öneriyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Kerem","en":"No problem. Friday works for me.","tr":"Sorun değil. Cuma bana uyar."},{"choose":[{"en":"Great, thanks for understanding!","correct":true,"why_tr":"Anlayış gösterdiği için teşekkür ediyor."},{"en":"Great, I cancel Friday too.","correct":false,"why_tr":"Az önce önerdiği günü iptal ediyor; anlamsız."},{"en":"Great, thanks for understand!","correct":false,"why_tr":"“for” sonrası -ing gerekir: understanding."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['346aafd8-1adc-5fc5-adda-cd7f5aa4096e','e74c0c92-6868-55b0-9f8a-a88f7e4c2d42','cc4ec634-3c5a-5409-b2f5-cca746cf6536']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('6549ddd3-72d2-5c59-9ad4-fed64eb0ee28','2fe5da34-f4cb-5c47-8c4e-d94faab76c7f','İlk iş günü','Yeni işinde ilk günün. Tasarım ekibinden bir iş arkadaşı kendini tanıtıyor.','[{"speaker":"Murat","en":"Hi, I''m Murat from the design team. You must be new here.","tr":"Selam, ben tasarım ekibinden Murat. Burada yenisin galiba."},{"choose":[{"en":"Yes, I started today. I''m Deniz. Nice to meet you!","correct":true,"why_tr":"Kendini tanıtıyor ve uygun selamlaşmayı kullanıyor."},{"en":"No, I''m Deniz. How do you do it?","correct":false,"why_tr":"“How do you do it?” “Bunu nasıl yapıyorsun?” demektir."},{"en":"Yes, I start yesterday. Nice to meat you!","correct":false,"why_tr":"Zaman yanlış; ayrıca “meat” et demektir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Murat","en":"Nice to meet you too. Where are you from?","tr":"Ben de memnun oldum. Nerelisin?"},{"choose":[{"en":"I''m originally from Trabzon, but I''ve lived in İstanbul for five years.","correct":true,"why_tr":"Aslen nereli olduğunu ve ne zamandır nerede yaşadığını doğru anlatıyor."},{"en":"I''m from Trabzon since five years.","correct":false,"why_tr":"Süre için “for” ve present perfect gerekir."},{"en":"I live from Trabzon.","correct":false,"why_tr":"“live from” denmez; “I''m from Trabzon” denir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['a10a7580-2b12-58a6-9341-3078301c7d05','a1b411b0-1da5-5f14-9e8f-0899e95821b3','ca08e11a-a09d-5b11-a14f-f39400ba8ca0']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('32120165-547a-5028-876c-56b4ae993734','2fe5da34-f4cb-5c47-8c4e-d94faab76c7f','Partide sohbet','Bir arkadaşının doğum günü partisindesin ve yeni tanıştığın biriyle sohbet ediyorsun.','[{"speaker":"Lena","en":"So, what do you do in your spare time?","tr":"Peki, boş zamanında neler yaparsın?"},{"choose":[{"en":"My spare time is on Saturday.","correct":false,"why_tr":"Soru ne yaptığını soruyor, ne zaman boş olduğunu değil."},{"en":"I like hike and take photo.","correct":false,"why_tr":"“like” sonrası -ing gerekir; “photos” çoğul olmalı."},{"en":"I like hiking and taking photos. What about you?","correct":true,"why_tr":"Soruyu yanıtlıyor ve sohbeti sürdürmek için geri soruyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Lena","en":"I love hiking too! There''s a nice trail near the lake.","tr":"Ben de yürüyüşe bayılırım! Gölün yakınında güzel bir parkur var."},{"choose":[{"en":"Really? Me neither.","correct":false,"why_tr":"“Me neither” olumsuz bir cümleye verilir."},{"en":"Really? I''m not interested on it.","correct":false,"why_tr":"Edat yanlış ve sohbeti kaba biçimde kapatıyor."},{"en":"Really? That sounds great. We should go together sometime.","correct":true,"why_tr":"İlgi gösteriyor ve doğal bir öneri yapıyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['2f943885-32d9-5760-babf-f15db7430c23','d3dbc965-20b5-5453-8d7b-3655064a251c','6d77ac97-dead-53c4-be13-a5c0dc202b65']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('350f12c6-217e-5741-8741-5eeac61e4cd2','9fec7c37-b21c-53df-8fc9-49684d6cfa85','Otelde arıza bildirme','Otel odanda klima çalışmıyor. Resepsiyonu arıyorsun.','[{"speaker":"Receptionist","en":"Good evening, reception. How can I help you?","tr":"İyi akşamlar, resepsiyon. Size nasıl yardımcı olabilirim?"},{"choose":[{"en":"Hi, room 304. The air conditioner don''t work.","correct":false,"why_tr":"Tekil özne ile “doesn''t” gerekir."},{"en":"Hi, I''m the air conditioner in room 304.","correct":false,"why_tr":"Kendini klima olarak tanıtıyor; anlamsız."},{"en":"Hi, this is room 304. The air conditioner doesn''t work.","correct":true,"why_tr":"Oda numarasını ve sorunu net söylüyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Receptionist","en":"I''m sorry about that. Someone will come to fix it in ten minutes.","tr":"Bunun için üzgünüm. On dakika içinde biri gelip tamir edecek."},{"choose":[{"en":"Thank you. Could I also has an extra blanket?","correct":false,"why_tr":"“could” sonrası fiil yalın olur: have."},{"en":"Thank you, but it''s not urgent, so fix it now.","correct":false,"why_tr":"Çelişkili: acil değil deyip hemen istiyor."},{"en":"Thank you. Could I also have an extra blanket, please?","correct":true,"why_tr":"Teşekkür ediyor ve kibar bir ek istekte bulunuyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['b7fab66e-d891-5139-9870-c333d6c6b3e1','65e28ef2-98ad-5705-aafd-4d3b7e637fa7','f9ed532c-f561-5409-84ed-e0327f0b1dec']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('902ecaed-f548-54ca-82f3-0550526d7166','9fec7c37-b21c-53df-8fc9-49684d6cfa85','Mağazada ürün değiştirme','Dün aldığın gömlek küçük geldi. Mağazada daha büyük bir bedenle değiştirmek istiyorsun.','[{"speaker":"Shop assistant","en":"Hello! Can I help you?","tr":"Merhaba! Yardımcı olabilir miyim?"},{"choose":[{"en":"Yes, I buyed this shirt, it''s too small.","correct":false,"why_tr":"“buy” düzensiz bir fiildir: bought."},{"en":"Yes, can I exchange me a medium?","correct":false,"why_tr":"Yapı bozuk; doğrusu “exchange it for a medium”."},{"en":"Yes, I bought this shirt yesterday, but it''s too small. Can I exchange it for a medium?","correct":true,"why_tr":"Durumu ve isteğini açık ve kibar biçimde anlatıyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Shop assistant","en":"Of course. Do you have the receipt?","tr":"Elbette. Fişiniz var mı?"},{"choose":[{"en":"Yes, here is it.","correct":false,"why_tr":"Kelime sırası yanlış: here it is."},{"en":"Yes, here it is.","correct":true,"why_tr":"Bir şeyi uzatırken kullanılan doğal kalıp."},{"en":"Yes, I have the recipe.","correct":false,"why_tr":"“recipe” yemek tarifidir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['30e2fa1c-d797-579a-b17f-e512f4d2e8d5','7bf53bc7-0a5c-5e6d-a432-93e882fd214d','691a24be-eb96-5a09-b1f4-54b43ee23d53']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('1daeafe5-f466-509e-a37a-42030e26899a','6669c461-b0f4-5b73-b7bd-cd4c249f1e3f','Doktora belirtileri anlatma','İki gündür ateşin ve boğaz ağrın var. Doktor belirtilerini soruyor.','[{"speaker":"Doctor","en":"Hello, please have a seat. What seems to be the problem?","tr":"Merhaba, buyurun oturun. Sorun nedir?"},{"choose":[{"en":"I had a fever tomorrow.","correct":false,"why_tr":"Zaman ifadesi ve fiil zamanı çelişiyor."},{"en":"I have fever since two days.","correct":false,"why_tr":"Süre için “for”, süregelen durum için “I''ve had” gerekir."},{"en":"I''ve had a fever and a sore throat for two days.","correct":true,"why_tr":"Süregelen belirti için “I''ve had … for two days” doğru."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Doctor","en":"I see. On a scale of 1 to 10, how bad is the pain when you swallow?","tr":"Anlıyorum. 1''den 10''a kadar bir ölçekte yutkunurken ağrı ne kadar şiddetli?"},{"choose":[{"en":"About seven. It hurts a lot when I swallow.","correct":true,"why_tr":"Ölçekle cevap veriyor ve “It hurts when I …” kalıbını doğru kullanıyor."},{"en":"It hurt me seven.","correct":false,"why_tr":"Dilbilgisi ve anlam bozuk."},{"en":"Seven times a day.","correct":false,"why_tr":"Soru şiddeti soruyor, sıklığı değil."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Doctor","en":"Let me take a look at your throat. Say “ah”.","tr":"Boğazınıza bir bakayım. “Aa” deyin."}]'::jsonb,array['e8361c82-0c00-5754-9a17-86348b558415','1adb3866-2f97-5380-aa2a-e24b3f43c665','34cac6d7-cc9b-5692-830c-880b7f5b66fb']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('3f8374bf-8153-5133-9ac9-41e062179abe','6669c461-b0f4-5b73-b7bd-cd4c249f1e3f','Eczanede ilaç talimatı','Eczacı reçetendeki antibiyotiği veriyor ve nasıl kullanacağını anlatıyor.','[{"speaker":"Pharmacist","en":"Here''s your antibiotic. Take one capsule twice a day, after meals.","tr":"İşte antibiyotiğiniz. Günde iki kez, yemekten sonra bir kapsül alın."},{"choose":[{"en":"How much long should I take it?","correct":false,"why_tr":"“how much long” denmez; “how long” yeterli."},{"en":"How long I should take it?","correct":false,"why_tr":"Soru cümlesinde yardımcı fiil özneden önce gelir: should I."},{"en":"How long should I take it for?","correct":true,"why_tr":"Tedavi süresini doğal bir soruyla soruyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Pharmacist","en":"For seven days. Make sure you finish the whole box, even if you feel better.","tr":"Yedi gün. Kendinizi daha iyi hissetseniz bile kutunun tamamını bitirdiğinizden emin olun."},{"choose":[{"en":"Has it got side effect?","correct":false,"why_tr":"Çoğul olmalı ve soru doğal değil."},{"en":"Are there any side effects I should know about?","correct":true,"why_tr":"Yan etkileri kibar ve doğru bir yapıyla soruyor."},{"en":"What is the side dish of this medicine?","correct":false,"why_tr":"“side dish” garnitür demektir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Pharmacist","en":"Some people feel mild nausea. If you get a rash, stop taking it and call your doctor.","tr":"Bazı kişilerde hafif bulantı olur. Döküntü çıkarsa almayı bırakın ve doktorunuzu arayın."}]'::jsonb,array['ad0dbacb-1623-52c3-89a6-232154d8de70','babee9dd-ec78-59e7-a081-68bb23c7ad28','cfe0f3eb-1cda-5e65-8d6d-5654b25b06f7']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('9fbc8d36-7ae3-5463-8007-2e8dfba3c3b6','a64481c9-1fe3-5f37-a501-1e99c5f1321f','Eczacıdan öneri isteme','Boğazın ağrıyor ve hafif ateşin var. Eczacıdan reçetesiz bir şey önermesini istiyorsun.','[{"speaker":"Pharmacist","en":"Hi, how can I help you today?","tr":"Merhaba, bugün size nasıl yardımcı olabilirim?"},{"choose":[{"en":"I have a sore throat and a slight fever. Can you recommend something?","correct":true,"why_tr":"Belirtiyi anlatıp kibarca öneri istiyor."},{"en":"I want medicine for throat.","correct":false,"why_tr":"Fazla kısa ve kaba; belirti anlatılmamış."},{"en":"Give me antibiotic, please.","correct":false,"why_tr":"Antibiyotik reçetesiz verilmez; belirtiyi anlatmak gerekir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Pharmacist","en":"These lozenges are available over the counter. Take one every three hours. Do you take any other medicine?","tr":"Bu pastiller reçetesiz satılıyor. Üç saatte bir tane alın. Başka ilaç kullanıyor musunuz?"},{"choose":[{"en":"Yes, I take blood pressure pills. Is it safe to take them together?","correct":true,"why_tr":"Kullandığı ilacı söyleyip etkileşimi soruyor."},{"en":"No problem, I take everything.","correct":false,"why_tr":"Soruya cevap vermiyor ve güvenli değil."},{"en":"Yes, I take. Is safe?","correct":false,"why_tr":"Nesne ve özne eksik; anlaşılmıyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Pharmacist","en":"That''s fine, there are no interactions. If symptoms persist for more than three days, please see a doctor.","tr":"Sorun yok, etkileşimi yok. Belirtiler üç günden fazla sürerse lütfen doktora görünün."}]'::jsonb,array['3541a6f8-8321-529a-be19-5136b0c4b1e7','a725cc88-affc-560d-b6d6-cac631fd1525','039292a3-63e7-543d-bc59-f947407e1861','d20cb03c-9259-58cd-95f9-4f4ec4614d8b']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('448f491d-5fc9-5212-9774-574cb0d8e74e','a64481c9-1fe3-5f37-a501-1e99c5f1321f','Reçeteli ilacı almak','Doktorun yazdığı antibiyotiği almaya gittin. Penisiline alerjin var.','[{"speaker":"Pharmacist","en":"Here''s your prescription. Do you have any allergies?","tr":"İşte reçeteniz. Herhangi bir alerjiniz var mı?"},{"choose":[{"en":"Yes, I''m allergic to penicillin.","correct":true,"why_tr":"Alerjiyi doğru kalıpla söylüyor."},{"en":"No, I like penicillin.","correct":false,"why_tr":"Alerji sorusuna uygun değil."},{"en":"Yes, I have allergic penicillin.","correct":false,"why_tr":"“allergic to” kalıbı bozuk."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Pharmacist","en":"Good that you told me. This one isn''t penicillin, so it''s safe for you. Take it for seven days and finish the course.","tr":"Söylemeniz iyi oldu. Bu penisilin değil, sizin için güvenli. Yedi gün kullanın ve kürü bitirin."},{"choose":[{"en":"What I do if I forget?","correct":false,"why_tr":"Soru yapısı eksik: should + özne."},{"en":"Can I stop when I feel better?","correct":false,"why_tr":"Eczacı kürü bitirmeyi söyledi; bu soru talimatla çelişiyor."},{"en":"What should I do if I miss a dose?","correct":true,"why_tr":"Unutulan doz için doğru soru."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Pharmacist","en":"Take it as soon as you remember, but never take a double dose.","tr":"Hatırlar hatırlamaz alın ama asla çift doz almayın."}]'::jsonb,array['a198bcfa-cdd2-5113-88ae-2d45b15cc6fa','f336ce5a-f252-50b9-a53d-d5c59f3fe486','8c4d10b7-78a7-5452-86cc-1e90523e5572']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('6d7fb75b-2525-5975-ad5c-293c645976f3','d7846284-4a8a-509a-b64b-155e6f82e9c6','Ameliyat öncesi kontrol','Yarın sabah ameliyat olacaksın. Hemşire son kontrolleri yapıyor.','[{"speaker":"Nurse","en":"Good evening. You''re having your surgery at eight tomorrow. Have you signed the consent form?","tr":"İyi akşamlar. Yarın sekizde ameliyat oluyorsunuz. Onam formunu imzaladınız mı?"},{"choose":[{"en":"What is consent?","correct":false,"why_tr":"Formu bilmiyorsa sorabilir ama soru eksik ve kaba."},{"en":"Yes, I sign it tomorrow.","correct":false,"why_tr":"Zaman uyumsuz; imzalama işi geçmişte olmalı."},{"en":"Yes, I signed it this afternoon.","correct":true,"why_tr":"Bitmiş bir işi doğru zamanla söylüyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Nurse","en":"Good. Remember, you''re nil by mouth from midnight. Have you had anything to eat since dinner?","tr":"Güzel. Unutmayın, gece yarısından itibaren ağızdan hiçbir şey almıyorsunuz. Akşam yemeğinden beri bir şey yediniz mi?"},{"choose":[{"en":"No, I don''t ate anything.","correct":false,"why_tr":"“don''t” sonrası yalın fiil gerekir."},{"en":"No, just some water. Is that OK?","correct":true,"why_tr":"Doğru bilgiyi verip uygun olup olmadığını soruyor."},{"en":"I will eat a sandwich at midnight.","correct":false,"why_tr":"Talimata aykırı."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Nurse","en":"Water is fine until midnight. Press the call button if you need anything.","tr":"Gece yarısına kadar su içebilirsiniz. Bir şeye ihtiyacınız olursa çağrı düğmesine basın."}]'::jsonb,array['cb8a87f8-6b2f-5bea-bda8-4a93de3fd274','24ff18be-d632-584a-8c43-3edda5219216','abceaeaa-392a-5eb2-9729-83e3d517a213']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('0d46195c-58be-57d3-8f78-befdc46c6787','d7846284-4a8a-509a-b64b-155e6f82e9c6','Taburculuk konuşması','Ameliyattan iki gün sonra taburcu oluyorsun. Hemşire evde dikkat etmen gerekenleri anlatıyor.','[{"speaker":"Nurse","en":"The doctor says you can be discharged today. Is there anyone who can pick you up?","tr":"Doktor bugün taburcu olabileceğinizi söylüyor. Sizi alabilecek biri var mı?"},{"choose":[{"en":"Yes, my sister come three o''clock.","correct":false,"why_tr":"Fiil çekimi ve edat eksik."},{"en":"No, I''ll drive myself.","correct":false,"why_tr":"Ameliyattan sonra araba kullanmak uygun değil."},{"en":"Yes, my sister is coming at three.","correct":true,"why_tr":"Planlanmış bir olay için “is coming” doğal."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Nurse","en":"Great. Keep the wound clean and dry. Your stitches will be removed in ten days.","tr":"Harika. Yarayı temiz ve kuru tutun. Dikişleriniz on gün içinde alınacak."},{"choose":[{"en":"Can I swim tomorrow?","correct":false,"why_tr":"Yara kuru tutulmalıyken yüzmek uygun değil."},{"en":"When can I have a shower?","correct":true,"why_tr":"Bakımla ilgili doğru soru yapısı."},{"en":"When I can have shower?","correct":false,"why_tr":"Soru sırası ve tanımlık eksik."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Nurse","en":"You can shower after 48 hours, but don''t soak the wound.","tr":"48 saat sonra duş alabilirsiniz ama yarayı ıslatıp bekletmeyin."}]'::jsonb,array['aecf2fca-8f5a-5104-9003-8ab0a114c93d','99ea80ba-e92d-538c-8181-9eaf740d61dd','6cc87bd5-d417-51ff-8544-12bf6d67e656']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('83e4f848-4ca9-5290-8551-7a38736ee546','53b5b8fc-d379-599c-9d8e-77b99bfec9e9','İK ile istifa görüşmesi','Uluslararası bir şirkette çalışıyorsun ve istifa etmek istiyorsun. İK uzmanıyla konuşuyorsun.','[{"speaker":"HR","en":"Hi, you wanted to talk to me?","tr":"Merhaba, benimle konuşmak istemiştiniz?"},{"choose":[{"en":"Yes, I am resign today.","correct":false,"why_tr":"Fiil yapısı yanlış: I''m resigning / I want to resign."},{"en":"Yes. I''ve decided to resign. What is my notice period?","correct":true,"why_tr":"Kararını net söyleyip ihbar süresini soruyor."},{"en":"Yes. Give me my money.","correct":false,"why_tr":"Kaba ve konuyla doğrudan ilgili değil."}],"q":"En uygun yanıt hangisi?"},{"speaker":"HR","en":"Under the terms of your employment contract, it''s four weeks. You''ll need to put it in writing.","tr":"İş sözleşmenizin şartlarına göre dört hafta. Bunu yazılı olarak bildirmeniz gerekecek."},{"choose":[{"en":"Of course. I''ll send you a formal letter today. Am I entitled to my unused leave?","correct":true,"why_tr":"Süreci kabul edip hakkını kibarca soruyor."},{"en":"OK. Can I don''t work the four weeks?","correct":false,"why_tr":"Soru yapısı bozuk."},{"en":"Writing is not necessary.","correct":false,"why_tr":"Sözleşme şartına aykırı."}],"q":"En uygun yanıt hangisi?"},{"speaker":"HR","en":"Yes, any unused leave will be paid in your final salary.","tr":"Evet, kullanılmamış izinler son maaşınızla ödenecek."}]'::jsonb,array['ed17308c-ff97-51fe-9ae8-40c0a5dfdd87','36286673-ba85-5aab-8c6a-a66355ee975b','20fe05b5-5808-5bee-8efd-45a044c363bb']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('014844a7-e977-517c-acb6-3da94f18a05f','53b5b8fc-d379-599c-9d8e-77b99bfec9e9','Kullanıcının veri sorusu','Bir uygulama şirketinin destek ekibindesin. Yabancı bir kullanıcı verilerini sorup rızasını geri çekmek istiyor.','[{"speaker":"User","en":"What personal data do you keep about me?","tr":"Hakkımda hangi kişisel verileri tutuyorsunuz?"},{"choose":[{"en":"We keep your email address and your learning progress. You can download a copy from your profile.","correct":true,"why_tr":"Açık bilgi verip kullanıcıya yol gösteriyor."},{"en":"Everything, don''t worry.","correct":false,"why_tr":"Belirsiz ve güven vermeyen bir cevap."},{"en":"Data is secret, I can''t say.","correct":false,"why_tr":"Kullanıcının bilgi alma hakkı var."}],"q":"En uygun yanıt hangisi?"},{"speaker":"User","en":"OK. I''d like to withdraw my consent for the AI features.","tr":"Tamam. AI özellikleri için verdiğim rızayı geri çekmek istiyorum."},{"choose":[{"en":"Please withdrawn it in settings.","correct":false,"why_tr":"Fiil biçimi yanlış."},{"en":"Of course. You can withdraw your consent by turning off “AI features” in Settings. Your other data won''t be affected.","correct":true,"why_tr":"Talebi kabul edip nasıl yapılacağını ve sonucunu anlatıyor."},{"en":"You can''t withdraw it now.","correct":false,"why_tr":"Rıza her zaman geri çekilebilir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"User","en":"Great, thank you for explaining.","tr":"Harika, açıkladığınız için teşekkürler."}]'::jsonb,array['5a5e0c78-455d-5767-aab7-19dcf1ba853e','1e19a322-8014-5cd8-8bb1-27fe4da4384f','ed64d297-643c-54e9-bcdc-2bc7bea41560']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('29abd55d-d7f7-54c7-bb3f-61b6249dbce8','35f00cb3-8900-51a4-aeb8-113195e43047','Müşteriyle sözleşme maddesini konuşma','Bir avukatlık bürosunda çalışıyorsun. Yabancı bir müşteri kira sözleşmesindeki fesih maddesini soruyor.','[{"speaker":"Client","en":"Can I end the lease early if I move to another city?","tr":"Başka bir şehre taşınırsam kira sözleşmesini erken bitirebilir miyim?"},{"choose":[{"en":"Yes, you can determine the lease.","correct":false,"why_tr":"“determine” belirlemek demektir; fesih “terminate”."},{"en":"Yes. Under clause 9, you may terminate the lease with two months'' written notice.","correct":true,"why_tr":"Maddeyi, hakkı (may) ve bildirim süresini doğru veriyor."},{"en":"Yes, under clause 9 you shall terminate whenever.","correct":false,"why_tr":"“shall” yükümlülük bildirir; ayrıca bildirim süresini atlıyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Client","en":"Will I lose my deposit?","tr":"Depozitomu kaybeder miyim?"},{"choose":[{"en":"Your deposit is liable.","correct":false,"why_tr":"“liable” kişi veya kurum için kullanılır; anlam bozuk."},{"en":"You will lose it in the event of.","correct":false,"why_tr":"“in the event of” sonrasında bir isim gerekir; cümle eksik."},{"en":"Not if you give proper notice and leave the flat in good condition.","correct":true,"why_tr":"Koşulu net ve doğal bir dille anlatıyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Client","en":"Good. Could you send me that clause by email?","tr":"Güzel. O maddeyi bana e-postayla gönderebilir misiniz?"}]'::jsonb,array['6c428b0f-2382-542a-abef-7b9925d21cd2','72fdfea8-f24b-5783-b445-ddd0a6b94326','4304d880-163b-56e8-a73d-f729eb7909fe']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('84fb4175-6716-5b14-a6c2-7b26e95c0929','35f00cb3-8900-51a4-aeb8-113195e43047','Karşı tarafa resmî cevap','Karşı tarafın avukatı sözleşme taslağına yorum gönderdi. Telefonda görüştükten sonra resmî bir e-posta yazacaksın.','[{"speaker":"Senior lawyer","en":"Write to them and say we accept most changes, but not the new penalty clause.","tr":"Onlara yaz; değişikliklerin çoğunu kabul ediyoruz ama yeni ceza maddesini kabul etmiyoruz de."},{"choose":[{"en":"Further to our phone call, on behalf of our client we accept most of the proposed amendments, except the new penalty clause.","correct":true,"why_tr":"Resmî açılış, temsil ifadesi ve istisna doğru kurulmuş."},{"en":"Hi, we like your changes but no penalty, thanks.","correct":false,"why_tr":"Hukuki yazışma için fazla samimi ve belirsiz."},{"en":"Farther to our phone call, we accept all amendments.","correct":false,"why_tr":"“Farther” yanlış; ayrıca ceza maddesini reddetmiyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Senior lawyer","en":"Good. Ask them to reply before the deadline.","tr":"Güzel. Son tarihten önce cevap vermelerini iste."},{"choose":[{"en":"We would be great if you reply 20 June.","correct":false,"why_tr":"“great” yerine “grateful”, tarih için “by” gerekir."},{"en":"Reply by 20 June or else.","correct":false,"why_tr":"Tehditkâr ve profesyonel değil."},{"en":"We would be grateful if you could reply by 20 June.","correct":true,"why_tr":"Kibar ve resmî istek kalıbı."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['d17a7f2b-0cc9-5338-bd94-8e77f1e6ea8c','6001fb32-6cdd-5a13-9d01-79b405785215','196ca581-9112-5c17-81ff-4ce15afdaabd']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('59b020b7-62e0-5407-8746-56f0894449e5','0f692eaa-47c8-5983-880d-2c55c738f67a','Müvekkille ilk görüşme','Bir hukuk bürosunda stajyersin. Yabancı bir müvekkil, eski işvereninin maaşını ödemediğini söylüyor.','[{"speaker":"Client","en":"My former employer hasn''t paid my last two salaries. What can I do?","tr":"Eski işverenim son iki maaşımı ödemedi. Ne yapabilirim?"},{"choose":[{"en":"Why you didn''t ask money?","correct":false,"why_tr":"Soru yapısı bozuk ve suçlayıcı."},{"en":"I''m sorry to hear that. Do you have your employment contract and payslips?","correct":true,"why_tr":"Empati kurup gerekli belgeleri soruyor."},{"en":"You must sue them tomorrow.","correct":false,"why_tr":"Bilgi almadan kesin tavsiye vermek uygun değil."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Client","en":"Yes, I have both. Should I go to court?","tr":"Evet, ikisi de var. Mahkemeye gitmeli miyim?"},{"choose":[{"en":"Yes, court is always the best.","correct":false,"why_tr":"Kesin ve gerçekçi olmayan bir yargı."},{"en":"First we would advise you to send a formal letter. If they don''t pay, we can file a lawsuit.","correct":true,"why_tr":"Aşamalı ve resmî bir tavsiye veriyor."},{"en":"We would advice you to wait.","correct":false,"why_tr":"“advice” isimdir; fiil “advise” olmalı."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Client","en":"That sounds sensible. How long do I have to file a claim?","tr":"Mantıklı görünüyor. Talep için ne kadar sürem var?"}]'::jsonb,array['73b0b235-93d5-5a23-b919-5f44869e64ef','669d2c6c-5a0c-5b34-8253-8008d8f45090','ae48975b-d46b-5632-8b8a-fb94274ba8b1']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('fe2d2b3e-a714-58e3-b582-dbe8c86f2e06','0f692eaa-47c8-5983-880d-2c55c738f67a','Duruşma ertelendi','Yabancı müvekkile telefonda duruşmanın ertelendiğini haber veriyorsun.','[{"speaker":"Client","en":"Hello, is everything ready for tomorrow''s hearing?","tr":"Merhaba, yarınki duruşma için her şey hazır mı?"},{"choose":[{"en":"Tomorrow is cancel.","correct":false,"why_tr":"Eksik ve yanlış yapı."},{"en":"I''m afraid the hearing has been adjourned until 3 June.","correct":true,"why_tr":"Kötü haberi kibarca ve doğru edilgen yapıyla veriyor."},{"en":"The hearing adjourned you.","correct":false,"why_tr":"Anlamsız bir cümle."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Client","en":"Oh no. Why?","tr":"Olamaz. Neden?"},{"choose":[{"en":"Because witness sick.","correct":false,"why_tr":"Fiil ve tanımlık eksik."},{"en":"One of the witnesses is ill and can''t attend.","correct":true,"why_tr":"Gerekçeyi açık ve doğru anlatıyor."},{"en":"I don''t know, the judge is lazy.","correct":false,"why_tr":"Profesyonel olmayan bir açıklama."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Client","en":"I see. Do I need to do anything before then?","tr":"Anlıyorum. O zamana kadar bir şey yapmam gerekiyor mu?"}]'::jsonb,array['e592a097-935a-5ed4-8434-b8648ebc0692','370bf2c5-05b1-5a22-83a5-09b425104bf3','b858e434-dec6-573f-81f0-df5520d1ea42']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('6f7cc84f-f7ed-58e0-b82b-3e642f341c02','26515c63-3bd4-5d24-9fbd-336e392868a3','İnceleme yorumuna yanıt verme','Bir ekip arkadaşın PR''ına yorum bıraktı: aynı mantık iki bileşende tekrarlanmış.','[{"speaker":"Reviewer","en":"This logic is duplicated in two components. Could we move it to a shared helper?","tr":"Bu mantık iki bileşende tekrarlanmış. Ortak bir yardımcıya taşıyabilir miyiz?"},{"choose":[{"en":"Good point. I''ll move it to a helper and update the PR.","correct":true,"why_tr":"Yorumu kabul edip ne yapacağını söylüyor."},{"en":"Good paint. I''ll move it to a helper.","correct":false,"why_tr":"“paint” boya demektir; doğru ifade “Good point”."},{"en":"No point. It is duplicated because duplicated.","correct":false,"why_tr":"Kaba ve anlamsız bir gerekçe."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Reviewer","en":"Thanks! Let me know when it''s ready for another look.","tr":"Teşekkürler! Tekrar bakmaya hazır olduğunda haber ver."},{"choose":[{"en":"Will do. I addressing all comments yesterday.","correct":false,"why_tr":"Fiil zamanı yanlış."},{"en":"Will do. I''ve added all your comments to the code.","correct":false,"why_tr":"Yorumlar koda eklenmez; gereği yapılır (addressed)."},{"en":"Will do. I''ve addressed all your comments now.","correct":true,"why_tr":"Kısa ve net; yorumların gereğinin yapıldığını bildiriyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['4d000725-ddb0-56f9-8259-b32b3a7f742c','414b1b96-7f37-5533-ae80-d590497284bc','f8f7e7b1-953c-54f2-9fa3-c714e686ba94']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('4775ddb6-ac52-573d-9c2d-5dfc36ad0202','26515c63-3bd4-5d24-9fbd-336e392868a3','PR onaylama','Bir PR''ı inceledin. Küçük bir öneri dışında her şey iyi görünüyor.','[{"speaker":"Author","en":"Hi! Did you have a chance to look at my PR?","tr":"Merhaba! PR''ıma bakma fırsatın oldu mu?"},{"choose":[{"en":"Yes, it is a nitpick, so I can''t approve.","correct":false,"why_tr":"Küçük bir not onayı engellemez; anlam çelişkili."},{"en":"Yes, looks good to me. Just one nitpick about a variable name.","correct":true,"why_tr":"Onay veriyor ve küçük notu belirtiyor."},{"en":"Yes, looks good at me, no nitpicks for merge.","correct":false,"why_tr":"Edat yanlış ve cümle bozuk."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Author","en":"Thanks! Can I merge it after I fix that?","tr":"Teşekkürler! Onu düzelttikten sonra birleştirebilir miyim?"},{"choose":[{"en":"Sure, feel free to merge once the tests pass.","correct":true,"why_tr":"Onay veriyor ve koşulu net söylüyor."},{"en":"Sure, feel free merge.","correct":false,"why_tr":"“feel free to + fiil” kalıbında “to” eksik."},{"en":"Sure, feel free to merge before you write it.","correct":false,"why_tr":"Mantıksız: henüz yazılmamış kod birleştirilmez."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['b989cb15-0fba-5e2a-8780-384bfb12e524','28fe1b03-a43d-5c98-9f2e-bd083346a336','0876e386-341f-5164-94ee-0fec3c70d5e8']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('01d466c0-5cd1-5ef2-8f8a-2276d54e1f2a','8c6847cf-f469-5cd6-b2d7-4c15dbfd531a','Çökmeyi bildirme','Ekip kanalındasın. Uygulama büyük dosya yüklenirken çöküyor ve sen bunu her seferinde yeniden oluşturabiliyorsun.','[{"speaker":"QA engineer","en":"Hey, did you see the crash report from this morning?","tr":"Selam, bu sabahki çökme raporunu gördün mü?"},{"choose":[{"en":"Yes. I reproduced it never.","correct":false,"why_tr":"“never” bu konumda kullanılmaz; doğrusu “I''ve never reproduced it.”"},{"en":"Yes. It crashes when I upload a large file, and I can reproduce it every time.","correct":true,"why_tr":"Ne olduğunu ve her seferinde yeniden oluşturulabildiğini net anlatıyor."},{"en":"Yes. It crushes when I upload a large file.","correct":false,"why_tr":"“crush” ezmek demektir; uygulama için “crash” kullanılır."}],"q":"En uygun yanıt hangisi?"},{"speaker":"QA engineer","en":"Great. Can you add the steps to reproduce to the ticket?","tr":"Harika. Yeniden oluşturma adımlarını kayda ekleyebilir misin?"},{"choose":[{"en":"Sure, I''ll remove them from the ticket.","correct":false,"why_tr":"İstenenin tersi: eklemek yerine kaldırmak."},{"en":"Sure, I''ll add them yesterday.","correct":false,"why_tr":"“will” ile “yesterday” birlikte kullanılmaz."},{"en":"Sure, I''ll add them with the full stack trace.","correct":true,"why_tr":"İsteği kabul edip faydalı bir ek bilgi sunuyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['f280db72-ad91-5c7a-a568-581292437396','8a79cd26-bd6e-5349-95ef-ca5ca4931667','98e4bf70-ae82-5171-a032-baec8fa2108d']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('b36504e8-cf8e-568e-89d9-fe5249ebfdc3','8c6847cf-f469-5cd6-b2d7-4c15dbfd531a','Kesintiyi açıklama','Kısa bir hizmet kesintisi oldu. Ekip lideri ne olduğunu ve kök nedeni soruyor.','[{"speaker":"Team lead","en":"What happened during the outage?","tr":"Kesinti sırasında ne oldu?"},{"choose":[{"en":"A bad config change caused timeouts, so we rolled back the release.","correct":true,"why_tr":"Nedeni ve alınan önlemi doğru sırayla anlatıyor."},{"en":"We rolled out the outage to all users.","correct":false,"why_tr":"Kesinti “roll out” edilmez; anlam saçma."},{"en":"The outage caused a bad config change.","correct":false,"why_tr":"Neden-sonuç ters kurulmuş."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Team lead","en":"Do we know the root cause yet?","tr":"Kök nedeni artık biliyor muyuz?"},{"choose":[{"en":"Not yet, so the root cause fixed it.","correct":false,"why_tr":"Anlamsız: bir neden bir şeyi düzeltmez."},{"en":"Not yet. For now, we have a workaround: we restart the service every hour.","correct":true,"why_tr":"Durumu dürüstçe söylüyor ve geçici çözümü açıklıyor."},{"en":"Yes, the root cause is a workaround.","correct":false,"why_tr":"Geçici çözüm bir neden değildir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['dd6348f0-0616-5661-830b-41055252e91b','9b01a6fc-4488-53fd-9b80-e50589889cc4','578b51f1-decc-5ff2-a3c1-c5c013ba7191','31432227-ee16-51fe-9e9e-dd96d70c358d']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('397399d1-1705-53cb-9114-55b027b305b5','b2d05b0d-3f42-5152-8985-f7b28dde1bdb','Toplantıda engeli açıklama','Günlük toplantıdasın. API değişikliği yüzünden ilerleyemiyorsun ve yardım istemek istiyorsun.','[{"speaker":"Team lead","en":"Morning, everyone! Any blockers today?","tr":"Herkese günaydın! Bugün bir engel var mı?"},{"choose":[{"en":"Yes, I''m blocked by the API change. Could someone from the backend team help me?","correct":true,"why_tr":"Engeli ve isteği açıkça söylüyor; “Could someone…” nazik bir istek."},{"en":"Yes, I block the API change today.","correct":false,"why_tr":"“I block” API''yi senin engellediğin anlamına gelir; anlam ters."},{"en":"No blockers, so I need help with the API.","correct":false,"why_tr":"Kendiyle çelişiyor: engel yok deyip yardım istiyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Team lead","en":"Sure. Ali, can you pair with her after the meeting?","tr":"Tabii. Ali, toplantıdan sonra onunla eşli çalışabilir misin?"},{"speaker":"Ali","en":"Of course. I''ll message you at eleven.","tr":"Elbette. Saat on birde sana yazarım."}]'::jsonb,array['d9d18a04-8e67-515f-9a2a-a9d76e0ab7d2','b032299d-4f4a-549f-bdc7-98fac97f090c','d321734c-f8bd-55a5-a87e-5796e9a5455e']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('0bb4da08-039b-5f4b-8856-3f8e2540f6d7','b2d05b0d-3f42-5152-8985-f7b28dde1bdb','Durum bildirme','Scrum master senden günlük durum bilgisi istiyor. Dün arama filtrelerini bitirdin, bugün test yazacaksın.','[{"speaker":"Scrum master","en":"Deniz, what''s your update?","tr":"Deniz, son durum ne?"},{"choose":[{"en":"I finish yesterday the search filters and tomorrow tests.","correct":false,"why_tr":"Fiil zamanı ve kelime sırası yanlış."},{"en":"Yesterday I finished the search filters. Today I''m going to write the tests.","correct":true,"why_tr":"Dün için geçmiş zaman, bugün için plan kalıbı doğru kullanılmış."},{"en":"Yesterday I''m finishing the search filters. Today I wrote the tests.","correct":false,"why_tr":"Zamanlar ters: dün için geçmiş, bugün için gelecek gerekir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Scrum master","en":"Great. Are you still on track for Friday?","tr":"Harika. Cuma için hâlâ plana uygun mu gidiyorsun?"},{"choose":[{"en":"No, the deadline is on track.","correct":false,"why_tr":"Soru senin işinin durumunu soruyor; son tarih “on track” olmaz."},{"en":"Yes, I''m on board for Friday.","correct":false,"why_tr":"“on board” ekibe katılmak demektir; işin plana uygunluğunu anlatmaz."},{"en":"Yes, but I''ll need the API key by Wednesday.","correct":true,"why_tr":"Evet deyip bir koşulu net belirtiyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['53347ac4-a54f-5723-9089-a284a5cc7ec0','2b2da3fb-2b99-5a05-8447-831c934b4add','2726a436-ecf6-5d10-8d91-7d00337fd354']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('d2143e4b-bae1-5fda-970a-8337139579f1','04ba1e9d-bfcb-5de1-8090-cb11f0c1e4cc','Check-in bankosunda','İstanbul''dan Londra''ya uçuyorsun. Check-in bankosundasın ve koridor tarafı koltuk istiyorsun.','[{"speaker":"Agent","en":"Good morning. Can I see your passport, please? Are you checking any bags?","tr":"Günaydın. Pasaportunuzu görebilir miyim? Bagaja verecek çantanız var mı?"},{"choose":[{"en":"I want window seat for my bag.","correct":false,"why_tr":"Anlamsız bir istek."},{"en":"Yes, just this suitcase. Could I have an aisle seat, please?","correct":true,"why_tr":"Soruyu cevaplayıp kibarca koltuk istiyor."},{"en":"Yes, this. Aisle.","correct":false,"why_tr":"Fazla kısa ve kaba."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Agent","en":"Sure. Your bag is two kilos overweight, I''m afraid. There''s a fee of 30 euros.","tr":"Tabii. Korkarım çantanız iki kilo fazla. 30 avroluk bir ücret var."},{"choose":[{"en":"OK, I''ll leave the bag here.","correct":false,"why_tr":"Mantıklı bir çözüm değil."},{"en":"Oh, can I move a few things into my carry-on instead?","correct":true,"why_tr":"Ücret yerine makul bir çözüm öneriyor."},{"en":"Why I pay?","correct":false,"why_tr":"Soru yapısı bozuk ve kaba."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Agent","en":"Of course. Here''s your boarding pass. Boarding starts at 9:40 at gate 12.","tr":"Tabii. İşte biniş kartınız. Biniş 9.40''ta 12 numaralı kapıda başlıyor."}]'::jsonb,array['a7b98204-1a30-5750-a719-c4d902272036','251d4530-0074-51a5-aebb-af159c1640af','5740c3f8-717f-55c7-acad-3dc34572301c']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('06029aac-dc55-5d94-bdc7-bbd6f88bb54a','04ba1e9d-bfcb-5de1-8090-cb11f0c1e4cc','Aktarmayı kaçırmak','İlk uçuşun rötar yaptı ve aktarmanı kaçırdın. Aktarma masasındasın.','[{"speaker":"Agent","en":"Hello, how can I help?","tr":"Merhaba, nasıl yardımcı olabilirim?"},{"choose":[{"en":"My first flight was delayed and I''ve missed my connecting flight to Rome.","correct":true,"why_tr":"Durumu net ve doğru zamanlarla anlatıyor."},{"en":"I miss connection Rome because delay.","correct":false,"why_tr":"Fiil zamanı ve bağlaçlar eksik."},{"en":"I want to go home now.","correct":false,"why_tr":"Sorunu anlatmıyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Agent","en":"I''m sorry about that. I can rebook you on the 6 pm flight.","tr":"Bunun için üzgünüm. Sizi akşam altıdaki uçuşa aktarabilirim."},{"choose":[{"en":"Thank you. Is the delay my fault?","correct":false,"why_tr":"Konuyla ilgisiz bir soru."},{"en":"Give me hotel and food.","correct":false,"why_tr":"Emir kipi kaba kaçıyor."},{"en":"Thank you. Am I entitled to a meal voucher while I wait?","correct":true,"why_tr":"Teşekkür edip hakkını kibarca soruyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Agent","en":"Yes, here''s a voucher for 15 euros. You can also claim compensation online.","tr":"Evet, işte 15 avroluk bir kupon. İnternetten tazminat da talep edebilirsiniz."}]'::jsonb,array['d3c14f90-dc53-5419-9dbf-64cd09dab2ac','2e681821-ab43-5336-8b8e-542962133f58','580e9aec-8f0e-5c01-bbcd-1b1e8e21515f']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('62cd671b-f8ec-561c-bf86-ecb268316322','4ad2bb76-da0e-5681-bb74-6e5fe545667a','Restoranda sipariş','Arkadaşınla bir restorandasın. Fındık alerjin var ve sipariş vermek istiyorsun.','[{"speaker":"Waiter","en":"Good evening. Are you ready to order?","tr":"İyi akşamlar. Sipariş vermeye hazır mısınız?"},{"choose":[{"en":"Yes. Does the chicken salad contain nuts? I''m allergic.","correct":true,"why_tr":"Alerjisini söyleyip içeriği soruyor."},{"en":"Yes, I''m allergy nuts.","correct":false,"why_tr":"“allergic to nuts” olmalı."},{"en":"Yes, give chicken.","correct":false,"why_tr":"Kaba ve eksik."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Waiter","en":"It has walnuts, but we can make it without them.","tr":"İçinde ceviz var ama onsuz yapabiliriz."},{"choose":[{"en":"Great, I''ll have it without walnuts, please.","correct":true,"why_tr":"“I''ll have … without …” ile doğru sipariş."},{"en":"OK, I have it with walnuts.","correct":false,"why_tr":"Alerjisi var; mantıksız."},{"en":"Great, I''ll having it.","correct":false,"why_tr":"“will” sonrası yalın fiil gelir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Waiter","en":"Perfect. And to drink?","tr":"Harika. İçecek olarak?"}]'::jsonb,array['6433940f-c3a5-5c44-912a-658cdb31a8b3','4234f88a-ed6a-5598-adb5-0f84328ba7ab','9375988a-f0e7-5091-b77d-ce94c14cc2b8']::uuid[],'choice',1,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('ed5a6bdc-54c3-5f8d-ae38-a658af270f66','4ad2bb76-da0e-5681-bb74-6e5fe545667a','Toplu taşıma bileti almak','Metro istasyonundasın. Gün boyunca şehri gezeceksin ve hangi bileti alacağını soruyorsun.','[{"speaker":"Staff","en":"Hi, can I help you?","tr":"Merhaba, yardımcı olabilir miyim?"},{"choose":[{"en":"Yes, I''m going to travel around the city all day. Which ticket should I buy?","correct":true,"why_tr":"Planını söyleyip doğru soruyu soruyor."},{"en":"I want to buy the metro.","correct":false,"why_tr":"Metroyu satın almak anlamına geliyor."},{"en":"Ticket, all day, which?","correct":false,"why_tr":"Cümle kurulmamış."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Staff","en":"A day pass is best. It''s 8 euros and you can use buses and trains.","tr":"Günlük kart en iyisi. 8 avro, otobüs ve trenlerde kullanabilirsiniz."},{"choose":[{"en":"Great. Which line go to museum?","correct":false,"why_tr":"Fiil çekimi ve tanımlık eksik."},{"en":"Great. And which line goes to the museum?","correct":true,"why_tr":"Bilgiyi alıp yol soruyor."},{"en":"Is it free?","correct":false,"why_tr":"Fiyat zaten söylendi."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Staff","en":"Take line 2 and change at Central Station. Get off at the third stop.","tr":"2 numaralı hatta binin ve Merkez İstasyonu''nda aktarma yapın. Üçüncü durakta inin."}]'::jsonb,array['8315b0c3-5fc7-5cf5-9325-068a4781569a','48bb6e9f-4576-52d5-afd0-ea14416dcb19','ff62f5e2-31ee-52fe-89d7-428e2790fabd']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('7da06d82-279f-52c1-8223-5a7315d320a0','d4a80253-58de-5511-a2bd-ff59540ed595','Resepsiyonda giriş','Resepsiyonda çalışıyorsun. Bir misafir rezervasyonuyla geliyor; erken giriş istiyor ama odası henüz hazır değil.','[{"speaker":"Guest","en":"Hi, I have a reservation under the name of Miller.","tr":"Merhaba, Miller adına bir rezervasyonum var."},{"choose":[{"en":"Give me your passport.","correct":false,"why_tr":"Dilbilgisi doğru ama misafire karşı fazla sert."},{"en":"Welcome. Could I give your passport?","correct":false,"why_tr":"“Could I give” vermek demektir; anlam ters."},{"en":"Welcome, Mr. Miller. Could I have your passport, please?","correct":true,"why_tr":"Kibar karşılama ve doğru istek kalıbı."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Guest","en":"Here you are. Is it possible to check in now? It''s only eleven.","tr":"Buyurun. Şimdi giriş yapmam mümkün mü? Saat daha on bir."},{"choose":[{"en":"I''m afraid of your room. Leave your luggages.","correct":false,"why_tr":"“afraid of” korkmak demektir; “luggage” çoğul eki almaz."},{"en":"I''m afraid your room isn''t ready yet. You can leave your luggage with us and check in at two.","correct":true,"why_tr":"Kötü haberi “I''m afraid” ile yumuşatıp çözüm sunuyor."},{"en":"No. Come at two.","correct":false,"why_tr":"Kısa ve kaba; çözüm sunmuyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Guest","en":"That''s fine. Thank you.","tr":"Olur. Teşekkürler."}]'::jsonb,array['35525821-ba94-550c-aaf0-f540504bb5fd','22434180-e059-57f0-8e53-bc1873609cd1','eb235b4c-df54-5635-a68d-199082ba557a']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('2010665e-fe44-5c27-9caf-8b4de1f19d66','d4a80253-58de-5511-a2bd-ff59540ed595','Şikâyeti karşılama','Bir misafir arıyor: odasının kliması çalışmıyor ve çok sıcak.','[{"speaker":"Guest","en":"Hello, this is room 304. The air conditioning isn''t working and it''s really hot.","tr":"Merhaba, 304 numaralı oda. Klima çalışmıyor ve çok sıcak."},{"choose":[{"en":"Sorry. I''ll sent someone yesterday.","correct":false,"why_tr":"Zaman çelişkili: “will” + yalın fiil ve gelecek zaman gerekir."},{"en":"I''m very sorry about that. I''ll send someone to fix it right away.","correct":true,"why_tr":"Özür ve hızlı çözüm; doğru kalıp."},{"en":"It''s not my problem, sir.","correct":false,"why_tr":"Misafire karşı kabul edilemez bir ton."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Guest","en":"Thank you. How long will it take?","tr":"Teşekkürler. Ne kadar sürer?"},{"choose":[{"en":"It takes fifteen minutes ago.","correct":false,"why_tr":"“ago” geçmiş için kullanılır; anlam bozuk."},{"en":"About fifteen minutes. If it can''t be fixed, we''ll move you to another room.","correct":true,"why_tr":"Süre veriyor ve yedek çözüm sunuyor."},{"en":"I don''t know, maybe tomorrow, maybe not.","correct":false,"why_tr":"Belirsiz ve profesyonel değil."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Guest","en":"Great, thanks.","tr":"Harika, teşekkürler."}]'::jsonb,array['5c25ba3e-6897-57d9-9a23-2fd8b284575a','d35aea31-a4a3-5699-a0ef-6351cea6b292','a266dbf8-e4d6-58fd-8e53-e7b97428637b']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('187b5a27-e2a5-5cb3-9a39-db48c2d9041e','2e27320a-9d7f-514d-b3d5-0606c1f40344','Bağlaç seçimi','Bir arkadaşınla sınava çalışıyorsunuz. Boşluğa hangi bağlacın uyduğunu tartışıyorsunuz.','[{"speaker":"Friend","en":"The sentence is: ''___ the high cost, many people buy electric cars.'' Which word fits?","tr":"Cümle şu: “___ the high cost, many people buy electric cars.” Hangi kelime uyar?"},{"choose":[{"en":"''Although'', because the sentence shows contrast.","correct":false,"why_tr":"Karşıtlık doğru ama “although” sonrası cümle gelir; burada isim var."},{"en":"''Because of'', because the cost is the reason.","correct":false,"why_tr":"Yüksek maliyet satın almanın nedeni değildir; anlam ters."},{"en":"''Despite'', because a noun follows and the sentence shows contrast.","correct":true,"why_tr":"Ardından isim (the high cost) geliyor ve karşıtlık var."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Friend","en":"And what about ''___ the cost was high, many people bought them.''?","tr":"Peki “___ the cost was high, many people bought them.” için?"},{"choose":[{"en":"''Despite'', because it shows contrast.","correct":false,"why_tr":"Ardından tam cümle geldiği için “despite” kullanılamaz."},{"en":"''Therefore'', because it''s a result.","correct":false,"why_tr":"Anlam karşıtlıktır, sonuç değil."},{"en":"''Although'', because a full clause follows.","correct":true,"why_tr":"Ardından tam bir cümle (özne + fiil) geliyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['546660da-64cf-55e1-9800-dec52ed32589','0006e22f-6efb-5de9-89ed-3f08260f8bf7']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('428e7fec-318d-5b98-85a7-6915c0c3136b','2e27320a-9d7f-514d-b3d5-0606c1f40344','Grafiği yorumlama','Seminerde şehirlerde artan hava kirliliğini gösteren bir grafiği yorumluyorsun.','[{"speaker":"Lecturer","en":"What are the main factors behind the rise in air pollution?","tr":"Hava kirliliğindeki artışın arkasındaki temel etkenler neler?"},{"choose":[{"en":"Traffic contributes with it, mainly because factories.","correct":false,"why_tr":"Yapı yanlış: contribute to, because of."},{"en":"Traffic and factories contribute to it, but the increase is mainly due to traffic.","correct":true,"why_tr":"Etkenleri sayıyor ve hangisinin ağır bastığını söylüyor."},{"en":"The main factor is that pollution causes traffic.","correct":false,"why_tr":"Neden-sonuç ters kurulmuş."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Lecturer","en":"And what are the consequences for public health?","tr":"Peki halk sağlığı açısından sonuçları neler?"},{"choose":[{"en":"It has no consequences; therefore, it is dangerous.","correct":false,"why_tr":"Kendiyle çelişen bir mantık."},{"en":"It can lead to breathing problems, especially in children.","correct":true,"why_tr":"Sonucu doğru kalıpla (lead to) anlatıyor."},{"en":"It can lead from breathing problems.","correct":false,"why_tr":"“lead from” denmez; doğrusu “lead to”."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['5b0f2ac9-f377-5853-9e36-2b03192fb39e','99cd6020-2e82-5d54-97b0-59a50f0ccd62','4fcc5c6e-1c14-5c44-90c8-6c8fc86cb906','4c8dc184-ff13-570f-b5f9-6f357f2be096']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('fe40c5ab-c9ec-5af1-8c5e-f427e0fd11c3','e6ad2555-ff51-5462-82ce-6e582d7ec447','Grafiği anlatma','Seminerde bir şirketin 2015–2024 satışlarını gösteren çizgi grafiği anlatıyorsun.','[{"speaker":"Lecturer","en":"Can you describe the trend in sales?","tr":"Satışlardaki eğilimi anlatabilir misin?"},{"choose":[{"en":"Sales increased steady from 2015 to 2019.","correct":false,"why_tr":"Fiili niteleyen zarf gerekir: steadily."},{"en":"Sales has increase from 2015 to 2019.","correct":false,"why_tr":"Çoğul özne ve fiil biçimi yanlış; bitmiş dönem için past simple gerekir."},{"en":"Sales increased steadily from 2015 to 2019 and reached a peak in 2020.","correct":true,"why_tr":"Zarf, zaman ve “reach a peak” kalıbı doğru."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Lecturer","en":"And what happened after 2020?","tr":"Peki 2020''den sonra ne oldu?"},{"choose":[{"en":"They have fallen in 2021 by slightly.","correct":false,"why_tr":"Belirli bir yılla present perfect kullanılmaz; “by slightly” yanlış."},{"en":"They fell slight and then leveled up.","correct":false,"why_tr":"Zarf gerekir (slightly); “level up” seviye atlamak demektir."},{"en":"They fell slightly and then leveled off.","correct":true,"why_tr":"Hafif düşüşü ve sabitlenmeyi doğru anlatıyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['8a7b1308-47ec-5620-bca8-8b81d8d29626','32e4d029-025b-5d5f-9dba-2d9853b41dee','9ab09d58-5c8f-5b1d-b2e1-cb760f2f35ae']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('32d1bc34-393a-5e7d-8eab-6732a4e7908d','e6ad2555-ff51-5462-82ce-6e582d7ec447','Oranı yorumlama','Bir rapordaki oranı arkadaşına açıklıyorsun.','[{"speaker":"Friend","en":"The report says women accounted for 60% of the participants. What does that mean?","tr":"Raporda katılımcıların %60''ını kadınların oluşturduğu yazıyor. Bu ne demek?"},{"choose":[{"en":"It means that six out of ten participants were women.","correct":true,"why_tr":"“account for” burada “oluşturmak” demektir."},{"en":"It means that women counted the participants.","correct":false,"why_tr":"“account for” burada saymak anlamında değildir."},{"en":"It means that exactly 60 women took part.","correct":false,"why_tr":"Oran ile sayı karıştırılmış; toplam katılımcı sayısı verilmiyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Friend","en":"Is that a large proportion?","tr":"Bu büyük bir oran mı?"},{"choose":[{"en":"Yes, it''s more than half.","correct":true,"why_tr":"%60 yarıdan fazladır."},{"en":"No, it''s less than a third.","correct":false,"why_tr":"%60 üçte birden fazladır."},{"en":"Yes, it''s more than double.","correct":false,"why_tr":"%60 yarıdan fazladır; iki kat değildir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['94696ac6-ac6e-5a6e-aa72-5f7813d67e59','c7e29852-350e-55bf-86e9-f156b85a391a','b4447e5a-cc97-5e2e-9f44-4510209677d8']::uuid[],'choice',2,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('2395615d-48ce-59f6-bacb-a46363b07e11','de1b4712-7243-59d2-b591-86fd886a91fd','Özetteki cümleyi yorumlama','Bir makale özeti okudun. Ders arkadaşın bir cümlenin ne anlama geldiğini soruyor.','[{"speaker":"Classmate","en":"The abstract says: ''The findings suggest that exercise may improve memory in older adults.'' What does that mean?","tr":"Özette şöyle yazıyor: “Bulgular, egzersizin yaşlı yetişkinlerde hafızayı geliştirebileceğini düşündürüyor.” Bu ne demek?"},{"choose":[{"en":"The study found that older adults don''t like exercise.","correct":false,"why_tr":"Cümlede böyle bir bilgi yok."},{"en":"The study proved that exercise always improves memory.","correct":false,"why_tr":"“suggest” ve “may” kesin kanıt anlamına gelmez; “always” da cümlede yok."},{"en":"The study found a possible positive effect of exercise on memory, but it isn''t certain.","correct":true,"why_tr":"“suggest” ve “may” temkinli dildir; kesinlik bildirmez."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Classmate","en":"So was their hypothesis supported?","tr":"Yani hipotezleri desteklendi mi?"},{"choose":[{"en":"Yes, so no further research is needed.","correct":false,"why_tr":"Temkinli bulgular kesin sonuç sayılmaz; çıkarım yanlış."},{"en":"Partly. The results point in that direction, but they are not conclusive.","correct":true,"why_tr":"Temkinli bulguyu doğru yorumluyor."},{"en":"No, because the hypothesis was a participant.","correct":false,"why_tr":"Hipotez bir katılımcı değildir; anlamsız."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['4a71443f-7aec-54e4-8fac-e8634d80e98e','4d056db7-9cbe-579f-a583-3e4b7ea23510','3290fd7c-7d66-5125-8013-1c767dc343f0']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('9a3142fd-5e83-5f4b-b49b-83f05ab9110d','de1b4712-7243-59d2-b591-86fd886a91fd','Kısıtlılıkları tartışma','Seminerde hoca bir çalışmanın kısıtlılıklarını soruyor.','[{"speaker":"Professor","en":"What is one limitation of this study?","tr":"Bu çalışmanın bir kısıtlılığı nedir?"},{"choose":[{"en":"The sample was very small, so the results are more reliable.","correct":false,"why_tr":"Küçük örneklem güvenilirliği artırmaz; mantık hatası."},{"en":"The sample was very small, so the results may not be reliable.","correct":true,"why_tr":"Kısıtlılığı ve sonucunu mantıklı biçimde bağlıyor."},{"en":"The limitation is that the study was conducted.","correct":false,"why_tr":"Anlamsız bir gerekçe."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Professor","en":"Good. Why do you think the two groups gave different answers?","tr":"Güzel. Sence iki grup neden farklı yanıtlar verdi?"},{"choose":[{"en":"This may be due to cultural differences between the groups.","correct":true,"why_tr":"Olası nedeni temkinli bir dille söylüyor."},{"en":"This may be do to cultural differences.","correct":false,"why_tr":"“do” bir fiildir; doğrusu “due to”."},{"en":"This may be due of cultural differences.","correct":false,"why_tr":"Edat yanlış: due to."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['83cc93e4-da20-54fa-8a46-a4fec28d34a7','43b63a4d-cb25-5171-b72f-85d61185a166','a874e378-882e-5a57-9860-1a40125b961e']::uuid[],'choice',3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('e754bb35-aa6d-534f-9ee3-cc88db69e87f','0fe90fa6-b48a-543a-a4ef-332bf34e617c','About me','Kısa tanıtım yazısı','[{"en":"Hello! My name is Arda and I''m nineteen years old.","tr":"Merhaba! Benim adım Arda ve on dokuz yaşındayım."},{"en":"I''m from Eskişehir, but I live in İstanbul now.","tr":"Eskişehirliyim ama şimdi İstanbul''da yaşıyorum."},{"en":"I''m a student at a technical university.","tr":"Bir teknik üniversitede öğrenciyim."},{"en":"My father is a bus driver and my mother is a nurse.","tr":"Babam otobüs şoförü, annem hemşire."},{"en":"I have one sister. She isn''t a student; she''s a cook.","tr":"Bir kız kardeşim var. O öğrenci değil; aşçı."}]'::jsonb,'[{"term":"bus driver","tr":"otobüs şoförü"},{"term":"nurse","tr":"hemşire"},{"term":"cook","tr":"aşçı"}]'::jsonb,'[{"q_tr":"Arda şu anda nerede yaşıyor?","options":["Eskişehir''de","İstanbul''da","Ankara''da"],"answer":1,"why_tr":"“but I live in İstanbul now”"},{"q_tr":"Arda''nın kız kardeşi ne iş yapıyor?","options":["Öğrenci","Hemşire","Aşçı"],"answer":2,"why_tr":"“She isn''t a student; she''s a cook.”"}]'::jsonb,1,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('1f039978-4dbd-5997-887d-9a6a2fbdbe87','0fe90fa6-b48a-543a-a4ef-332bf34e617c','Our new neighbours','Kısa paragraf','[{"en":"We have new neighbours. They''re from Spain.","tr":"Yeni komşularımız var. İspanyalılar."},{"en":"Their names are Pablo and Lucia.","tr":"Adları Pablo ve Lucia."},{"en":"Pablo is an engineer and Lucia is a teacher.","tr":"Pablo mühendis, Lucia öğretmen."},{"en":"Their son is five years old. His name is Leo.","tr":"Oğulları beş yaşında. Adı Leo."},{"en":"They''re very friendly, and Leo''s English is very good!","tr":"Çok cana yakınlar ve Leo''nun İngilizcesi çok iyi!"}]'::jsonb,'[{"term":"neighbour","tr":"komşu"},{"term":"son","tr":"oğul"},{"term":"engineer","tr":"mühendis"}]'::jsonb,'[{"q_tr":"Komşular nereli?","options":["İspanya","İtalya","Türkiye"],"answer":0,"why_tr":"“They''re from Spain.”"},{"q_tr":"Leo kim?","options":["Mühendis","Komşuların oğlu","Öğretmen"],"answer":1,"why_tr":"“Their son is five years old. His name is Leo.”"}]'::jsonb,1,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('889d0edb-fe17-541d-a254-a1755aca08e5','fe12b100-e015-5fb9-929c-a7577550770c','A day in my life','Blog yazısı','[{"en":"I''m Kaan and I work in a hotel.","tr":"Ben Kaan, bir otelde çalışıyorum."},{"en":"I get up at half past five because my work starts at seven.","tr":"Beş buçukta kalkıyorum çünkü işim yedide başlıyor."},{"en":"I don''t have breakfast at home; I eat at the hotel.","tr":"Kahvaltıyı evde yapmıyorum; otelde yiyorum."},{"en":"I finish work at three and I usually go to the gym.","tr":"Saat üçte işi bitiriyorum ve genellikle spor salonuna gidiyorum."},{"en":"In the evening I cook dinner and go to bed early.","tr":"Akşam yemek yapıyorum ve erken yatıyorum."}]'::jsonb,'[{"term":"half past five","tr":"beş buçuk"},{"term":"finish work","tr":"işi bitirmek"},{"term":"go to bed","tr":"yatmak"}]'::jsonb,'[{"q_tr":"Kaan neden çok erken kalkıyor?","options":["Spor yapmak için","İşi yedide başladığı için","Kahvaltı hazırlamak için"],"answer":1,"why_tr":"“because my work starts at seven”"},{"q_tr":"Kaan işten sonra genellikle ne yapıyor?","options":["Spor salonuna gidiyor","Televizyon izliyor","Otelde kalıyor"],"answer":0,"why_tr":"“I usually go to the gym.”"}]'::jsonb,1,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('1e1c04b1-f0cc-5b5b-963b-ac13a681b69a','fe12b100-e015-5fb9-929c-a7577550770c','Flat for rent','Kiralık ev ilanı','[{"en":"Flat for rent in Kadıköy, near the sea.","tr":"Kadıköy''de, denize yakın kiralık daire."},{"en":"There are two bedrooms, a living room and a small kitchen.","tr":"İki yatak odası, bir oturma odası ve küçük bir mutfak var."},{"en":"There''s a balcony, but there isn''t a lift.","tr":"Balkon var ama asansör yok."},{"en":"The bus stop is next to the building.","tr":"Otobüs durağı binanın yanında."},{"en":"Pets are not allowed.","tr":"Evcil hayvan kabul edilmiyor."}]'::jsonb,'[{"term":"flat","tr":"daire"},{"term":"lift","tr":"asansör"},{"term":"pets","tr":"evcil hayvanlar"}]'::jsonb,'[{"q_tr":"Dairede hangisi yok?","options":["Balkon","Asansör","Mutfak"],"answer":1,"why_tr":"“there isn''t a lift”"},{"q_tr":"Kedisi olan biri bu daireyi kiralayabilir mi?","options":["Evet","Hayır","İlanda bilgi yok"],"answer":1,"why_tr":"“Pets are not allowed.”"}]'::jsonb,1,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('fea05aa3-a911-5a6c-9175-2b72feb7aa33','61d6af77-625c-535b-96ca-5f8745c3a368','A postcard from Cappadocia','Kartpostal','[{"en":"Hi Ece! We arrived in Cappadocia on Friday evening.","tr":"Selam Ece! Kapadokya''ya cuma akşamı vardık."},{"en":"On Saturday we got up at four and took a balloon tour.","tr":"Cumartesi saat dörtte kalktık ve balon turuna katıldık."},{"en":"It was cold, but the view was amazing!","tr":"Soğuktu ama manzara muhteşemdi!"},{"en":"We didn''t visit the underground city because it was too crowded.","tr":"Yeraltı şehrini gezmedik çünkü çok kalabalıktı."},{"en":"We''re going back home tomorrow. See you soon! — Burak","tr":"Yarın eve dönüyoruz. Görüşmek üzere! — Burak"}]'::jsonb,'[{"term":"balloon tour","tr":"balon turu"},{"term":"view","tr":"manzara"},{"term":"underground city","tr":"yeraltı şehri"}]'::jsonb,'[{"q_tr":"Burak cumartesi sabahı ne yaptı?","options":["Yeraltı şehrini gezdi","Balon turuna katıldı","Eve döndü"],"answer":1,"why_tr":"“On Saturday we got up at four and took a balloon tour.”"},{"q_tr":"Neden yeraltı şehrine gitmediler?","options":["Kapalıydı","Çok kalabalıktı","Hava soğuktu"],"answer":1,"why_tr":"“because it was too crowded”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('08f4b361-113e-5335-bcce-d6e6deea3612','61d6af77-625c-535b-96ca-5f8745c3a368','A bad day','Kısa hikâye','[{"en":"Last Tuesday was a terrible day for Selim.","tr":"Geçen salı Selim için berbat bir gündü."},{"en":"He didn''t hear his alarm and woke up at nine.","tr":"Alarmını duymadı ve dokuzda uyandı."},{"en":"He ran to the bus stop, but the bus left without him.","tr":"Otobüs durağına koştu ama otobüs onsuz gitti."},{"en":"At work, he noticed he forgot his laptop at home.","tr":"İşte dizüstü bilgisayarını evde unuttuğunu fark etti."},{"en":"In the evening his friends took him out for dinner, and he finally smiled.","tr":"Akşam arkadaşları onu yemeğe çıkardı ve sonunda gülümsedi."}]'::jsonb,'[{"term":"alarm","tr":"çalar saat"},{"term":"notice","tr":"fark etmek"},{"term":"finally","tr":"sonunda"}]'::jsonb,'[{"q_tr":"Selim neden geç uyandı?","options":["Hastaydı","Alarmını duymadı","Otobüsü kaçırdı"],"answer":1,"why_tr":"“He didn''t hear his alarm”"},{"q_tr":"Gün nasıl bitti?","options":["Daha da kötü","Arkadaşlarıyla yemekle güzel bitti","İşte geç saate kadar kaldı"],"answer":1,"why_tr":"“his friends took him out for dinner, and he finally smiled”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('add6f65b-6be1-5411-b61a-3967ef7f6509','bc5f3cd8-55f8-5a25-8906-26008f507e61','Summer plans','Mesaj','[{"en":"Hi Leyla! My exams finish next week, so I''m going to have a long holiday.","tr":"Selam Leyla! Sınavlarım gelecek hafta bitiyor, yani uzun bir tatil yapacağım."},{"en":"I''m flying to Trabzon on the 5th of July to stay with my grandparents.","tr":"Büyükannemle büyükbabamın yanında kalmak için 5 Temmuz''da Trabzon''a uçuyorum."},{"en":"In August I''m going to work in a café to save money.","tr":"Ağustosta para biriktirmek için bir kafede çalışacağım."},{"en":"The job isn''t as exciting as a holiday, but it will be useful.","tr":"İş, tatil kadar heyecanlı değil ama faydalı olacak."},{"en":"What about you? Are you going to visit us?","tr":"Peki ya sen? Bizi ziyaret edecek misin?"}]'::jsonb,'[{"term":"grandparents","tr":"büyükanne ve büyükbaba"},{"term":"save money","tr":"para biriktirmek"},{"term":"useful","tr":"faydalı"}]'::jsonb,'[{"q_tr":"Yazan kişi ağustosta ne yapacak?","options":["Trabzon''a gidecek","Bir kafede çalışacak","Sınavlara girecek"],"answer":1,"why_tr":"“In August I''m going to work in a café”"},{"q_tr":"Trabzon yolculuğu neden present continuous ile anlatılmış?","options":["Geçmişte olduğu için","Tarihi belli, ayarlanmış bir plan olduğu için","Sadece bir tahmin olduğu için"],"answer":1,"why_tr":"Tarih belli bir uçuş: ayarlanmış plan → I''m flying."}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('eec08fd1-2874-50af-9428-8af34d0e5ff1','bc5f3cd8-55f8-5a25-8906-26008f507e61','Which phone should I buy?','Ürün karşılaştırması','[{"en":"The Nova X is cheaper than the Sky 5, but its camera isn''t as good.","tr":"Nova X, Sky 5''ten daha ucuz ama kamerası o kadar iyi değil."},{"en":"The Sky 5 has the biggest screen and the longest battery life.","tr":"Sky 5''in en büyük ekranı ve en uzun pil ömrü var."},{"en":"However, it''s heavier and more expensive.","tr":"Ancak daha ağır ve daha pahalı."},{"en":"If you take a lot of photos, the Sky 5 is the better choice.","tr":"Çok fotoğraf çekiyorsan Sky 5 daha iyi bir seçim."},{"en":"If you want a light, cheap phone, buy the Nova X.","tr":"Hafif ve ucuz bir telefon istiyorsan Nova X''i al."}]'::jsonb,'[{"term":"battery life","tr":"pil ömrü"},{"term":"however","tr":"ancak"},{"term":"choice","tr":"seçim"}]'::jsonb,'[{"q_tr":"Hangi telefonun pili daha uzun gider?","options":["Nova X","Sky 5","İkisi aynı"],"answer":1,"why_tr":"“The Sky 5 has … the longest battery life.”"},{"q_tr":"Az parası olan ve hafif telefon isteyen biri hangisini almalı?","options":["Nova X","Sky 5","Metinde öneri yok"],"answer":0,"why_tr":"“If you want a light, cheap phone, buy the Nova X.”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('3524dfe5-0421-5fce-a16f-7ec33223a14d','8886d6de-85b1-5473-95de-ae8213ec5037','Ask Aylin','Tavsiye köşesi','[{"en":"Dear Aylin, my flatmate never cleans the kitchen and I''m tired of doing everything.","tr":"Sevgili Aylin, ev arkadaşım mutfağı hiç temizlemiyor ve her şeyi yapmaktan bıktım."},{"en":"If I say something, I''m afraid she''ll get angry. — Kerem","tr":"Bir şey söylersem kızacağından korkuyorum. — Kerem"},{"en":"Dear Kerem, avoiding the problem won''t make it disappear.","tr":"Sevgili Kerem, sorundan kaçınmak onu yok etmez."},{"en":"If I were you, I''d suggest making a cleaning plan together.","tr":"Senin yerinde olsam birlikte bir temizlik planı yapmayı önerirdim."},{"en":"Unless you talk to her calmly, nothing will change. — Aylin","tr":"Onunla sakin bir şekilde konuşmazsan hiçbir şey değişmez. — Aylin"}]'::jsonb,'[{"term":"flatmate","tr":"ev arkadaşı"},{"term":"be tired of","tr":"bıkmak"},{"term":"calmly","tr":"sakince"}]'::jsonb,'[{"q_tr":"Aylin''in önerisi ne?","options":["Evden taşınmak","Birlikte temizlik planı yapmak","Hiçbir şey söylememek"],"answer":1,"why_tr":"“I''d suggest making a cleaning plan together.”"},{"q_tr":"“Unless you talk to her calmly” ne anlama gelir?","options":["Onunla sakince konuşursan","Onunla sakince konuşmazsan","Onunla konuştuktan sonra"],"answer":1,"why_tr":"“unless” = if … not."}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('3879dc53-1871-5313-ab70-45ee46152f87','8886d6de-85b1-5473-95de-ae8213ec5037','What would you do?','Anket cevapları','[{"en":"We asked our readers: what would you do if you had a year off?","tr":"Okurlarımıza sorduk: Bir yıl izniniz olsa ne yapardınız?"},{"en":"Deniz, 29: I''d travel around South America and learn Spanish.","tr":"Deniz, 29: Güney Amerika''yı gezer ve İspanyolca öğrenirdim."},{"en":"Hakan, 41: I wouldn''t go anywhere. I''d spend more time with my kids.","tr":"Hakan, 41: Hiçbir yere gitmezdim. Çocuklarımla daha çok vakit geçirirdim."},{"en":"Sena, 35: If I could, I''d open a small bakery by the sea.","tr":"Sena, 35: Yapabilsem deniz kenarında küçük bir fırın açardım."},{"en":"What about you?","tr":"Peki ya siz?"}]'::jsonb,'[{"term":"a year off","tr":"bir yıl izin"},{"term":"spend time","tr":"vakit geçirmek"},{"term":"bakery","tr":"fırın, pastane"}]'::jsonb,'[{"q_tr":"Hakan bir yıl izinde ne yapardı?","options":["Seyahat ederdi","Çocuklarıyla vakit geçirirdi","Fırın açardı"],"answer":1,"why_tr":"“I''d spend more time with my kids.”"},{"q_tr":"Metindeki cümleler neden “would” ile kurulmuş?","options":["Geçmişi anlattıkları için","Hayali bir durumu anlattıkları için","Kesin planları anlattıkları için"],"answer":1,"why_tr":"Soru gerçek dışı bir durum: 2. tip koşul."}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('d72f5209-3eb1-58a4-a09b-e0cb180b74d2','cda9518c-acc9-50f6-8edf-1221122b1601','Two years in Canada','Blog yazısı','[{"en":"I moved to Toronto two years ago, and my life has changed completely.","tr":"İki yıl önce Toronto''ya taşındım ve hayatım tamamen değişti."},{"en":"At first I missed my family and Turkish food a lot.","tr":"İlk başta ailemi ve Türk yemeklerini çok özledim."},{"en":"Since then I''ve made many friends and found a good job.","tr":"O zamandan beri birçok arkadaş edindim ve iyi bir iş buldum."},{"en":"I still haven''t got used to the winters, though — they''re really long!","tr":"Ama kışlara hâlâ alışamadım — gerçekten çok uzunlar!"},{"en":"I''ve visited Turkey twice so far, and each time it was hard to leave.","tr":"Şimdiye kadar Türkiye''ye iki kez gittim ve her seferinde ayrılmak zor oldu."}]'::jsonb,'[{"term":"completely","tr":"tamamen"},{"term":"since then","tr":"o zamandan beri"},{"term":"though","tr":"yine de, ama"}]'::jsonb,'[{"q_tr":"Yazar hâlâ neye alışamamış?","options":["Yemeklere","Kışlara","İşine"],"answer":1,"why_tr":"“I still haven''t got used to the winters”"},{"q_tr":"“I moved … two years ago” cümlesinde neden past simple var?","options":["Çünkü “ago” ile belli bir geçmiş zaman veriliyor","Çünkü taşınma hâlâ sürüyor","Çünkü olumsuz bir cümle"],"answer":0,"why_tr":"“ago” geçmişte belli bir zamanı gösterir; present perfect ile kullanılmaz."}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('ff15fc49-495d-5f1a-99a3-f3563bc7946f','cda9518c-acc9-50f6-8edf-1221122b1601','Volunteer of the month','Bülten yazısı','[{"en":"This month''s volunteer is Gül, a retired teacher.","tr":"Bu ayın gönüllüsü emekli öğretmen Gül."},{"en":"She has helped at our animal shelter since 2020.","tr":"2020''den beri hayvan barınağımızda yardım ediyor."},{"en":"So far she has found homes for more than eighty cats.","tr":"Şimdiye kadar seksenden fazla kediye yuva buldu."},{"en":"Last year she also started a reading club for children.","tr":"Geçen yıl çocuklar için bir okuma kulübü de başlattı."},{"en":"We are very proud to have her in our team.","tr":"Onun ekibimizde olmasından gurur duyuyoruz."}]'::jsonb,'[{"term":"volunteer","tr":"gönüllü"},{"term":"animal shelter","tr":"hayvan barınağı"},{"term":"retired","tr":"emekli"}]'::jsonb,'[{"q_tr":"Gül ne zamandan beri barınakta gönüllü?","options":["Geçen yıldan beri","2020''den beri","Emekli olduğundan beri"],"answer":1,"why_tr":"“She has helped at our animal shelter since 2020.”"},{"q_tr":"Okuma kulübü ne zaman başladı?","options":["2020''de","Geçen yıl","Bu ay"],"answer":1,"why_tr":"“Last year she also started a reading club”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('bc5bbfcc-7839-5029-b917-d2b4a91fbdfa','7bf0c681-79b3-5002-b1b1-c7d262f7cff7','Is remote work here to stay?','Görüş yazısı','[{"en":"Remote work, which became common during the pandemic, is still popular.","tr":"Pandemi sırasında yaygınlaşan uzaktan çalışma hâlâ popüler."},{"en":"Supporters argue that it saves time and money, since there is no commute.","tr":"Destekçileri, işe gidip gelme olmadığı için zaman ve para kazandırdığını savunuyor."},{"en":"On the other hand, some managers believe that teamwork suffers.","tr":"Öte yandan bazı yöneticiler ekip çalışmasının zarar gördüğüne inanıyor."},{"en":"Although there is evidence for both views, most companies have chosen a hybrid model.","tr":"Her iki görüş için de kanıtlar olsa da şirketlerin çoğu hibrit modeli seçti."},{"en":"In my opinion, this compromise is the fairest option for everyone.","tr":"Bence bu orta yol herkes için en adil seçenek."}]'::jsonb,'[{"term":"commute","tr":"işe gidip gelme"},{"term":"suffer","tr":"zarar görmek"},{"term":"compromise","tr":"orta yol, uzlaşma"}]'::jsonb,'[{"q_tr":"Bazı yöneticilerin uzaktan çalışmayla ilgili endişesi ne?","options":["Pahalı olması","Ekip çalışmasının zarar görmesi","Daha çok zaman alması"],"answer":1,"why_tr":"“some managers believe that teamwork suffers”"},{"q_tr":"Yazarın kendi görüşü ne?","options":["Tamamen uzaktan çalışma","Tamamen ofis","Hibrit model"],"answer":2,"why_tr":"“this compromise is the fairest option” — hibrit model."}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('4131ef86-1843-5230-9305-c18f7cc164c2','7bf0c681-79b3-5002-b1b1-c7d262f7cff7','City or countryside?','Karşılaştırma yazısı','[{"en":"People who grow up in cities often find the countryside too quiet.","tr":"Şehirde büyüyen insanlar kırsalı çoğu zaman fazla sessiz bulur."},{"en":"Cities offer better job opportunities, whereas villages offer a calmer lifestyle.","tr":"Şehirler daha iyi iş fırsatları sunar, oysa köyler daha sakin bir yaşam tarzı sunar."},{"en":"Despite the high cost of living, young people continue to move to big cities.","tr":"Yüksek yaşam maliyetine rağmen gençler büyük şehirlere taşınmaya devam ediyor."},{"en":"As a result, many villages are losing their populations.","tr":"Bunun sonucunda birçok köy nüfusunu kaybediyor."},{"en":"However, remote work may slowly change this trend.","tr":"Ancak uzaktan çalışma bu eğilimi yavaş yavaş değiştirebilir."}]'::jsonb,'[{"term":"opportunity","tr":"fırsat"},{"term":"cost of living","tr":"yaşam maliyeti"},{"term":"trend","tr":"eğilim"}]'::jsonb,'[{"q_tr":"Köyler neden nüfus kaybediyor?","options":["Gençler büyük şehirlere taşındığı için","Yaşam maliyeti yüksek olduğu için","Uzaktan çalışma yüzünden"],"answer":0,"why_tr":"“young people continue to move to big cities. As a result, many villages are losing …”"},{"q_tr":"“whereas” bu metinde ne işe yarıyor?","options":["Sebep bildiriyor","İki şeyi karşılaştırıyor","Sonuç bildiriyor"],"answer":1,"why_tr":"Şehirler ile köyleri karşılaştırıyor."}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('f8226119-d658-5a5a-8500-7f6836edbdd2','0d6376db-346e-5a63-b3ee-03e2b9fef8c1','The road not taken','Kişisel yazı','[{"en":"When I was eighteen, I was offered a place at a music school in Vienna.","tr":"On sekiz yaşımdayken Viyana''daki bir müzik okulunda yer teklif edildi."},{"en":"My parents thought it was too risky, so I studied economics instead.","tr":"Ailem bunun çok riskli olduğunu düşündü, ben de onun yerine ekonomi okudum."},{"en":"If I had gone to Vienna, I might have become a professional pianist.","tr":"Viyana''ya gitseydim profesyonel bir piyanist olabilirdim."},{"en":"In hindsight, though, I don''t regret my choice: I met my wife at university.","tr":"Yine de geriye dönüp bakınca seçimimden pişman değilim: Eşimle üniversitede tanıştım."},{"en":"I still wish I played more often, so I''ve started taking lessons again.","tr":"Hâlâ keşke daha sık çalabilsem diyorum, bu yüzden yeniden ders almaya başladım."}]'::jsonb,'[{"term":"was offered","tr":"teklif edildi"},{"term":"instead","tr":"onun yerine"},{"term":"in hindsight","tr":"geriye dönüp bakınca"}]'::jsonb,'[{"q_tr":"Yazar neden Viyana''ya gitmedi?","options":["Parası yetmediği için","Ailesi çok riskli bulduğu için","Okula kabul edilmediği için"],"answer":1,"why_tr":"“My parents thought it was too risky”"},{"q_tr":"Yazar seçiminden pişman mı?","options":["Evet, çok pişman","Hayır, çünkü eşiyle üniversitede tanıştı","Metinde söylenmiyor"],"answer":1,"why_tr":"“I don''t regret my choice: I met my wife at university.”"}]'::jsonb,4,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('557f92f2-d671-557e-a959-1f72665dcc0f','0d6376db-346e-5a63-b3ee-03e2b9fef8c1','The empty office','Kısa hikâye','[{"en":"When Naz arrived at the office, the door was open but nobody was there.","tr":"Naz ofise vardığında kapı açıktı ama kimse yoktu."},{"en":"The coffee on the desk was still warm, so someone must have left only minutes earlier.","tr":"Masadaki kahve hâlâ sıcaktı, yani biri sadece birkaç dakika önce çıkmış olmalıydı."},{"en":"It can''t have been the cleaner, because she only comes in the evening.","tr":"Temizlikçi olamazdı, çünkü o sadece akşamları geliyor."},{"en":"Naz thought her boss might have gone to the meeting room.","tr":"Naz, patronunun toplantı odasına gitmiş olabileceğini düşündü."},{"en":"It turned out that everyone was hiding there with a birthday cake for her.","tr":"Herkesin orada, onun için bir doğum günü pastasıyla saklandığı ortaya çıktı."}]'::jsonb,'[{"term":"still warm","tr":"hâlâ sıcak"},{"term":"cleaner","tr":"temizlikçi"},{"term":"hide","tr":"saklanmak"}]'::jsonb,'[{"q_tr":"Naz neden birinin az önce çıktığını düşündü?","options":["Kapı açıktı","Kahve hâlâ sıcaktı","Bir not vardı"],"answer":1,"why_tr":"“The coffee … was still warm, so someone must have left only minutes earlier.”"},{"q_tr":"Temizlikçi neden şüpheli değildi?","options":["Sadece akşamları geliyor","O gün izinliydi","Toplantı odasındaydı"],"answer":0,"why_tr":"“she only comes in the evening”"}]'::jsonb,4,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('645fb8ea-b4f4-5d1b-873d-ec031d62933d','46fa5ffe-78fe-5175-8072-3b2621cc801c','Study abstract','Makale özeti','[{"en":"This study examines the relationship between screen time and sleep quality among teenagers.","tr":"Bu çalışma gençlerde ekran süresi ile uyku kalitesi arasındaki ilişkiyi inceliyor."},{"en":"The sample consisted of 1,200 students aged 13 to 17.","tr":"Örneklem 13-17 yaş arası 1.200 öğrenciden oluşuyordu."},{"en":"The findings indicate a moderate negative correlation between evening screen use and sleep duration.","tr":"Bulgular, akşam ekran kullanımı ile uyku süresi arasında orta düzeyde negatif bir ilişkiye işaret ediyor."},{"en":"However, the data do not imply that screens alone account for poor sleep.","tr":"Ancak veriler kötü uykunun tek açıklamasının ekranlar olduğu anlamına gelmiyor."},{"en":"A key limitation is the reliance on self-reported data.","tr":"Önemli bir sınırlılık, öz bildirime dayalı verilere dayanılmasıdır."}]'::jsonb,'[{"term":"moderate","tr":"orta düzeyde"},{"term":"self-reported","tr":"öz bildirime dayalı"},{"term":"reliance","tr":"dayanma, bağımlılık"}]'::jsonb,'[{"q_tr":"Çalışmanın bulgusu nedir?","options":["Ekranlar kötü uykunun tek nedenidir","Akşam ekran kullanımı arttıkça uyku süresi kısalma eğiliminde","Ekran süresi uykuyu etkilemiyor"],"answer":1,"why_tr":"Orta düzeyde negatif korelasyon: biri artınca diğeri azalma eğiliminde."},{"q_tr":"Yazarların belirttiği sınırlılık ne?","options":["Örneklemin küçük olması","Verilerin katılımcıların kendi beyanına dayanması","Sadece yetişkinlerin incelenmesi"],"answer":1,"why_tr":"“the reliance on self-reported data”"}]'::jsonb,5,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('974dabf1-c82f-5325-ae75-c70a3e6a40bd','46fa5ffe-78fe-5175-8072-3b2621cc801c','Why are young people leaving?','Analiz yazısı','[{"en":"Young graduates are thought to be leaving the region at a record rate.","tr":"Genç mezunların bölgeden rekor bir hızla ayrıldığı düşünülüyor."},{"en":"The decline in local industry has, to a large extent, reduced job opportunities.","tr":"Yerel sanayideki düşüş, iş fırsatlarını büyük ölçüde azalttı."},{"en":"It could also be argued that poor public transport plays a role.","tr":"Yetersiz toplu taşımanın da bir rol oynadığı ileri sürülebilir."},{"en":"Some towns have introduced schemes whereby graduates receive housing support.","tr":"Bazı kasabalar, mezunların konut desteği aldığı programlar başlattı."},{"en":"It is too early, however, to assess whether these schemes are effective.","tr":"Ancak bu programların etkili olup olmadığını değerlendirmek için henüz çok erken."}]'::jsonb,'[{"term":"record rate","tr":"rekor hız"},{"term":"scheme","tr":"program, plan"},{"term":"housing support","tr":"konut desteği"}]'::jsonb,'[{"q_tr":"Gençlerin ayrılmasının temel nedeni olarak ne gösteriliyor?","options":["Yerel sanayinin gerilemesi","Yüksek kiralar","Kötü hava"],"answer":0,"why_tr":"“The decline in local industry has, to a large extent, reduced job opportunities.”"},{"q_tr":"Konut desteği programlarının sonucu hakkında ne söyleniyor?","options":["Çok başarılı oldular","Başarısız oldular","Değerlendirmek için henüz erken"],"answer":2,"why_tr":"“It is too early … to assess whether these schemes are effective.”"}]'::jsonb,5,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('468f65ed-a5a5-51e3-8d97-30fc73fba07a','39054825-3f71-5559-9822-6a4004d50c22','Graduation speech','Konuşma metni','[{"en":"Four years ago, few of us imagined standing here today.","tr":"Dört yıl önce pek azımız bugün burada duracağımızı hayal ederdi."},{"en":"Not only did we survive a pandemic, but we also learned to support one another.","tr":"Yalnızca bir salgını atlatmakla kalmadık, birbirimizi desteklemeyi de öğrendik."},{"en":"What made the difference was not talent, but persistence.","tr":"Farkı yaratan yetenek değil, azimdi."},{"en":"It was our teachers who fostered that persistence, often without recognition.","tr":"Bu azmi, çoğu zaman takdir görmeden, besleyen öğretmenlerimizdi."},{"en":"Never again should we take such support for granted.","tr":"Böyle bir desteği bir daha asla hafife almamalıyız."}]'::jsonb,'[{"term":"persistence","tr":"azim, sebat"},{"term":"recognition","tr":"takdir, tanınma"},{"term":"one another","tr":"birbiri"}]'::jsonb,'[{"q_tr":"Konuşmacıya göre farkı ne yarattı?","options":["Yetenek","Azim","Şans"],"answer":1,"why_tr":"“What made the difference was not talent, but persistence.”"},{"q_tr":"“It was our teachers who fostered that persistence” cümlesinde vurgulanan ne?","options":["Azmin kendisi","Azmi besleyenlerin öğretmenler olması","Takdir görmemek"],"answer":1,"why_tr":"It-cleft yapısı “öğretmenler” bilgisini öne çıkarır."}]'::jsonb,4,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('a5fbffbb-540f-5fff-a120-0277aeeb9dfa','39054825-3f71-5559-9822-6a4004d50c22','Traffic policy review','Resmî rapor özeti','[{"en":"The congestion charge, introduced in 2023, has come under considerable scrutiny.","tr":"2023''te getirilen trafik sıkışıklığı ücreti ciddi biçimde mercek altına alındı."},{"en":"Critics argue that it undermines small businesses in the city centre.","tr":"Eleştirmenler bunun şehir merkezindeki küçük işletmeleri zayıflattığını savunuyor."},{"en":"However, the data show a substantial drop in air pollution, notably near schools.","tr":"Ancak veriler, özellikle okulların yakınında, hava kirliliğinde önemli bir düşüş gösteriyor."},{"en":"There is, admittedly, a discrepancy between official figures and those of independent groups.","tr":"Kabul etmek gerekir ki resmî rakamlarla bağımsız grupların rakamları arasında bir tutarsızlık var."},{"en":"The report recommends measures to mitigate the impact on local shops.","tr":"Rapor, yerel dükkânlar üzerindeki etkiyi hafifletecek önlemler öneriyor."}]'::jsonb,'[{"term":"congestion charge","tr":"trafik sıkışıklığı ücreti"},{"term":"admittedly","tr":"kabul etmek gerekir ki"},{"term":"measures","tr":"önlemler"}]'::jsonb,'[{"q_tr":"Eleştirmenlerin temel kaygısı ne?","options":["Hava kirliliği","Küçük işletmelerin zarar görmesi","Okulların kapanması"],"answer":1,"why_tr":"“it undermines small businesses in the city centre”"},{"q_tr":"Rapor ne öneriyor?","options":["Ücretin kaldırılmasını","Yerel dükkânlara etkiyi azaltacak önlemleri","Daha çok veri toplanmasını"],"answer":1,"why_tr":"“recommends measures to mitigate the impact on local shops”"}]'::jsonb,5,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('7930e765-0f9a-581d-978f-6530b5604864','e6ae5d8c-b653-5966-870b-5abc222f4d1b','The attention economy','Köşe yazısı','[{"en":"Smartphones are now so ubiquitous that we rarely notice how much of our attention they consume.","tr":"Akıllı telefonlar artık öyle yaygın ki dikkatimizin ne kadarını tükettiklerini nadiren fark ediyoruz."},{"en":"The complaints about screen addiction are, I suspect, merely the tip of the iceberg.","tr":"Ekran bağımlılığıyla ilgili şikâyetler, sanırım, buzdağının sadece görünen yüzü."},{"en":"Were it not for a few meticulous researchers, we would know very little about the problem.","tr":"Birkaç titiz araştırmacı olmasaydı sorun hakkında çok az şey bilirdik."},{"en":"It is high time regulators took the issue seriously, albeit without banning the technology outright.","tr":"Teknolojiyi tamamen yasaklamadan da olsa, düzenleyicilerin konuyu ciddiye almasının vakti çoktan geldi."},{"en":"Claims from the industry itself, however, should be taken with a pinch of salt.","tr":"Ancak sektörün kendi iddialarına ihtiyatla yaklaşılmalı."}]'::jsonb,'[{"term":"consume","tr":"tüketmek"},{"term":"regulator","tr":"düzenleyici kurum"},{"term":"outright","tr":"tamamen, doğrudan"}]'::jsonb,'[{"q_tr":"Yazar sektörün iddialarına nasıl yaklaşılmasını öneriyor?","options":["Tamamen güvenilmesini","İhtiyatla yaklaşılmasını","Görmezden gelinmesini"],"answer":1,"why_tr":"“should be taken with a pinch of salt” = tam inanmamak, ihtiyatlı olmak."},{"q_tr":"Yazar teknolojinin yasaklanmasını istiyor mu?","options":["Evet, tamamen","Hayır, yasaklamadan düzenlenmesini istiyor","Metinde söz edilmiyor"],"answer":1,"why_tr":"“albeit without banning the technology outright”"}]'::jsonb,5,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('d7864ae1-630c-516a-90ba-36f8c480f1f3','e6ae5d8c-b653-5966-870b-5abc222f4d1b','A blessing in disguise','Anı','[{"en":"When the publisher rejected my first novel, I felt utterly crushed.","tr":"Yayınevi ilk romanımı reddettiğinde kendimi tamamen yıkılmış hissettim."},{"en":"Had they accepted it, I would probably still be writing the same kind of book today.","tr":"Kabul etselerdi muhtemelen bugün hâlâ aynı türden kitaplar yazıyor olurdum."},{"en":"Instead, I spent two years rewriting it, and it took me that long to get the hang of dialogue.","tr":"Bunun yerine iki yıl yeniden yazmakla geçirdim; diyaloğun püf noktasını kavramam o kadar sürdü."},{"en":"My editor insisted that I cut a third of the chapters, which felt unprecedented at the time.","tr":"Editörüm bölümlerin üçte birini çıkarmamda ısrar etti; bu o zaman eşi görülmemiş bir şey gibi gelmişti."},{"en":"In hindsight, that rejection was a blessing in disguise.","tr":"Geriye dönüp bakınca, o ret aslında hayırlı olmuş."}]'::jsonb,'[{"term":"utterly","tr":"tamamen"},{"term":"crushed","tr":"yıkılmış"},{"term":"rewrite","tr":"yeniden yazmak"}]'::jsonb,'[{"q_tr":"“Had they accepted it, I would probably still be writing…” cümlesi ne anlatıyor?","options":["Geçmişteki bir koşulun şimdiki sonucunu","Gelecekteki bir planı","Geçmişte gerçekten olmuş bir olayı"],"answer":0,"why_tr":"Karma koşul: geçmiş koşul (had accepted) → şimdiki sonuç (would be writing)."},{"q_tr":"Yazar reddedilmeyi şimdi nasıl görüyor?","options":["Büyük bir haksızlık","Hayırlı bir şey","Önemsiz bir olay"],"answer":1,"why_tr":"“that rejection was a blessing in disguise”"}]'::jsonb,5,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('29535b57-642b-57b4-a985-9753b51d5629','d085f43c-2ece-5c98-b9a2-fccd790e4488','Theatre review','Eleştiri yazısı','[{"en":"Staged ostensibly as a comedy, the play is in fact a bleak meditation on loneliness.","tr":"Görünüşte komedi olarak sahnelenen oyun aslında yalnızlık üzerine kasvetli bir düşünce yolculuğu."},{"en":"The playwright juxtaposes noisy family dinners with long, silent scenes in an empty flat.","tr":"Oyun yazarı gürültülü aile yemeklerini boş bir dairedeki uzun, sessiz sahnelerle yan yana koyuyor."},{"en":"Having seen the original production, I found this version less coherent.","tr":"Orijinal sahnelemeyi izlemiş biri olarak bu versiyonu daha az tutarlı buldum."},{"en":"The lead actor is superb; the supporting cast, to put it mildly, less so.","tr":"Başrol oyuncusu mükemmel; yardımcı oyuncular ise, en hafif deyimle, o kadar değil."},{"en":"Despite some scathing reviews, the show has sold out every night.","tr":"Bazı yerden yere vuran eleştirilere rağmen gösterinin biletleri her gece tükendi."}]'::jsonb,'[{"term":"bleak","tr":"kasvetli"},{"term":"meditation","tr":"derin düşünme"},{"term":"sold out","tr":"biletleri tükenmiş"}]'::jsonb,'[{"q_tr":"Yazara göre oyun aslında ne hakkında?","options":["Aile komedisi","Yalnızlık","Tiyatro tarihi"],"answer":1,"why_tr":"“ostensibly as a comedy … in fact a bleak meditation on loneliness”"},{"q_tr":"“the supporting cast, to put it mildly, less so” ne demek?","options":["Yardımcı oyuncular da mükemmel","Yardımcı oyuncular hiç iyi değil (kibarca söylenmiş)","Yardımcı oyuncular sahneye çıkmadı"],"answer":1,"why_tr":"Ellipsis: “less so” = less superb; “to put it mildly” eleştiriyi yumuşatır."}]'::jsonb,5,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('5d244d29-d895-50f4-8db3-5d7ab8c466c1','d085f43c-2ece-5c98-b9a2-fccd790e4488','Writing well','Yazım kılavuzu','[{"en":"Good writing is succinct: every word must earn its place.","tr":"İyi yazı özlüdür: her sözcük yerini hak etmelidir."},{"en":"Given that readers skim, the main point should come first.","tr":"Okurların göz gezdirdiği düşünülürse ana fikir önce gelmelidir."},{"en":"Avoid words with unintended connotations; “cheap” and “inexpensive” are not interchangeable.","tr":"İstenmeyen çağrışımları olan sözcüklerden kaçının; “cheap” ile “inexpensive” birbirinin yerine kullanılamaz."},{"en":"Rhetorical questions can engage readers, but use them sparingly — the former effect fades quickly if overused.","tr":"Retorik sorular okuru içine çekebilir ama idareli kullanın; aşırı kullanılırsa bu etki çabuk kaybolur."},{"en":"Above all, read your work aloud: if you stumble, so will your reader.","tr":"Her şeyden önce yazınızı yüksek sesle okuyun: siz takılırsanız okurunuz da takılır."}]'::jsonb,'[{"term":"skim","tr":"göz gezdirmek"},{"term":"interchangeable","tr":"birbirinin yerine kullanılabilir"},{"term":"sparingly","tr":"idareli, az"}]'::jsonb,'[{"q_tr":"Kılavuza göre ana fikir nerede olmalı?","options":["Sonda","Başta","Ortada"],"answer":1,"why_tr":"“Given that readers skim, the main point should come first.”"},{"q_tr":"“if you stumble, so will your reader” cümlesindeki yapı nedir?","options":["Ellipsis/ikame: okur da takılır","Edilgen yapı","Retorik soru"],"answer":0,"why_tr":"“so will your reader” = your reader will stumble too."}]'::jsonb,5,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('eb2863b0-d37e-544c-9dc1-5d68d26e76df','6fbbf6ec-47c4-5a61-ae2a-085acb973117','Incident report: conveyor stop','Arıza raporu','[{"en":"On 12 March, conveyor 4 stopped for two hours.","tr":"12 Mart''ta 4 numaralı konveyör iki saat durdu."},{"en":"The stop was caused by a worn bearing in the main motor.","tr":"Duruş, ana motordaki aşınmış bir rulmandan kaynaklandı."},{"en":"As a temporary fix, the team replaced the bearing with a spare part.","tr":"Geçici çözüm olarak ekip rulmanı yedek parçayla değiştirdi."},{"en":"To prevent this issue in the future, we recommend inspecting the bearings every month.","tr":"Bu sorunun gelecekte yaşanmaması için rulmanların her ay muayene edilmesini öneriyoruz."}]'::jsonb,'[{"term":"conveyor","tr":"konveyör, taşıma bandı"},{"term":"worn","tr":"aşınmış"},{"term":"spare part","tr":"yedek parça"},{"term":"inspecting","tr":"muayene etmek"}]'::jsonb,'[{"q_tr":"Konveyör neden durdu?","options":["Elektrik kesildi","Ana motordaki rulman aşınmıştı","Operatör hata yaptı"],"answer":1,"why_tr":"“caused by a worn bearing in the main motor”"},{"q_tr":"Gelecek için öneri ne?","options":["Konveyörü tamamen değiştirmek","Rulmanları her ay muayene etmek","Motoru kalıcı olarak kapatmak"],"answer":1,"why_tr":"“we recommend inspecting the bearings every month”"}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('efe30f1e-c47d-5777-afc2-49fcf46560be','6fbbf6ec-47c4-5a61-ae2a-085acb973117','Options for the cooling problem','E-posta','[{"en":"Hi team, here are two options for the cooling problem.","tr":"Herkese merhaba, soğutma sorunu için iki seçenek var."},{"en":"Option A is to add a second fan. It''s quick and cheap, but it''s noisy.","tr":"A seçeneği ikinci bir fan eklemek. Hızlı ve ucuz ama gürültülü."},{"en":"Option B is to redesign the housing for better airflow. It''s more cost-effective in the long term, but it will take six weeks.","tr":"B seçeneği, daha iyi hava akışı için gövdeyi yeniden tasarlamak. Uzun vadede maliyet açısından daha verimli ama altı hafta sürecek."},{"en":"I suggest that we start with option A and plan option B for the next version.","tr":"A seçeneğiyle başlayıp B seçeneğini bir sonraki sürüm için planlamamızı öneriyorum."}]'::jsonb,'[{"term":"option","tr":"seçenek"},{"term":"airflow","tr":"hava akışı"},{"term":"cost-effective","tr":"maliyet açısından verimli"},{"term":"in the long term","tr":"uzun vadede"}]'::jsonb,'[{"q_tr":"A seçeneğinin dezavantajı ne?","options":["Pahalı olması","Gürültülü olması","Altı hafta sürmesi"],"answer":1,"why_tr":"“It''s quick and cheap, but it''s noisy.”"},{"q_tr":"Yazar ne öneriyor?","options":["Yalnız B seçeneğini uygulamak","Önce A seçeneğini uygulayıp B''yi sonraki sürüme planlamak","Hiçbir şey yapmamak"],"answer":1,"why_tr":"“start with option A and plan option B for the next version”"}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('9d298179-c283-5f80-8e68-9a9726a305e6','c016cb37-6858-58cd-ae01-49689b107921','Datasheet: centrifugal pump CP-40','Veri sayfası','[{"en":"Rated power: 2.2 kW.","tr":"Anma gücü: 2,2 kW."},{"en":"Maximum flow rate: 40 liters per minute.","tr":"Azami debi: dakikada 40 litre."},{"en":"Operating temperature range: −10 to 80 °C.","tr":"Çalışma sıcaklığı aralığı: −10 ile 80 °C arası."},{"en":"Housing material: stainless steel.","tr":"Gövde malzemesi: paslanmaz çelik."},{"en":"Weight: approximately 18 kg.","tr":"Ağırlık: yaklaşık 18 kg."}]'::jsonb,'[{"term":"rated power","tr":"anma gücü"},{"term":"flow rate","tr":"debi"},{"term":"range","tr":"aralık"},{"term":"housing","tr":"gövde, muhafaza"}]'::jsonb,'[{"q_tr":"Pompa hangi sıcaklıkta çalıştırılmamalı?","options":["0 °C","50 °C","95 °C"],"answer":2,"why_tr":"Çalışma aralığı −10 ile 80 °C arası; 95 °C bu aralığın dışında."},{"q_tr":"Pompanın gövdesi hangi malzemeden?","options":["Alüminyum","Paslanmaz çelik","Plastik"],"answer":1,"why_tr":"“Housing material: stainless steel.”"},{"q_tr":"Pompa dakikada en fazla ne kadar sıvı basabilir?","options":["18 litre","40 litre","80 litre"],"answer":1,"why_tr":"“Maximum flow rate: 40 liters per minute.”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('0e6c6c67-fe81-5e68-86a2-b975577619ea','c016cb37-6858-58cd-ae01-49689b107921','Measurement results','E-posta','[{"en":"Hi Burak, I measured the ten sample parts this morning.","tr":"Merhaba Burak, bu sabah on numune parçayı ölçtüm."},{"en":"Eight parts are within tolerance.","tr":"Sekiz parça tolerans içinde."},{"en":"Two parts have a diameter of 25.08 mm, which is 0.03 mm above the limit.","tr":"İki parçanın çapı 25,08 mm; bu, sınırın 0,03 mm üzerinde."},{"en":"The new gauge is more accurate than the old one, so I''m confident about the results.","tr":"Yeni ölçü aleti eskisinden daha hassas, bu yüzden sonuçlardan eminim."}]'::jsonb,'[{"term":"sample","tr":"numune"},{"term":"within tolerance","tr":"tolerans içinde"},{"term":"above the limit","tr":"sınırın üzerinde"},{"term":"gauge","tr":"ölçü aleti"}]'::jsonb,'[{"q_tr":"Kaç parça tolerans dışında?","options":["İki","Sekiz","On"],"answer":0,"why_tr":"On parçanın sekizi tolerans içinde; iki parça sınırın üzerinde."},{"q_tr":"Yazar sonuçlardan neden emin?","options":["Parçalar yeni","Yeni ölçü aleti daha hassas","Burak sonuçları onayladı"],"answer":1,"why_tr":"“The new gauge is more accurate than the old one.”"}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('208368da-0b36-568f-881d-d1eb5948dc55','233b0925-1efe-5baa-9090-54d6f8aef7d6','Test report: seal durability','Test raporu özeti','[{"en":"Objective: to check the durability of the new rubber seal.","tr":"Amaç: yeni kauçuk contanın dayanıklılığını kontrol etmek."},{"en":"Ten samples were tested at 90 °C for 500 hours.","tr":"On numune 90 °C''de 500 saat boyunca test edildi."},{"en":"Nine samples passed; one sample failed after 420 hours.","tr":"Dokuz numune testi geçti; bir numune 420 saat sonra başarısız oldu."},{"en":"There was no sign of corrosion on the metal parts.","tr":"Metal parçalarda korozyon belirtisi yoktu."},{"en":"We recommend testing a second batch before mass production.","tr":"Seri üretimden önce ikinci bir partinin test edilmesini öneriyoruz."}]'::jsonb,'[{"term":"objective","tr":"amaç"},{"term":"seal","tr":"conta"},{"term":"mass production","tr":"seri üretim"},{"term":"corrosion","tr":"korozyon"}]'::jsonb,'[{"q_tr":"Kaç numune başarısız oldu?","options":["Bir","Dokuz","On"],"answer":0,"why_tr":"“one sample failed after 420 hours”"},{"q_tr":"Raporun önerisi ne?","options":["Seri üretime hemen başlamak","Seri üretimden önce ikinci bir partiyi test etmek","Metal parçaları değiştirmek"],"answer":1,"why_tr":"“We recommend testing a second batch before mass production.”"},{"q_tr":"Test hangi sıcaklıkta yapıldı?","options":["20 °C","90 °C","500 °C"],"answer":1,"why_tr":"“tested at 90 °C for 500 hours”"}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('e436f6ce-78a0-5e7b-becf-5da891d3cdd0','233b0925-1efe-5baa-9090-54d6f8aef7d6','Lab rules: test bench 3','Laboratuvar notu','[{"en":"Always calibrate the load cell before each test.","tr":"Her testten önce mutlaka yük hücresini kalibre et."},{"en":"If the temperature exceeds 100 °C, the system stops automatically.","tr":"Sıcaklık 100 °C''yi aşarsa sistem otomatik olarak durur."},{"en":"Record all results in the shared spreadsheet.","tr":"Tüm sonuçları ortak tabloya kaydet."},{"en":"If you see a significant deviation, repeat the test and inform the lab manager.","tr":"Belirgin bir sapma görürsen testi tekrarla ve laboratuvar yöneticisine haber ver."}]'::jsonb,'[{"term":"load cell","tr":"yük hücresi"},{"term":"exceeds","tr":"aşar"},{"term":"spreadsheet","tr":"hesap tablosu"},{"term":"inform","tr":"haber vermek"}]'::jsonb,'[{"q_tr":"Sıcaklık 100 °C''yi aşarsa ne olur?","options":["Alarm çalar ama sistem çalışmaya devam eder","Sistem otomatik olarak durur","Test kendiliğinden tekrarlanır"],"answer":1,"why_tr":"“the system stops automatically”"},{"q_tr":"Belirgin bir sapma görürsen ne yapmalısın?","options":["Sonuçları silmelisin","Testi tekrarlayıp laboratuvar yöneticisine haber vermelisin","Yük hücresini değiştirmelisin"],"answer":1,"why_tr":"“repeat the test and inform the lab manager”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('cbd55bc7-deb4-5e27-908b-0ea5244e35a0','1ec86e14-8694-5f09-89f1-2ad9ef7f19f5','My typical week','Kişisel blog','[{"en":"On weekdays, I usually get up at 6:30 and commute to work by ferry.","tr":"Hafta içi genellikle 6.30''da kalkarım ve işe vapurla gidip gelirim."},{"en":"The ferry takes about 25 minutes, so I read a book on the way.","tr":"Vapur yaklaşık 25 dakika sürüyor, bu yüzden yolda kitap okurum."},{"en":"I always avoid the roads during rush hour.","tr":"Yoğun saatlerde yollardan hep uzak dururum."},{"en":"On Saturdays, I do the laundry and the grocery shopping.","tr":"Cumartesileri çamaşır yıkar ve market alışverişi yaparım."},{"en":"Sundays are for my family, and sometimes I take a nap after lunch.","tr":"Pazarlar ailem içindir ve bazen öğle yemeğinden sonra kısa bir uyku çekerim."}]'::jsonb,'[{"term":"commute","tr":"işe gidip gelmek"},{"term":"rush hour","tr":"yoğun saat"},{"term":"laundry","tr":"çamaşır"},{"term":"take a nap","tr":"kısa uyku çekmek"}]'::jsonb,'[{"q_tr":"Yazar işe nasıl gidip geliyor?","options":["Metroyla","Vapurla","Arabayla"],"answer":1,"why_tr":"“commute to work by ferry”"},{"q_tr":"Yazar cumartesileri ne yapar?","options":["Ailesini ziyaret eder","Çamaşır yıkar ve market alışverişi yapar","İşe gider"],"answer":1,"why_tr":"“On Saturdays, I do the laundry and the grocery shopping.”"},{"q_tr":"Yazar yolculuk sırasında ne yapar?","options":["Kitap okur","Uyur","E-posta yazar"],"answer":0,"why_tr":"“I read a book on the way.”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('f6660a06-ad8c-5c06-963f-e3252e044206','1ec86e14-8694-5f09-89f1-2ad9ef7f19f5','Weekend plans','Mesajlaşma','[{"en":"Ayşe: Hi! Do you have any plans for the weekend?","tr":"Ayşe: Selam! Hafta sonu için bir planın var mı?"},{"en":"Ali: I''m going to visit my grandparents on Saturday, but I''m free on Sunday.","tr":"Ali: Cumartesi büyükannemlere gideceğim ama pazar boşum."},{"en":"Ayşe: Great! How about a picnic in the park on Sunday?","tr":"Ayşe: Harika! Pazar günü parkta pikniğe ne dersin?"},{"en":"Ali: Sounds good. Let me check the weather and get back to you.","tr":"Ali: Olur. Havaya bir bakıp sana döneyim."}]'::jsonb,'[{"term":"plans","tr":"planlar"},{"term":"free","tr":"boş, müsait"},{"term":"How about … ?","tr":"… ne dersin?"},{"term":"get back to you","tr":"sana dönmek"}]'::jsonb,'[{"q_tr":"Ali cumartesi ne yapacak?","options":["Pikniğe gidecek","Büyükannesine ve büyükbabasına gidecek","Evde dinlenecek"],"answer":1,"why_tr":"“I''m going to visit my grandparents on Saturday.”"},{"q_tr":"Ali piknik için ne zaman kesin cevap verecek?","options":["Hemen","Havaya baktıktan sonra","Pazartesi"],"answer":1,"why_tr":"“Let me check the weather and get back to you.”"}]'::jsonb,1,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('7665891e-040f-5ec4-ba01-806b14c9b55b','2fe5da34-f4cb-5c47-8c4e-d94faab76c7f','About me','Kısa tanıtım','[{"en":"Hi! My name is Selin and I''m a physiotherapist.","tr":"Merhaba! Adım Selin ve fizyoterapistim."},{"en":"I''m originally from Eskişehir, but I''ve lived in Ankara for six years.","tr":"Aslen Eskişehirliyim ama altı yıldır Ankara''da yaşıyorum."},{"en":"I work at a small clinic near my home.","tr":"Evimin yakınındaki küçük bir klinikte çalışıyorum."},{"en":"In my spare time, I go swimming and I''m learning to play the violin.","tr":"Boş zamanımda yüzmeye gidiyorum ve keman çalmayı öğreniyorum."},{"en":"I''m a bit shy at first, but I get along well with most people.","tr":"İlk başta biraz utangacım ama çoğu insanla iyi geçinirim."}]'::jsonb,'[{"term":"originally","tr":"aslen"},{"term":"spare time","tr":"boş zaman"},{"term":"shy","tr":"utangaç"},{"term":"get along","tr":"iyi geçinmek"}]'::jsonb,'[{"q_tr":"Selin şu anda nerede yaşıyor?","options":["Eskişehir''de","Ankara''da","İstanbul''da"],"answer":1,"why_tr":"“I''ve lived in Ankara for six years.”"},{"q_tr":"Selin şu sıralar ne öğreniyor?","options":["Yüzmeyi","Keman çalmayı","Fizyoterapiyi"],"answer":1,"why_tr":"“I''m learning to play the violin.”"}]'::jsonb,1,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('234bf142-2aaf-5085-8c8b-ba5c9c816043','2fe5da34-f4cb-5c47-8c4e-d94faab76c7f','New team member','E-posta','[{"en":"Hello everyone, I''d like to introduce our new colleague, Emre.","tr":"Herkese merhaba, yeni iş arkadaşımız Emre''yi tanıtmak istiyorum."},{"en":"He graduated from Hacettepe University and he''s interested in data analysis.","tr":"Hacettepe Üniversitesi''nden mezun oldu ve veri analizine ilgi duyuyor."},{"en":"Emre is fluent in English and German.","tr":"Emre İngilizce ve Almancayı akıcı konuşuyor."},{"en":"He''s based in our Ankara office, so please say hello if you see him!","tr":"Ankara ofisimizde çalışıyor; onu görürseniz lütfen merhaba deyin!"}]'::jsonb,'[{"term":"introduce","tr":"tanıtmak"},{"term":"graduated from","tr":"-den mezun oldu"},{"term":"fluent in","tr":"-i akıcı konuşan"},{"term":"based in","tr":"-de çalışan"}]'::jsonb,'[{"q_tr":"Emre hangi alana ilgi duyuyor?","options":["Veri analizi","Tasarım","Satış"],"answer":0,"why_tr":"“he''s interested in data analysis”"},{"q_tr":"Emre hangi ofiste çalışıyor?","options":["İstanbul","Ankara","İzmir"],"answer":1,"why_tr":"“He''s based in our Ankara office.”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('2ad7e786-efe2-55d6-bd6a-024de6615bbd','9fec7c37-b21c-53df-8fc9-49684d6cfa85','Complaint: damaged order','E-posta','[{"en":"Dear Customer Service, I ordered a coffee machine from your website on 3 May.","tr":"Sayın Müşteri Hizmetleri, 3 Mayıs''ta web sitenizden bir kahve makinesi sipariş ettim."},{"en":"It was delivered yesterday, but the box arrived damaged and the machine doesn''t work.","tr":"Dün teslim edildi ama kutu hasarlı geldi ve makine çalışmıyor."},{"en":"I''d like to exchange it for a new one or get a full refund.","tr":"Makineyi yenisiyle değiştirmek ya da paramın tamamını geri almak istiyorum."},{"en":"I''ve attached a photo of the box and my receipt.","tr":"Kutunun fotoğrafını ve fişimi ekledim."}]'::jsonb,'[{"term":"delivered","tr":"teslim edildi"},{"term":"damaged","tr":"hasarlı"},{"term":"refund","tr":"para iadesi"},{"term":"attached","tr":"(e-postaya) ekledim"}]'::jsonb,'[{"q_tr":"Sorun ne?","options":["Sipariş hiç gelmedi","Kutu hasarlı geldi ve makine çalışmıyor","Yanlış renk geldi"],"answer":1,"why_tr":"“the box arrived damaged and the machine doesn''t work”"},{"q_tr":"Yazar ne istiyor?","options":["Yeni bir makine ya da para iadesi","Bir indirim kodu","Teslimatın ertelenmesi"],"answer":0,"why_tr":"“exchange it for a new one or get a full refund”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('0e708355-73bc-5b4c-9f92-14df11576094','9fec7c37-b21c-53df-8fc9-49684d6cfa85','Notice to all residents','Duyuru','[{"en":"Dear residents, there is a water leak in the basement.","tr":"Sayın sakinler, bodrum katta bir su sızıntısı var."},{"en":"A plumber will come to fix it on Tuesday morning.","tr":"Salı sabahı bir tesisatçı gelip tamir edecek."},{"en":"There will be no hot water from 9 am to 12 pm.","tr":"Saat 9 ile 12 arasında sıcak su olmayacak."},{"en":"If you have an urgent problem, please call the building manager.","tr":"Acil bir sorununuz olursa lütfen bina yöneticisini arayın."},{"en":"We''re sorry for the inconvenience.","tr":"Verdiğimiz rahatsızlık için özür dileriz."}]'::jsonb,'[{"term":"leak","tr":"sızıntı"},{"term":"plumber","tr":"tesisatçı"},{"term":"urgent","tr":"acil"},{"term":"inconvenience","tr":"rahatsızlık"}]'::jsonb,'[{"q_tr":"Salı sabahı ne olacak?","options":["Bina boyanacak","Bir tesisatçı sızıntıyı tamir edecek","Asansör değiştirilecek"],"answer":1,"why_tr":"“A plumber will come to fix it on Tuesday morning.”"},{"q_tr":"Acil bir sorunda kimi aramalısın?","options":["Tesisatçıyı","Bina yöneticisini","Komşunu"],"answer":1,"why_tr":"“please call the building manager”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('48781dba-da06-502e-9712-2cdf42d982c3','6669c461-b0f4-5b73-b7bd-cd4c249f1e3f','Discharge instructions','Taburcu notu','[{"en":"You were treated for a mild ankle sprain.","tr":"Hafif ayak bileği burkulması için tedavi edildiniz."},{"en":"Keep your foot raised and use ice for 20 minutes three times a day.","tr":"Ayağınızı yukarıda tutun ve günde üç kez 20 dakika buz uygulayın."},{"en":"You may take paracetamol for the pain, up to four times a day.","tr":"Ağrı için günde en fazla dört kez parasetamol alabilirsiniz."},{"en":"Avoid sports for at least two weeks.","tr":"En az iki hafta spordan kaçının."},{"en":"Come back to the emergency department if the swelling gets worse or your toes feel cold.","tr":"Şişlik kötüleşirse veya ayak parmaklarınız soğuk gelirse acil servise geri gelin."}]'::jsonb,'[{"term":"sprain","tr":"burkulma"},{"term":"raised","tr":"yukarı kaldırılmış"},{"term":"up to","tr":"-e kadar, en fazla"},{"term":"swelling","tr":"şişlik"}]'::jsonb,'[{"q_tr":"Buz günde kaç kez uygulanmalı?","options":["Bir kez","Üç kez","Dört kez"],"answer":1,"why_tr":"“use ice for 20 minutes three times a day”"},{"q_tr":"Hangi durumda tekrar acile gelinmeli?","options":["Ağrı kesici bitince","Şişlik kötüleşirse","İki hafta dolunca"],"answer":1,"why_tr":"“if the swelling gets worse or your toes feel cold”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('19af935b-75ca-5d80-ab81-6b9a02cce3a6','6669c461-b0f4-5b73-b7bd-cd4c249f1e3f','Message to the clinic','Hasta mesajı','[{"en":"Hello, my name is Selin Arslan and I have an appointment on Thursday at 10.","tr":"Merhaba, adım Selin Arslan, perşembe saat 10''da randevum var."},{"en":"Unfortunately, I can''t come because I have to travel for work.","tr":"Maalesef iş için seyahat etmem gerektiğinden gelemiyorum."},{"en":"Could I move the appointment to next Monday?","tr":"Randevuyu gelecek pazartesiye alabilir miyim?"},{"en":"Also, I''m almost out of my blood pressure medicine.","tr":"Ayrıca tansiyon ilacım bitmek üzere."},{"en":"Could the doctor send a new prescription to my pharmacy?","tr":"Doktor eczaneme yeni bir reçete gönderebilir mi?"}]'::jsonb,'[{"term":"unfortunately","tr":"maalesef"},{"term":"move","tr":"(randevuyu) ertelemek, kaydırmak"},{"term":"be out of","tr":"(bir şey) bitmek"},{"term":"prescription","tr":"reçete"}]'::jsonb,'[{"q_tr":"Selin neden perşembe gelemiyor?","options":["Hasta olduğu için","İş seyahati olduğu için","İlacı bittiği için"],"answer":1,"why_tr":"“I have to travel for work.”"},{"q_tr":"Selin doktordan ne istiyor?","options":["Yeni bir reçete","Kan tahlili","Taburcu notu"],"answer":0,"why_tr":"“Could the doctor send a new prescription to my pharmacy?”"}]'::jsonb,1,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('b975087c-ad62-5966-a8ae-6276c4642a9b','a64481c9-1fe3-5f37-a501-1e99c5f1321f','Patient information leaflet','Prospektüs','[{"en":"Read all of this leaflet carefully before you start taking this medicine.","tr":"Bu ilacı almaya başlamadan önce bu prospektüsün tamamını dikkatle okuyun."},{"en":"Adults: take one or two tablets every four to six hours.","tr":"Yetişkinler: dört ila altı saatte bir, bir veya iki tablet alın."},{"en":"Do not take more than eight tablets in 24 hours.","tr":"24 saatte sekiz tabletten fazla almayın."},{"en":"This medicine may cause drowsiness. If affected, do not drive.","tr":"Bu ilaç uyku hâli yapabilir. Etkilenirseniz araç kullanmayın."},{"en":"Store below 25°C and keep out of the reach of children.","tr":"25°C''nin altında saklayın ve çocukların ulaşamayacağı yerde tutun."}]'::jsonb,'[{"term":"leaflet","tr":"prospektüs, broşür"},{"term":"drowsiness","tr":"uyku hâli"},{"term":"if affected","tr":"etkilenirseniz"},{"term":"out of the reach of","tr":"ulaşamayacağı yerde"}]'::jsonb,'[{"q_tr":"Bir yetişkin 24 saatte en fazla kaç tablet alabilir?","options":["Dört","Altı","Sekiz"],"answer":2,"why_tr":"“Do not take more than eight tablets in 24 hours.”"},{"q_tr":"İlaç uyku hâli yaparsa ne yapılmamalı?","options":["Yemek yenmemeli","Araç kullanılmamalı","Su içilmemeli"],"answer":1,"why_tr":"“If affected, do not drive.”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('d31d0acb-8cf6-5dcb-9112-cfff8c580e4e','a64481c9-1fe3-5f37-a501-1e99c5f1321f','Your prescription is ready','Eczane bildirimi','[{"en":"Your repeat prescription is ready to collect.","tr":"Tekrarlanan reçeteniz hazır, alabilirsiniz."},{"en":"Please bring your ID when you come to the pharmacy.","tr":"Eczaneye gelirken kimliğinizi getirin."},{"en":"One of your medicines is out of stock, so we have given you a generic version.","tr":"İlaçlarınızdan biri stokta olmadığı için eşdeğerini verdik."},{"en":"It contains the same active ingredient and works in the same way.","tr":"Aynı etken maddeyi içerir ve aynı şekilde etki eder."},{"en":"If you have any questions, our pharmacist can talk to you in private.","tr":"Sorunuz varsa eczacımız sizinle özel olarak görüşebilir."}]'::jsonb,'[{"term":"repeat prescription","tr":"tekrarlanan reçete"},{"term":"collect","tr":"teslim almak"},{"term":"active ingredient","tr":"etken madde"},{"term":"in private","tr":"özel olarak, baş başa"}]'::jsonb,'[{"q_tr":"Eczaneye giderken ne götürülmeli?","options":["Eski kutular","Kimlik","Doktor raporu"],"answer":1,"why_tr":"“Please bring your ID”"},{"q_tr":"Neden eşdeğer ilaç verildi?","options":["Daha ucuz olduğu için","Orijinali stokta olmadığı için","Doktor istediği için"],"answer":1,"why_tr":"“One of your medicines is out of stock”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('75201e2c-25ba-5d9f-88bc-e5bcb377e04b','d7846284-4a8a-509a-b64b-155e6f82e9c6','Information for visitors','Servis duyurusu','[{"en":"Visiting hours on Ward 4 are from 2 pm to 8 pm every day.","tr":"4. Serviste ziyaret saatleri her gün 14.00–20.00 arasıdır."},{"en":"No more than two visitors are allowed at a bed at one time.","tr":"Bir yatağın yanında aynı anda en fazla iki ziyaretçiye izin verilir."},{"en":"Please clean your hands when you enter and leave the ward.","tr":"Lütfen servise girerken ve çıkarken ellerinizi temizleyin."},{"en":"Do not visit if you have had a cold or stomach bug in the last 48 hours.","tr":"Son 48 saatte soğuk algınlığı veya mide virüsü geçirdiyseniz ziyarete gelmeyin."},{"en":"Flowers are not allowed for infection control reasons.","tr":"Enfeksiyon kontrolü nedeniyle çiçeğe izin verilmez."}]'::jsonb,'[{"term":"at one time","tr":"aynı anda"},{"term":"stomach bug","tr":"mide virüsü"},{"term":"infection control","tr":"enfeksiyon kontrolü"}]'::jsonb,'[{"q_tr":"Aynı anda bir yatağı kaç kişi ziyaret edebilir?","options":["Bir","İki","Dört"],"answer":1,"why_tr":"“No more than two visitors are allowed at a bed at one time.”"},{"q_tr":"Çiçek neden yasak?","options":["Yer olmadığı için","Enfeksiyon kontrolü için","Alerji yaptığı için"],"answer":1,"why_tr":"“for infection control reasons”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('707910b9-7b28-5a77-ac9d-08212d27e113','d7846284-4a8a-509a-b64b-155e6f82e9c6','Caring for your wound at home','Taburcu broşürü','[{"en":"Keep your dressing on for 48 hours after the operation.","tr":"Ameliyattan sonra pansumanınızı 48 saat çıkarmayın."},{"en":"After that, you can shower, but pat the wound dry with a clean towel.","tr":"Sonra duş alabilirsiniz ama yarayı temiz bir havluyla tampon yaparak kurulayın."},{"en":"Some redness and swelling around the wound is normal.","tr":"Yaranın çevresinde biraz kızarıklık ve şişlik olması normaldir."},{"en":"Contact us if the wound becomes hot, very painful or starts to leak.","tr":"Yara ısınır, çok ağrır veya akıntı yapmaya başlarsa bize ulaşın."},{"en":"Your stitches will be removed at your GP practice in 10 to 14 days.","tr":"Dikişleriniz 10–14 gün içinde aile hekiminizde alınacak."}]'::jsonb,'[{"term":"dressing","tr":"pansuman, yara örtüsü"},{"term":"pat dry","tr":"tampon yaparak kurulamak"},{"term":"leak","tr":"akıntı yapmak"},{"term":"GP","tr":"aile hekimi"}]'::jsonb,'[{"q_tr":"Pansuman ne kadar süre çıkarılmamalı?","options":["24 saat","48 saat","10 gün"],"answer":1,"why_tr":"“Keep your dressing on for 48 hours”"},{"q_tr":"Hangi durum normal kabul ediliyor?","options":["Yaranın akıntı yapması","Biraz kızarıklık ve şişlik","Yaranın ısınması"],"answer":1,"why_tr":"“Some redness and swelling around the wound is normal.”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('95723c9e-942e-578a-935e-158ac46e211c','53b5b8fc-d379-599c-9d8e-77b99bfec9e9','Termination of employment','İş sözleşmesi maddesi','[{"en":"Either party may terminate this agreement by giving four weeks'' written notice.","tr":"Taraflardan her biri dört hafta önceden yazılı bildirimde bulunarak bu sözleşmeyi feshedebilir."},{"en":"During the probation period, the notice period is one week.","tr":"Deneme süresi boyunca ihbar süresi bir haftadır."},{"en":"The Company may dismiss the Employee without notice in the event of serious misconduct.","tr":"Ciddi kusurlu davranış hâlinde Şirket, Çalışanı bildirimsiz olarak işten çıkarabilir."},{"en":"Upon termination, the Employee shall return all company property.","tr":"Fesih üzerine Çalışan tüm şirket mallarını iade edecektir."},{"en":"Any unused annual leave will be paid in the final salary.","tr":"Kullanılmamış yıllık izinler son maaşla ödenecektir."}]'::jsonb,'[{"term":"either party","tr":"taraflardan her biri"},{"term":"written notice","tr":"yazılı bildirim"},{"term":"misconduct","tr":"kusurlu davranış"},{"term":"upon termination","tr":"fesih üzerine"}]'::jsonb,'[{"q_tr":"Deneme süresinde ihbar süresi ne kadar?","options":["Bir hafta","İki hafta","Dört hafta"],"answer":0,"why_tr":"“During the probation period, the notice period is one week.”"},{"q_tr":"Hangi durumda bildirim olmadan işten çıkarma mümkün?","options":["Deneme süresinde","Ciddi kusurlu davranışta","İzin kullanılmadığında"],"answer":1,"why_tr":"“without notice in the event of serious misconduct”"}]'::jsonb,4,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('b045f29d-cd3f-509e-9058-fb44c6f8d6a3','53b5b8fc-d379-599c-9d8e-77b99bfec9e9','How we use your data','Gizlilik bildirimi','[{"en":"We process your personal data to provide and improve our services.","tr":"Kişisel verilerinizi hizmetlerimizi sunmak ve geliştirmek için işliyoruz."},{"en":"We never sell your data to third parties.","tr":"Verilerinizi asla üçüncü taraflara satmayız."},{"en":"Some data is processed by service providers outside your country, with your explicit consent.","tr":"Bazı veriler, açık rızanızla, ülkeniz dışındaki hizmet sağlayıcılar tarafından işlenir."},{"en":"You can withdraw your consent at any time in your settings.","tr":"Rızanızı istediğiniz zaman ayarlardan geri çekebilirsiniz."},{"en":"If a data breach occurs, we will inform you without undue delay.","tr":"Bir veri ihlali olursa sizi gecikmeksizin bilgilendiririz."}]'::jsonb,'[{"term":"third parties","tr":"üçüncü taraflar"},{"term":"explicit consent","tr":"açık rıza"},{"term":"without undue delay","tr":"gecikmeksizin"}]'::jsonb,'[{"q_tr":"Şirket verilerle ilgili ne yapmayacağını söylüyor?","options":["Yurt dışına göndermeyecek","Üçüncü taraflara satmayacak","Hiç işlemeyecek"],"answer":1,"why_tr":"“We never sell your data to third parties.”"},{"q_tr":"Veri ihlalinde ne olacak?","options":["Kullanıcı gecikmeksizin bilgilendirilecek","Hesap kapatılacak","Hiçbir şey yapılmayacak"],"answer":0,"why_tr":"“we will inform you without undue delay”"}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('c678a2d6-643d-563e-942c-1d99af11d252','35f00cb3-8900-51a4-aeb8-113195e43047','Extract from a confidentiality agreement','Sözleşme maddesi','[{"en":"The Recipient shall keep all Confidential Information strictly confidential.","tr":"Alıcı taraf tüm Gizli Bilgileri kesinlikle gizli tutacaktır."},{"en":"The Recipient may share Confidential Information only with employees who need it for the Project.","tr":"Alıcı taraf Gizli Bilgileri yalnızca Proje için ihtiyaç duyan çalışanlarla paylaşabilir."},{"en":"This obligation does not apply to information that is already public.","tr":"Bu yükümlülük zaten kamuya açık bilgilere uygulanmaz."},{"en":"The obligations in this clause will continue for three years after termination of this Agreement.","tr":"Bu maddedeki yükümlülükler, bu Sözleşmenin feshinden sonra üç yıl devam edecektir."},{"en":"Any breach of this clause entitles the Disclosing Party to seek compensation.","tr":"Bu maddenin her türlü ihlali, bilgiyi açıklayan tarafa tazminat talep etme hakkı verir."}]'::jsonb,'[{"term":"Recipient","tr":"bilgiyi alan taraf"},{"term":"apply to","tr":"-e uygulanmak"},{"term":"termination","tr":"fesih"},{"term":"compensation","tr":"tazminat"}]'::jsonb,'[{"q_tr":"Alıcı taraf gizli bilgiyi kimlerle paylaşabilir?","options":["Herkesle","Projede bilgiye ihtiyaç duyan çalışanlarla","Hiç kimseyle"],"answer":1,"why_tr":"“only with employees who need it for the Project” — may = izin."},{"q_tr":"Gizlilik yükümlülüğü sözleşme bittikten sonra ne kadar sürer?","options":["Hiç sürmez","Bir yıl","Üç yıl"],"answer":2,"why_tr":"“will continue for three years after termination”"}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('48b0423d-7b70-5b20-83a2-dc2234472814','35f00cb3-8900-51a4-aeb8-113195e43047','Email to a client','Hukuki e-posta','[{"en":"Dear Ms. Carter, further to our meeting on Monday, please find attached the revised employment contract.","tr":"Sayın Carter, pazartesi günkü toplantımıza istinaden ekte revize edilmiş iş sözleşmesini bulabilirsiniz."},{"en":"We have amended clause 6 so that you are entitled to 20 days of paid leave.","tr":"6. maddeyi, 20 gün ücretli izin hakkınız olacak şekilde değiştirdik."},{"en":"The notice period remains one month for both parties.","tr":"Bildirim süresi her iki taraf için de bir ay olarak kalıyor."},{"en":"Please read the document carefully and let us know if you have any questions.","tr":"Lütfen belgeyi dikkatle okuyun ve sorunuz olursa bize bildirin."},{"en":"We would be grateful if you could return the signed copy by 30 April.","tr":"İmzalı kopyayı 30 Nisan''a kadar iade edebilirseniz minnettar oluruz."}]'::jsonb,'[{"term":"revised","tr":"revize edilmiş"},{"term":"amended","tr":"değiştirildi"},{"term":"notice period","tr":"bildirim süresi"},{"term":"remains","tr":"olarak kalıyor"}]'::jsonb,'[{"q_tr":"6. maddede ne değişti?","options":["Bildirim süresi","Ücretli izin hakkı","Maaş"],"answer":1,"why_tr":"“We have amended clause 6 so that you are entitled to 20 days of paid leave.”"},{"q_tr":"İmzalı kopya ne zamana kadar gönderilmeli?","options":["Pazartesiye kadar","30 Nisan''a kadar","Bir ay içinde"],"answer":1,"why_tr":"“return the signed copy by 30 April”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('ae61bbe8-144f-5f12-8593-eaffa5fcbd28','0f692eaa-47c8-5983-880d-2c55c738f67a','Notice of hearing','Duruşma tebligatı','[{"en":"You are hereby notified that a hearing will take place on 14 March at 10:00.","tr":"14 Mart saat 10.00''da bir duruşma yapılacağı işbu yazıyla tarafınıza bildirilir."},{"en":"The hearing will be held at Court Room 3, Istanbul Commercial Court.","tr":"Duruşma İstanbul Ticaret Mahkemesi 3 No''lu Salonda yapılacaktır."},{"en":"You are required to attend in person or be represented by a lawyer.","tr":"Bizzat katılmanız veya bir avukat tarafından temsil edilmeniz gerekmektedir."},{"en":"Any written evidence must be submitted no later than seven days before the hearing.","tr":"Yazılı deliller duruşmadan en geç yedi gün önce sunulmalıdır."},{"en":"If you fail to attend, the court may decide the case in your absence.","tr":"Katılmamanız hâlinde mahkeme davayı yokluğunuzda karara bağlayabilir."}]'::jsonb,'[{"term":"hereby notified","tr":"işbu yazıyla bildirilir"},{"term":"in person","tr":"bizzat"},{"term":"be represented by","tr":"tarafından temsil edilmek"},{"term":"in your absence","tr":"yokluğunuzda"}]'::jsonb,'[{"q_tr":"Yazılı deliller en geç ne zaman sunulmalı?","options":["Duruşma günü","Duruşmadan yedi gün önce","Duruşmadan bir gün sonra"],"answer":1,"why_tr":"“no later than seven days before the hearing”"},{"q_tr":"Katılım olmazsa ne olabilir?","options":["Duruşma iptal edilir","Dava yokluğunda karara bağlanabilir","Ceza ödenir"],"answer":1,"why_tr":"“the court may decide the case in your absence”"}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('21a996de-3769-5062-b6b7-a7f9f4650548','0f692eaa-47c8-5983-880d-2c55c738f67a','Case summary','Dava özeti','[{"en":"The plaintiff, a software company, claims that the defendant failed to pay for services delivered in 2025.","tr":"Davacı bir yazılım şirketi, davalının 2025''te verilen hizmetlerin bedelini ödemediğini iddia ediyor."},{"en":"The defendant denies the allegation and argues that the software did not work as agreed.","tr":"Davalı iddiayı reddediyor ve yazılımın kararlaştırıldığı gibi çalışmadığını ileri sürüyor."},{"en":"An expert witness examined the system and found several serious defects.","tr":"Bir bilirkişi sistemi inceledi ve birkaç ciddi kusur buldu."},{"en":"The court ruled that the defendant must pay half of the invoice.","tr":"Mahkeme davalının faturanın yarısını ödemesi gerektiğine karar verdi."},{"en":"Both parties have 14 days to appeal against the ruling.","tr":"Her iki tarafın da karara itiraz etmek için 14 günü var."}]'::jsonb,'[{"term":"services delivered","tr":"verilen hizmetler"},{"term":"argue","tr":"ileri sürmek"},{"term":"defect","tr":"kusur"},{"term":"appeal against","tr":"-e itiraz etmek"}]'::jsonb,'[{"q_tr":"Davalı neden ödeme yapmadığını söylüyor?","options":["Fatura hiç gelmediği için","Yazılım kararlaştırıldığı gibi çalışmadığı için","Şirket iflas ettiği için"],"answer":1,"why_tr":"“argues that the software did not work as agreed”"},{"q_tr":"Mahkeme ne karar verdi?","options":["Davalı faturanın tamamını ödeyecek","Davalı faturanın yarısını ödeyecek","Dava reddedildi"],"answer":1,"why_tr":"“the defendant must pay half of the invoice”"}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('81f037ee-9380-5bb3-a1f6-2dff7d490023','26515c63-3bd4-5d24-9fbd-336e392868a3','PR: Add search filters','PR açıklaması','[{"en":"This PR adds price and category filters to the search page.","tr":"Bu PR, arama sayfasına fiyat ve kategori filtreleri ekliyor."},{"en":"I refactored the search service so that each filter is a small function.","tr":"Arama servisini, her filtre küçük bir fonksiyon olacak şekilde yeniden düzenledim."},{"en":"Test coverage for the search module is now 85%.","tr":"Arama modülünün test kapsamı artık %85."},{"en":"The old filter API is deprecated but still works.","tr":"Eski filtre API''si kullanımdan kaldırıldı ama hâlâ çalışıyor."},{"en":"Please review the naming in filters.ts carefully.","tr":"Lütfen filters.ts dosyasındaki adlandırmayı dikkatle incele."}]'::jsonb,'[{"term":"refactored","tr":"yeniden düzenlendi"},{"term":"coverage","tr":"test kapsamı"},{"term":"deprecated","tr":"kullanımdan kaldırılmış"},{"term":"naming","tr":"adlandırma"}]'::jsonb,'[{"q_tr":"Bu PR ne ekliyor?","options":["Fiyat ve kategori filtreleri","Yeni bir giriş sayfası","Ödeme sistemi"],"answer":0,"why_tr":"“adds price and category filters to the search page”"},{"q_tr":"Eski filtre API''si için doğru olan hangisi?","options":["Artık hiç çalışmıyor","Kullanımdan kaldırıldı ama hâlâ çalışıyor","Yeni eklendi"],"answer":1,"why_tr":"“deprecated but still works”"},{"q_tr":"Yazar incelemecilerden özellikle neye bakmalarını istiyor?","options":["Test kapsamına","filters.ts dosyasındaki adlandırmaya","Ödeme ekranına"],"answer":1,"why_tr":"“Please review the naming in filters.ts carefully.”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('2240d1ac-de85-5905-8160-6d603f57ae22','26515c63-3bd4-5d24-9fbd-336e392868a3','Review comments','Kod inceleme yorumları','[{"en":"Reviewer: Nice catch on the empty list case!","tr":"İnceleyen: Boş liste durumunu iyi yakalamışsın!"},{"en":"Reviewer: The API URL is hardcoded here. Could we read it from the config instead?","tr":"İnceleyen: API adresi burada koda sabit yazılmış. Bunun yerine yapılandırmadan okuyabilir miyiz?"},{"en":"Author: Good point, I''ve moved it to the config file.","tr":"Yazar: Haklısın, yapılandırma dosyasına taşıdım."},{"en":"Reviewer: There is also a merge conflict in package.json.","tr":"İnceleyen: package.json dosyasında bir birleştirme çakışması da var."},{"en":"Author: Fixed. Ready for another look.","tr":"Yazar: Düzelttim. Tekrar bakmaya hazır."}]'::jsonb,'[{"term":"nice catch","tr":"iyi yakaladın"},{"term":"hardcoded","tr":"koda sabit yazılmış"},{"term":"merge conflict","tr":"birleştirme çakışması"},{"term":"ready for another look","tr":"tekrar incelemeye hazır"}]'::jsonb,'[{"q_tr":"İnceleyen API adresiyle ilgili ne öneriyor?","options":["Adresi silmeyi","Adresi yapılandırmadan okumayı","Adresi başka bir dala taşımayı"],"answer":1,"why_tr":"“Could we read it from the config instead?”"},{"q_tr":"Konuşmanın sonunda durum ne?","options":["Yazar düzeltmeleri yaptı ve yeniden inceleme bekliyor","İnceleyen PR''ı reddetti","Çakışma hâlâ duruyor"],"answer":0,"why_tr":"“Fixed. Ready for another look.”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('70a8da23-056c-5361-b5aa-89fce2f65d48','8c6847cf-f469-5cd6-b2d7-4c15dbfd531a','Login fails after password reset','Hata kaydı','[{"en":"Title: Login fails after password reset.","tr":"Başlık: Parola sıfırlamadan sonra giriş başarısız oluyor."},{"en":"Steps to reproduce: reset the password from the email link, then log in with the new password.","tr":"Yeniden oluşturma adımları: parolayı e-postadaki bağlantıdan sıfırla, sonra yeni parolayla giriş yap."},{"en":"Expected result: the user sees the dashboard.","tr":"Beklenen sonuç: kullanıcı ana paneli görür."},{"en":"Actual result: an ''Invalid session'' error appears.","tr":"Gerçekleşen sonuç: “Geçersiz oturum” hatası çıkıyor."},{"en":"The issue is intermittent; it does not happen on every attempt.","tr":"Sorun aralıklı; her denemede olmuyor."}]'::jsonb,'[{"term":"steps to reproduce","tr":"yeniden oluşturma adımları"},{"term":"expected result","tr":"beklenen sonuç"},{"term":"actual result","tr":"gerçekleşen sonuç"},{"term":"intermittent","tr":"aralıklı"}]'::jsonb,'[{"q_tr":"Hata ne zaman ortaya çıkıyor?","options":["Parola sıfırlandıktan sonra yeni parolayla giriş yaparken","Kullanıcı kayıt olurken","Ana panel açıldığında"],"answer":0,"why_tr":"Adımlar: parolayı sıfırla, sonra yeni parolayla giriş yap."},{"q_tr":"“intermittent” bu kayıtta ne anlatıyor?","options":["Hata her denemede oluyor","Hata bazen oluyor, bazen olmuyor","Hata düzeltildi"],"answer":1,"why_tr":"“it does not happen on every attempt” = her denemede olmuyor."}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('a8f1b2bb-362c-5af5-9bfa-4afda7fd3bf4','8c6847cf-f469-5cd6-b2d7-4c15dbfd531a','README: Troubleshooting','README parçası','[{"en":"If the app does not start, check that Node 22 is installed.","tr":"Uygulama başlamazsa Node 22''nin kurulu olduğunu kontrol et."},{"en":"If you see a timeout error, increase REQUEST_TIMEOUT in the config file.","tr":"Zaman aşımı hatası görürsen yapılandırma dosyasındaki REQUEST_TIMEOUT değerini artır."},{"en":"The old login method is deprecated and will be removed in version 3.","tr":"Eski giriş yöntemi kullanımdan kaldırıldı ve 3. sürümde tamamen silinecek."},{"en":"Please include the full stack trace when you open an issue.","tr":"Bir sorun kaydı açarken lütfen tam yığın izini ekle."}]'::jsonb,'[{"term":"troubleshooting","tr":"sorun giderme"},{"term":"deprecated","tr":"kullanımdan kaldırılmış"},{"term":"stack trace","tr":"yığın izi"},{"term":"open an issue","tr":"sorun kaydı açmak"}]'::jsonb,'[{"q_tr":"Zaman aşımı hatası görürsen ne yapmalısın?","options":["Node''u kaldırmalısın","REQUEST_TIMEOUT değerini artırmalısın","Eski giriş yöntemini kullanmalısın"],"answer":1,"why_tr":"“increase REQUEST_TIMEOUT in the config file”"},{"q_tr":"Eski giriş yöntemi için ne söyleniyor?","options":["3. sürümde kaldırılacak","Yeni eklendi","Önerilen yöntem bu"],"answer":0,"why_tr":"“deprecated and will be removed in version 3”"}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('15bc6b33-a1d6-5fac-bff5-8f029a51b6dc','b2d05b0d-3f42-5152-8985-f7b28dde1bdb','Team chat: release update','Ekip mesajı','[{"en":"Hi team, here is a quick update on the 2.4 release.","tr":"Herkese merhaba, 2.4 sürümüyle ilgili kısa bir durum bilgisi."},{"en":"The search filters are done and merged.","tr":"Arama filtreleri bitti ve ana koda eklendi."},{"en":"The payment bug is still open, so we are not on track for Thursday.","tr":"Ödeme hatası hâlâ açık, bu yüzden perşembe için plana uygun değiliz."},{"en":"Our new estimate for the release is Monday.","tr":"Sürüm için yeni tahminimiz pazartesi."},{"en":"Ece is out of office tomorrow, so please send payment questions to Ali.","tr":"Ece yarın izinli, bu yüzden ödeme sorularını lütfen Ali''ye gönderin."}]'::jsonb,'[{"term":"merged","tr":"ana koda eklendi"},{"term":"on track","tr":"plana uygun"},{"term":"estimate","tr":"tahmin"},{"term":"out of office","tr":"izinli, ofis dışında"}]'::jsonb,'[{"q_tr":"Sürüm neden perşembeye yetişmiyor?","options":["Ödeme hatası hâlâ açık","Arama filtreleri bitmedi","Ece izinli"],"answer":0,"why_tr":"“The payment bug is still open, so we are not on track” cümlesi nedeni veriyor."},{"q_tr":"Yarın ödeme sorularını kime göndermelisin?","options":["Ece''ye","Ali''ye","Takım liderine"],"answer":1,"why_tr":"Ece izinli; sorular Ali''ye gönderilecek."},{"q_tr":"Sürüm için yeni tahmin hangi gün?","options":["Perşembe","Cuma","Pazartesi"],"answer":2,"why_tr":"“Our new estimate for the release is Monday.”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('7c7b5109-f52f-5671-9133-541403ef8aab','b2d05b0d-3f42-5152-8985-f7b28dde1bdb','Daily standup notes','Toplantı notu','[{"en":"Mert: Yesterday I fixed the login timeout.","tr":"Mert: Dün giriş zaman aşımını düzelttim."},{"en":"Today I''m working on the profile page.","tr":"Bugün profil sayfası üzerinde çalışıyorum."},{"en":"Selin: I''m stuck on a failing integration test.","tr":"Selin: Başarısız olan bir entegrasyon testinde takıldım."},{"en":"Mert will pair with her after the standup.","tr":"Mert toplantıdan sonra onunla eşli çalışacak."},{"en":"Action item: Selin will share the test logs in the team channel.","tr":"Yapılacak iş: Selin test kayıtlarını ekip kanalında paylaşacak."}]'::jsonb,'[{"term":"timeout","tr":"zaman aşımı"},{"term":"integration test","tr":"entegrasyon testi"},{"term":"action item","tr":"yapılacak iş"},{"term":"logs","tr":"kayıtlar"}]'::jsonb,'[{"q_tr":"Selin''in engeli ne?","options":["Profil sayfası","Başarısız bir entegrasyon testi","Giriş zaman aşımı"],"answer":1,"why_tr":"“I''m stuck on a failing integration test.”"},{"q_tr":"Toplantıdan sonra ne olacak?","options":["Mert ile Selin eşli çalışacak","Mert izne çıkacak","Selin profil sayfasını bitirecek"],"answer":0,"why_tr":"“Mert will pair with her after the standup.”"}]'::jsonb,1,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('6cb74742-e3ac-5835-af85-0c13a5ebd287','04ba1e9d-bfcb-5de1-8090-cb11f0c1e4cc','Important: change to your flight','Havayolu e-postası','[{"en":"We''re sorry to inform you that your flight LH 1301 on 12 May has been cancelled.","tr":"12 Mayıs''taki LH 1301 sefer sayılı uçuşunuzun iptal edildiğini üzülerek bildiririz."},{"en":"We have rebooked you on flight LH 1305, which departs at 18:15 on the same day.","tr":"Sizi aynı gün 18.15''te kalkan LH 1305 sefer sayılı uçuşa aktardık."},{"en":"Your seat and baggage allowance remain the same.","tr":"Koltuğunuz ve bagaj hakkınız aynı kalıyor."},{"en":"If the new flight does not suit you, you can change it free of charge or request a full refund.","tr":"Yeni uçuş size uymuyorsa ücretsiz değiştirebilir veya tam iade isteyebilirsiniz."},{"en":"Please check in online no later than 23 hours before departure.","tr":"Lütfen kalkıştan en geç 23 saat önce çevrim içi check-in yapın."}]'::jsonb,'[{"term":"rebook","tr":"yeniden rezervasyon yapmak"},{"term":"allowance","tr":"hak (bagaj hakkı)"},{"term":"free of charge","tr":"ücretsiz"},{"term":"no later than","tr":"en geç"}]'::jsonb,'[{"q_tr":"Yolcuya ne yapıldı?","options":["Para iadesi yapıldı","Başka bir uçuşa aktarıldı","Otel verildi"],"answer":1,"why_tr":"“We have rebooked you on flight LH 1305”"},{"q_tr":"Yeni uçuş uymazsa yolcu ne yapabilir?","options":["Ek ücretle değiştirebilir","Ücretsiz değiştirebilir veya tam iade alabilir","Hiçbir şey yapamaz"],"answer":1,"why_tr":"“you can change it free of charge or request a full refund”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('7f5e29b7-6f12-5e8a-8c29-7f5d95ab56c3','04ba1e9d-bfcb-5de1-8090-cb11f0c1e4cc','At the airport','Havalimanı tabelaları ve anonslar','[{"en":"Departures: please check in at least two hours before your flight.","tr":"Dış hatlar gidiş: lütfen uçuşunuzdan en az iki saat önce check-in yapın."},{"en":"Liquids must be in containers of 100 ml or less.","tr":"Sıvılar 100 ml veya daha küçük kaplarda olmalıdır."},{"en":"Do not leave your bags unattended.","tr":"Çantalarınızı başıboş bırakmayın."},{"en":"Flight TK 1985 to London is now boarding at gate 14.","tr":"Londra''ya giden TK 1985 sefer sayılı uçuşun biniş işlemi 14 numaralı kapıda başladı."},{"en":"Baggage from flight TK 1986 will arrive at belt 5.","tr":"TK 1986 sefer sayılı uçuşun bagajları 5 numaralı banda gelecek."}]'::jsonb,'[{"term":"at least","tr":"en az"},{"term":"container","tr":"kap"},{"term":"unattended","tr":"gözetimsiz, başıboş"},{"term":"belt","tr":"(bagaj) bant"}]'::jsonb,'[{"q_tr":"Sıvı kapları en fazla kaç ml olabilir?","options":["50 ml","100 ml","500 ml"],"answer":1,"why_tr":"“containers of 100 ml or less”"},{"q_tr":"TK 1985 için hangi işlem başladı?","options":["Check-in","Biniş","Bagaj teslimi"],"answer":1,"why_tr":"“is now boarding at gate 14”"}]'::jsonb,1,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('4a505ec6-d9a0-5cc3-b305-b4345c2edc5e','4ad2bb76-da0e-5681-bb74-6e5fe545667a','Visitor information','Müze bilgilendirmesi','[{"en":"The museum is open from 9 am to 6 pm, Tuesday to Sunday.","tr":"Müze salıdan pazara 09.00–18.00 arası açıktır."},{"en":"Last admission is one hour before closing.","tr":"Son giriş, kapanıştan bir saat öncedir."},{"en":"Tickets are cheaper online, and admission is free for under-18s.","tr":"Biletler internetten daha ucuzdur ve 18 yaş altı için giriş ücretsizdir."},{"en":"Free guided tours in English start at 11 am and 3 pm.","tr":"İngilizce ücretsiz rehberli turlar 11.00 ve 15.00''te başlar."},{"en":"Large bags must be left in the cloakroom.","tr":"Büyük çantalar vestiyere bırakılmalıdır."}]'::jsonb,'[{"term":"last admission","tr":"son giriş"},{"term":"under-18s","tr":"18 yaş altındakiler"},{"term":"cloakroom","tr":"vestiyer, emanet"}]'::jsonb,'[{"q_tr":"Müze hangi gün kapalı?","options":["Pazartesi","Salı","Pazar"],"answer":0,"why_tr":"“open … Tuesday to Sunday” — pazartesi yok."},{"q_tr":"Saat 17.30''da müzeye girilebilir mi?","options":["Evet","Hayır, son giriş 17.00","Yalnız rehberli turla"],"answer":1,"why_tr":"“Last admission is one hour before closing.” Kapanış 18.00."}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('17bc2333-ff77-504d-84b8-52b1ffdf5f47','4ad2bb76-da0e-5681-bb74-6e5fe545667a','A short review','Restoran yorumu','[{"en":"We had dinner here on our first night in Lisbon.","tr":"Lizbon''daki ilk gecemizde burada akşam yemeği yedik."},{"en":"The grilled fish was fresh and the portions were generous.","tr":"Izgara balık tazeydi ve porsiyonlar boldu."},{"en":"It was quite crowded, so we waited about twenty minutes for a table.","tr":"Oldukça kalabalıktı, bu yüzden masa için yaklaşık yirmi dakika bekledik."},{"en":"The staff were friendly and recommended a great local wine.","tr":"Çalışanlar güler yüzlüydü ve harika bir yerel şarap önerdiler."},{"en":"It''s cash only, so bring some money with you.","tr":"Yalnız nakit geçiyor, yanınıza para alın."}]'::jsonb,'[{"term":"portion","tr":"porsiyon"},{"term":"generous","tr":"bol, cömert"},{"term":"staff","tr":"çalışanlar, personel"}]'::jsonb,'[{"q_tr":"Yorumu yazan kişiler neden beklemiş?","options":["Yemek geç geldiği için","Restoran kalabalık olduğu için","Rezervasyonları olmadığı için"],"answer":1,"why_tr":"“It was quite crowded, so we waited …”"},{"q_tr":"Ödeme hakkında ne söyleniyor?","options":["Kart geçiyor","Yalnız nakit","Bahşiş zorunlu"],"answer":1,"why_tr":"“It''s cash only”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('152aed4e-e885-51c9-90d7-8b726b92bc28','d4a80253-58de-5511-a2bd-ff59540ed595','Pre-arrival email','Otel e-postası','[{"en":"Dear Ms. Yıldız, thank you for choosing the Blue Bay Hotel.","tr":"Sayın Yıldız Hanım, Blue Bay Otel''i seçtiğiniz için teşekkür ederiz."},{"en":"Check-in is from 2 pm and check-out is until 12 noon.","tr":"Giriş saat 14.00''ten itibaren, çıkış ise öğlen 12.00''ye kadardır."},{"en":"Breakfast is complimentary and is served from 7 to 10:30.","tr":"Kahvaltı ücretsizdir ve 7.00–10.30 arası servis edilir."},{"en":"If you would like an airport transfer, please let us know your flight number in advance.","tr":"Havalimanı transferi isterseniz lütfen uçuş numaranızı önceden bildirin."},{"en":"We look forward to welcoming you.","tr":"Sizi ağırlamayı sabırsızlıkla bekliyoruz."}]'::jsonb,'[{"term":"complimentary","tr":"ücretsiz"},{"term":"served","tr":"servis edilir"},{"term":"in advance","tr":"önceden"},{"term":"look forward to","tr":"dört gözle beklemek"}]'::jsonb,'[{"q_tr":"Kahvaltı için ücret ödenir mi?","options":["Evet, ayrıca ödenir","Hayır, ücretsizdir","Sadece hafta sonu ücretsizdir"],"answer":1,"why_tr":"“Breakfast is complimentary.” — complimentary = ücretsiz."},{"q_tr":"Transfer için misafir ne yapmalı?","options":["Uçuş numarasını önceden bildirmeli","Resepsiyonu havalimanından aramalı","Taksi çağırmalı"],"answer":0,"why_tr":"“please let us know your flight number in advance”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('a3fae9fb-4a90-517f-a7c9-782a14346b8c','d4a80253-58de-5511-a2bd-ff59540ed595','A guest review','Misafir yorumu','[{"en":"We stayed at the hotel for four nights in June.","tr":"Haziranda otelde dört gece kaldık."},{"en":"The location is perfect: the old town is within walking distance.","tr":"Konum mükemmel: eski şehir yürüme mesafesinde."},{"en":"On the first night, the shower didn''t work, but the staff fixed it within an hour.","tr":"İlk gece duş çalışmadı ama personel bir saat içinde tamir etti."},{"en":"They even upgraded us to a sea-view room for the inconvenience.","tr":"Yaşattıkları sıkıntı için bizi deniz manzaralı bir odaya bile yükselttiler."},{"en":"I would definitely recommend this hotel.","tr":"Bu oteli kesinlikle tavsiye ederim."}]'::jsonb,'[{"term":"within walking distance","tr":"yürüme mesafesinde"},{"term":"staff","tr":"personel"},{"term":"upgraded","tr":"yükseltti"},{"term":"definitely","tr":"kesinlikle"}]'::jsonb,'[{"q_tr":"İlk gece ne sorun yaşandı?","options":["Klima çalışmadı","Duş çalışmadı","Oda hazır değildi"],"answer":1,"why_tr":"“the shower didn''t work”"},{"q_tr":"Otel sorunu nasıl telafi etti?","options":["Para iadesi yaptı","Ücretsiz akşam yemeği verdi","Deniz manzaralı odaya yükseltti"],"answer":2,"why_tr":"“They even upgraded us to a sea-view room for the inconvenience.”"}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('ccb814ec-731a-5d20-80a3-26e92d0ebb45','2e27320a-9d7f-514d-b3d5-0606c1f40344','Working from home','Akademik paragraf','[{"en":"Working from home has become common in many countries.","tr":"Evden çalışma pek çok ülkede yaygınlaştı."},{"en":"Its main benefit is that employees save time because they do not commute.","tr":"Temel faydası, çalışanların işe gidip gelmedikleri için zaman kazanmasıdır."},{"en":"However, some workers feel isolated, and this can reduce their motivation.","tr":"Ancak bazı çalışanlar kendini yalnız hissediyor ve bu durum motivasyonlarını düşürebiliyor."},{"en":"Whereas large companies can offer online support, small firms often lack the resources to do so.","tr":"Büyük şirketler çevrim içi destek sunabilirken küçük firmalar çoğu zaman bunun için gereken kaynaklardan yoksun."},{"en":"Therefore, the impact of remote work depends partly on the size of the company.","tr":"Bu nedenle uzaktan çalışmanın etkisi kısmen şirketin büyüklüğüne bağlı."}]'::jsonb,'[{"term":"benefit","tr":"fayda"},{"term":"isolated","tr":"yalnız, yalıtılmış"},{"term":"lack","tr":"-den yoksun olmak"},{"term":"impact","tr":"etki"}]'::jsonb,'[{"q_tr":"Paragrafa göre evden çalışmanın bir sakıncası nedir?","options":["Çalışanların zaman kaybetmesi","Bazı çalışanların yalnız hissetmesi","Şirketlerin daha çok para harcaması"],"answer":1,"why_tr":"“some workers feel isolated, and this can reduce their motivation”"},{"q_tr":"“Whereas” ile başlayan cümle neyi karşılaştırıyor?","options":["Büyük ve küçük şirketlerin destek olanaklarını","Evden ve ofisten çalışmayı","Çalışanların yaşlarını"],"answer":0,"why_tr":"Büyük şirketlerin destek sunabildiği, küçük firmaların ise kaynaktan yoksun olduğu karşılaştırılıyor."},{"q_tr":"Paragraf hangi sonuca varıyor?","options":["Uzaktan çalışma herkes için kötüdür","Uzaktan çalışmanın etkisi şirket büyüklüğüne kısmen bağlıdır","Küçük firmalar uzaktan çalışmayı yasaklamalıdır"],"answer":1,"why_tr":"Son cümle “Therefore” ile bu sonucu veriyor."}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('bc1bc712-7e06-5814-b110-b5d99ad9e867','2e27320a-9d7f-514d-b3d5-0606c1f40344','Urban trees','Akademik paragraf','[{"en":"Trees play a crucial role in cities.","tr":"Ağaçlar şehirlerde çok önemli bir rol oynar."},{"en":"They reduce temperatures in summer and contribute to cleaner air.","tr":"Yazın sıcaklıkları düşürür ve havanın temizlenmesine katkıda bulunurlar."},{"en":"Despite these benefits, many cities cut down trees to build roads.","tr":"Bu faydalara rağmen pek çok şehir yol yapmak için ağaç kesiyor."},{"en":"This often leads to hotter streets and higher energy use for air conditioning.","tr":"Bu da çoğu zaman daha sıcak sokaklara ve klima için daha fazla enerji kullanımına yol açıyor."}]'::jsonb,'[{"term":"crucial","tr":"çok önemli"},{"term":"contribute to","tr":"katkıda bulunmak"},{"term":"despite","tr":"-e rağmen"},{"term":"lead to","tr":"yol açmak"}]'::jsonb,'[{"q_tr":"Paragrafa göre ağaç kesmenin bir sonucu nedir?","options":["Sokakların serinlemesi","Klima için daha fazla enerji kullanılması","Havanın temizlenmesi"],"answer":1,"why_tr":"“leads to hotter streets and higher energy use for air conditioning”"},{"q_tr":"“Despite these benefits” ifadesi neyi vurgular?","options":["Faydalara rağmen ağaçların kesildiğini","Faydaların az olduğunu","Ağaçların yol yapımına yardım ettiğini"],"answer":0,"why_tr":"“despite” karşıtlık bildirir: faydalar var ama ağaçlar yine de kesiliyor."}]'::jsonb,2,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('9990c561-55e2-510e-894e-674cdf92405d','e6ad2555-ff51-5462-82ce-6e582d7ec447','Daily internet use, 2010–2024','Grafik yorumu','[{"en":"The chart shows the proportion of adults who used the internet daily between 2010 and 2024.","tr":"Grafik, 2010 ile 2024 arasında interneti her gün kullanan yetişkinlerin oranını gösteriyor."},{"en":"In 2010, the figure was about 40%.","tr":"2010''da bu oran yaklaşık %40''tı."},{"en":"It rose steadily over the next decade and reached 80% in 2020.","tr":"Sonraki on yılda düzenli olarak arttı ve 2020''de %80''e ulaştı."},{"en":"Since then, it has risen slightly and leveled off at around 85%.","tr":"O zamandan beri biraz arttı ve yaklaşık %85''te sabitlendi."},{"en":"Overall, daily internet use more than doubled over the period.","tr":"Genel olarak günlük internet kullanımı bu dönemde iki katından fazla arttı."}]'::jsonb,'[{"term":"proportion","tr":"oran"},{"term":"steadily","tr":"düzenli olarak"},{"term":"leveled off","tr":"sabitlendi"},{"term":"overall","tr":"genel olarak"}]'::jsonb,'[{"q_tr":"2020''de oran neydi?","options":["%40","%80","%85"],"answer":1,"why_tr":"“reached 80% in 2020”"},{"q_tr":"Paragrafa göre hangisi doğrudur?","options":["Oran 2020''den sonra keskin biçimde düştü","Oran dönem boyunca iki katından fazla arttı","Oran hep %40 civarında kaldı"],"answer":1,"why_tr":"%40''tan yaklaşık %85''e çıkmış: “more than doubled”."}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('7a23badc-fa8c-5652-b810-3831f3233e93','e6ad2555-ff51-5462-82ce-6e582d7ec447','Birth rates in developed countries','Akademik paragraf','[{"en":"In many developed countries, birth rates have declined over the last fifty years.","tr":"Pek çok gelişmiş ülkede doğum oranları son elli yılda düştü."},{"en":"This trend is mainly attributed to higher education levels and the rising cost of raising children.","tr":"Bu eğilim esas olarak daha yüksek eğitim düzeylerine ve çocuk yetiştirmenin artan maliyetine bağlanıyor."},{"en":"As a result, the proportion of older people in the population has increased.","tr":"Sonuç olarak nüfus içindeki yaşlıların oranı arttı."},{"en":"Some governments now offer financial support to families; however, its effect has been limited so far.","tr":"Bazı hükümetler artık ailelere maddi destek sunuyor; ancak bunun etkisi şimdiye kadar sınırlı kaldı."}]'::jsonb,'[{"term":"birth rate","tr":"doğum oranı"},{"term":"attributed to","tr":"-e bağlanan"},{"term":"proportion","tr":"oran"},{"term":"so far","tr":"şimdiye kadar"}]'::jsonb,'[{"q_tr":"Paragrafa göre doğum oranlarındaki düşüşün bir nedeni nedir?","options":["Daha yüksek eğitim düzeyleri","Yaşlı nüfusun azalması","Devlet desteğinin artması"],"answer":0,"why_tr":"“mainly attributed to higher education levels and the rising cost of raising children”"},{"q_tr":"Devletlerin maddi desteği hakkında ne söyleniyor?","options":["Doğum oranlarını iki katına çıkardı","Etkisi şimdiye kadar sınırlı kaldı","Hiç uygulanmadı"],"answer":1,"why_tr":"“its effect has been limited so far”"},{"q_tr":"“As a result” ile başlayan cümle neyi anlatıyor?","options":["Düşen doğum oranlarının bir sonucunu","Bir karşıtlığı","Bir örneği"],"answer":0,"why_tr":"“As a result” sonuç bildirir: yaşlı nüfusun oranı arttı."}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('ae99d991-6b78-5184-ad8b-95397fedf2a7','de1b4712-7243-59d2-b591-86fd886a91fd','Sleep and memory','Akademik paragraf','[{"en":"Many studies have examined the link between sleep and memory.","tr":"Pek çok çalışma uyku ile hafıza arasındaki bağlantıyı incelemiştir."},{"en":"In a recent study, researchers asked 120 participants to learn a list of words before going to bed.","tr":"Yakın tarihli bir çalışmada araştırmacılar 120 katılımcıdan yatmadan önce bir kelime listesi öğrenmelerini istedi."},{"en":"Participants who slept at least seven hours remembered more words the next day.","tr":"En az yedi saat uyuyan katılımcılar ertesi gün daha fazla kelime hatırladı."},{"en":"However, the authors note that the sample consisted only of university students.","tr":"Ancak yazarlar, örneklemin yalnızca üniversite öğrencilerinden oluştuğunu belirtiyor."},{"en":"Thus, further research is needed before the results can be generalized.","tr":"Bu nedenle sonuçlar genellenmeden önce daha fazla araştırma gerekiyor."}]'::jsonb,'[{"term":"examine","tr":"incelemek"},{"term":"participant","tr":"katılımcı"},{"term":"sample","tr":"örneklem"},{"term":"generalize","tr":"genellemek"}]'::jsonb,'[{"q_tr":"Paragrafa göre aşağıdakilerden hangisi doğrudur?","options":["Daha uzun uyuyan katılımcılar daha fazla kelime hatırladı","Katılımcılar farklı yaş gruplarından seçildi","Sonuçlar herkese genellenebilir"],"answer":0,"why_tr":"“Participants who slept at least seven hours remembered more words.” Diğer iki seçenek paragrafla çelişiyor."},{"q_tr":"Yazarlar neden temkinli?","options":["Çalışma çok uzun sürdü","Örneklem yalnızca üniversite öğrencilerinden oluşuyordu","Kelime listesi çok kısaydı"],"answer":1,"why_tr":"“the sample consisted only of university students”"},{"q_tr":"Son cümledeki “Thus” hangi ilişkiyi kuruyor?","options":["Karşıtlık","Sonuç","Örnekleme"],"answer":1,"why_tr":"“Thus” = bu nedenle; önceki cümledeki kısıtlılığın sonucunu bildiriyor."}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('bd56a350-4163-56da-9d14-9665fe501261','de1b4712-7243-59d2-b591-86fd886a91fd','Online learning survey','Akademik paragraf','[{"en":"A survey of 1,500 university students was conducted in 2023.","tr":"2023''te 1.500 üniversite öğrencisiyle bir anket yapıldı."},{"en":"About 70% of respondents said they preferred online lectures, which they could watch at any time.","tr":"Yanıt verenlerin yaklaşık %70''i, istedikleri zaman izleyebildikleri çevrim içi dersleri tercih ettiğini söyledi."},{"en":"Yet many of them also reported feeling less connected to their classmates.","tr":"Yine de birçoğu sınıf arkadaşlarına daha az bağlı hissettiğini de bildirdi."},{"en":"The authors claim that universities should combine online and face-to-face teaching.","tr":"Yazarlar, üniversitelerin çevrim içi ve yüz yüze öğretimi birleştirmesi gerektiğini ileri sürüyor."}]'::jsonb,'[{"term":"survey","tr":"anket"},{"term":"respondent","tr":"yanıt veren kişi"},{"term":"yet","tr":"yine de, ancak"},{"term":"claim","tr":"ileri sürmek"}]'::jsonb,'[{"q_tr":"Paragrafa göre öğrencilerin çoğu çevrim içi dersleri neden tercih ediyor?","options":["Dersler daha kısa olduğu için","Dersleri istedikleri zaman izleyebildikleri için","Hocalar daha iyi olduğu için"],"answer":1,"why_tr":"“online lectures, which they could watch at any time”"},{"q_tr":"Yazarlar ne öneriyor?","options":["Yalnızca çevrim içi öğretim","Çevrim içi ve yüz yüze öğretimin birleştirilmesi","Yüz yüze öğretimin kaldırılması"],"answer":1,"why_tr":"“combine online and face-to-face teaching”"}]'::jsonb,3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('c8b93679-fdc2-5bb7-81ad-02c3e4a00783','0fe90fa6-b48a-543a-a4ef-332bf34e617c','Kendini 4–5 cümleyle tanıt: adın, yaşın, nerelisin, ne iş yapıyorsun ve ailende kimler var?','["am / is / are doğru kullanılmış","my / his / her doğru seçilmiş","Meslekten önce a / an var (I''m a teacher)"]'::jsonb,array['Hi, my name is Merve and I''m twenty-three years old. I''m from Samsun, but I live in Ankara. I''m a nurse. My father is a driver and my mother is a teacher. I have one brother; his name is Efe.']::text[],1,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('d5fe9f99-4355-52d4-b87c-aeff7a1d60d5','fe12b100-e015-5fb9-929c-a7577550770c','Sıradan bir gününü 4–5 cümleyle anlat: kaçta kalkarsın, ne yersin, nereye gidersin, akşam ne yaparsın?','["Present simple doğru kullanılmış (he/she ile -s)","Saatler “at” ile verilmiş","En az bir sıklık zarfı var (usually, always, never)"]'::jsonb,array['I get up at seven o''clock. I usually have eggs and tea for breakfast. I go to work by bus and I start at nine. In the evening I cook dinner and watch TV. I never go to bed late.']::text[],1,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('496bfe7e-bfea-5b69-bd6e-486f48119ac9','61d6af77-625c-535b-96ca-5f8745c3a368','Geçen hafta sonunu 5–6 cümleyle anlat: nereye gittin, kiminle, ne yaptın, nasıldı?','["Past simple doğru (düzenli ve düzensiz fiiller)","En az bir was / were cümlesi","Sıralama sözcükleri var (first, then, after that)"]'::jsonb,array['Last weekend I went to Eskişehir with two friends. First we visited the Odunpazarı houses, then we had lunch by the river. The food was delicious. In the evening we saw a play, but it was a bit boring. We came back on Sunday by train. It was a lovely weekend.']::text[],2,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('797d8fbe-a599-5411-9fbe-d05a045756f4','bc5f3cd8-55f8-5a25-8906-26008f507e61','Bir arkadaşına önümüzdeki ay için planlarını anlatan 5–6 cümlelik bir mesaj yaz. En az bir karşılaştırma cümlesi kullan.','["going to veya present continuous ile plan anlatılmış","En az bir karşılaştırma var (-er / more / as … as)","Mesaj selamlama ve kapanışla bitmiş"]'::jsonb,array['Hi Arda! Next month is going to be busy. I''m starting a new job on the 3rd, and I''m going to move to a smaller flat. It''s further from the centre, but it''s cheaper than my old one. On the 20th I''m visiting my parents in Edirne. Are you free at the end of the month? Let''s meet! — Deniz']::text[],2,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('d3021bbb-1f7b-5f34-8c01-87c7ab782dd9','8886d6de-85b1-5473-95de-ae8213ec5037','Bir arkadaşın İngilizce konuşmaktan çekindiğini yazdı. Ona 5–6 cümlelik bir tavsiye mesajı yaz.','["En az bir if cümlesi (1. veya 2. tip) doğru kurulmuş","should / Why don''t you / If I were you ile tavsiye verilmiş","En az bir -ing / to fiil yapısı doğru (enjoy watching, try to speak)"]'::jsonb,array['Hi Burcu! Don''t worry, everyone feels nervous at first. If I were you, I''d practise a little every day. Why don''t you try watching series with English subtitles? You should also find a speaking partner — it''s worth trying even if it feels strange. If you keep going, you''ll feel more confident in a few months. Good luck!']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('ef5e6fd9-9be0-528a-b866-a48e13eaea5b','cda9518c-acc9-50f6-8edf-1221122b1601','Son birkaç yılda hayatında neler değişti? 5–7 cümleyle anlat; present perfect ve past simple''ı doğru yerde kullan.','["Present perfect: zamanı belli olmayan değişimler (I''ve started, I''ve learned)","Past simple: belli zamanlı olaylar (in 2022, last year)","for / since doğru kullanılmış"]'::jsonb,array['A lot has changed in my life recently. I graduated from university in 2024 and moved to İstanbul last year. I''ve worked as a junior designer since January. I''ve also taken up swimming, and I''ve lost five kilos so far. I haven''t got used to the traffic yet, but I really love my new job.']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('d5166bc2-47e5-53b6-93dd-5363f65021ca','7bf0c681-79b3-5002-b1b1-c7d262f7cff7','“Üniversite eğitimi ücretsiz olmalı mı?” konusunda 6–8 cümlelik bir görüş paragrafı yaz. Karşı görüşe de değin.','["Görüş net bir giriş cümlesiyle verilmiş (In my opinion / I believe)","Karşı görüş although / despite / on the other hand ile ele alınmış","En az bir relative clause var (who / which / whose)","Sonuç cümlesi var (As a result / Therefore / Overall)"]'::jsonb,array['In my opinion, university education should be free for students who cannot afford it. Education is a right, and talented young people should not lose opportunities because of money. On the other hand, free education for everyone would be very expensive for the government. Despite this, a system which supports low-income students seems fair to me. Countries that invest in education usually have stronger economies. Therefore, I believe free education, at least for those in need, benefits the whole society.']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('91789c74-5dbd-5b94-b054-06a29e3b1a3f','0d6376db-346e-5a63-b3ee-03e2b9fef8c1','Hayatında farklı karar verseydin ne olurdu? 6–8 cümlelik bir paragraf yaz; 3. tip if, wish ve en az bir geçmiş modal kullan.','["3. tip if doğru (If I had …, I would have …)","wish / if only ile pişmanlık ya da istek","should have / might have / must have doğru kullanılmış","Olaylar mantıklı bir sırayla anlatılmış"]'::jsonb,array['Three years ago I had to choose between a job in Ankara and a master''s degree in Germany. I chose the job because I didn''t want to leave my family. If I had gone to Germany, I would have learned German and I might have found a job there. Sometimes I wish I had been braver. On the other hand, I''ve learned a lot at work, and I''ve been promoted twice. My manager says I must have been the fastest learner in the team. In hindsight, I shouldn''t have worried so much — both options were good.']::text[],4,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('e180bfb3-246b-597a-a816-45acea441b6f','46fa5ffe-78fe-5175-8072-3b2621cc801c','Kendi ilgi alanından bir konuda (ör. uzaktan çalışma, uyku, sosyal medya) kısa bir araştırma özeti yaz: amaç, yöntem, bulgu ve sınırlılık. 6–8 cümle.','["Temkinli dil kullanılmış (suggest, may, tend to, appear to)","En az bir isimleştirme (the increase in, a lack of, the failure to)","Bulgu ve sınırlılık ayrı ayrı belirtilmiş","Akademik kelimeler doğru kullanılmış (sample, findings, significant)"]'::jsonb,array['This study investigated the effect of remote work on employee wellbeing. The sample consisted of 300 office workers in three Turkish cities. The findings suggest that remote workers tend to report lower stress levels, although the difference was not statistically significant for parents with young children. The increase in flexibility appears to be the main benefit. However, a lack of social contact was frequently mentioned. One limitation is that the data were self-reported. Further research with a larger sample may provide more robust evidence.']::text[],5,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('e02dd7b0-392f-5bd6-95c7-8a6a5edfc9d3','39054825-3f71-5559-9822-6a4004d50c22','Belediyeye, şehir merkezinin hafta sonları araç trafiğine kapatılmasını öneren 6–8 cümlelik ikna edici bir paragraf yaz.','["En az bir devrik yapı (Not only…, Rarely…, Under no circumstances…)","En az bir cleft cümle (What we need is…, It is … that…)","İleri düzey kelimeler doğal biçimde kullanılmış (substantial, alleviate, foster…)","Karşı görüşe kısa bir cevap var"]'::jsonb,array['What our city centre needs is space for people, not cars. Closing it to traffic at weekends would not only alleviate pollution, but it would also foster a stronger sense of community. Rarely do residents get the chance to enjoy their streets without noise. Some shop owners are reluctant, fearing a drop in customers; however, evidence from other cities shows a substantial rise in foot traffic. It is local businesses, in fact, that benefit most. Under no circumstances should we ignore this opportunity.']::text[],4,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('db877a99-e06b-5c9e-8e4b-30970c105f7e','e6ae5d8c-b653-5966-870b-5abc222f4d1b','Hayatında kötü görünüp sonradan iyi sonuçlanan bir olayı 7–9 cümlelik düşünceli bir paragrafta anlat. En az bir deyim, bir karma/devrik koşul ve bir subjunctive yapı kullan.','["En az iki deyim doğal biçimde kullanılmış","Karma veya devrik koşul doğru (Had I…, If I had…, I would be … now)","Subjunctive veya gerçek dışı geçmiş biçim (insisted that he be, it''s time we…)","Üslup tutarlı ve doğal"]'::jsonb,array['Being made redundant at thirty-two felt like the end of the world, so to speak. For weeks I was on the fence about whether to look for a similar job or retrain completely. My sister insisted that I take a coding course, and I reluctantly agreed. It took me months to get the hang of it, and there were moments when I wanted to give up. Had I not lost that job, I would still be sitting in an office I didn''t enjoy. Instead, I now work for a small company that genuinely values my ideas. Looking back, the redundancy was a blessing in disguise, albeit a painful one.']::text[],5,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('689bf6c7-31fc-5d3f-a964-b1f45e39faed','d085f43c-2ece-5c98-b9a2-fccd790e4488','Son okuduğun bir kitap, izlediğin bir film ya da oyun hakkında 7–9 cümlelik bir eleştiri yaz. Üslup sözcükleri, en az bir participle clause ve bir ellipsis/ikame kullan.','["En az bir participle clause (Having…, Set in…, Given…)","En az bir ellipsis veya ikame (so do I, as did…, the former / the latter, less so)","Değerlendirme dengeli: güçlü ve zayıf yönler","Üslup sözcükleri doğru (vivid, coherent, succinct, subtle…)"]'::jsonb,array['Set in 1970s İzmir, the film follows two sisters who run a failing bakery. The cinematography is vivid, capturing the city''s light beautifully, and the dialogue is succinct and often funny. The older sister is played with real subtlety; the younger, unfortunately, less so. Having built the tension so carefully, the director rushes the final act, which feels less coherent than the rest. Needless to say, the ending divided the audience, as did the music. Still, it is a moving portrait of family loyalty, and one I would happily watch again.']::text[],5,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('4870d590-aef7-5e55-970b-b51ec745a32c','6fbbf6ec-47c4-5a61-ae2a-085acb973117','Bir teknik sorunu ve iki olası çözümü 3–4 cümleyle anlat; birini öner ve nedenini söyle.','["Sorunu “The problem is that …” ile tanımlıyor","İki seçeneği “One option is to … / Another option is to …” ile sunuyor","Önerisini gerekçesiyle ve doğru yapıyla (suggest that / recommend -ing) yapıyor"]'::jsonb,array['The problem is that the motor overheats after an hour. One option is to add a second fan, and another option is to use a bigger motor. I suggest that we add a fan, because it is cheaper and faster. If we do this, the temperature will drop by about 10 degrees.']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('8494e6e8-77c2-57a2-bac8-ff04a6bdda38','c016cb37-6858-58cd-ae01-49689b107921','Bir ürünün 3–4 temel teknik özelliğini İngilizce yaz (boyut, ağırlık, malzeme, çalışma değeri) ve onu eski modelle karşılaştır.','["Ölçüleri doğru biçimde veriyor (by, per, up to)","Malzemeyi “made of” ile söylüyor","Karşılaştırma için -er/more … than ya da compared to kullanıyor"]'::jsonb,array['The new sensor measures 40 by 20 mm and weighs 35 grams. It is made of aluminum and operates at 5 volts. Compared to the old model, it is lighter and more accurate.']::text[],2,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('b20981e0-eb47-5623-ae5b-476cf1cd98f6','233b0925-1efe-5baa-9090-54d6f8aef7d6','Bir testin sonucunu 3–4 cümleyle özetle: ne test edildi, hangi koşulda, sonuç ne ve önerin ne?','["Test koşulunu (sıcaklık, yük, süre) veriyor","Sonucu sayılarla ve geçmiş zamanla anlatıyor","Öneriyi “We recommend …-ing” ile yapıyor"]'::jsonb,array['We tested five prototypes at full load for 48 hours. Four prototypes passed the test, but one failed after 30 hours because of overheating. We recommend using a larger fan in the next design.']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('e68fd1ea-71a0-547d-94cf-5b38c4d6bcb7','1ec86e14-8694-5f09-89f1-2ad9ef7f19f5','Bir arkadaşına 3–4 cümlelik bir mesaj yaz: hafta sonu planını anlat ve onu bir etkinliğe davet et.','["Planını “I''m going to …” ile anlatıyor","Daveti “How about …?” veya “Are you free …?” ile yapıyor","Somut bir gün, saat veya yer veriyor"]'::jsonb,array['Hi Ece! I''m going to clean the house on Saturday morning, but I''m free in the afternoon. How about going to the new café in Moda at three? Let me know if you''re free!']::text[],2,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('df4acf57-9455-5f4c-b038-ce63a2d91236','2fe5da34-f4cb-5c47-8c4e-d94faab76c7f','Kendini 3–4 cümleyle tanıt: nerelisin, ne iş yapıyorsun, boş zamanında neler yaparsın?','["Adını ve nereli olduğunu söylüyor","Mesleğini veya okulunu “I''m a …” ya da “I work at …” ile anlatıyor","Bir ilgi alanını “I like …-ing” ile anlatıyor"]'::jsonb,array['Hi, I''m Deniz. I''m originally from Bursa, but I''ve lived in İstanbul for three years. I work at a small software company. In my spare time, I like cooking and playing tennis.']::text[],1,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('1e0666e5-1431-5000-810e-05877917e678','9fec7c37-b21c-53df-8fc9-49684d6cfa85','Bir mağazaya ya da otele 3–4 cümlelik kibar bir şikâyet mesajı yaz: sorun ne, ne zaman oldu ve ne istiyorsun?','["Sorunu ve ne zaman olduğunu açıkça anlatıyor","İsteğini “I''d like …” ile kibarca söylüyor","Kaba veya suçlayıcı ifade kullanmıyor"]'::jsonb,array['Hello, I bought a lamp from your store last week, but it doesn''t work. I tried different sockets, but it still doesn''t turn on. I''d like to exchange it for a new one. I still have the receipt.']::text[],2,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('744a6b8c-0145-58b7-be17-00eee2d38839','6669c461-b0f4-5b73-b7bd-cd4c249f1e3f','Doktora göndereceğin 3–4 cümlelik bir mesaj yaz: hangi belirtilerin var, ne zamandır sürüyor ve ne istiyorsun (randevu, öneri vb.)?','["Belirtiler doğru kelimelerle anlatılmış (pain, fever, cough vb.)","Süre için “for/since” ile “I''ve had / I''ve been” kullanılmış","Kibar bir istek cümlesi var (Could I …? / Could you …?)"]'::jsonb,array['Hello Dr. Kaya, I''ve had a bad cough and a fever since Sunday. I''ve also been feeling very tired. Could I get an appointment this week?']::text[],2,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('b788bacb-249b-54dc-b404-c5505478481f','a64481c9-1fe3-5f37-a501-1e99c5f1321f','Eczacıya göndereceğin 3–4 cümlelik bir mesaj yaz: hangi ilacı kullanıyorsun, neyi merak ediyorsun (doz, yan etki, başka ilaçla birlikte kullanım) ve ne istiyorsun?','["İlaç ve sorun açıkça belirtilmiş","Kibar soru yapısı kullanılmış (Is it safe to …? / Could you …?)","Sıklık veya süre doğru ifade edilmiş (twice a day, for a week)"]'::jsonb,array['Hello, I''m taking amoxicillin twice a day for a tooth infection. Is it safe to take it with ibuprofen for the pain? Could you also tell me if I should take it with food? Thank you.']::text[],2,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('d4781ed0-9588-5cc3-b5f7-2e5c525fdce1','d7846284-4a8a-509a-b64b-155e6f82e9c6','Taburcu olduktan sonra servis hemşiresine 3–4 cümlelik bir mesaj yaz: nasıl olduğunu anlat, yaranla ilgili bir soru sor ve kontrol randevusunu teyit et.','["Durumunu anlatmak için uygun zaman kullanılmış (I''ve been / I feel)","Yara veya ilaçla ilgili açık bir soru var (Is it normal …? / When can I …?)","Kibar bir kapanış ve randevu teyidi var"]'::jsonb,array['Hello, I was discharged from Ward 4 on Monday. I''ve been feeling much better, but there is some redness around the wound. Is that normal? Could you also confirm that my check-up is on 24 May? Thank you.']::text[],2,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('c60b71f3-6fc4-5e34-af92-e29654a6b294','53b5b8fc-d379-599c-9d8e-77b99bfec9e9','İşvereninize 3–4 cümlelik resmî bir istifa mektubu yaz: istifa ettiğini, son çalışma gününü ve devir teslim için yardım teklifini belirt.','["Resmî açılış ve kapanış var (Dear …, Kind regards / Yours sincerely)","Amaç cümlesi doğru (I am writing to give notice of my resignation)","Tarih ve ihbar süresi açık; nazik bir teşekkür veya yardım teklifi var"]'::jsonb,array['Dear Ms Kaya, I am writing to give notice of my resignation from my position as Junior Developer. In line with my contract, my last working day will be 30 June. I would like to thank you for the opportunities I have had, and I will do my best to ensure a smooth handover. Kind regards, Can Yıldız']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('9946049e-07a5-5558-8c81-0b146b9f73a8','35f00cb3-8900-51a4-aeb8-113195e43047','Bir müşteriye 3–4 cümlelik resmî bir e-posta yaz: sözleşme taslağını ekte gönderdiğini, bir maddeyi değiştirdiğini ve belirli bir tarihe kadar cevap beklediğini belirt.','["Resmî açılış ve kapanış (Dear …, Kind regards) kullanılmış","“Please find attached” ve değişiklik için “amend” kullanılmış","Son tarihli kibar bir istek var (We would be grateful if you could … by …)"]'::jsonb,array['Dear Mr. Smith, please find attached the draft agreement. We have amended clause 4 regarding the payment terms. We would be grateful if you could send us your comments by 10 June. Kind regards, Elif Kaya']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('ec830878-d0ba-5ee8-8d6c-97d100cc2b37','0f692eaa-47c8-5983-880d-2c55c738f67a','Yabancı bir müvekkile 3–4 cümlelik resmî bir e-posta yaz: duruşmanın ertelendiğini bildir, yeni tarihi ver ve ondan istenen bir belgeyi belirt.','["Resmî açılış ve kapanış var (Dear …, Kind regards)","Edilgen yapı doğru kullanılmış (has been adjourned / postponed)","İstenen işlem açık ve kibar (You are required to … / We would be grateful if …)"]'::jsonb,array['Dear Mr Smith, I am writing to inform you that the hearing has been adjourned until 3 June at 10:00. One of the witnesses is unable to attend on the original date. We would be grateful if you could send us a copy of your employment contract by 20 May. Kind regards, Selin Demir']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('a0d7cfe7-527b-57d1-ad1c-545db1c9bff4','26515c63-3bd4-5d24-9fbd-336e392868a3','Bir PR''a 2–3 cümlelik nazik bir inceleme yorumu yaz: bir şeyi beğen, bir değişiklik öner ve nedenini söyle.','["Olumlu bir geri bildirimle başlıyor","Öneriyi “could / maybe / what about” gibi nazik bir kalıpla yapıyor","Önerinin nedenini açıklıyor"]'::jsonb,array['Nice work on the search filters! One suggestion: the API URL is hardcoded, so maybe we could read it from the config file. This would make it easier to change per environment.']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('29475f0b-7aa1-5143-8f3f-bee9b08d44ea','8c6847cf-f469-5cd6-b2d7-4c15dbfd531a','Bir hata kaydı için 3–4 cümle yaz: ne oluyor, nasıl yeniden oluşturulur, beklenen ve gerçekleşen sonuç ne?','["Hatayı tek cümlede net anlatıyor","Yeniden oluşturma adımlarını sırayla veriyor","Beklenen ve gerçekleşen sonucu ayırıyor"]'::jsonb,array['The app crashes when I upload a PDF larger than 10 MB. Steps to reproduce: open the Files page and upload a large PDF. Expected result: the file is uploaded. Actual result: the app closes without an error message.']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('2fa1d240-3f90-5d15-a724-2cce18b46d92','b2d05b0d-3f42-5152-8985-f7b28dde1bdb','Günlük toplantı için 3–4 cümlelik bir durum mesajı yaz: dün ne yaptın, bugün ne yapacaksın, bir engelin var mı?','["Dün için geçmiş zaman kullanılmış","Bugün için “I''m going to” veya “I''m working on” kullanılmış","Engel varsa açıkça ve bir yardım isteğiyle söylenmiş"]'::jsonb,array['Yesterday I finished the search filters. Today I''m working on the unit tests. My only blocker is the missing API key. Could someone from the backend team help me?']::text[],2,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('f54e8bc5-ca4b-5c51-b2bc-918ebb30e141','04ba1e9d-bfcb-5de1-8090-cb11f0c1e4cc','Uçuşun 4 saat rötar yaptı ve aktarmanı kaçırdın. Havayoluna 3–4 cümlelik kibar bir şikâyet e-postası yaz: ne oldu, nasıl etkilendin ve ne istiyorsun?','["Olay doğru zamanlarla anlatılmış (was delayed, I missed / I''ve missed)","Talep kibar ve açık (I would like to claim … / Would it be possible …?)","Uçuş numarası, tarih gibi somut bilgi var"]'::jsonb,array['Dear Sir or Madam, my flight TK 1985 from Istanbul to London on 12 May was delayed by four hours. As a result, I missed my connecting flight to Dublin and had to stay overnight. I would like to claim compensation for the delay. Kind regards, Ayşe Yılmaz']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('e4c67636-d7f2-5787-9e38-72ce628bf090','4ad2bb76-da0e-5681-bb74-6e5fe545667a','Gezdiğin bir şehirdeki restoran ya da müze için 3–4 cümlelik kısa bir yorum yaz: ne yaptın, neyi beğendin, başkalarına ne önerirsin?','["Deneyim geçmiş zamanla anlatılmış (We visited / We had)","Beğenilen ve beğenilmeyen bir şey sıfatlarla anlatılmış","Öneri cümlesi var (I''d recommend … / It''s worth …)"]'::jsonb,array['We visited the city museum on Saturday morning. It wasn''t crowded, and the guided tour in English was really interesting. The café was a bit expensive, though. I''d recommend booking tickets online — it''s cheaper.']::text[],2,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('0eb3e74f-1fbb-5850-82fd-740a8ed965ba','d4a80253-58de-5511-a2bd-ff59540ed595','Bir misafir e-postayla erken giriş isteyip istemediğini ve kahvaltının dahil olup olmadığını soruyor. 3–4 cümlelik kibar bir cevap yaz.','["Kibar açılış ve kapanış var","Erken giriş için net bir cevap veya koşul var (I''m afraid / If …)","Kahvaltı sorusuna “included / complimentary” ile cevap verilmiş"]'::jsonb,array['Dear Mr. Brown, thank you for your email. Check-in is from 2 pm, but if your room is ready earlier, we will be happy to check you in. Breakfast is included in the price. We look forward to welcoming you.']::text[],2,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('9bafc039-b2cc-5323-bc2b-d0fa86a98db8','2e27320a-9d7f-514d-b3d5-0606c1f40344','Bir konu hakkında 3 cümle yaz: bir faydasını, bir sakıncasını ve bir sonucunu bağlaçlarla bağla (however, therefore, although …).','["Bir fayda ve bir sakınca belirtiyor","En az bir karşıtlık bağlacını doğru kullanıyor","En az bir sonuç bağlacını doğru kullanıyor"]'::jsonb,array['Online courses are flexible, so students can study at any time. However, some students find it hard to stay motivated. Therefore, many universities combine online and face-to-face classes.']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('daf183e6-28f0-5e58-a6c6-c40097d66d43','e6ad2555-ff51-5462-82ce-6e582d7ec447','Bir grafiği veya eğilimi 3 cümleyle anlat: başlangıç değeri, değişim ve son durum.','["Başlangıç ve son değeri “from … to” veya “reach” ile veriyor","Değişimi zarf veya sıfatla niteliyor (steadily, sharp, slight)","Etkisi süren değişim için present perfect kullanıyor"]'::jsonb,array['In 2015, about 30% of people shopped online. The figure rose steadily and reached a peak of 70% in 2021. Since then, it has leveled off at around 68%.']::text[],3,'draft') on conflict do nothing;
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('6494c65d-f55d-589d-b142-7752f016501d','de1b4712-7243-59d2-b591-86fd886a91fd','Okuduğun bir araştırmayı 2–3 akademik cümleyle özetle: amacı, temel bulgusu ve bir kısıtlılığı.','["Amacı “The aim of this study was to …” gibi bir kalıpla veriyor","Bulguyu temkinli bir raporlama fiiliyle (suggest, indicate) aktarıyor","Bir kısıtlılığı ve sonucunu belirtiyor"]'::jsonb,array['The aim of this study was to examine the link between sleep and memory. The results suggest that participants who sleep longer remember more words. However, the sample consisted only of students, so further research is needed.']::text[],3,'draft') on conflict do nothing;
